function roleAllows(role, targetRoleList){
  return (targetRoleList||'').split(',').map(x=>x.trim()).includes(role);
}

function updateRoleNavigation(role){
  document.querySelectorAll('.nav-item, .nav-section').forEach(el=>{
    const roles=el.getAttribute('data-roles');
    if(!roles){el.classList.remove('nav-hidden');return;}
    el.classList.toggle('nav-hidden', !roleAllows(role, roles));
  });
  // garder le sélecteur de profil synchronisé avec le rôle actif
  document.querySelectorAll('.role-switch3 .rsw-btn').forEach(b=>b.classList.toggle('active', b.dataset.role===role));
}

// Bascule de profil depuis la sidebar : relance l'onboarding du rôle,
// qui enchaîne ensuite sur l'écran de création de fiche (comme à l'inscription).
// Fiche de ce profil déjà faite ? Marqueur du compte (multi-appareils) OU
// fiche créée pendant la session courante (couvre le mode visiteur sans compte).
function roleFicheDone(role){
  if (typeof evadFicheDone === 'function' && evadFicheDone(role)) return true;
  if (role === 'pilote')    return !!(typeof myLieuData  !== 'undefined' && myLieuData  && myLieuData.id);
  if (role === 'batisseur') return !!(typeof batFicheData !== 'undefined' && batFicheData && batFicheData.id);
  if (role === 'semeur')    return !!(typeof semFicheData !== 'undefined' && semFicheData && semFicheData.id);
  return false;
}

async function switchRole(role){
  if(!ROLE_CONFIG[role]) return;
  currentRole = role;
  updateRoleNavigation(role);            // met à jour la nav + le bouton actif
  let done = roleFicheDone(role);
  // Rattrapage comptes existants : une fiche Pilote déjà en base = fiche faite
  // (même si le marqueur de compte n'a pas encore été posé).
  if (!done && role === 'pilote' && window.evadSupabase) {
    try {
      const { data: sess } = await window.evadSupabase.auth.getSession();
      const uid = sess && sess.session && sess.session.user && sess.session.user.id;
      if (uid) {
        const { data } = await window.evadSupabase.from('fiche_pilote').select('*').eq('user_id', uid).order('created_at', { ascending: false }).limit(1);
        if (data && data.length) {
          done = true;
          if (typeof evadMarkFicheDone === 'function') evadMarkFicheDone('pilote');
          // Rattache myLieuData à SA fiche (id réel) : toute sauvegarde ultérieure
          // met à jour cette ligne au lieu d'en insérer une nouvelle (doublon).
          const _row = data[0];
          myLieuData = Object.assign({}, _row.donnees || {}, _row, { id: _row.id, lat: _row.latitude, lng: _row.longitude });
        }
      }
    } catch (e) {}
  }
  if (done) {
    // Fiche déjà faite → tableau de bord direct (on est déjà dans l'app, pas
    // besoin de repasser par l'onboarding ni la création de fiche).
    if (typeof renderProfileContext === 'function') renderProfileContext();
    const dash = { pilote:'pilote', batisseur:'quete', semeur:'semeur' }[role] || 'carte';
    showScreen(dash);
  } else {
    showOnboarding(role);                // assistant du rôle → puis création de fiche
  }
}

// Entrée directe au tableau de bord (fiche déjà faite) : on saute l'onboarding.
function evadEnterDashboard(role){
  currentRole = role;
  const splash = document.getElementById('evad-splash');
  if (splash) splash.classList.add('hidden');
  setTimeout(function(){
    if (splash) { splash.style.opacity = ''; splash.style.pointerEvents = ''; splash.style.display = 'none'; }
    document.body.style.overflow = 'hidden';
    updateRoleNavigation(role);
    if (typeof renderProfileContext === 'function') renderProfileContext();
    const dash = { pilote:'pilote', batisseur:'quete', semeur:'semeur' }[role] || 'carte';
    // Au rafraîchissement (pas à la connexion), revenir sur la dernière page
    // consultée. L'onglet du tableau de bord est restauré dans showScreen, tant
    // que __evadRestoring est vrai — on ne le remet à faux qu'ensuite.
    const target = _evadRestoreScreen(role, dash);
    if (typeof showScreen === 'function') showScreen(target);
    window.__evadRestoring = false;
  }, 300);
}

// Écran à restaurer au rafraîchissement (sinon tableau de bord par défaut). Ne
// restaure que si __evadRestoring est vrai (posé par evadRestoreSession) : à la
// connexion normale, on garde le tableau de bord par défaut.
function _evadRestoreScreen(role, defaultScreen){
  if (!window.__evadRestoring) return defaultScreen;
  let saved = null; try { saved = localStorage.getItem('evad:last-screen'); } catch (e) {}
  const roleScreens = (ROLE_CONFIG[role] && ROLE_CONFIG[role].screens) ? ROLE_CONFIG[role].screens : {};
  const shared = { carte:1, reseau:1, modelisation:1, contribuer:1 };
  if (saved && saved !== 'creer'
      && document.getElementById('screen-' + saved)
      && (roleScreens[saved] || shared[saved])) {
    return saved;
  }
  return defaultScreen;
}

// Onglet d'entrée d'un tableau de bord : l'onglet mémorisé (au refresh, s'il
// existe encore), sinon l'onglet par défaut. En navigation normale, on garde
// toujours le défaut.
function _evadDashEntryTab(screen, def){
  if (!window.__evadRestoring) return def;
  let t = null; try { t = localStorage.getItem('evad:tab:' + screen); } catch (e) {}
  const panelPrefix = { pilote:'pilote-panel-', quete:'bat-panel-', semeur:'semeur-panel-' }[screen];
  if (t && panelPrefix && document.getElementById(panelPrefix + t)) return t;
  return def;
}

function firstAllowedScreen(role){
  return ROLE_CONFIG[role]?.defaultScreen||'carte';
}

function renderProfileContext(){
  const cfg=ROLE_CONFIG[currentRole]||ROLE_CONFIG.pilote;
  const activeScreen=document.querySelector('.screen.active')?.id?.replace('screen-','')||cfg.defaultScreen;
  document.getElementById('profile-summary-title').textContent=cfg.label;
  document.getElementById('profile-summary-text').textContent=cfg.summary;
  const ctx=cfg.screens[activeScreen];
  const box=document.getElementById('context-'+activeScreen);
  if(box&&ctx){
    box.innerHTML=`<div class="context-label">Contexte du profil</div><div class="context-title">${ctx.title}</div><div class="context-text">${ctx.text}</div><div class="context-actions">${ctx.actions.map(a=>`<span class="context-badge">${a}</span>`).join('')}</div>`;
  }
  const primary=document.getElementById('carte-primary-btn');
  const secondary=document.getElementById('carte-secondary-btn');
  if(primary) primary.textContent=cfg.cartePrimary||'+ Ajouter mon lieu';
  if(secondary) secondary.textContent=cfg.carteSecondary||'Filtrer';
  const mapPanelTitle=document.querySelector('.map-panel-title');
  const mapPanelCount=document.querySelector('.map-panel-count');
  if(mapPanelTitle){
    mapPanelTitle.textContent='La communauté EVAD';
  }
}

function setRole(role, btn){
  currentRole=role;
  document.querySelectorAll('.role-chip').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  updateRoleNavigation(role);
  // Show onboarding for this role
  showOnboarding(role);
}

function updateActiveNav(id){
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
  const activeItem=document.querySelector(`.nav-item[data-screen="${id}"]`);
  if(activeItem&&!activeItem.classList.contains('nav-hidden')) activeItem.classList.add('active');
}

/* ─── SIDEBAR WIZARD MODE ─── */
const WIZARD_SCREENS = ['creer', 'fiche-bat', 'fiche-sem'];

function navWizardSet(steps, currentIdx, onJump) {
  const nav = document.querySelector('.nav');
  const container = document.getElementById('nav-stepper');
  if (!nav || !container) return;
  nav.classList.add('wizard-mode');
  container.setAttribute('aria-hidden', 'false');
  container.innerHTML = `
    <div class="nav-stepper-title">Progression</div>
    ${steps.map((label, i) => {
      const state = i < currentIdx ? 'done' : i === currentIdx ? 'active' : 'upcoming';
      const icon = state === 'done' ? '✓' : (i + 1);
      const showLine = i < steps.length - 1;
      return `
        <div class="nav-step ${state}" data-step-idx="${i}">
          <div class="nav-step-rail">
            <div class="nav-step-circle">${icon}</div>
            ${showLine ? `<div class="nav-step-line"></div>` : ''}
          </div>
          <div class="nav-step-text">
            <div class="nav-step-num">Étape ${i + 1}</div>
            <div class="nav-step-label">${label}</div>
          </div>
        </div>
      `;
    }).join('')}
  `;
  if (typeof onJump === 'function') {
    container.querySelectorAll('.nav-step').forEach(el => {
      const idx = parseInt(el.dataset.stepIdx, 10);
      if (idx < currentIdx) {
        el.addEventListener('click', () => onJump(idx));
      }
    });
  }
  // Raccourci réservé aux environnements de test (dev.evad.org, préview, local) :
  // sauter l'assistant pour aller voir le reste de l'app sans remplir la fiche.
  // Absent de la production, où EVAD_SUPABASE_ENV.isProd vaut true
  // (liste des hôtes : PROD_HOSTS dans js/supabase-config.js).
  if (!(window.EVAD_SUPABASE_ENV && window.EVAD_SUPABASE_ENV.isProd)) {
    const skip = document.createElement('button');
    skip.type = 'button';
    skip.className = 'nav-stepper-skip';
    skip.id = 'nav-stepper-skip';
    skip.innerHTML = '<span>⏭</span> Passer la création de fiche';
    skip.title = 'Raccourci de test, absent de app.evad.org';
    skip.addEventListener('click', evadSkipFiche);
    container.appendChild(skip);
  }
  // Mémorise l'état pour la barre mobile (qui affiche les étapes à la place des onglets).
  window._navWizard = { steps: steps.slice(), currentIdx: currentIdx, onJump: onJump };
  if (typeof window.renderMobNav === 'function') window.renderMobNav();
}

// Quitte l'assistant de création et ouvre le tableau de bord du profil en cours.
// Couvre les trois assistants : Pilote (creer), Bâtisseur (fiche-bat) et
// Semeur (fiche-sem). Réservé aux environnements de test, voir navWizardSet.
function evadSkipFiche() {
  const active = document.querySelector('.screen.active');
  const roleByScreen = { 'screen-creer': 'pilote', 'screen-fiche-bat': 'batisseur', 'screen-fiche-sem': 'semeur' };
  const role = (active && roleByScreen[active.id]) || currentRole;
  currentRole = role;
  if (typeof updateRoleNavigation === 'function') updateRoleNavigation(role);
  navWizardClear();
  showScreen({ pilote: 'pilote', batisseur: 'quete', semeur: 'semeur' }[role] || 'carte');
}

// Saut vers une étape déjà franchie depuis la barre wizard mobile.
function navWizardJump(idx) {
  const w = window._navWizard;
  if (w && typeof w.onJump === 'function' && idx < w.currentIdx) w.onJump(idx);
}

function navWizardClear() {
  const nav = document.querySelector('.nav');
  if (nav) nav.classList.remove('wizard-mode');
  const container = document.getElementById('nav-stepper');
  if (container) {
    container.innerHTML = '';
    container.setAttribute('aria-hidden', 'true');
  }
  window._navWizard = null;
  if (typeof window.renderMobNav === 'function') window.renderMobNav();
}

