// Remplit l'onglet « Impact » de la modale lieu depuis cData (KPIs + score détaillé).
function lieuRenderImpact() {
  const kpisEl = document.getElementById('lieu-impact-kpis');
  if (kpisEl) {
    // Lieu de référence : la fiche affichée (cData, alimentée par le lieu ouvert).
    const L = (typeof cData !== 'undefined' && cData) ? cData : {};
    // Indicateurs sélectionnés à la création de la fiche (ICI des solutions
    // retenues + ajoutés − retirés).
    const iciIds = (typeof evadLieuIciIds === 'function') ? evadLieuIciIds(L) : [];
    const icis = (typeof ICI_CATALOG !== 'undefined')
      ? iciIds.map(id => ICI_CATALOG.find(i => i.id === id)).filter(Boolean) : [];

    // Quêtes du lieu : ce sont elles qui apportent la preuve. On les lit dans le
    // store par lieu_id (repli sur la liste en mémoire du tableau de bord).
    const lieuQuetes = (window.store && L && L.id)
      ? store.where('quetes', r => r.lieu_id === L.id && r.statut !== 'retiree')
      : ((typeof PILOTE_QUETES_DEMO !== 'undefined') ? PILOTE_QUETES_DEMO : []);
    const estProuvee = (q) => (typeof quetesValidees !== 'undefined') && quetesValidees.has(q.id);

    // Preuve d'un indicateur : quêtes qui le portent (lien explicite icis, ou via
    // la solution dont elles sont issues) et proportion déjà validée.
    const preuveDe = (ici) => {
      const liees = (lieuQuetes || []).filter(q =>
        (Array.isArray(q.icis) && q.icis.indexOf(ici.id) >= 0) ||
        (q.source && Array.isArray(ici.solutionIds) && ici.solutionIds.indexOf(q.source) >= 0)
      );
      const prouvees = liees.filter(estProuvee);
      const pct = liees.length ? Math.round(prouvees.length / liees.length * 100) : 0;
      return { liees: liees.length, prouvees: prouvees.length, pct };
    };

    const fmt = (n) => { n = Math.round(n); return (n >= 1000) ? n.toLocaleString('fr-FR') : String(n); };

    if (!icis.length) {
      kpisEl.innerHTML = `<div style="grid-column:1/-1;padding:1.4rem;text-align:center;font-size:.72rem;color:var(--moss);opacity:.55;border:1.5px dashed rgba(46,102,66,.15);border-radius:var(--r-lg)">Aucun indicateur sélectionné dans la fiche de ce lieu.</div>`;
    } else {
      kpisEl.innerHTML = icis.map(ici => {
        const meta = (typeof ICI_LIVRE_META !== 'undefined' ? ICI_LIVRE_META[ici.livre] : null) || { col: '#4a8c5c', ic: '◆' };
        const col = meta.col;
        const p = preuveDe(ici);
        const p0 = (typeof ici.point0 === 'number') ? ici.point0 : 0;
        // Cible adaptée à la taille/type du lieu (repli : catalogue).
        const p100 = (typeof iciPoint100For === 'function') ? iciPoint100For(ici)
                   : ((typeof ici.point100 === 'number') ? ici.point100 : 100);
        const val = p0 + (p100 - p0) * p.pct / 100;
        const statut = p.prouvees > 0
          ? `✓ ${p.pct}% prouvé · ${p.prouvees}/${p.liees} quête${p.liees > 1 ? 's' : ''}`
          : (p.liees > 0
              ? `${p.liees} quête${p.liees > 1 ? 's' : ''} à valider`
              : 'à renseigner');
        return `
          <div style="background:white;border:1px solid ${col}26;border-radius:var(--r-lg);padding:.85rem 1rem;border-left:3px solid ${col}">
            <div style="font-size:.58rem;color:var(--moss);opacity:.7;text-transform:uppercase;letter-spacing:.08em;margin-bottom:.3rem;line-height:1.25">${meta.ic} ${ici.nom}</div>
            <div style="display:flex;align-items:baseline;gap:.3rem">
              <span style="font-family:'Satoshi', sans-serif;font-size:1.5rem;font-weight:900;color:${col};line-height:1">${p.pct > 0 ? fmt(val) : '-'}</span>
              <span style="font-size:.6rem;color:var(--moss);opacity:.6">${ici.unite || ''}</span>
            </div>
            <div style="height:4px;background:rgba(46,102,66,.1);border-radius:100px;overflow:hidden;margin:.45rem 0 .3rem"><div style="width:${p.pct}%;height:100%;background:${col};border-radius:100px;transition:width .5s ease"></div></div>
            <div style="font-size:.58rem;color:${p.prouvees > 0 ? col : 'var(--moss)'};opacity:${p.prouvees > 0 ? '.9' : '.5'};font-weight:${p.prouvees > 0 ? '700' : '500'}">${statut}</div>
            <div style="font-size:.54rem;color:var(--moss);opacity:.45;margin-top:.15rem">cible ${fmt(p100)} ${ici.unite || ''}</div>
          </div>`;
      }).join('');
    }

    // Preuves certifiées : les quêtes du lieu déjà validées. Ce sont elles qui
    // remplissent les indicateurs ci-dessus.
    const preuvesEl = document.getElementById('lieu-impact-preuves');
    if (preuvesEl) {
      const prouvees = (lieuQuetes || []).filter(estProuvee);
      if (!prouvees.length) {
        preuvesEl.innerHTML = `<div style="padding:1.2rem;text-align:center;font-size:.72rem;color:var(--moss);opacity:.5">Aucune preuve certifiée pour l'instant. Valide une quête dans « Mes quêtes » pour qu'elle apparaisse ici.</div>`;
      } else {
        const iciNomsDe = (q) => {
          const qIcis = q.icis || (q.donnees && q.donnees.icis) || [];
          return icis.filter(ici =>
            (Array.isArray(qIcis) && qIcis.indexOf(ici.id) >= 0) ||
            (q.source && Array.isArray(ici.solutionIds) && ici.solutionIds.indexOf(q.source) >= 0)
          ).map(ici => ici.nom);
        };
        preuvesEl.innerHTML = prouvees.map(q => {
          const noms = iciNomsDe(q);
          return `
            <div style="background:white;border:1px solid rgba(74,140,92,.18);border-left:3px solid var(--fern);border-radius:var(--r-lg);padding:.7rem .9rem">
              <div style="display:flex;align-items:center;gap:.45rem">
                <span style="font-size:.58rem;font-weight:800;color:var(--fern);background:rgba(74,140,92,.12);border-radius:100px;padding:.12rem .5rem;white-space:nowrap">✓ Certifiée</span>
                <span style="font-size:.76rem;font-weight:700;color:var(--ink)">${q.titre || 'Quête'}</span>
              </div>
              ${noms.length ? `<div style="font-size:.62rem;color:var(--moss);opacity:.75;margin-top:.35rem">Valide : ${noms.join(' · ')}</div>` : ''}
              <div style="font-size:.58rem;color:var(--moss);opacity:.5;margin-top:.2rem">🌱 ${q.graines || 0} graines</div>
            </div>`;
        }).join('');
      }
    }
  }
  const scoreEl = document.getElementById('lieu-impact-score');
  if (scoreEl) {
    const score = (typeof cData.score === 'number') ? cData.score : null;
    const dims = (cData.dims && cData.dims.length) ? cData.dims : [];
    const cols = ['#82b894','#6aa0bc','#e8a55a','#a09ad8'];
    const grad = ['linear-gradient(90deg,#4a8c5c,#82b894)','linear-gradient(90deg,#3a6e8c,#6aa0bc)','linear-gradient(90deg,#c8732a,#e8a55a)','linear-gradient(90deg,#7a6ea8,#a09ad8)'];
    scoreEl.innerHTML = `
      <div style="font-size:.58rem;color:var(--sage);text-transform:uppercase;letter-spacing:.12em;opacity:.7;margin-bottom:.5rem">Vadance globale</div>
      <div style="font-family:'Satoshi', sans-serif;font-size:2.4rem;font-weight:900;color:var(--sun);line-height:1;margin-bottom:.2rem">${score!=null?score:'-'}</div>
      <div style="font-size:.65rem;color:rgba(255,255,255,.4);margin-bottom:1rem">${score!=null?(cData.scoreTrim?'tendance '+cData.scoreTrim+' ce trimestre':'sur 100'):'à certifier'}</div>
      <div style="display:flex;flex-direction:column;gap:.45rem">
        ${dims.slice(0,4).map((d,i)=>`
        <div>
          <div style="display:flex;justify-content:space-between;font-size:.62rem;color:var(--mist);opacity:.75;margin-bottom:.2rem"><span>${d.l}</span><span style="color:${cols[i]};font-weight:700">${d.v}</span></div>
          <div style="height:4px;background:rgba(255,255,255,.08);border-radius:100px;overflow:hidden"><div style="width:${d.v}%;height:100%;background:${grad[i]};border-radius:100px"></div></div>
        </div>`).join('')}
      </div>`;
  }
}

// Ouvre la modale « fiche complète » à partir d'un lieu réel de la carte.
function openLieuModalFromPlace(idx) {
  const p = MAP_PLACES[idx];
  if (!p) return;
  cData = Object.assign(_CDATA_EMPTY(), (p.fiche || {}), {
    nom: p.nom,
    icon: p.icon,
    localisation: p.ville,
    lat: p.lat, lng: p.lng,
    desc: p.desc || '',
    besoins: p.besoins || [],
    score: p.score,
    scoreTrim: p.score_trim,
    dims: p.dims || []
  });
  openLieuModal();
}

let currentMapFilter = 'tous';
let batisseurMarkers = [];
let semeurMarkers = [];

function mapSearch(query) {
  const q = query.trim().toLowerCase();
  const clearBtn = document.getElementById('map-search-clear');
  clearBtn.style.display = q ? 'block' : 'none';

  const cards = document.querySelectorAll('#map-panel-main .place-card-mini');
  let totalVisible = 0;

  cards.forEach(card => {
    const text = card.textContent.toLowerCase();
    const match = !q || text.includes(q);
    card.style.display = match ? '' : 'none';
    if (match) totalVisible++;
  });

  // Show/hide section headers based on visible cards inside
  ['map-section-lieux', 'map-section-batisseurs', 'map-section-semeurs'].forEach(id => {
    const section = document.getElementById(id);
    if (!section) return;
    const visibleCards = section.querySelectorAll('.place-card-mini:not([style*="display: none"])');
    const header = section.querySelector('div:first-child');
    if (header) header.style.display = visibleCards.length ? '' : 'none';
  });

  document.getElementById('map-search-empty').style.display = q && totalVisible === 0 ? 'block' : 'none';
}

function mapSearchClear() {
  const input = document.getElementById('map-search-input');
  input.value = '';
  mapSearch('');
  input.focus();
}

function mapFilter(type, btn) {
  currentMapFilter = type;
  document.querySelectorAll('.filter-chip').forEach(c => c.classList.remove('active'));
  btn.classList.add('active');

  // Show/hide panel sections
  const sLieux = document.getElementById('map-section-lieux');
  const sBat = document.getElementById('map-section-batisseurs');
  const sSem = document.getElementById('map-section-semeurs');

  if (type === 'tous') {
    sLieux.style.display = ''; sBat.style.display = ''; sSem.style.display = '';
  } else if (type === 'lieu') {
    sLieux.style.display = ''; sBat.style.display = 'none'; sSem.style.display = 'none';
  } else if (type === 'batisseur') {
    sLieux.style.display = 'none'; sBat.style.display = ''; sSem.style.display = 'none';
  } else if (type === 'semeur') {
    sLieux.style.display = 'none'; sBat.style.display = 'none'; sSem.style.display = '';
  } else if (type === 'quete') {
    sLieux.style.display = ''; sBat.style.display = 'none'; sSem.style.display = 'none';
  }

  // Show/hide map markers
  evadMarkers.forEach(m => {
    const el = m.getElement();
    if (el) el.style.opacity = (type === 'tous' || type === 'lieu' || type === 'quete') ? '1' : '0.18';
  });
  batisseurMarkers.forEach(m => {
    const el = m.getElement();
    if (el) el.style.opacity = (type === 'tous' || type === 'batisseur') ? '1' : '0.18';
  });
  semeurMarkers.forEach(m => {
    const el = m.getElement();
    if (el) el.style.opacity = (type === 'tous' || type === 'semeur') ? '1' : '0.18';
  });

  // Close acteur panel
  document.getElementById('map-acteur-panel').style.display = 'none';
  document.getElementById('map-panel-main').style.display = '';
}

