/* ─── Gamification : Vadance projetée vivante pendant la création ───
   Les points viennent du potentiel d'impact de ce que le Pilote déclare
   (solutions = ICI, espaces, ambition), pas juste du remplissage. ── */
const VADANCE_PALIERS = [
  { min: 88, label: '🚀 Lieu à fort impact' },
  { min: 65, label: '✨ Prêt à publier' },
  { min: 38, label: '🌱 Impact déclaré' },
  { min: 10, label: '🌿 Lieu esquissé' },
];
let creerLastVadance = 0;

// Calcul pur de la Vadance (promesse) à partir d'une fiche lieu (cData OU myLieuData).
function computeVadance(d){
  d = d || {};
  let v = 0;
  // Fondations (mise en place) : peu de points, ce n'est PAS de l'impact.
  if (d.nom) v += 3;
  if (d.type) v += 3;
  if (d.localisation) v += 2;
  if (d.desc && String(d.desc).trim().length > 15) v += 3;
  if (d.phase) v += 2;
  // (année / surface / statut : 0 point, pur remplissage administratif)

  // Impact projeté : les espaces structurent, les solutions PORTENT l'impact (ICI).
  v += Math.min(3, (d.espacesData || []).length) * 5;
  let solPts = 0;
  (d.solutions || []).forEach(nom => {
    const nbIci = (typeof iciPourSolution === 'function') ? iciPourSolution(nom).length : 0;
    solPts += 10 + nbIci * 6;   // base impact + bonus par ICI réel porté (CO₂ évité, m² renaturés…)
  });
  v += Math.min(72, solPts);    // l'impact déclaré domine le score

  return Math.min(100, v);
}
function creerVadance(){ return computeVadance(cData); }
const creerVadancePalier = (s) => VADANCE_PALIERS.find(p => s >= p.min) || null;

function creerUpdateVadance(silent){
  if (window.store && (cData.nom || (cData.espacesData || []).length || (cData.solutions || []).length)) store.saveDraft('lieu', cData);   // brouillon auto-sauvegardé (si contenu)
  const v = creerVadance();
  const bar = document.getElementById('creer-vadance-bar');
  if (!bar) { creerLastVadance = v; return; }
  bar.style.width = v + '%';
  const valEl = document.getElementById('creer-vadance-val'); if (valEl) valEl.textContent = v;
  const p = creerVadancePalier(v);
  const palEl = document.getElementById('creer-vadance-palier'); if (palEl) palEl.textContent = p ? p.label : '';
  if (!silent) {
    const delta = v - creerLastVadance;
    if (delta > 0) creerVadanceFloat('+' + delta);
    const prevP = creerVadancePalier(creerLastVadance);
    if (p && (!prevP || p.min > prevP.min)) creerVadanceCelebrate(p.label);
  }
  creerLastVadance = v;
  if (typeof creerUpdateHint === 'function') creerUpdateHint(silent);
}

function creerVadanceFloat(txt){
  const g = document.getElementById('creer-vadance'); if (!g) return;
  const f = document.createElement('div');
  f.textContent = txt + ' 🌱';
  f.style.cssText = 'position:absolute;top:44px;left:50%;transform:translateX(-50%);z-index:26;font-family:Satoshi,sans-serif;font-weight:900;font-size:.92rem;color:#018262;pointer-events:none;text-shadow:0 2px 6px rgba(255,255,255,.8);animation:vadFloat 1s ease-out forwards';
  g.parentElement.appendChild(f);
  setTimeout(() => f.remove(), 1000);
  g.style.animation = 'none'; void g.offsetWidth; g.style.animation = 'vadPop .42s ease';
}

function creerVadanceCelebrate(label){
  const g = document.getElementById('creer-vadance'); if (!g) return;
  const host = g.parentElement;
  ['✨','🌱','💚','✨','🌿'].forEach((e, i) => {
    const ang = (i / 5) * Math.PI * 2;
    const s = document.createElement('div');
    s.textContent = e;
    s.style.cssText = 'position:absolute;top:26px;left:50%;z-index:27;font-size:1.15rem;pointer-events:none;transform:translate(-50%,0);transition:transform .85s cubic-bezier(.2,.8,.2,1),opacity .85s ease-out';
    host.appendChild(s);
    requestAnimationFrame(() => { s.style.transform = 'translate(calc(-50% + ' + Math.round(Math.cos(ang) * 72) + 'px), ' + Math.round(-32 - Math.abs(Math.sin(ang)) * 46) + 'px)'; s.style.opacity = '0'; });
    setTimeout(() => s.remove(), 880);
  });
  const t = document.createElement('div');
  t.textContent = 'Palier atteint · ' + label;
  t.style.cssText = 'position:absolute;top:52px;left:50%;transform:translateX(-50%);z-index:28;background:#018262;color:#fff;font-family:Satoshi,sans-serif;font-weight:800;font-size:.7rem;padding:.4rem .85rem;border-radius:100px;box-shadow:0 10px 24px -6px rgba(1,130,98,.6);white-space:nowrap;pointer-events:none;animation:vadFloat 1.7s ease-out forwards';
  host.appendChild(t);
  setTimeout(() => t.remove(), 1700);
}

// Écran d'attente « Deva cherche… » affiché avant de révéler un résultat
// généré (solutions d'un lieu, quêtes d'un bâtisseur). opts = {title, msgs}.
function renderDevaSearching(c, opts){
  opts = opts || {};
  const title = opts.title || 'Deva explore la bibliothèque';
  const msgs = opts.msgs || [
    'Analyse des espaces de ton lieu…',
    'Exploration de la bibliothèque de solutions…',
    'Sélection des solutions les plus adaptées…',
    'Détection des synergies circulaires…'
  ];
  c.innerHTML =
    '<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:2.5rem 1rem;min-height:320px;animation:obFadeIn .35s ease">'
      +'<div style="position:relative;width:84px;height:84px;margin-bottom:1.3rem">'
        +'<div style="position:absolute;inset:0;border-radius:50%;background:rgba(74,200,110,.12);animation:pulse 1.8s ease-in-out infinite"></div>'
        +'<div style="position:absolute;inset:5px;border-radius:50%;border:2.5px solid rgba(74,200,110,.2);border-top-color:#4ac86e;animation:spin .9s linear infinite"></div>'
        +'<img src="Deva.png" alt="Deva" style="position:absolute;inset:15px;width:54px;height:54px;object-fit:contain;object-position:bottom;transform:scaleX(-1) rotate(12deg);filter:drop-shadow(0 0 8px rgba(74,200,110,.5))">'
      +'</div>'
      +'<div style="font-size:.95rem;font-weight:800;color:var(--ink);margin-bottom:.45rem;font-family:\'Satoshi\',sans-serif">'+title+'</div>'
      +'<div id="creer-sol-loading-msg" style="font-size:.72rem;color:var(--moss);opacity:.8;min-height:1.1em;transition:opacity .25s">'+msgs[0]+'</div>'
      +'<div style="display:flex;gap:.32rem;margin-top:1.05rem">'
        +'<span style="width:7px;height:7px;border-radius:50%;background:#4ac86e;animation:typingBounce 1.1s ease-in-out infinite"></span>'
        +'<span style="width:7px;height:7px;border-radius:50%;background:#4ac86e;animation:typingBounce 1.1s ease-in-out .18s infinite"></span>'
        +'<span style="width:7px;height:7px;border-radius:50%;background:#4ac86e;animation:typingBounce 1.1s ease-in-out .36s infinite"></span>'
      +'</div>'
    +'</div>';
  // Fait défiler les messages pendant la recherche
  let mi = 0;
  clearInterval(window._creerSolMsgTimer);
  window._creerSolMsgTimer = setInterval(()=>{
    const el = document.getElementById('creer-sol-loading-msg');
    if(!el){ clearInterval(window._creerSolMsgTimer); return; }
    mi = (mi + 1) % msgs.length;
    el.style.opacity = '0';
    setTimeout(()=>{ if(el){ el.textContent = msgs[mi]; el.style.opacity = '.8'; } }, 200);
  }, 720);
}

// Clic sur la pastille Deva : ouvre simplement le chat. L'utilisateur pose
// lui-même sa question (plus d'envoi automatique de message scripté).
function devaPillClick(){
  if (typeof devaToggleChat === 'function') devaToggleChat();
}

// État « rempli » du lieu, pour détecter ce que l'utilisateur vient d'ajouter.
function creerSnapshot(){
  return {
    nom: !!cData.nom, loc: !!cData.localisation, type: !!cData.type,
    desc: !!(cData.desc && cData.desc.trim().length > 15), phase: !!cData.phase,
    esp: (cData.espacesData || []).length,
    sols: (cData.solutions || []).slice().sort().join('|')
  };
}
// Nudge vers le prochain palier de Vadance.
function creerNextNudge(){
  if (typeof creerVadance !== 'function' || typeof VADANCE_PALIERS === 'undefined') return '';
  const v = creerVadance();
  const next = VADANCE_PALIERS.slice().reverse().find(p => p.min > v);
  if (!next) return ' 🚀 Lieu à fort impact, bravo !';
  return ' Plus que <b>+' + (next.min - v) + '</b> pour <b>' + next.label + '</b>.';
}
// Réaction de Deva à ce qui vient d'être rempli (gain + bénéfice concret).
function creerChangeMsg(prev, cur){
  const prevSols = (prev.sols || '').split('|').filter(Boolean);
  const curSols = (cur.sols || '').split('|').filter(Boolean);
  const added = curSols.find(s => !prevSols.includes(s));
  if (added){
    const n = (typeof iciPourSolution === 'function') ? iciPourSolution(added).length : 0;
    if (n > 0) return '☀️ <b>' + added + '</b> : elle porte <b>' + n + ' ICI</b>' + (n > 1 ? '' : '') + ', du concret pour tes Semeurs 🌿';
    return '✅ <b>' + added + '</b> ajoutée, une action de plus pour ton lieu.';
  }
  if (cur.esp > (prev.esp || 0)) return '🧩 Un espace de plus : ton lieu devient lisible, les Bâtisseurs voient où agir.';
  if (cur.nom && !prev.nom)   return '🌱 Ton lieu a un nom, il existe !';
  if (cur.type && !prev.type) return '🏷️ Type choisi : je peux adapter les solutions et les quêtes.';
  if (cur.loc && !prev.loc)   return '📍 Localisé : il apparaîtra sur la carte, près des bâtisseurs du coin.';
  if (cur.desc && !prev.desc) return '✍️ Belle vision : ça aide les financeurs à te comprendre.';
  if (cur.phase && !prev.phase) return '🚧 Phase indiquée : la communauté sait où en est ton projet.';
  return null;
}
// Bulle Deva : réagit à chaque champ rempli, sinon message d'aide / explication ICI.
function creerUpdateHint(silent){
  const txt = document.getElementById('deva-fiche-hint-txt');
  const tip = document.getElementById('deva-fiche-hint');
  if (!txt) return;
  const cur = creerSnapshot();
  const prev = window._creerSnap;
  let reaction = null;
  if (!silent && prev){
    const msg = creerChangeMsg(prev, cur);
    if (msg) reaction = msg + creerNextNudge();
  }
  window._creerSnap = cur;
  if (reaction){
    txt.innerHTML = reaction;
    if (tip) tip.style.display = 'block';
  } else {
    txt.innerHTML = (cStep === 3 && window._creerPhase === 'quetes')
      ? "Voici une quête par solutions, adaptée à chaque espace. Ajoute-en ou crée les tiennes. Tu pourras modifier les quêtes avant leur publication dans le tableau de bord."
      : (cStep === 3 && cData._solsReady)
        ? "Voici les solutions repérées, et sous chacune ses <b>ICI</b> 🌱 : l'impact que ton lieu va mesurer."
        : "Besoin d'aide pour remplir la fiche ? Je suis là :)";
    if (tip && cStep === 3) tip.style.display = 'block';
  }
}

function renderStep(){
  // Étape 5 « Quête » = phase quêtes de l'étape guidée (cStep reste 3 en interne).
  const _stepIdx = (cStep === 3 && window._creerPhase === 'quetes') ? 4 : cStep;
  navWizardSet(STEPS.map(s=>s.t), _stepIdx, creerGoStep);
  if (typeof creerUpdateVadance === 'function') creerUpdateVadance();
  _creerMajNav();

  const c=document.getElementById('creer-step-content');
  if(cStep===0){
    c.innerHTML=`
      <label class="creer-lbl">Nom du lieu</label>
      <input class="creer-inp" type="text" placeholder="Ex : La Ferme des Possibles" value="${cData.nom}" oninput="cData.nom=this.value;mmCenter()">
      <label class="creer-lbl">Localisation</label>
      <div style="position:relative" id="loc-wrap">
        <input class="creer-inp" type="text" id="loc-inp" placeholder="Tapez une adresse, ville…"
          value="${cData.localisation||''}" autocomplete="off"
          oninput="geoAutoInput(this.value)"
          onfocus="if(this.value.length>2)geoAutoInput(this.value)"
          onblur="setTimeout(()=>{const d=document.getElementById('loc-drop');if(d)d.remove();},200)">
        ${cData.localisation?`<div style="font-size:.6rem;color:var(--fern);margin-top:.2rem;padding-left:.1rem">📍 Position vérifiée</div>`:''}
      </div>
      <label class="creer-lbl">Type de lieu</label>
      <div style="display:flex;flex-direction:column;gap:.6rem;margin-bottom:.8rem">
        ${Object.entries(TYPES_LIEU.reduce((acc,t)=>{(acc[t.cat]=acc[t.cat]||[]).push(t);return acc;},{})).map(([cat,types])=>`
          <div>
            <div style="font-size:.58rem;font-weight:700;color:var(--moss);opacity:.55;text-transform:uppercase;letter-spacing:.1em;margin-bottom:.3rem">${cat}</div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:.3rem">
              ${types.map(t=>`<button class="type-btn${cData.type===t.id?' sel':''}" onclick="cData.type='${t.id}';cData.icon='${t.ic}';document.querySelectorAll('#creer-step-content .type-btn').forEach(b=>b.classList.remove('sel'));this.classList.add('sel');mmCenter()" style="padding:.45rem .5rem"><div style="font-size:1rem;margin-bottom:.15rem">${t.ic}</div><div style="font-size:.68rem">${t.l}</div></button>${t.id==='autre'?`<input class="creer-inp" type="text" placeholder="Précisez…" value="${cData.autreType||''}" oninput="cData.autreType=this.value;mmCenter()" style="align-self:center;margin:0">`:''}`).join('')}
            </div>
          </div>`).join('')}
      </div>
      `;
  } else if(cStep===1){
    c.innerHTML=`
      <label class="creer-lbl">Logo du lieu</label>
      <div style="display:flex;align-items:center;gap:.8rem;margin-bottom:.8rem">
        <div id="creer-logo-preview" style="width:60px;height:60px;border-radius:var(--r);border:1.5px dashed rgba(46,102,66,.25);background:rgba(46,102,66,.04);display:flex;align-items:center;justify-content:center;font-size:1.5rem;flex-shrink:0;overflow:hidden">${cData.logo?`<img src="${cData.logo}" style="width:100%;height:100%;object-fit:cover">`:(cData.icon||'🌿')}</div>
        <div style="flex:1">
          <label style="display:inline-flex;align-items:center;gap:.4rem;cursor:pointer;font-size:.7rem;font-weight:600;color:var(--forest);padding:.35rem .8rem;border:1px solid rgba(46,102,66,.3);border-radius:100px;background:rgba(46,102,66,.06)">
            📁 Déposer une image
            <input type="file" accept="image/*" style="display:none" onchange="creerLogo(this)">
          </label>
          <div style="font-size:.6rem;color:var(--moss);opacity:.55;margin-top:.3rem">PNG, JPG ou SVG · recommandé 200×200 px</div>
        </div>
      </div>
      <label class="creer-lbl">Documents <span style="font-weight:400;opacity:.5;font-size:.65rem">(plaquette, statuts, dossier…)</span></label>
      <label style="display:flex;align-items:center;gap:.5rem;cursor:pointer;font-size:.72rem;font-weight:600;color:var(--forest);padding:.6rem .9rem;border:1.5px dashed rgba(46,102,66,.3);border-radius:var(--r);background:rgba(46,102,66,.04);margin-bottom:.5rem">
        📎 Déposer des documents
        <input type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.odt" multiple style="display:none" onchange="creerDocs(this)">
      </label>
      <div id="creer-docs-list" style="display:flex;flex-direction:column;gap:.3rem;margin-bottom:.8rem">${(cData.docs||[]).map((d,i)=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:.5rem;background:rgba(46,102,66,.05);border:1px solid rgba(46,102,66,.12);border-radius:var(--r);padding:.4rem .6rem"><span style="font-size:.68rem;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">📄 ${d}</span><button onclick="cData.docs.splice(${i},1);renderStep()" style="background:none;border:none;color:var(--moss);opacity:.55;cursor:pointer;font-size:.85rem;flex-shrink:0;line-height:1">✕</button></div>`).join('')}</div>
      <div id="creer-doc-status" style="display:none;align-items:center;gap:.55rem;background:rgba(46,102,66,.07);border:1px solid rgba(46,102,66,.18);border-radius:var(--r);padding:.5rem .7rem;margin-bottom:.8rem;font-size:.7rem;color:var(--forest)"><span id="creer-doc-status-spin" class="creer-doc-spin"></span><span id="creer-doc-status-txt"></span></div>
      <label class="creer-lbl">Description</label>
      <textarea class="creer-inp" placeholder="En quelques phrases, décris ton lieu, sa vision et ses activités…" style="height:90px;resize:none" oninput="cData.desc=this.value">${cData.desc||''}</textarea>
      <label class="creer-lbl">Phase du lieu</label>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:.4rem;margin-bottom:.8rem">
        ${[['idee','💭','Idée'],['conception','📐','Conception'],['chantier','🏗','Chantier'],['operationnel','🌿','Opérationnel']].map(([id,ic,l])=>`<button class="type-btn${cData.phase===id?' sel':''}" onclick="cData.phase='${id}';this.closest('div').querySelectorAll('.type-btn').forEach(b=>b.classList.remove('sel'));this.classList.add('sel')"><div style="font-size:1.1rem;margin-bottom:.2rem">${ic}</div><div>${l}</div></button>`).join('')}
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem">
        <div>
          <label class="creer-lbl">Année de création</label>
          <input class="creer-inp" type="text" placeholder="Ex : 2022" value="${cData.annee||''}" oninput="cData.annee=this.value">
        </div>
        <div>
          <label class="creer-lbl">Surface</label>
          <input class="creer-inp" type="text" placeholder="Ex : 1 200 m²" value="${cData.surface||''}" oninput="cData.surface=this.value">
        </div>
      </div>
      <label class="creer-lbl">Statut juridique</label>
      <select class="creer-inp" onchange="cData.statut=this.value" style="cursor:pointer">
        <option value="">Choisir</option>
        ${STATUTS.map(([v,l])=>`<option value="${v}" ${cData.statut===v?'selected':''}>${l}</option>`).join('')}
      </select>
      <label class="creer-lbl" style="margin-top:.6rem">Contact</label>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:.4rem;margin-bottom:.4rem">
        <input class="creer-inp" type="email" placeholder="📧 Email" value="${cData.email||''}" oninput="cData.email=this.value" style="margin:0">
        <input class="creer-inp" type="tel" placeholder="📞 Téléphone" value="${cData.tel||''}" oninput="cData.tel=this.value" style="margin:0">
      </div>
      <input class="creer-inp" type="url" placeholder="🌐 Site web, https://…" value="${cData.web||''}" oninput="cData.web=this.value">
      `;
  } else if(cStep===2){
    c.innerHTML=`
      <label class="creer-lbl">Les espaces du lieu</label>
      <p style="font-size:.68rem;color:var(--moss);opacity:.7;margin:-.3rem 0 .9rem;line-height:1.5">Décris chaque espace physique de ton lieu, nom, fonctions, capacité.</p>
      <div style="display:flex;justify-content:flex-end;margin-bottom:.6rem">
        <button class="btn btn-ghost" style="font-size:0.65rem;padding:0.25rem 0.65rem" onclick="creerOpenEspaceModal(null)">+ Ajouter un espace</button>
      </div>
      <div id="creer-espace-list">
        <div id="creer-espace-empty" style="padding:1rem;text-align:center;font-size:.72rem;color:var(--moss);opacity:.5;border:1px dashed rgba(46,102,66,.2);border-radius:var(--r)">Aucun espace ajouté, clique sur "+ Ajouter un espace"</div>
      </div>`;
    creerRenderEspaces();
  } else if(cStep===3){
    // Temps d'attente : Deva « cherche » les solutions dans la bibliothèque
    // avant de les révéler (rejoué à chaque clic sur « Générer les solutions »).
    if(!cData._solsReady){
      renderDevaSearching(c);
      // (le bouton d'enregistrement est déjà masqué par _creerMajNav)
      if(!window._creerSolGenerating){
        window._creerSolGenerating = true;
        setTimeout(()=>{
          window._creerSolGenerating = false;
          clearInterval(window._creerSolMsgTimer);
          cData._solsReady = true;
          if(cStep===3) renderStep();   // révèle les solutions (si toujours à l'étape)
        }, 2300);
      }
      return;
    }
    const FN_TO_ESPS={cuisine:'cuisine',cafe:'cafe',cantine:'cafe',coworking:'bureau',reunion:'bureau',atelier:'atelier',fablab:'fablab',scene:'salle',expo:'salle',boutique:'boutique',biblio:'salle',formation:'salle',jardin:'jardin',serre:'serre',compost:'jardin',hebergement:'dortoir',sport:'salle',meditation:'salle',stockage:'bureau',autre:'cafe',elec_gestion:'dortoir',renouv_prod:'dortoir',therm_gestion:'dortoir',eau_gestion:'serre',ecoconstruct:'atelier',dechets_gestion:'jardin',mobilite:'bureau',gouvernance:'bureau',numerique:'bureau'};
    const espItems=cData.espacesData.length>0
      ? cData.espacesData.map((esp,i)=>{
          const fnId=esp.fonctions[0];
          const fn=FONCTIONS_ESPACE.find(f=>f.id===fnId);
          const eid=FN_TO_ESPS[fnId]||'cafe';
          const style=MM_DOMAINE_STYLE[fn?.domaine]||MM_DOMAINE_STYLE.Autre;
          return{esp,eid,ic:fn?.ic||'📦',c:style.c,bg:style.bg};
        })
      : [{esp:{nom:'Mon lieu'},eid:'cafe',ic:'🏡',c:'#4a8c5c',bg:'rgba(74,140,92,.1)'}];
    const uniqueEids=[...new Set(espItems.map(x=>x.eid))];
    const allPicked=devaPickSols(uniqueEids);
    const byEid={};
    uniqueEids.forEach(eid=>byEid[eid]=[]);
    allPicked.forEach(({sol,eid})=>{if(byEid[eid])byEid[eid].push(sol);});
    const circLinks=computeCircularLinks(cData.espacesData);

    // Expose espItems so creerBddPanelHTML can resolve eid per espace
    window._creerEspItems = espItems;

    // Deva pré-sélectionne les solutions. On régénère si les espaces ou leurs
    // problématiques ont changé depuis la dernière présélection (ou si elle
    // vient d'un ancien brouillon), sauf si l'utilisateur a modifié les
    // solutions à la main : dans ce cas son choix prime.
    const _solsFp=JSON.stringify(espItems.map(({esp})=>[(esp&&esp.nom)||'',(esp&&esp.fonctions&&esp.fonctions[0])||'',(esp&&esp.probleme)||'']));
    if(!cData.solsByEspace || Object.keys(cData.solsByEspace).length===0
       || (!cData._solsCustomized && cData._solsFingerprint!==_solsFp)){
      cData.solsByEspace={};
      cData._problemeSols={};        // solution → problématique qui l'a fait remonter
      const _seenSols=new Set();   // une solution n'est proposée qu'une seule fois
      const _CAP=3;                // on ne propose pas trop de solutions par espace
      espItems.forEach(({eid,esp},idx)=>{
        const meta=ESPS.find(e=>e.id===eid);
        const base=(meta?.sols||[]);
        const _prob=(esp&&esp.probleme)||'';
        // Quand une problématique est déclarée, elle PILOTE la sélection : les solutions
        // de la BDD qui y répondent passent en tête (et sont taguées 🎯).
        let ordered=base;
        if(_prob && typeof solutionsForProbleme==='function'){
          const matched=solutionsForProbleme(_prob,{lieux:[cData.type],limit:6});
          matched.forEach(n=>{ cData._problemeSols[n]=_prob; });
          ordered=[...matched, ...base.filter(n=>!matched.includes(n))];
        }
        // dédup global + limite
        const chosen=[];
        for(const n of ordered){
          if(chosen.length>=_CAP) break;
          if(!_seenSols.has(n)){ chosen.push(n); _seenSols.add(n); }
        }
        // Deva garantit les 3 capitaux : au moins une solution écologique,
        // sociale et économie locale par espace (indicateurs des 3 catégories).
        CAPITAUX_ORDRE.forEach(cap => _devaEnsureCapital(chosen, cap, idx));
        cData.solsByEspace[idx]=chosen;
      });
      cData._solsFingerprint=_solsFp;
      cData._capsEnsured=true;
      cData.solutions=[...new Set(Object.values(cData.solsByEspace).flat())];
      // La présélection ajoute des solutions APRÈS le 1er calcul de jauge :
      // on recalcule pour que la Vadance projetée = celle de la fiche publiée.
      if (typeof creerUpdateVadance === 'function') creerUpdateVadance();
    }

    // Rattrapage (une fois par fiche) : les sélections déjà en place, brouillons
    // d'avant la garantie des 3 capitaux, reçoivent aussi leur complément.
    if (!cData._capsEnsured) {
      espItems.forEach((_, idx) => {
        const chosen = cData.solsByEspace[idx] || (cData.solsByEspace[idx] = []);
        CAPITAUX_ORDRE.forEach(cap => _devaEnsureCapital(chosen, cap, idx));
      });
      cData._capsEnsured = true;
      cData.solutions = [...new Set(Object.values(cData.solsByEspace).flat())];
      if (typeof creerUpdateVadance === 'function') creerUpdateVadance();
    }

    const totalSols=cData.solutions.length;
    const totalEsps=espItems.length;

    // Build per-espace blocks
    const espacesHTML=espItems.map(({esp,eid,ic,c:col,bg},idx)=>{
      const assigned=(cData.solsByEspace&&cData.solsByEspace[idx])||[];
      const isOpen=window._activeEspacePanel===idx;
      const nbAvail=SOLS.filter(s=>!assigned.includes(s.nom)).length;

      // Chips des solutions sélectionnées par Deva (modifiables)
      const assignedChips=assigned.length
        ? assigned.map(nom=>{
            const safeNom=nom.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
            return '<span style="display:inline-flex;align-items:center;gap:0;border-radius:100px;background:'+bg+';border:1.5px solid '+col+'55;font-size:.65rem;font-weight:600;color:'+col+';margin:.15rem;overflow:hidden">'
              // Nom cliquable → fiche solution
              +'<span onclick="creerOpenSolDetail(\''+safeNom+'\')" title="Voir la fiche" style="padding:.22rem .45rem .22rem .6rem;cursor:pointer;display:flex;align-items:center;gap:.28rem">'
              +((cData._problemeSols&&cData._problemeSols[nom])?'<span title="Proposée pour ta problématique : '+String(cData._problemeSols[nom]).replace(/[<>"]/g,'')+'" style="font-size:.62rem">🎯</span>':'')
              +'<span>'+nom+'</span>'
              +'<span style="font-size:.58rem;opacity:.55">↗</span>'
              +'</span>'
              // Séparateur
              +'<span style="width:1px;height:16px;background:'+col+'33;flex-shrink:0"></span>'
              // Bouton retirer
              +'<button onclick="creerRemoveSol('+idx+',\''+safeNom+'\')" title="Retirer" style="border:none;background:none;color:'+col+';cursor:pointer;font-size:.72rem;line-height:1;padding:.22rem .5rem;opacity:.55;transition:opacity .15s" onmouseover="this.style.opacity=\'1\'" onmouseout="this.style.opacity=\'.55\'">✕</button>'
              +'</span>';
          }).join('')
        : '<span style="font-size:.65rem;color:var(--moss);opacity:.4;font-style:italic">Aucune solution</span>';

      // Sous-titre du header
      const subTxt = assigned.length
        ? assigned.length+' solution'+(assigned.length!==1?'s':'')+' proposée'+(assigned.length!==1?'s':'')
        : 'Aucune solution proposée';

      // Panneau "ajouter d'autres solutions" (sans filtres)
      const bddPanelHTML=isOpen
        ? '<div style="padding:.55rem .75rem .75rem;background:rgba(46,102,66,.03);border-top:1px solid rgba(46,102,66,.1)">'
            +'<div style="font-size:.6rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em;margin-bottom:.4rem">Bibliothèque · ajouter une solution</div>'
            +'<div id="creer-bdd-panel-'+idx+'" style="max-height:200px;overflow-y:auto">'
            +creerBddPanelHTML(idx)
            +'</div>'
          +'</div>'
        : '';

      return '<div class="creer-esp-block">'
        +'<div class="creer-esp-header" onclick="creerToggleEspacePanel('+idx+')" style="cursor:default">'
        +'<span style="font-size:1rem">'+ic+'</span>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:.75rem;font-weight:700;color:var(--ink)">'+esp.nom+'</div>'
        +'<div style="font-size:.6rem;color:var(--forest);opacity:.85">'+subTxt+'</div>'
        +'</div>'
        +'</div>'
        // Chips des solutions sélectionnées
        +'<div style="padding:.5rem .75rem .6rem;background:white;display:flex;flex-wrap:wrap;align-items:center;gap:0;border-bottom:1px solid rgba(46,102,66,.07)">'
        +assignedChips
        +'</div>'
        +bddPanelHTML
        +(isOpen?'':'<div style="padding:.32rem .75rem .45rem;background:white">'
            +'<button onclick="creerToggleEspacePanel('+idx+')" style="font-size:.63rem;color:var(--moss);background:none;border:none;padding:0;cursor:pointer;font-family:inherit;opacity:.65">+ Ajouter une solution depuis la bibliothèque</button>'
            +'</div>')
        +'</div>';
    }).join('');

    // Synergies section
    let synergiesHTML='';
    if(circLinks.length){
      const synRows=circLinks.map(function(link){
        const from=link.from, to=link.to, fluxIds=link.fluxIds;
        const fromFn=FONCTIONS_ESPACE.find(f=>f.id===from.fonctions[0]);
        const toFn=FONCTIONS_ESPACE.find(f=>f.id===to.fonctions[0]);
        const chips=fluxIds.map(function(fid){
          const f=FLUX_CATALOG.find(x=>x.id===fid);
          return f?'<span style="display:inline-flex;align-items:center;gap:.2rem;padding:.15rem .45rem;border-radius:100px;font-size:.6rem;font-weight:600;background:rgba(46,153,112,.15);color:#2e9970;border:1px solid rgba(46,153,112,.3)">'+f.ic+' '+f.label+'</span>':'';
        }).join('');
        return '<div style="display:flex;align-items:center;flex-wrap:wrap;gap:.4rem;padding:.35rem .5rem;background:rgba(255,255,255,.45);border-radius:calc(var(--r) - 2px);margin-bottom:.3rem;font-size:.68rem">'
          +'<span style="font-weight:600;color:var(--ink)">'+(fromFn?fromFn.ic:'📦')+' '+from.nom+'</span>'
          +'<span style="color:#2e9970;font-size:.75rem">→</span>'
          +chips
          +'<span style="color:#2e9970;font-size:.75rem">→</span>'
          +'<span style="font-weight:600;color:var(--ink)">'+(toFn?toFn.ic:'📦')+' '+to.nom+'</span>'
          +'</div>';
      }).join('');
      synergiesHTML='<div style="background:linear-gradient(135deg,rgba(46,153,112,.08),rgba(26,96,64,.04));border:1px solid rgba(46,153,112,.25);border-radius:var(--r);padding:.65rem .8rem;margin-top:.75rem">'
        +'<div style="font-size:.6rem;font-weight:700;color:#2e9970;letter-spacing:.08em;text-transform:uppercase;margin-bottom:.45rem">🔄 Économie circulaire · '+circLinks.length+' synergie'+(circLinks.length>1?'s':'')+' détectée'+(circLinks.length>1?'s':'')+'</div>'
        +synRows
        +'</div>';
    }

    // ── Sidebar : flux guidé espace par espace ──
    c.innerHTML = creerStep3SidebarHTML();
    _creerQuetesLoadingRun();

    genMM(espItems);
    mmDrawCircularLinks(espItems, circLinks);
    renderFluxTable();
    if (typeof _creerMajBoutonVueMap === 'function') _creerMajBoutonVueMap();
    // Focalise le mind map sur l'espace actif une fois l'animation d'apparition posée.
    if (window._creerMapFocusT) clearTimeout(window._creerMapFocusT);
    window._creerMapFocusT = setTimeout(function(){ try { creerApplyMapFocus(); } catch(e){} }, Math.min(1700, 550 + espItems.length * 230 + 400));
  }
}
window._solFilter = window._solFilter || {cat:'tous', q:''};
window._activeEspacePanel = window._activeEspacePanel !== undefined ? window._activeEspacePanel : null;
window._creerStep3Tab = window._creerStep3Tab || 'solutions';
window._creerActiveEsp = (window._creerActiveEsp !== undefined) ? window._creerActiveEsp : 0;
window._creerPhase = window._creerPhase || 'espaces';

/* ───────────────────────────────────────────────────────────────────────────
   Étape 3, flux guidé « espace par espace »
   Boutons d'espace en haut ; en cliquant sur un espace, on ne voit que ses
   solutions / quêtes / indicateurs et le mind map zoome dessus ; « Valider cet
   espace » coche l'espace et bascule sur le suivant.
   ─────────────────────────────────────────────────────────────────────────── */
function creerStep3SidebarHTML(){
  const espItems = window._creerEspItems || [];
  if (!espItems.length) return '<div style="padding:1rem;font-size:.72rem;color:var(--moss)">Aucun espace défini, reviens à l\'étape précédente pour en ajouter.</div>';
  let active = window._creerActiveEsp;
  if (active == null || active < 0 || active >= espItems.length) active = 0;
  window._creerActiveEsp = active;
  const valides = cData.espacesValides || (cData.espacesValides = []);
  const it = espItems[active];
  const col = it.c || '#2e9970';
  const totalN = espItems.length;
  // Visiter (afficher) un espace le marque d'une coche ✓ : garantit que
  // l'utilisateur passe sur tous les espaces avant de générer les quêtes.
  if (window._creerPhase !== 'quetes' && valides.indexOf(active) < 0) valides.push(active);
  const allDone = valides.length >= totalN;

  // 1. Boutons d'espace — une seule ligne, défilement horizontal.
  let btns = '<div style="display:flex;flex-wrap:nowrap;gap:.4rem;margin-bottom:.85rem;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:thin;padding-bottom:.3rem">';
  espItems.forEach((e, i) => {
    const on = i === active, done = valides.indexOf(i) >= 0;
    const c2 = e.c || '#2e9970';
    // À l'étape quêtes, l'onglet FILTRE les quêtes par espace (creerSelectEsp) ;
    // à l'étape solutions, il focalise l'édition de l'espace (creerFocusEsp).
    btns += '<button onclick="creerSelectEsp(' + i + ')" style="flex-shrink:0;white-space:nowrap;display:inline-flex;align-items:center;gap:.32rem;font-size:.66rem;font-weight:700;font-family:inherit;padding:.42rem .7rem;border-radius:100px;cursor:pointer;border:1.5px solid ' + c2 + ';background:' + (on ? c2 : (done ? c2 + '1f' : 'white')) + ';color:' + (on ? '#fff' : c2) + ';transition:all .15s">'
      + (done ? '<span style="font-size:.72rem">✓</span>' : '')
      + '<span style="font-size:.82rem">' + (e.ic || '📦') + '</span>'
      + '<span>' + ((e.esp && e.esp.nom) || ('Espace ' + (i + 1))) + '</span>'
      + '</button>';
  });
  btns += '</div>';

  // Titre d'étape (comme « Les espaces du lieu »), selon la phase.
  const _t = (window._creerPhase === 'quetes')
    ? { l: 'Les quêtes du lieu', s: 'Choisis les quêtes ou crée les tiennes.' }
    : { l: 'Les solutions du lieu', s: 'Choisis les solutions et vérifie les indicateurs de chaque espace.' };
  const titre = '<label class="creer-lbl">' + _t.l + '</label>'
    + '<p style="font-size:.68rem;color:var(--moss);opacity:.7;margin:-.3rem 0 .9rem;line-height:1.5">' + _t.s + '</p>';

  // 2. En-tête de l'espace actif
  const head = '<div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.6rem">'
    + '<span style="font-size:1.15rem">' + (it.ic || '📦') + '</span>'
    + '<div style="font-size:.92rem;font-weight:800;color:var(--ink)">' + ((it.esp && it.esp.nom) || ('Espace ' + (active + 1))) + '</div>'
    + '<span style="margin-left:auto;font-size:.6rem;font-weight:700;color:' + col + ';background:' + col + '1f;padding:.12rem .5rem;border-radius:100px">' + (active + 1) + '/' + totalN + '</span>'
    + '</div>';

  // 3. Sections
  const secTitle = (ic, txt, c) => '<div style="font-size:.64rem;font-weight:800;color:' + c + ';text-transform:uppercase;letter-spacing:.06em;margin:.9rem 0 .5rem">' + ic + ' ' + txt + '</div>';

  // Phase QUÊTES : temps de chargement Deva, puis les quêtes proposées.
  if (window._creerPhase === 'quetes') {
    if (!window._creerQuetesReady) return titre + btns + creerQuetesLoadingHTML();
    return titre + btns + creerQuetesPhaseHTML();
  }

  // 4. Navigation d'espace : aller au prochain non visité. Une fois tous les
  //    espaces parcourus, le bouton « Générer les quêtes » est dans la barre du bas.
  let _next = -1;
  for (let k = 1; k <= totalN; k++) { const j = (active + k) % totalN; if (valides.indexOf(j) < 0) { _next = j; break; } }
  const navBtn = (_next >= 0)
    ? '<button onclick="creerFocusEsp(' + _next + ')" style="width:100%;margin-top:1rem;padding:.72rem;border:none;border-radius:100px;background:var(--forest);color:#fff;font-family:inherit;font-size:.8rem;font-weight:800;cursor:pointer">Aller à l\'espace suivant →</button>'
    : '<div style="margin-top:1rem;text-align:center;font-size:.66rem;color:var(--fern);font-weight:700;line-height:1.5">✓ Tous les espaces sont passés en revue.<br>Génère les quêtes en bas 👇</div>';

  // Potentiel économique : affiché ICI, au moment de choisir solutions &
  // indicateurs (le coût des solutions retenues nourrit le point mort).
  const rentaLieu = (typeof evadLieuRentabiliteHTML === 'function') ? evadLieuRentabiliteHTML(cData) : '';
  const espaceEco = (typeof evadEspaceEcoHTML === 'function') ? evadEspaceEcoHTML(it.esp, active, cData) : '';

  return titre + btns
    + '<div style="background:' + col + '0a;border:1px solid ' + col + '26;border-radius:14px;padding:.85rem .9rem">'
    + head
    + secTitle('🧩', 'Solutions', col)
    + creerEspaceSolBlockHTML(active)
    + secTitle('📊', 'Indicateurs', 'var(--sky)')
    + creerEspaceIndicsHTML(active)
    + espaceEco
    + navBtn
    + '</div>'
    // Récap du lieu SOUS le bloc de l'espace (pas au-dessus).
    + '<div style="margin-top:1rem">' + rentaLieu + '</div>';
}

// Écran de chargement « Deva compose tes quêtes » (avant la phase quêtes),
// dans le même esprit que la recherche de solutions/indicateurs.
function creerQuetesLoadingHTML(){
  return '<div id="creer-quetes-loading" style="display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:2.2rem 1rem;min-height:280px;animation:obFadeIn .35s ease">'
    + '<div style="position:relative;width:80px;height:80px;margin-bottom:1.2rem">'
      + '<div style="position:absolute;inset:0;border-radius:50%;background:rgba(200,115,42,.12);animation:pulse 1.8s ease-in-out infinite"></div>'
      + '<div style="position:absolute;inset:5px;border-radius:50%;border:2.5px solid rgba(200,115,42,.2);border-top-color:#c8732a;animation:spin .9s linear infinite"></div>'
      + '<img src="Deva.png" alt="Deva" style="position:absolute;inset:14px;width:52px;height:52px;object-fit:contain;object-position:bottom;transform:scaleX(-1) rotate(12deg);filter:drop-shadow(0 0 8px rgba(200,115,42,.5))">'
    + '</div>'
    + '<div style="font-size:.95rem;font-weight:800;color:var(--ink);margin-bottom:.45rem;font-family:\'Satoshi\',sans-serif">Deva compose tes quêtes</div>'
    + '<div id="creer-quetes-loading-msg" style="font-size:.72rem;color:var(--moss);opacity:.8;min-height:1.1em;transition:opacity .25s">Analyse de tes solutions retenues…</div>'
    + '<div style="display:flex;gap:.32rem;margin-top:1rem">'
      + '<span style="width:7px;height:7px;border-radius:50%;background:#c8732a;animation:typingBounce 1.1s ease-in-out infinite"></span>'
      + '<span style="width:7px;height:7px;border-radius:50%;background:#c8732a;animation:typingBounce 1.1s ease-in-out .18s infinite"></span>'
      + '<span style="width:7px;height:7px;border-radius:50%;background:#c8732a;animation:typingBounce 1.1s ease-in-out .36s infinite"></span>'
    + '</div>'
  + '</div>';
}

// Démarre la rotation des messages et planifie l'affichage des quêtes après le
// temps de chargement. Idempotent : le minuteur n'est planifié qu'une fois.
function _creerQuetesLoadingRun(){
  if (!document.getElementById('creer-quetes-loading') || window._creerQuetesLoadingScheduled) return;
  window._creerQuetesLoadingScheduled = true;
  const msgs = ['Analyse de tes solutions retenues…', 'Croisement avec tes indicateurs…', 'Composition d\'une quête par action…', 'Personnalisation par espace…'];
  let mi = 0;
  clearInterval(window._creerQuetesMsgTimer);
  window._creerQuetesMsgTimer = setInterval(() => {
    const el = document.getElementById('creer-quetes-loading-msg');
    if (!el) { clearInterval(window._creerQuetesMsgTimer); return; }
    mi = (mi + 1) % msgs.length;
    el.style.opacity = '0';
    setTimeout(() => { el.textContent = msgs[mi]; el.style.opacity = '.8'; }, 220);
  }, 850);
  clearTimeout(window._creerQuetesReadyTimer);
  window._creerQuetesReadyTimer = setTimeout(() => {
    clearInterval(window._creerQuetesMsgTimer);
    window._creerQuetesReady = true;
    if (typeof creerRefreshSidebar === 'function') creerRefreshSidebar();
    if (typeof creerApplyMapFocus === 'function') creerApplyMapFocus();
  }, 2100);
}

// Phase finale : quêtes de l'espace ACTIF uniquement (les onglets d'espace
// filtrent la liste, cf. creerSelectEsp).
function creerQuetesPhaseHTML(){
  const espItems = window._creerEspItems || [];
  let active = window._creerActiveEsp;
  if (active == null || active < 0 || active >= espItems.length) active = 0;
  const it = espItems[active] || {};
  const c2 = it.c || '#2e9970';
  let h = '<div style="background:rgba(200,115,42,.06);border:1px solid rgba(200,115,42,.22);border-radius:14px;padding:.85rem .9rem">';
  h += '<div style="display:flex;align-items:center;gap:.4rem;margin:.2rem 0 .6rem"><span style="font-size:.85rem">' + (it.ic || '📦') + '</span><span style="font-size:.66rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:' + c2 + '">' + ((it.esp && it.esp.nom) || ('Espace ' + (active + 1))) + '</span></div>';
  h += creerEspaceQuetesHTML(active);
  h += '<button onclick="creerRevoirEspaces()" style="width:100%;margin-top:1rem;padding:.6rem;border:1.5px solid rgba(46,102,66,.2);border-radius:100px;background:white;color:var(--moss);font-family:inherit;font-size:.74rem;font-weight:700;cursor:pointer">← Revoir les solutions & indicateurs</button>'
    + '<div style="margin-top:.5rem;text-align:center;font-size:.66rem;color:var(--fern);font-weight:600">🎉 Ton lieu est prêt, crée-le en bas 👇</div>'
    + '</div>';
  return h;
}

function creerRevoirEspaces(){
  window._creerPhase = 'espaces';
  window._creerActiveEsp = 0;
  window._creerMapOverview = false;
  if (typeof creerSidePanelClose === 'function') creerSidePanelClose();
  creerRefreshSidebar();
  creerApplyMapFocus();
  _creerMajBoutonVueMap();
  _creerMajStepper();   // stepper → retour à l'étape Solutions
  if (typeof creerUpdateHint === 'function') creerUpdateHint(true);   // bulle Deva : retour au message solutions
}

// Contenu de la vue inline (fiche solution/quête/indicateur ou formulaire de
// création), affichée en extension de la section blanche au lieu d'une modale.
// L'étape 3 (flux guidé) est-elle affichée ? (sinon : fiches en modale classique)
function creerIsGuided(){
  return typeof cStep !== 'undefined' && cStep === 3 && !!document.querySelector('#screen-creer .mm-stage');
}

/* ─── Panneau latéral droit (comme « Nouvel espace ») ───
   Sert à voir une fiche, créer une quête, ou ajouter depuis la bibliothèque.
   Il recouvre la zone du mind map et laisse la colonne de gauche visible. */
function creerEnsureSidePanel(){
  let p = document.getElementById('creer-side-panel');
  if (p) return p;
  const stage = document.querySelector('#screen-creer .mm-stage');
  if (!stage) return null;
  p = document.createElement('div');
  p.id = 'creer-side-panel';
  p.style.cssText = 'display:none;position:absolute;top:0;left:0;bottom:0;width:min(600px,78%);z-index:60;background:var(--paper,#fbfaf7);flex-direction:column;box-shadow:16px 0 48px -16px rgba(14,26,18,.42);border-right:1px solid rgba(46,102,66,.12)';
  p.innerHTML = ''
    + '<div style="padding:1.1rem 1.3rem .9rem;border-bottom:1px solid rgba(46,102,66,.1);display:flex;align-items:center;justify-content:space-between;flex-shrink:0">'
      + '<span id="creer-side-panel-title" style="font-size:.95rem;font-weight:800;color:var(--ink)"></span>'
      + '<button onclick="creerSidePanelClose()" aria-label="Fermer" style="background:rgba(46,102,66,.08);border:none;border-radius:50%;width:30px;height:30px;cursor:pointer;font-size:.85rem;color:var(--moss);display:flex;align-items:center;justify-content:center;font-family:inherit">✕</button>'
    + '</div>'
    + '<div id="creer-side-panel-body" style="flex:1;min-height:0;overflow-y:auto;padding:1.1rem 1.3rem"></div>'
    + '<div id="creer-side-panel-footer" style="display:none;padding:.9rem 1.3rem 1.1rem;border-top:1px solid rgba(46,102,66,.08);gap:.6rem;justify-content:flex-end;flex-shrink:0"></div>';
  stage.appendChild(p);
  return p;
}

function creerSidePanelClose(){
  window._creerPanel = null;
  window._creerSolSearch = ''; window._creerQueteSearch = ''; window._creerIciSearch = '';
  const p = document.getElementById('creer-side-panel'); if (p) p.style.display = 'none';
}

// Ouvre / (re)dessine le panneau selon window._creerPanel = {kind, ref}.
function creerPanelRefresh(){
  const el = creerEnsureSidePanel(); if (!el) return;
  const p = window._creerPanel; if (!p) { creerSidePanelClose(); return; }
  const titleEl = document.getElementById('creer-side-panel-title');
  const bodyEl = document.getElementById('creer-side-panel-body');
  const footEl = document.getElementById('creer-side-panel-footer');
  let title = '', body = '', footer = '', after = null;
  if (p.kind === 'sol-detail') {
    title = 'Fiche solution';
    const s = (typeof SOLS !== 'undefined') ? SOLS.find(x => x.nom === p.ref) : null;
    body = (s && typeof solFicheHTML === 'function') ? solFicheHTML(s, { context: 'modal' }) : '<div style="font-size:.75rem;color:var(--moss)">Fiche indisponible.</div>';
  } else if (p.kind === 'quete-detail') {
    title = 'Fiche quête'; body = '<div id="creer-panel-fiche"></div>';
    after = function(){ const i = (typeof SOLS !== 'undefined') ? SOLS.findIndex(x => x.nom === p.ref) : -1; const t = document.getElementById('creer-panel-fiche'); if (i >= 0 && t && typeof bddQueteDetailByIdx === 'function') bddQueteDetailByIdx(i, t); };
  } else if (p.kind === 'ici-detail') {
    title = 'Fiche indicateur'; body = '<div id="creer-panel-fiche"></div>';
    after = function(){ const t = document.getElementById('creer-panel-fiche'); if (t && typeof bddIciDetail === 'function') bddIciDetail(p.ref, t); };
  } else if (p.kind === 'creer') {
    title = 'Nouvelle quête'; body = creerQueteFormPanelHTML();
    footer = '<button onclick="creerSidePanelClose()" style="background:rgba(46,102,66,.06);border:none;border-radius:100px;padding:.55rem 1.1rem;font-size:.78rem;font-weight:700;color:var(--moss);cursor:pointer;font-family:inherit">Annuler</button>'
      + '<button onclick="creerQuetePanelSave()" style="background:var(--forest);color:#fff;border:none;border-radius:100px;padding:.55rem 1.3rem;font-size:.78rem;font-weight:700;cursor:pointer;font-family:inherit">Créer la quête</button>';
  } else if (p.kind === 'biblio-sol') {
    title = 'Ajouter une solution'; body = creerBddPanelHTML(p.ref);
  } else if (p.kind === 'biblio-quete') {
    title = 'Ajouter une quête'; body = creerQueteBiblioPanelBody(p.ref);
  } else if (p.kind === 'biblio-ici') {
    title = 'Ajouter un indicateur'; body = creerIciBiblioPanelBody(p.ref);
  }
  titleEl.textContent = title;
  bodyEl.innerHTML = body; bodyEl.scrollTop = 0;
  if (footer) { footEl.innerHTML = footer; footEl.style.display = 'flex'; } else { footEl.style.display = 'none'; footEl.innerHTML = ''; }
  el.style.display = 'flex';
  if (after) after();
}

function creerOpenPanel(kind, ref){ window._creerPanel = { kind: kind, ref: ref }; creerPanelRefresh(); }

// Formulaire de création de quête (champs seuls ; boutons dans le pied du panneau).
// Mêmes ids que la modale → réutilise piloteQueteCreerSave.
function creerQueteFormPanelHTML(){
  const inS = 'width:100%;box-sizing:border-box;padding:.55rem .7rem;border-radius:8px;border:1px solid rgba(46,102,66,.2);font-family:inherit;font-size:.8rem;color:var(--ink);background:#fff';
  const lbS = 'display:block;font-size:.7rem;font-weight:700;color:var(--moss);margin:.75rem 0 .3rem';
  const comp = ['Aucune en particulier','💧 Gestion de l\'eau','⚡ Énergie','🧱 Éco-construction','🌾 Maraîchage & permaculture','♻️ Réemploi & compostage','🌿 Biodiversité','🤝 Animation & facilitation','🌡 Adaptation climatique','🔧 Autre / polyvalent'];
  const icisChips = (typeof ICI_CATALOG !== 'undefined' ? ICI_CATALOG : []).map(function(ici){ var m = ((typeof ICI_LIVRE_META !== 'undefined') ? ICI_LIVRE_META[ici.livre] : null) || {ic:'◆', col:'#4a8c5c'}; return '<button type="button" data-ici="' + ici.id + '" data-col="' + m.col + '" data-sel="0" onclick="pqCreerToggleIci(this)" style="font-size:.66rem;font-weight:600;color:' + m.col + ';background:transparent;border:1px solid ' + m.col + '55;border-radius:100px;padding:.28rem .6rem;cursor:pointer;font-family:inherit">' + m.ic + ' ' + ici.nom + '</button>'; }).join('');
  return ''
    + '<label style="' + lbS + '" for="pq-create-titre">Titre de la quête *</label>'
    + '<input id="pq-create-titre" style="' + inS + '" placeholder="Ex : Planter la haie champêtre du verger">'
    + '<label style="' + lbS + '" for="pq-create-desc">📝 Description</label>'
    + '<textarea id="pq-create-desc" rows="2" style="' + inS + ';resize:vertical" placeholder="L\'action concrète à réaliser sur le lieu…"></textarea>'
    + '<div style="display:flex;gap:.6rem"><div style="flex:1"><label style="' + lbS + '" for="pq-create-duree">Durée</label><input id="pq-create-duree" style="' + inS + '" placeholder="1 journée"></div><div style="flex:1"><label style="' + lbS + '" for="pq-create-nb">Participants</label><input id="pq-create-nb" style="' + inS + '" placeholder="2–4 pers."></div></div>'
    + '<div style="display:flex;gap:.6rem"><div style="flex:1"><label style="' + lbS + '" for="pq-create-graines">🌱 Graines</label><input id="pq-create-graines" type="number" min="0" style="' + inS + '" placeholder="50"></div><div style="flex:1"><label style="' + lbS + '" for="pq-create-date">📅 Date</label><input id="pq-create-date" type="date" style="' + inS + '"></div></div>'
    + '<label style="' + lbS + '" for="pq-create-competence">🎯 Compétence nécessaire</label>'
    + '<select id="pq-create-competence" style="' + inS + '">' + comp.map(function(o){ return '<option>' + o + '</option>'; }).join('') + '</select>'
    + '<label style="' + lbS + '" for="pq-create-impact">🌿 Impact visé (facultatif)</label>'
    + '<input id="pq-create-impact" style="' + inS + '" placeholder="Ex : +8 pts eau · 200 m de haie">'
    + '<label style="' + lbS + '" for="pq-create-materiel">🧰 Matériel <span style="font-weight:400;opacity:.7">(un par ligne)</span></label>'
    + '<textarea id="pq-create-materiel" rows="3" style="' + inS + ';resize:vertical" placeholder="Bêche&#10;Plants d\'arbustes locaux&#10;Paillage"></textarea>'
    + '<label style="' + lbS + '" for="pq-create-etapes">🪜 Étapes <span style="font-weight:400;opacity:.7">(une par ligne)</span></label>'
    + '<textarea id="pq-create-etapes" rows="3" style="' + inS + ';resize:vertical" placeholder="Préparer le terrain&#10;Planter&#10;Pailler et arroser"></textarea>'
    + '<label style="' + lbS + '" for="pq-create-preuve">✅ Preuve pour valider la quête</label>'
    + '<textarea id="pq-create-preuve" rows="2" style="' + inS + ';resize:vertical">Photos de l\'action réalisée + indicateurs mesurés.</textarea>'
    + '<label style="' + lbS + '">📊 Indicateurs validés par la preuve</label>'
    + '<div id="pq-create-icis" style="display:flex;flex-wrap:wrap;gap:.3rem;margin-top:.1rem">' + icisChips + '</div>'
    + '<div id="pq-create-hint" style="font-size:.7rem;color:var(--terracotta);margin-top:.45rem;min-height:1rem"></div>';
}

function creerQuetePanelSave(){
  const ok = (typeof piloteQueteCreerSave === 'function') ? piloteQueteCreerSave() : false;
  if (ok === false) return;   // validation échouée : on garde le formulaire ouvert
  creerSidePanelClose();
  creerRefreshSidebar();
  if (typeof creerMapRevealRefresh === 'function') creerMapRevealRefresh();
}

// Corps du panneau « ajouter une quête » : recherche + tri par catégorie.
function creerQueteBiblioPanelBody(idx){
  const retir = new Set(cData.quetesRetirees || []);
  const shown = new Set();
  (cData.solutions || []).forEach(nom => { const s = (typeof SOLS !== 'undefined') ? SOLS.find(x => x.nom === nom) : null; if (s && s.quete && !retir.has('sol:' + nom)) shown.add(nom); });
  (cData.quetesAjoutees || []).forEach(nom => { if (!retir.has('sol:' + nom)) shown.add(nom); });
  const searchRaw = window._creerQueteSearch || '', search = searchRaw.toLowerCase().trim();
  let dispo = (typeof SOLS !== 'undefined') ? SOLS.filter(s => s.quete && !shown.has(s.nom)) : [];
  if (search) dispo = dispo.filter(s => ((((s.quete && s.quete.titre) || '') + ' ' + s.nom).toLowerCase().indexOf(search) >= 0));
  const rowFor = (s) => { const safeNom = String(s.nom).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return '<div style="display:flex;align-items:center;gap:.55rem;padding:.45rem .6rem;border-radius:.6rem;background:rgba(46,102,66,.03);border:1px solid rgba(46,102,66,.08);margin-bottom:.3rem">'
      + '<span style="font-size:1rem;flex-shrink:0">' + (s.img || '⚡') + '</span>'
      + '<div style="flex:1;min-width:0"><div style="font-size:.76rem;font-weight:600;color:var(--ink)">' + ((s.quete && s.quete.titre) || s.nom) + '</div><div style="font-size:.62rem;color:var(--moss);opacity:.65">issue de « ' + s.nom + ' »</div></div>'
      + '<button onclick="creerOpenPanel(\'quete-detail\',\'' + safeNom + '\')" style="flex-shrink:0;padding:.3rem .5rem;border-radius:.45rem;border:1.5px solid rgba(46,102,66,.2);background:transparent;color:var(--forest);font-size:.66rem;cursor:pointer">👁</button>'
      + '<button onclick="creerAddQuete(\'' + safeNom + '\',' + idx + ')" style="flex-shrink:0;padding:.3rem .65rem;border-radius:.45rem;border:none;background:var(--forest);color:white;font-size:.66rem;font-weight:700;cursor:pointer">+ Ajouter</button>'
    + '</div>';
  };
  let h = '<input id="pq-bdd-search" type="text" value="' + searchRaw.replace(/"/g,'&quot;') + '" oninput="creerQueteSearchInput(this.value)" placeholder="🔍 Rechercher une quête…" style="width:100%;box-sizing:border-box;padding:.5rem .7rem;margin-bottom:.6rem;border:1.5px solid rgba(46,102,66,.2);border-radius:8px;font-size:.78rem;font-family:inherit;background:#f6faf7;outline:none">';
  if (!dispo.length) { h += '<div style="padding:.6rem;text-align:center;font-size:.72rem;color:var(--moss);opacity:.45;font-style:italic">' + (search ? 'Aucune quête ne correspond' : 'Toutes les quêtes sont déjà présentes') + '</div>'; return h; }
  const catMeta = (typeof CAT_META !== 'undefined') ? CAT_META : {}, catOrder = Object.keys(catMeta);
  catOrder.forEach(cat => { const grp = dispo.filter(s => s.cat === cat); if (!grp.length) return; const cm = catMeta[cat] || {ic:'', l:cat, c:'#666'};
    h += '<div style="font-size:.62rem;font-weight:700;color:' + cm.c + ';text-transform:uppercase;letter-spacing:.07em;margin:.6rem 0 .35rem;display:flex;align-items:center;gap:.3rem"><span>' + cm.ic + '</span><span>' + cm.l + '</span></div>';
    grp.forEach(s => { h += rowFor(s); });
  });
  const rest = dispo.filter(s => catOrder.indexOf(s.cat) < 0);
  if (rest.length) { h += '<div style="font-size:.62rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em;margin:.6rem 0 .35rem">Autres</div>'; rest.forEach(s => { h += rowFor(s); }); }
  return h;
}

// Corps du panneau « ajouter un indicateur » : recherche + tri par capital.
function creerIciBiblioPanelBody(idx){
  if (typeof ICI_CATALOG === 'undefined') return '';
  const retir = new Set(cData.icisRetires || []);
  // Toute la bibliothèque d'indicateurs ; on exclut seulement ceux déjà présents
  // dans CET espace (dérivés de ses solutions ou ajoutés à lui).
  const shown = new Set();
  ((cData.solsByEspace && cData.solsByEspace[idx]) || []).forEach(nom => { (typeof iciPourSolution === 'function' ? (iciPourSolution(nom) || []) : []).forEach(i => { if (!retir.has(i.id)) shown.add(i.id); }); });
  const _espMap = cData.icisEspMap || {};
  (cData.icisAjoutes || []).forEach(id => { if (_espMap[id] === idx && !retir.has(id)) shown.add(id); });
  const searchRaw = window._creerIciSearch || '', search = searchRaw.toLowerCase().trim();
  let dispo = ICI_CATALOG.filter(i => !shown.has(i.id));
  if (search) dispo = dispo.filter(i => ((i.nom + ' ' + (i.unite || '')).toLowerCase().indexOf(search) >= 0));
  const rowFor = (ici) =>
    '<div style="display:flex;align-items:center;gap:.55rem;padding:.45rem .6rem;border-radius:.6rem;background:rgba(46,102,66,.03);border:1px solid rgba(46,102,66,.08);margin-bottom:.3rem">'
    + '<div style="flex:1;min-width:0"><div style="font-size:.76rem;font-weight:600;color:var(--ink)">' + ici.nom + '</div><div style="font-size:.62rem;color:var(--moss);opacity:.65">' + (ici.unite || '') + '</div></div>'
    + '<button onclick="creerOpenPanel(\'ici-detail\',\'' + ici.id + '\')" style="flex-shrink:0;padding:.3rem .5rem;border-radius:.45rem;border:1.5px solid rgba(46,102,66,.2);background:transparent;color:var(--forest);font-size:.66rem;cursor:pointer">👁</button>'
    + '<button onclick="creerAddIci(\'' + ici.id + '\',' + idx + ')" style="flex-shrink:0;padding:.3rem .65rem;border-radius:.45rem;border:none;background:var(--forest);color:white;font-size:.66rem;font-weight:700;cursor:pointer">+ Ajouter</button>'
    + '</div>';
  let h = '<input id="pq-ici-search" type="text" value="' + searchRaw.replace(/"/g,'&quot;') + '" oninput="creerIciSearchInput(this.value)" placeholder="🔍 Rechercher un indicateur…" style="width:100%;box-sizing:border-box;padding:.5rem .7rem;margin-bottom:.6rem;border:1.5px solid rgba(46,102,66,.2);border-radius:8px;font-size:.78rem;font-family:inherit;background:#f6faf7;outline:none">';
  if (!dispo.length) { h += '<div style="padding:.6rem;text-align:center;font-size:.72rem;color:var(--moss);opacity:.45;font-style:italic">' + (search ? 'Aucun indicateur ne correspond' : 'Tous les indicateurs sont déjà présents') + '</div>'; return h; }
  ['ecologie','social','economie_locale'].forEach(livre => {
    const grp = dispo.filter(i => i.livre === livre); if (!grp.length) return;
    const meta = (typeof ICI_LIVRE_META !== 'undefined' && ICI_LIVRE_META[livre]) || { label: livre, ic:'◆', col:'#4a8c5c' };
    h += '<div style="font-size:.62rem;font-weight:700;color:' + meta.col + ';text-transform:uppercase;letter-spacing:.07em;margin:.6rem 0 .35rem;display:flex;align-items:center;gap:.3rem"><span>' + meta.ic + '</span><span>' + meta.label + '</span></div>';
    grp.forEach(i => { h += rowFor(i); });
  });
  return h;
}

// Les 3 capitaux (livres ICI) : ordre + sous-titre de section.
const CAPITAUX_ORDRE = ['ecologie', 'social', 'economie_locale'];
function _capMeta(livre){ return (typeof ICI_LIVRE_META !== 'undefined' && ICI_LIVRE_META[livre]) || { label: livre, ic: '◆', col: '#4a8c5c' }; }
function _capSousTitre(livre){
  const m = _capMeta(livre);
  return '<div style="display:flex;align-items:center;gap:.32rem;margin:.55rem 0 .32rem"><span style="font-size:.72rem">' + m.ic + '</span><span style="font-size:.55rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:' + m.col + '">' + m.label + '</span></div>';
}
// Capital d'une solution. Les catégories purement environnementales forcent
// l'écologie (une mare reste écologique même si ses chantiers mobilisent des
// bénévoles) ; sinon, capital majoritaire des indicateurs portés.
const _CATS_ECOLOGIE = ['eau', 'electricite', 'biodiversite', 'adaptation'];
function _solCapital(nom){
  const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === nom) : null;
  if (sol && _CATS_ECOLOGIE.includes(sol.cat)) return 'ecologie';
  const icis = (typeof iciPourSolution === 'function') ? (iciPourSolution(nom) || []) : [];
  const c = { ecologie: 0, social: 0, economie_locale: 0 };
  icis.forEach(i => { if (c[i.livre] != null) c[i.livre]++; });
  let best = 'ecologie', bestN = -1;
  CAPITAUX_ORDRE.forEach(k => { if (c[k] > bestN) { bestN = c[k]; best = k; } });
  return best;
}

// Solutions transversales que Deva peut proposer pour couvrir un capital manquant.
const DEVA_CAPITAL_POOL = {
  ecologie: ['Compostage partagé', 'Jardin permaculture', 'Récupération eau de pluie', 'Haie champêtre'],
  social: ['Atelier de transmission', 'Chantier participatif'],
  economie_locale: ['Approvisionnement local', 'Recyclerie & réemploi local', 'AMAP circuit court'],
};
// Garantit au moins une solution du capital `livre` dans la sélection d'un espace.
function _devaEnsureCapital(chosen, livre, idx){
  if (chosen.some(n => _solCapital(n) === livre)) return;
  const pool = DEVA_CAPITAL_POOL[livre] || [];
  const start = pool.length ? ((idx || 0) % pool.length) : 0;
  for (let k = 0; k < pool.length; k++) {
    const nom = pool[(start + k) % pool.length];
    if ((typeof SOLS !== 'undefined') && SOLS.find(s => s.nom === nom) && !chosen.includes(nom)) { chosen.push(nom); return; }
  }
  // Repli : le pool est absent du catalogue (ex. base pas encore migrée) →
  // n'importe quelle solution du catalogue dont le capital dominant correspond.
  if (typeof SOLS !== 'undefined') {
    const cand = SOLS.find(s => !chosen.includes(s.nom) && _solCapital(s.nom) === livre);
    if (cand) chosen.push(cand.nom);
  }
}

// Bloc solutions d'un espace : liste simple de cartes (sans classement par
// capital, réservé aux indicateurs) + ajout depuis la bibliothèque.
function creerEspaceSolBlockHTML(idx){
  const espItems = window._creerEspItems || [];
  const it = espItems[idx] || {};
  const col = it.c || '#2e9970';
  const assigned = (cData.solsByEspace && cData.solsByEspace[idx]) || [];
  const solCard = (nom) => {
    const safeNom = nom.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === nom) : null;
    const ic = (sol && sol.img) || '🧩';
    const impact = (sol && sol.impact) || '';
    return '<div style="display:flex;align-items:stretch;gap:0;margin-bottom:.3rem">'
      + '<div onclick="creerOpenSolDetail(\'' + safeNom + '\')" title="Voir la fiche" style="flex:1;min-width:0;background:white;border:1px solid ' + col + '22;border-left:3px solid ' + col + ';border-radius:10px 0 0 10px;padding:.45rem .6rem;cursor:pointer">'
        + '<div style="display:flex;align-items:center;gap:.4rem"><span style="font-size:.82rem">' + ic + '</span><span style="font-size:.7rem;font-weight:700;color:var(--ink);line-height:1.2;flex:1">' + nom + '</span><span style="font-size:.58rem;opacity:.5">↗</span></div>'
        + (impact ? '<div style="font-size:.6rem;color:var(--fern);font-weight:600;margin-top:.22rem">🌿 ' + impact + '</div>' : '')
      + '</div>'
      + '<button onclick="creerRemoveSol(' + idx + ',\'' + safeNom + '\')" title="Retirer" style="flex-shrink:0;border:1px solid ' + col + '22;border-left:none;border-radius:0 10px 10px 0;background:' + col + '08;color:' + col + ';cursor:pointer;font-size:.78rem;line-height:1;padding:0 .55rem;opacity:.55" onmouseover="this.style.opacity=\'1\'" onmouseout="this.style.opacity=\'.55\'">✕</button>'
      + '</div>';
  };
  let html = assigned.length
    ? assigned.map(solCard).join('')
    : '<div style="font-size:.62rem;color:var(--moss);opacity:.5;font-style:italic;padding:.15rem 0">Aucune solution, ajoute-en depuis la bibliothèque.</div>';
  html += '<div style="margin-top:.5rem"><button onclick="creerOpenPanel(\'biblio-sol\',' + idx + ')" style="font-size:.66rem;color:var(--forest);background:rgba(1,130,98,.05);border:1.5px dashed rgba(1,130,98,.4);border-radius:10px;padding:.5rem;width:100%;cursor:pointer;font-family:inherit;font-weight:700">+ Ajouter une solution depuis la bibliothèque</button></div>';
  return html;
}

// Indicateurs que le pilote a retenus ET que la solution fait progresser :
// c'est ce qui personnalise la quête proposée par Deva pour cette solution.
function _quetePersoIcis(nom){
  const effIds = new Set((typeof evadLieuIciIds === 'function') ? evadLieuIciIds(cData) : []);
  return (typeof iciPourSolution === 'function' ? (iciPourSolution(nom) || []) : []).filter(ici => effIds.has(ici.id));
}
function _quetePersoChips(nom){
  const icis = _quetePersoIcis(nom);
  if (!icis.length) return '';
  const chips = icis.map(ici => { const m = ((typeof ICI_LIVRE_META !== 'undefined') ? ICI_LIVRE_META[ici.livre] : null) || {col:'#3a6e8c'}; return '<span style="font-size:.55rem;font-weight:600;color:' + m.col + ';background:' + m.col + '14;border:1px solid ' + m.col + '30;border-radius:100px;padding:.1rem .4rem">📊 ' + ici.nom + '</span>'; }).join(' ');
  return '<div style="margin-top:.35rem"><div style="font-size:.53rem;font-weight:700;color:var(--sky);text-transform:uppercase;letter-spacing:.05em;margin-bottom:.22rem">🎯 Fera progresser</div><div style="display:flex;flex-wrap:wrap;gap:.25rem">' + chips + '</div></div>';
}

// Bloc quêtes d'un espace : une quête personnalisée par solution (proposée par
// Deva selon les indicateurs retenus) + ajout depuis la biblio + sur mesure.
function creerEspaceQuetesHTML(idx){
  const retir = new Set(cData.quetesRetirees || []);
  const card = (ic, titre, duree, nb, impact, foot, footCol, removeCall, openCall, extra) =>
    '<div style="display:flex;align-items:stretch;gap:0;margin-bottom:.35rem">'
    + '<div ' + (openCall ? 'onclick="' + openCall + '" style="cursor:pointer;' : 'style="') + 'flex:1;min-width:0;background:white;border:1px solid rgba(46,102,66,.14);border-left:3px solid var(--amber);border-radius:10px 0 0 10px;padding:.5rem .65rem">'
      + '<div style="display:flex;align-items:center;gap:.4rem"><span style="font-size:.85rem">' + ic + '</span><span style="font-size:.72rem;font-weight:700;color:var(--ink);line-height:1.2;flex:1">' + titre + '</span>' + (openCall ? '<span style="font-size:.58rem;opacity:.5">↗</span>' : '') + '</div>'
      + '<div style="display:flex;flex-wrap:wrap;gap:.45rem;font-size:.6rem;color:var(--moss);opacity:.85;margin-top:.22rem">' + (duree && duree !== '-' ? '<span>⏱ ' + duree + '</span>' : '') + (nb && nb !== '-' ? '<span>👥 ' + nb + '</span>' : '') + (impact ? '<span style="color:var(--fern);font-weight:600">🌿 ' + impact + '</span>' : '') + '</div>'
      + (extra || '')
      + '<div style="font-size:.55rem;color:' + footCol + ';opacity:.6;margin-top:.25rem">' + foot + '</div>'
    + '</div>'
    + '<button onclick="' + removeCall + '" title="Retirer" style="flex-shrink:0;border:1px solid rgba(46,102,66,.14);border-left:none;border-radius:0 10px 10px 0;background:rgba(200,115,42,.05);color:var(--amber);cursor:pointer;font-size:.78rem;line-height:1;padding:0 .55rem;opacity:.55" onmouseover="this.style.opacity=\'1\'" onmouseout="this.style.opacity=\'.55\'">✕</button>'
    + '</div>';
  let cards = '', n = 0;
  // Dérivées des solutions de l'espace, personnalisées par Deva.
  ((cData.solsByEspace && cData.solsByEspace[idx]) || []).forEach(nom => {
    const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === nom) : null;
    if (!sol || !sol.quete || retir.has('sol:' + nom)) return;
    n++; const q = sol.quete; const safeNom = String(nom).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    cards += card(sol.img || '⚡', q.titre || 'Quête', q.duree, q.nb, q.impact_quete, '✦ Proposée par Deva · issue de « ' + nom + ' »', 'var(--forest)', "creerRemoveQuete('sol:" + safeNom + "')", "creerOpenQueteDetail('" + safeNom + "')", _quetePersoChips(nom));
  });
  // Ajoutées depuis la bibliothèque à cet espace.
  const espMap = cData.quetesEspMap || {};
  (cData.quetesAjoutees || []).forEach(nom => {
    if (espMap[nom] !== idx || retir.has('sol:' + nom)) return;
    const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === nom) : null;
    if (!sol || !sol.quete) return;
    n++; const q = sol.quete; const safeNom = String(nom).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    cards += card(sol.img || '⚡', q.titre || 'Quête', q.duree, q.nb, q.impact_quete, 'issue de « ' + nom + ' »', 'var(--moss)', "creerRemoveQuete('sol:" + safeNom + "')", "creerOpenQueteDetail('" + safeNom + "')", _quetePersoChips(nom));
  });
  // Sur mesure (custom, rattachées à cet espace) : uniquement celles du lieu
  // en cours (sinon les quêtes d'un autre lieu du même Pilote apparaissent).
  const _qLieuId = (cData && cData.id) || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.id) || 'lieu-demo';
  const customs = (window.store) ? store.where('quetes', q => q.custom === true && q.statut !== 'retiree'
    && (q.lieu_id === _qLieuId || q.lieu_id === 'lieu-demo' || q.lieu_id === 'draft' || !q.lieu_id)
    && ((q.espIdx === idx) || (q.donnees && q.donnees.espIdx === idx))) : [];
  customs.forEach(q => { n++; cards += card(q.sourceIc || '⚡', q.titre || 'Quête', q.duree, q.nb, q.impact, '✦ créée sur mesure', 'var(--forest)', "creerRemoveQuete('cst:" + q.id + "')", null, ''); });
  if (!n) cards = '<div style="font-size:.62rem;color:var(--moss);opacity:.5;font-style:italic;padding:.15rem 0 .3rem">Les quêtes des solutions de cet espace apparaîtront ici.</div>';
  let html = cards;
  html += '<div style="margin-top:.4rem"><button onclick="creerOpenPanel(\'biblio-quete\',' + idx + ')" style="font-size:.66rem;color:#c8732a;background:#c8732a0d;border:1.5px dashed #c8732a59;border-radius:10px;padding:.5rem;width:100%;cursor:pointer;font-family:inherit;font-weight:700">+ Ajouter une quête depuis la bibliothèque</button></div>';
  html += '<button onclick="creerQueteNouvelleEsp(' + idx + ')" style="width:100%;margin-top:.35rem;padding:.5rem;border:1.5px dashed rgba(1,130,98,.4);border-radius:10px;background:rgba(1,130,98,.05);color:var(--forest);font-family:inherit;font-size:.68rem;font-weight:700;cursor:pointer">＋ Créer une quête sur mesure</button>';
  return html;
}

// Bloc indicateurs d'un espace : ICI portés par ses solutions + ajoutés,
// avec ajout depuis la bibliothèque.
function creerEspaceIndicsHTML(idx){
  const retir = new Set(cData.icisRetires || []);
  const seen = new Set();
  const row = (ici) => {
    const meta = (typeof ICI_LIVRE_META !== 'undefined' && ICI_LIVRE_META[ici.livre]) || { ic:'◆', col:'#4a8c5c', label:ici.livre };
    return '<div style="display:flex;align-items:stretch;gap:0;margin-bottom:.3rem">'
      + '<div onclick="creerOpenIciDetail(\'' + ici.id + '\')" title="Voir la fiche" style="flex:1;min-width:0;background:white;border:1px solid ' + meta.col + '22;border-left:3px solid ' + meta.col + ';border-radius:10px 0 0 10px;padding:.45rem .6rem;cursor:pointer">'
        + '<div style="display:flex;align-items:center;justify-content:space-between;gap:.5rem">'
          + '<span style="font-size:.7rem;font-weight:700;color:var(--ink);line-height:1.2">' + meta.ic + ' ' + ici.nom + '</span>'
          + '<span style="font-size:.55rem;color:' + meta.col + ';font-weight:600;white-space:nowrap">' + (ici.unite || '') + '</span>'
        + '</div>'
      + '</div>'
      + '<button onclick="creerRemoveIci(\'' + ici.id + '\')" title="Retirer" style="flex-shrink:0;border:1px solid ' + meta.col + '22;border-left:none;border-radius:0 10px 10px 0;background:' + meta.col + '08;color:' + meta.col + ';cursor:pointer;font-size:.78rem;line-height:1;padding:0 .55rem;opacity:.55" onmouseover="this.style.opacity=\'1\'" onmouseout="this.style.opacity=\'.55\'">✕</button>'
      + '</div>';
  };
  // Collecte des indicateurs de l'espace (dérivés + ajoutés), dédupliqués.
  const list = [];
  ((cData.solsByEspace && cData.solsByEspace[idx]) || []).forEach(nom => {
    (typeof iciPourSolution === 'function' ? (iciPourSolution(nom) || []) : []).forEach(ici => {
      if (seen.has(ici.id) || retir.has(ici.id)) return;
      seen.add(ici.id); list.push(ici);
    });
  });
  const espMap = cData.icisEspMap || {};
  (cData.icisAjoutes || []).forEach(id => {
    if (espMap[id] !== idx || seen.has(id) || retir.has(id)) return;
    const ici = (typeof iciGetICI === 'function') ? iciGetICI(id) : null;
    if (!ici) return;
    seen.add(id); list.push(ici);
  });
  // Classement par capital : écologique / sociale / économie locale.
  let cards = '';
  CAPITAUX_ORDRE.forEach(livre => {
    const grp = list.filter(i => i.livre === livre);
    if (!grp.length) return;
    cards += _capSousTitre(livre) + grp.map(row).join('');
  });
  if (!list.length) cards = '<div style="font-size:.62rem;color:var(--moss);opacity:.5;font-style:italic;padding:.15rem 0">Les indicateurs des solutions de cet espace apparaîtront ici.</div>';
  return cards + '<div style="margin-top:.5rem"><button onclick="creerOpenPanel(\'biblio-ici\',' + idx + ')" style="font-size:.66rem;color:#3a6e8c;background:#3a6e8c0d;border:1.5px dashed #3a6e8c59;border-radius:10px;padding:.5rem;width:100%;cursor:pointer;font-family:inherit;font-weight:700">+ Ajouter un indicateur depuis la bibliothèque</button></div>';
}

// Panneau « ajouter une quête depuis la bibliothèque » d'un espace (chips +
// recherche + tri par catégorie, comme les solutions).
function creerQueteBiblioBlockHTML(idx){
  const col = '#c8732a';
  if (!window._creerQuetePanelOpen) {
    return '<div style="margin-top:.4rem"><button onclick="creerToggleQuetePanel()" style="font-size:.66rem;color:' + col + ';background:' + col + '0d;border:1.5px dashed ' + col + '59;border-radius:10px;padding:.5rem;width:100%;cursor:pointer;font-family:inherit;font-weight:700">+ Ajouter une quête depuis la bibliothèque</button></div>';
  }
  const retir = new Set(cData.quetesRetirees || []);
  const shown = new Set();
  (cData.solutions || []).forEach(nom => { const s = (typeof SOLS !== 'undefined') ? SOLS.find(x => x.nom === nom) : null; if (s && s.quete && !retir.has('sol:' + nom)) shown.add(nom); });
  (cData.quetesAjoutees || []).forEach(nom => { if (!retir.has('sol:' + nom)) shown.add(nom); });
  const searchRaw = window._creerQueteSearch || '', search = searchRaw.toLowerCase().trim();
  let dispo = (typeof SOLS !== 'undefined') ? SOLS.filter(s => s.quete && !shown.has(s.nom)) : [];
  if (search) dispo = dispo.filter(s => ((((s.quete && s.quete.titre) || '') + ' ' + s.nom).toLowerCase().indexOf(search) >= 0));
  const rowFor = (s) => { const safeNom = String(s.nom).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return '<div style="display:flex;align-items:center;gap:.5rem;padding:.38rem .5rem;border-radius:.6rem;background:rgba(46,102,66,.03);border:1px solid rgba(46,102,66,.08);margin-bottom:.2rem">'
      + '<span style="font-size:.88rem;flex-shrink:0">' + (s.img || '⚡') + '</span>'
      + '<div style="flex:1;min-width:0"><div style="font-size:.68rem;font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + ((s.quete && s.quete.titre) || s.nom) + '</div><div style="font-size:.57rem;color:var(--moss);opacity:.65">issue de « ' + s.nom + ' »</div></div>'
      + '<button onclick="creerOpenQueteDetail(\'' + safeNom + '\')" style="flex-shrink:0;padding:.25rem .45rem;border-radius:.45rem;border:1.5px solid rgba(46,102,66,.2);background:transparent;color:var(--forest);font-size:.6rem;cursor:pointer">👁</button>'
      + '<button onclick="creerAddQuete(\'' + safeNom + '\')" style="flex-shrink:0;padding:.25rem .55rem;border-radius:.45rem;border:none;background:var(--forest);color:white;font-size:.6rem;font-weight:700;cursor:pointer">+ Ajouter</button>'
    + '</div>';
  };
  let h = '<div style="margin-top:.5rem;border-top:1px dashed ' + col + '40;padding-top:.5rem">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.4rem">'
      + '<span style="font-size:.6rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em">Bibliothèque · ajouter une quête</span>'
      + '<button onclick="creerToggleQuetePanel()" style="font-size:.62rem;color:var(--moss);background:none;border:none;cursor:pointer;font-family:inherit;opacity:.7">Fermer ✕</button>'
    + '</div>'
    + '<input id="pq-bdd-search" type="text" value="' + searchRaw.replace(/"/g,'&quot;') + '" oninput="creerQueteSearchInput(this.value)" placeholder="🔍 Rechercher une quête…" style="width:100%;box-sizing:border-box;padding:.4rem .6rem;margin-bottom:.5rem;border:1.5px solid rgba(46,102,66,.2);border-radius:8px;font-size:.72rem;font-family:inherit;background:#f6faf7;outline:none">';
  if (!dispo.length) {
    h += '<div style="padding:.5rem;text-align:center;font-size:.66rem;color:var(--moss);opacity:.45;font-style:italic">' + (search ? 'Aucune quête ne correspond' : 'Toutes les quêtes sont déjà présentes') + '</div>';
  } else {
    const catMeta = (typeof CAT_META !== 'undefined') ? CAT_META : {}, catOrder = Object.keys(catMeta);
    catOrder.forEach(cat => { const grp = dispo.filter(s => s.cat === cat); if (!grp.length) return; const cm = catMeta[cat] || {ic:'', l:cat, c:'#666'};
      h += '<div style="font-size:.58rem;font-weight:700;color:' + cm.c + ';text-transform:uppercase;letter-spacing:.07em;margin:.5rem 0 .28rem;display:flex;align-items:center;gap:.3rem"><span>' + cm.ic + '</span><span>' + cm.l + '</span></div>';
      grp.forEach(s => { h += rowFor(s); });
    });
    const rest = dispo.filter(s => catOrder.indexOf(s.cat) < 0);
    if (rest.length) { h += '<div style="font-size:.58rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em;margin:.5rem 0 .28rem">Autres</div>'; rest.forEach(s => { h += rowFor(s); }); }
  }
  h += '</div>';
  return h;
}

// Panneau « ajouter un indicateur depuis la bibliothèque » d'un espace
// (recherche + tri par capital, comme les solutions).
function creerIciBiblioBlockHTML(idx){
  const col = '#3a6e8c';
  if (!window._creerIciPanelOpen) {
    return '<div style="margin-top:.4rem"><button onclick="creerToggleIciPanel()" style="font-size:.66rem;color:' + col + ';background:' + col + '0d;border:1.5px dashed ' + col + '59;border-radius:10px;padding:.5rem;width:100%;cursor:pointer;font-family:inherit;font-weight:700">+ Ajouter un indicateur depuis la bibliothèque</button></div>';
  }
  if (typeof ICI_CATALOG === 'undefined') return '';
  const retir = new Set(cData.icisRetires || []);
  const shown = new Set();
  (cData.solutions || []).forEach(nom => { (typeof iciPourSolution === 'function' ? (iciPourSolution(nom) || []) : []).forEach(i => { if (!retir.has(i.id)) shown.add(i.id); }); });
  (cData.icisAjoutes || []).forEach(id => { if (!retir.has(id)) shown.add(id); });
  const searchRaw = window._creerIciSearch || '', search = searchRaw.toLowerCase().trim();
  let dispo = ICI_CATALOG.filter(i => !shown.has(i.id));
  if (search) dispo = dispo.filter(i => ((i.nom + ' ' + (i.unite || '')).toLowerCase().indexOf(search) >= 0));
  const rowFor = (ici) =>
    '<div style="display:flex;align-items:center;gap:.5rem;padding:.38rem .5rem;border-radius:.6rem;background:rgba(46,102,66,.03);border:1px solid rgba(46,102,66,.08);margin-bottom:.2rem">'
    + '<div style="flex:1;min-width:0"><div style="font-size:.68rem;font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + ici.nom + '</div><div style="font-size:.57rem;color:var(--moss);opacity:.65">' + (ici.unite || '') + '</div></div>'
    + '<button onclick="creerOpenIciDetail(\'' + ici.id + '\')" style="flex-shrink:0;padding:.25rem .45rem;border-radius:.45rem;border:1.5px solid rgba(46,102,66,.2);background:transparent;color:var(--forest);font-size:.6rem;cursor:pointer">👁</button>'
    + '<button onclick="creerAddIci(\'' + ici.id + '\')" style="flex-shrink:0;padding:.25rem .55rem;border-radius:.45rem;border:none;background:var(--forest);color:white;font-size:.6rem;font-weight:700;cursor:pointer">+ Ajouter</button>'
    + '</div>';
  let h = '<div style="margin-top:.5rem;border-top:1px dashed ' + col + '40;padding-top:.5rem">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.4rem">'
      + '<span style="font-size:.6rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em">Bibliothèque · ajouter un indicateur</span>'
      + '<button onclick="creerToggleIciPanel()" style="font-size:.62rem;color:var(--moss);background:none;border:none;cursor:pointer;font-family:inherit;opacity:.7">Fermer ✕</button>'
    + '</div>'
    + '<input id="pq-ici-search" type="text" value="' + searchRaw.replace(/"/g,'&quot;') + '" oninput="creerIciSearchInput(this.value)" placeholder="🔍 Rechercher un indicateur…" style="width:100%;box-sizing:border-box;padding:.4rem .6rem;margin-bottom:.5rem;border:1.5px solid rgba(46,102,66,.2);border-radius:8px;font-size:.72rem;font-family:inherit;background:#f6faf7;outline:none">';
  if (!dispo.length) {
    h += '<div style="padding:.5rem;text-align:center;font-size:.66rem;color:var(--moss);opacity:.45;font-style:italic">' + (search ? 'Aucun indicateur ne correspond' : 'Tous les indicateurs sont déjà présents') + '</div>';
  } else {
    ['ecologie','social','economie_locale'].forEach(livre => {
      const grp = dispo.filter(i => i.livre === livre); if (!grp.length) return;
      const meta = (typeof ICI_LIVRE_META !== 'undefined' && ICI_LIVRE_META[livre]) || { label: livre, ic:'◆', col:'#4a8c5c' };
      h += '<div style="font-size:.58rem;font-weight:700;color:' + meta.col + ';text-transform:uppercase;letter-spacing:.07em;margin:.5rem 0 .28rem;display:flex;align-items:center;gap:.3rem"><span>' + meta.ic + '</span><span>' + meta.label + '</span></div>';
      grp.forEach(i => { h += rowFor(i); });
    });
  }
  h += '</div>';
  return h;
}

// Rafraîchit uniquement la sidebar de l'étape 3 (sans redessiner le mind map).
function creerRefreshSidebar(){
  const c = document.getElementById('creer-step-content');
  if (c && cStep === 3) { c.innerHTML = creerStep3SidebarHTML(); _creerQuetesLoadingRun(); }
}

// Clic sur un onglet d'espace : à l'étape quêtes, il FILTRE la liste des
// quêtes sur cet espace (on reste dans la phase quêtes) ; sinon il focalise
// l'édition des solutions/indicateurs de l'espace.
function creerSelectEsp(idx){
  if (window._creerPhase === 'quetes') {
    window._creerActiveEsp = idx;
    creerRefreshSidebar();
    return;
  }
  creerFocusEsp(idx);
}

// Clique sur un bouton d'espace : focalise sidebar + mind map sur cet espace.
function creerFocusEsp(idx){
  window._creerActiveEsp = idx;
  window._creerPhase = 'espaces';   // cliquer un espace = revenir l'éditer
  window._creerMapOverview = false; // cliquer un espace = repasser en focus
  if (typeof creerSidePanelClose === 'function') creerSidePanelClose();   // referme le panneau latéral
  creerRefreshSidebar();
  creerApplyMapFocus();
  _creerMajBoutonVueMap();
  _creerMajNav();   // « Générer les quêtes » apparaît quand tous les espaces sont visités
}

// Bascule entre vue d'ensemble (tout le mind map) et focus sur l'espace actif.
function creerToggleVueMap(){
  window._creerMapOverview = !window._creerMapOverview;
  creerApplyMapFocus();
  _creerMajBoutonVueMap();
}
function _creerMajBoutonVueMap(){
  const b = document.getElementById('creer-vue-map-btn');
  if (!b) return;
  // Masqué en phase quêtes (le mind map y est déjà en vue d'ensemble).
  b.style.display = (window._creerPhase === 'quetes') ? 'none' : 'flex';
  b.innerHTML = window._creerMapOverview ? '🎯 Revenir à l\'espace' : '🗺 Vue d\'ensemble';
}

// Tous les espaces ont été parcourus → Deva compose les quêtes (chargement).
function creerGenererQuetes(){
  window._creerPhase = 'quetes';
  window._creerActiveEsp = 0;   // on démarre le tri des quêtes sur le 1er espace
  window._creerQuetesReady = false;
  window._creerQuetesLoadingScheduled = false;
  window._creerMapOverview = false;
  if (typeof creerSidePanelClose === 'function') creerSidePanelClose();
  creerRefreshSidebar();
  creerApplyMapFocus();
  _creerMajBoutonVueMap();
  _creerMajStepper();   // stepper → étape Quête + bouton « Créer le lieu »
  if (typeof creerUpdateHint === 'function') creerUpdateHint(true);   // bulle Deva : message des quêtes
}

// « Créer une quête sur mesure » depuis un espace : formulaire dans le panneau
// latéral droit (comme « Nouvel espace »), rattaché à cet espace.
function creerQueteNouvelleEsp(idx){
  window._creerQueteEspIdx = idx;
  window._creerActiveEsp = idx;
  // Toujours le formulaire pleine page (même format partout, y compris en guidé).
  if (typeof piloteQueteCreerOuvrir === 'function') piloteQueteCreerOuvrir();
}

/* Onglet « Indicateurs » de l'étape 3 : les ICI portés par les solutions
   sélectionnées, regroupés par capital (écologie / social / économie locale). */
function creerStep3IndicateursHTML(){
  if (typeof iciPourSolution !== 'function' || typeof ICI_CATALOG === 'undefined') return '';
  const selSols = cData.solutions || [];
  // Origine (solutions) de chaque ICI, pour l'afficher en chips.
  const solsParIci = {};
  selSols.forEach(sn => {
    (iciPourSolution(sn) || []).forEach(ici => {
      (solsParIci[ici.id] = solsParIci[ici.id] || []);
      if (!solsParIci[ici.id].includes(sn)) solsParIci[ici.id].push(sn);
    });
  });
  // Ensemble effectif = solutions (∪ ajoutés) − retirés.
  const effIds = (typeof evadLieuIciIds === 'function') ? evadLieuIciIds(cData) : Object.keys(solsParIci);
  const entries = effIds.map(id => iciGetICI(id)).filter(Boolean);
  const total = entries.length;
  let html = ''
    + '<div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.3rem">'
      + '<div style="font-size:.72rem;font-weight:700;color:var(--ink)">📊 Indicateurs de Changement d\'Impact</div>'
      + '<div style="margin-left:auto;font-size:.65rem;font-weight:700;background:rgba(1,130,98,.1);color:var(--forest);padding:.1rem .5rem;border-radius:100px">'+total+' ICI</div>'
    + '</div>'
    + '<div style="font-size:.65rem;color:var(--moss);opacity:.75;margin-bottom:.9rem;line-height:1.55">Chaque solution porte ses ICI : les changements concrets et mesurables que ton lieu projette. Retire ceux qui ne te concernent pas ou ajoute-en d\'autres depuis la bibliothèque.</div>';
  if (total) {
    const order = ['ecologie','social','economie_locale'];
    const byLivre = {};
    entries.forEach(ici => { (byLivre[ici.livre] = byLivre[ici.livre] || []).push(ici); });
    order.forEach(livre => {
      const list = byLivre[livre];
      if (!list || !list.length) return;
      const meta = (typeof ICI_LIVRE_META !== 'undefined' && ICI_LIVRE_META[livre]) || { label: livre, ic: '◆', col: '#4a8c5c' };
      html += '<div style="display:flex;align-items:center;gap:.4rem;margin:.7rem 0 .45rem">'
        + '<span style="font-size:.85rem">'+meta.ic+'</span>'
        + '<span style="font-size:.62rem;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:'+meta.col+'">'+meta.label+'</span>'
        + '<span style="margin-left:auto;font-size:.58rem;font-weight:700;color:'+meta.col+';background:'+meta.col+'18;padding:.05rem .45rem;border-radius:100px">'+list.length+'</span>'
        + '</div>';
      list.forEach(ici => {
        const origine = solsParIci[ici.id] || [];
        const chips = origine.length
          ? origine.map(sn => '<span style="font-size:.58rem;color:'+meta.col+';background:'+meta.col+'12;border:1px solid '+meta.col+'33;border-radius:100px;padding:.1rem .4rem">'+sn+'</span>').join(' ')
          : '<span style="font-size:.56rem;color:var(--moss);opacity:.6;font-style:italic">✦ ajouté à la main</span>';
        html += '<div style="display:flex;align-items:stretch;gap:0;margin-bottom:.35rem">'
          + '<div onclick="creerOpenIciDetail(\''+ici.id+'\')" title="Voir la fiche indicateur" style="flex:1;min-width:0;background:white;border:1px solid '+meta.col+'22;border-left:3px solid '+meta.col+';border-radius:var(--r) 0 0 var(--r);padding:.5rem .6rem;cursor:pointer;transition:box-shadow .15s" onmouseover="this.style.boxShadow=\'0 2px 10px rgba(46,102,66,.12)\'" onmouseout="this.style.boxShadow=\'none\'">'
            + '<div style="display:flex;align-items:center;justify-content:space-between;gap:.5rem;margin-bottom:.3rem">'
              + '<span style="font-size:.72rem;font-weight:700;color:var(--ink);line-height:1.2">'+ici.nom+'</span>'
              + '<span style="font-size:.56rem;color:'+meta.col+';font-weight:600;white-space:nowrap">'+(ici.unite||'')+'</span>'
            + '</div>'
            + '<div style="display:flex;flex-wrap:wrap;gap:.25rem">'+chips+'</div>'
          + '</div>'
          + '<button onclick="creerRemoveIci(\''+ici.id+'\')" title="Retirer cet indicateur" style="flex-shrink:0;border:1px solid '+meta.col+'22;border-left:none;border-radius:0 var(--r) var(--r) 0;background:'+meta.col+'08;color:'+meta.col+';cursor:pointer;font-size:.8rem;line-height:1;padding:0 .6rem;opacity:.55;transition:opacity .15s" onmouseover="this.style.opacity=\'1\'" onmouseout="this.style.opacity=\'.55\'">✕</button>'
        + '</div>';
      });
    });
  } else {
    html += '<div style="padding:1rem;text-align:center;font-size:.7rem;color:var(--moss);opacity:.55;border:1px dashed rgba(46,102,66,.2);border-radius:var(--r);margin-bottom:.5rem">Aucun indicateur, ajoute des solutions qui en portent, ou ajoute-en depuis la bibliothèque.</div>';
  }
  // Panneau « ajouter depuis la bibliothèque » (groupé par capital + recherche)
  const shown = new Set(effIds);
  const iSearchRaw = window._creerIciSearch || '';
  const iSearch = iSearchRaw.toLowerCase().trim();
  let dispo = ICI_CATALOG.filter(i => !shown.has(i.id));
  if (iSearch) dispo = dispo.filter(i => ((i.nom + ' ' + (i.unite || '')).toLowerCase().indexOf(iSearch) >= 0));
  if (window._creerIciPanelOpen) {
    html += '<div style="margin-top:.5rem;padding:.6rem .7rem;background:rgba(46,102,66,.03);border:1px solid rgba(46,102,66,.12);border-radius:var(--r)">'
      + '<div style="font-size:.6rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em;margin-bottom:.45rem">Bibliothèque · ajouter un indicateur</div>'
      + '<input id="pq-ici-search" type="text" value="'+iSearchRaw.replace(/"/g,'&quot;')+'" oninput="creerIciSearchInput(this.value)" placeholder="🔍 Rechercher un indicateur…" style="width:100%;box-sizing:border-box;padding:.4rem .6rem;margin-bottom:.5rem;border:1.5px solid rgba(46,102,66,.2);border-radius:8px;font-size:.72rem;font-family:inherit;background:#f6faf7;outline:none">';
    if (!dispo.length) {
      html += '<div style="padding:.5rem;text-align:center;font-size:.66rem;color:var(--moss);opacity:.45;font-style:italic">'+(iSearch?'Aucun indicateur ne correspond à ta recherche':'Tous les indicateurs sont déjà présents')+'</div>';
    } else {
      const order2 = ['ecologie','social','economie_locale'];
      order2.forEach(livre => {
        const grp = dispo.filter(i => i.livre === livre);
        if (!grp.length) return;
        const meta = (typeof ICI_LIVRE_META !== 'undefined' && ICI_LIVRE_META[livre]) || { label: livre, ic: '◆', col: '#4a8c5c' };
        html += '<div style="font-size:.58rem;font-weight:700;color:'+meta.col+';text-transform:uppercase;letter-spacing:.07em;margin:.5rem 0 .28rem;display:flex;align-items:center;gap:.3rem"><span>'+meta.ic+'</span><span>'+meta.label+'</span></div>';
        grp.forEach(ici => {
          html += '<div style="display:flex;align-items:center;gap:.5rem;padding:.38rem .5rem;border-radius:.6rem;background:white;border:1px solid rgba(46,102,66,.08);margin-bottom:.2rem">'
            + '<div style="flex:1;min-width:0">'
              + '<div style="font-size:.68rem;font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+ici.nom+'</div>'
              + '<div style="font-size:.57rem;color:var(--moss);opacity:.65">'+(ici.unite||'')+'</div>'
            + '</div>'
            + '<button onclick="creerOpenIciDetail(\''+ici.id+'\')" style="flex-shrink:0;padding:.25rem .45rem;border-radius:.45rem;border:1.5px solid rgba(46,102,66,.2);background:transparent;color:var(--forest);font-size:.6rem;cursor:pointer">👁</button>'
            + '<button onclick="creerAddIci(\''+ici.id+'\')" style="flex-shrink:0;padding:.25rem .55rem;border-radius:.45rem;border:none;background:var(--forest);color:white;font-size:.6rem;font-weight:700;cursor:pointer">+ Ajouter</button>'
          + '</div>';
        });
      });
    }
    html += '<div style="margin-top:.5rem;text-align:right"><button onclick="creerToggleIciPanel()" style="font-size:.62rem;color:var(--moss);background:none;border:none;cursor:pointer;font-family:inherit;opacity:.7">Fermer</button></div>'
      + '</div>';
  } else {
    html += '<div style="margin-top:.4rem"><button onclick="creerToggleIciPanel()" style="font-size:.66rem;color:var(--forest);background:rgba(1,130,98,.05);border:1.5px dashed rgba(1,130,98,.35);border-radius:var(--r);padding:.55rem;width:100%;cursor:pointer;font-family:inherit;font-weight:700">+ Ajouter un indicateur depuis la bibliothèque</button></div>';
  }
  return html;
}

/* Ajout / retrait d'indicateurs. L'ajout rattache l'ICI à l'espace donné. */
function creerAddIci(id, espIdx){
  cData.icisAjoutes = cData.icisAjoutes || [];
  if (!cData.icisAjoutes.includes(id)) cData.icisAjoutes.push(id);
  cData.icisRetires = (cData.icisRetires || []).filter(x => x !== id);
  cData.icisEspMap = cData.icisEspMap || {};
  cData.icisEspMap[id] = (espIdx != null) ? espIdx : ((window._creerActiveEsp != null) ? window._creerActiveEsp : 0);
  creerStep3RefreshIndicateurs();
}
function creerRemoveIci(id){
  cData.icisRetires = cData.icisRetires || [];
  if (!cData.icisRetires.includes(id)) cData.icisRetires.push(id);
  cData.icisAjoutes = (cData.icisAjoutes || []).filter(x => x !== id);
  if (cData.icisEspMap) delete cData.icisEspMap[id];
  creerStep3RefreshIndicateurs();
}
function creerToggleIciPanel(){
  window._creerIciPanelOpen = !window._creerIciPanelOpen;
  window._creerIciSearch = '';
  creerStep3RefreshIndicateurs();
}
function creerIciSearchInput(v){
  window._creerIciSearch = v;
  if (window._creerPanel && typeof creerPanelRefresh === 'function') creerPanelRefresh();
  _creerRefocusSearch('pq-ici-search');
}
function creerStep3RefreshIndicateurs(){
  // La sidebar montre les indicateurs de l'espace, le mind map met à jour sa
  // révélation, et le panneau latéral (s'il est ouvert) retire l'ajouté.
  if (typeof creerRefreshSidebar === 'function') creerRefreshSidebar();
  if (typeof creerMapRevealRefresh === 'function') creerMapRevealRefresh();
  if (window._creerPanel && typeof creerPanelRefresh === 'function') creerPanelRefresh();
}

/* Onglet « Quêtes » de l'étape 3 : l'aperçu des quêtes portées par les
   solutions sélectionnées (l'action concrète que rejoindront les Bâtisseurs). */
function creerStep3QuetesHTML(){
  const queteSols = (typeof evadLieuQueteSols === 'function') ? evadLieuQueteSols(cData) : (cData.solutions || []);
  const quetes = [];
  if (typeof SOLS !== 'undefined') {
    queteSols.forEach(sn => {
      const sol = SOLS.find(s => s.nom === sn);
      if (sol && sol.quete) quetes.push({ sol: sol, q: sol.quete });
    });
  }
  // Quêtes créées manuellement (custom), visibles ici dès leur création.
  const customs = (window.store) ? store.where('quetes', function(q){ return q.custom === true && q.statut !== 'retiree'; }) : [];
  const total = quetes.length + customs.length;
  const btnNouvelle = '<button onclick="creerQueteNouvelle()" style="width:100%;margin-top:.4rem;padding:.6rem;border:1.5px dashed rgba(1,130,98,.4);border-radius:var(--r);background:rgba(1,130,98,.05);color:var(--forest);font-family:inherit;font-size:.74rem;font-weight:700;cursor:pointer">＋ Créer une nouvelle quête</button>';

  // Panneau « ajouter une quête depuis la bibliothèque » : solutions de la BDD
  // qui portent une quête et qui ne sont pas déjà affichées, triées par
  // catégorie (comme les solutions) et filtrables par une barre de recherche.
  const shown = new Set(queteSols);
  const qSearchRaw = window._creerQueteSearch || '';
  const qSearch = qSearchRaw.toLowerCase().trim();
  let dispo = (typeof SOLS !== 'undefined') ? SOLS.filter(s => s.quete && !shown.has(s.nom)) : [];
  if (qSearch) dispo = dispo.filter(s => ((((s.quete && s.quete.titre) || '') + ' ' + s.nom).toLowerCase().indexOf(qSearch) >= 0));
  const queteBddRow = function(s){
    const safeNom = String(s.nom).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return '<div style="display:flex;align-items:center;gap:.5rem;padding:.38rem .5rem;border-radius:.6rem;background:white;border:1px solid rgba(46,102,66,.08);margin-bottom:.2rem">'
      + '<span style="font-size:.88rem;flex-shrink:0">'+(s.img||'⚡')+'</span>'
      + '<div style="flex:1;min-width:0">'
        + '<div style="font-size:.68rem;font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+((s.quete&&s.quete.titre)||s.nom)+'</div>'
        + '<div style="font-size:.57rem;color:var(--moss);opacity:.65">issue de « '+s.nom+' »</div>'
      + '</div>'
      + '<button onclick="creerOpenQueteDetail(\''+safeNom+'\')" style="flex-shrink:0;padding:.25rem .45rem;border-radius:.45rem;border:1.5px solid rgba(46,102,66,.2);background:transparent;color:var(--forest);font-size:.6rem;cursor:pointer">👁</button>'
      + '<button onclick="creerAddQuete(\''+safeNom+'\')" style="flex-shrink:0;padding:.25rem .55rem;border-radius:.45rem;border:none;background:var(--forest);color:white;font-size:.6rem;font-weight:700;cursor:pointer">+ Ajouter</button>'
    + '</div>';
  };
  let bddPanel = '';
  if (window._creerQuetePanelOpen) {
    bddPanel = '<div style="margin-top:.5rem;padding:.6rem .7rem;background:rgba(46,102,66,.03);border:1px solid rgba(46,102,66,.12);border-radius:var(--r)">'
      + '<div style="font-size:.6rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em;margin-bottom:.45rem">Bibliothèque · ajouter une quête</div>'
      + '<input id="pq-bdd-search" type="text" value="'+qSearchRaw.replace(/"/g,'&quot;')+'" oninput="creerQueteSearchInput(this.value)" placeholder="🔍 Rechercher une quête…" style="width:100%;box-sizing:border-box;padding:.4rem .6rem;margin-bottom:.5rem;border:1.5px solid rgba(46,102,66,.2);border-radius:8px;font-size:.72rem;font-family:inherit;background:#f6faf7;outline:none">';
    if (!dispo.length) {
      bddPanel += '<div style="padding:.5rem;text-align:center;font-size:.66rem;color:var(--moss);opacity:.45;font-style:italic">'+(qSearch?'Aucune quête ne correspond à ta recherche':'Toutes les quêtes de la bibliothèque sont déjà présentes')+'</div>';
    } else {
      const catMeta = (typeof CAT_META !== 'undefined') ? CAT_META : {};
      const catOrder = Object.keys(catMeta);
      catOrder.forEach(cat => {
        const grp = dispo.filter(s => s.cat === cat);
        if (!grp.length) return;
        const cm = catMeta[cat] || {ic:'', l:cat, c:'#666'};
        bddPanel += '<div style="font-size:.58rem;font-weight:700;color:'+cm.c+';text-transform:uppercase;letter-spacing:.07em;margin:.5rem 0 .28rem;display:flex;align-items:center;gap:.3rem"><span>'+cm.ic+'</span><span>'+cm.l+'</span></div>';
        grp.forEach(s => { bddPanel += queteBddRow(s); });
      });
      const rest = dispo.filter(s => catOrder.indexOf(s.cat) < 0);
      if (rest.length) {
        bddPanel += '<div style="font-size:.58rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.07em;margin:.5rem 0 .28rem">Autres</div>';
        rest.forEach(s => { bddPanel += queteBddRow(s); });
      }
    }
    bddPanel += '<div style="margin-top:.5rem;text-align:right"><button onclick="creerToggleQuetePanel()" style="font-size:.62rem;color:var(--moss);background:none;border:none;cursor:pointer;font-family:inherit;opacity:.7">Fermer</button></div>'
      + '</div>';
  } else {
    bddPanel = '<div style="margin-top:.4rem"><button onclick="creerToggleQuetePanel()" style="font-size:.66rem;color:var(--forest);background:rgba(1,130,98,.05);border:1.5px dashed rgba(1,130,98,.35);border-radius:var(--r);padding:.55rem;width:100%;cursor:pointer;font-family:inherit;font-weight:700">+ Ajouter une quête depuis la bibliothèque</button></div>';
  }

  let html = ''
    + '<div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.3rem">'
      + '<div style="font-size:.72rem;font-weight:700;color:var(--ink)">⚡ Quêtes proposées</div>'
      + '<div style="margin-left:auto;font-size:.65rem;font-weight:700;background:rgba(1,130,98,.1);color:var(--forest);padding:.1rem .5rem;border-radius:100px">'+total+' quête'+(total!==1?'s':'')+'</div>'
    + '</div>'
    + '<div style="font-size:.65rem;color:var(--moss);opacity:.75;margin-bottom:.9rem;line-height:1.55">Chaque solution propose une quête : l\'action concrète que les Bâtisseurs pourront rejoindre. Retire celles qui ne conviennent pas, ajoute-en depuis la bibliothèque ou crée-en une sur mesure. Tu les retrouveras dans « Mes quêtes » pour les publier.</div>';
  if (!total) {
    return html + '<div style="padding:1rem;text-align:center;font-size:.7rem;color:var(--moss);opacity:.55;border:1px dashed rgba(46,102,66,.2);border-radius:var(--r);margin-bottom:.5rem">Aucune quête pour l\'instant, ajoute des solutions qui en portent, ajoute-en depuis la bibliothèque, ou crée-en une sur mesure.</div>' + bddPanel + btnNouvelle;
  }
  // Carte d'une quête portée par une solution (avec bouton retirer).
  const queteCard = function(sol, q){
    const ic = sol.img || '⚡';
    const safeNom = String(sol.nom).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return '<div style="display:flex;align-items:stretch;gap:0;margin-bottom:.4rem">'
      + '<div onclick="creerOpenQueteDetail(\''+safeNom+'\')" title="Voir la fiche quête" style="flex:1;min-width:0;background:white;border:1px solid rgba(46,102,66,.14);border-left:3px solid var(--amber);border-radius:var(--r) 0 0 var(--r);padding:.55rem .7rem;cursor:pointer;transition:box-shadow .15s" onmouseover="this.style.boxShadow=\'0 2px 10px rgba(46,102,66,.12)\'" onmouseout="this.style.boxShadow=\'none\'">'
        + '<div style="display:flex;align-items:center;gap:.45rem;margin-bottom:.3rem">'
          + '<span style="font-size:.9rem">'+ic+'</span>'
          + '<span style="font-size:.74rem;font-weight:700;color:var(--ink);line-height:1.2;flex:1">'+(q.titre||'Quête')+'</span>'
        + '</div>'
        + '<div style="display:flex;flex-wrap:wrap;gap:.5rem;font-size:.62rem;color:var(--moss);opacity:.85">'
          + (q.duree ? '<span>⏱ '+q.duree+'</span>' : '')
          + (q.nb ? '<span>👥 '+q.nb+'</span>' : '')
          + (q.impact_quete ? '<span style="color:var(--fern);font-weight:600">🌿 '+q.impact_quete+'</span>' : '')
        + '</div>'
        + '<div style="font-size:.56rem;color:var(--moss);opacity:.5;margin-top:.3rem">issue de « '+sol.nom+' »</div>'
      + '</div>'
      + '<button onclick="creerRemoveQuete(\'sol:'+safeNom+'\')" title="Retirer cette quête" style="flex-shrink:0;border:1px solid rgba(46,102,66,.14);border-left:none;border-radius:0 var(--r) var(--r) 0;background:rgba(200,115,42,.05);color:var(--amber);cursor:pointer;font-size:.8rem;line-height:1;padding:0 .6rem;opacity:.55;transition:opacity .15s" onmouseover="this.style.opacity=\'1\'" onmouseout="this.style.opacity=\'.55\'">✕</button>'
    + '</div>';
  };
  // En-tête d'un groupe (espace, ajoutées, sur mesure).
  const grpHeader = function(ic, nom, n){
    return '<div style="display:flex;align-items:center;gap:.4rem;margin:.7rem 0 .45rem">'
      + '<span style="font-size:.85rem">'+ic+'</span>'
      + '<span style="font-size:.62rem;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--forest)">'+nom+'</span>'
      + '<span style="margin-left:auto;font-size:.58rem;font-weight:700;color:var(--forest);background:rgba(1,130,98,.1);padding:.05rem .45rem;border-radius:100px">'+n+'</span>'
    + '</div>';
  };

  // Rattacher chaque quête-solution à son espace (comme pour les solutions).
  const bySol = {};
  quetes.forEach(item => { bySol[item.sol.nom] = item; });
  const espItems = window._creerEspItems || [];
  const sbe = cData.solsByEspace || {};
  const espIdxList = espItems.length ? espItems.map((_, i) => i) : Object.keys(sbe).map(k => parseInt(k, 10));

  const shownSols = new Set();
  espIdxList.forEach(function(idx){
    const it = espItems[idx] || {};
    const names = (sbe[idx] || []).filter(nom => bySol[nom] && !shownSols.has(nom));
    if (!names.length) return;
    html += grpHeader(it.ic || '📦', (it.esp && it.esp.nom) || ('Espace ' + (idx + 1)), names.length);
    names.forEach(nom => { shownSols.add(nom); html += queteCard(bySol[nom].sol, bySol[nom].q); });
  });

  // Quêtes ajoutées depuis la bibliothèque (solution non rattachée à un espace).
  const orphan = quetes.filter(item => !shownSols.has(item.sol.nom));
  if (orphan.length) {
    html += grpHeader('✦', 'Ajoutées', orphan.length);
    orphan.forEach(item => { html += queteCard(item.sol, item.q); });
  }

  // Quêtes créées sur mesure.
  if (customs.length) {
    html += grpHeader('✦', 'Sur mesure', customs.length);
    customs.forEach(function(q){
      html += '<div style="display:flex;align-items:stretch;gap:0;margin-bottom:.4rem">'
        + '<div style="flex:1;min-width:0;background:white;border:1px solid rgba(46,102,66,.14);border-left:3px solid var(--forest);border-radius:var(--r) 0 0 var(--r);padding:.55rem .7rem">'
          + '<div style="display:flex;align-items:center;gap:.45rem;margin-bottom:.3rem">'
            + '<span style="font-size:.9rem">'+(q.sourceIc||'⚡')+'</span>'
            + '<span style="font-size:.74rem;font-weight:700;color:var(--ink);line-height:1.2;flex:1">'+(q.titre||'Quête')+'</span>'
          + '</div>'
          + '<div style="display:flex;flex-wrap:wrap;gap:.5rem;font-size:.62rem;color:var(--moss);opacity:.85">'
            + (q.duree && q.duree!=='-' ? '<span>⏱ '+q.duree+'</span>' : '')
            + (q.nb && q.nb!=='-' ? '<span>👥 '+q.nb+'</span>' : '')
            + '<span style="color:var(--amber);font-weight:700">🌱 '+(q.graines||50)+'</span>'
            + (q.impact ? '<span style="color:var(--fern);font-weight:600">🌿 '+q.impact+'</span>' : '')
          + '</div>'
          + '<div style="font-size:.56rem;color:var(--forest);opacity:.65;margin-top:.3rem;font-weight:600">✦ créée sur mesure</div>'
        + '</div>'
        + '<button onclick="creerRemoveQuete(\'cst:'+q.id+'\')" title="Retirer cette quête" style="flex-shrink:0;border:1px solid rgba(46,102,66,.14);border-left:none;border-radius:0 var(--r) var(--r) 0;background:rgba(46,102,66,.04);color:var(--forest);cursor:pointer;font-size:.8rem;line-height:1;padding:0 .6rem;opacity:.55;transition:opacity .15s" onmouseover="this.style.opacity=\'1\'" onmouseout="this.style.opacity=\'.55\'">✕</button>'
      + '</div>';
    });
  }
  return html + bddPanel + btnNouvelle;
}

/* Ajout / retrait de quêtes (curation de l'onglet Quêtes du wizard). */
function creerAddQuete(solNom, espIdx){
  cData.quetesAjoutees = cData.quetesAjoutees || [];
  if (!cData.quetesAjoutees.includes(solNom)) cData.quetesAjoutees.push(solNom);
  cData.quetesRetirees = (cData.quetesRetirees || []).filter(k => k !== 'sol:' + solNom);
  cData.quetesEspMap = cData.quetesEspMap || {};
  cData.quetesEspMap[solNom] = (espIdx != null) ? espIdx : ((window._creerActiveEsp != null) ? window._creerActiveEsp : 0);
  creerStep3RefreshQuetes();
}
function creerRemoveQuete(key){
  if (key.indexOf('cst:') === 0) {
    // Quête sur mesure : on la retire du store (statut « retiree »).
    const id = key.slice(4);
    if (window.store) {
      const r = store.get('quetes', id);
      if (r) {
        const wasPublished = r.statut === 'ouverte';
        store.upsert('quetes', Object.assign({}, r, { statut: 'retiree' }));
        // Si elle était publiée, on la retire aussi de Supabase (donc du
        // réseau) : sans ça, elle resterait visible des bâtisseurs à jamais.
        if (wasPublished && typeof store.deleteQueteRemote === 'function') store.deleteQueteRemote(id);
      }
    }
    // Reflète le retrait dans la copie en mémoire, sinon _creerCustomQuetes la
    // relit et la quête reste dessinée sur le mind map.
    if (typeof PILOTE_QUETES_DEMO !== 'undefined') {
      const pq = PILOTE_QUETES_DEMO.find(x => x.id === id);
      if (pq) pq.statut = 'retiree';
    }
  } else {
    cData.quetesRetirees = cData.quetesRetirees || [];
    if (!cData.quetesRetirees.includes(key)) cData.quetesRetirees.push(key);
    const nom = key.slice(4);
    cData.quetesAjoutees = (cData.quetesAjoutees || []).filter(n => n !== nom);
    if (cData.quetesEspMap) delete cData.quetesEspMap[nom];
  }
  creerStep3RefreshQuetes();
}
function creerToggleQuetePanel(){
  window._creerQuetePanelOpen = !window._creerQuetePanelOpen;
  window._creerQueteSearch = '';   // repartir d'une recherche vierge à chaque ouverture
  creerStep3RefreshQuetes();
}
function creerQueteSearchInput(v){
  window._creerQueteSearch = v;
  if (window._creerPanel && typeof creerPanelRefresh === 'function') creerPanelRefresh();
  _creerRefocusSearch('pq-bdd-search');
}
// Rend le focus (et place le curseur en fin) à une barre de recherche après un
// re-render du panneau, pour ne pas couper la saisie de l'utilisateur.
function _creerRefocusSearch(id){
  const el = document.getElementById(id);
  if (el) { el.focus(); const n = el.value.length; try { el.setSelectionRange(n, n); } catch(e){} }
}

// Bouton « Créer une nouvelle quête » de l'étape 3 : ouvre la fiche quête
// vierge (même modale que « Mes quêtes »).
function creerQueteNouvelle(){
  if (typeof piloteQueteCreerOuvrir === 'function') piloteQueteCreerOuvrir();
}

// Recompose la sidebar (flux guidé) après création/retrait d'une quête, et
// met à jour la révélation quête/ICI du mind map.
function creerStep3RefreshQuetes(){
  if (typeof creerRefreshSidebar === 'function') creerRefreshSidebar();
  if (typeof creerMapRevealRefresh === 'function') creerMapRevealRefresh();
  if (window._creerPanel && typeof creerPanelRefresh === 'function') creerPanelRefresh();
}

/* Bascule entre les onglets « Solutions » / « Indicateurs » / « Quêtes » sans redessiner le mind map. */
function creerStep3Tab(tab){
  window._creerStep3Tab = tab;
  const pane = document.getElementById('creer-s3-pane');
  if (pane && window._creerS3Panes) pane.innerHTML = window._creerS3Panes[tab] || '';
  const tabs = document.getElementById('creer-s3-tabs');
  if (tabs) {
    tabs.querySelectorAll('[data-tab]').forEach(b => {
      const on = b.getAttribute('data-tab') === tab;
      b.style.background = on ? 'var(--forest)' : 'white';
      b.style.color = on ? 'white' : 'var(--moss)';
      b.style.borderColor = on ? 'var(--forest)' : 'rgba(46,102,66,.2)';
    });
  }
}

function creerSolFilter(cat, btn){
  window._solFilter.cat = cat;
  document.querySelectorAll('.sol-cat-chip').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  creerSolRefresh();
}

function creerSolSearch(q){
  window._solFilter.q = q.toLowerCase();
  creerSolRefresh();
}

function creerToggleEspacePanel(idx){
  window._activeEspacePanel = window._activeEspacePanel === idx ? null : idx;
  window._creerSolSearch = '';   // recherche vierge à chaque ouverture de panneau
  // Flux guidé : on ne redessine que la sidebar (le mind map reste focalisé).
  if (typeof creerRefreshSidebar === 'function' && cStep === 3) creerRefreshSidebar();
  else renderStep();
}
function creerSolSearchInput(v){
  window._creerSolSearch = v;
  if (window._creerPanel && typeof creerPanelRefresh === 'function') creerPanelRefresh();
  _creerRefocusSearch('creer-sol-search');
}

// Rafraîchit sidebar + branches de solutions du mind map, puis re-focalise,
// sans ré-animer tout le mind map (utilisé après add/remove de solution).
function creerSolChangeRefresh(){
  if (typeof creerUpdateVadance === 'function') creerUpdateVadance();
  if (cStep === 3 && typeof creerRefreshSidebar === 'function') {
    creerRefreshSidebar();
    if (typeof mmRefreshSolsStep4 === 'function') mmRefreshSolsStep4();
    if (typeof creerApplyMapFocus === 'function') creerApplyMapFocus();
  } else {
    renderStep();
    if (typeof mmRefreshSolsStep4 === 'function') mmRefreshSolsStep4();
  }
  if (window._creerPanel && typeof creerPanelRefresh === 'function') creerPanelRefresh();
}

function creerAddSol(espIdx, solNom){
  if(!cData.solsByEspace) cData.solsByEspace = {};
  if(!cData.solsByEspace[espIdx]) cData.solsByEspace[espIdx] = [];
  if(!cData.solsByEspace[espIdx].includes(solNom)){
    cData.solsByEspace[espIdx].push(solNom);
    cData.solutions = [...new Set(Object.values(cData.solsByEspace).flat())];
    cData._solsCustomized = true;   // choix manuel : la présélection ne l'écrasera plus
  }
  creerSolChangeRefresh();
}

function creerRemoveSol(espIdx, solNom){
  if(cData.solsByEspace && cData.solsByEspace[espIdx]){
    cData.solsByEspace[espIdx] = cData.solsByEspace[espIdx].filter(n=>n!==solNom);
    cData.solutions = Object.values(cData.solsByEspace).flat();
    cData._solsCustomized = true;   // choix manuel : la présélection ne l'écrasera plus
  }
  creerSolChangeRefresh();
}

function creerSolRefresh(){
  const espIdx = window._activeEspacePanel;
  if(espIdx === null || espIdx === undefined) return;
  const panel = document.getElementById('creer-bdd-panel-' + espIdx);
  if(!panel) return;
  panel.innerHTML = creerBddPanelHTML(espIdx);
}

// Catégories pertinentes par type d'espace ESPS
const EID_CATS = {
  jardin:   ['alimentaire','biodiversite','dechets','eau'],
  serre:    ['alimentaire','eau','dechets','biodiversite'],
  cuisine:  ['alimentaire','dechets','eau','social'],
  cafe:     ['social','dechets','alimentaire','electricite'],
  fablab:   ['construction','dechets','social','electricite'],
  atelier:  ['construction','dechets','social','biodiversite'],
  bureau:   ['electricite','social','construction'],
  salle:    ['social','electricite','biodiversite'],
  dortoir:  ['construction','electricite','eau','biodiversite'],
  boutique: ['social','construction','dechets','alimentaire'],
};

// Labels et couleurs des catégories
const CAT_META = {
  eau:          {ic:'💧', l:'Eau',          c:'#2a7cb8'},
  electricite:  {ic:'⚡', l:'Énergie',      c:'#b08800'},
  construction: {ic:'🧱', l:'Construction', c:'#8b6914'},
  alimentaire:  {ic:'🌱', l:'Alimentaire',  c:'#4a8c5c'},
  dechets:      {ic:'♻️', l:'Déchets',      c:'#2e9970'},
  biodiversite: {ic:'🌿', l:'Biodiversité', c:'#3a7a3a'},
  social:       {ic:'🤝', l:'Social',       c:'#7a5a9a'},
  adaptation:   {ic:'🌡', l:'Adaptation',   c:'#b84e35'},
};

function creerBddPanelHTML(espIdx){
  const assigned = (cData.solsByEspace && cData.solsByEspace[espIdx]) || [];
  const eid = (window._creerEspItems && window._creerEspItems[espIdx]?.eid) || 'cafe';
  const relevantCats = EID_CATS[eid] || Object.keys(CAT_META);
  const sSearchRaw = window._creerSolSearch || '';
  const sSearch = sSearchRaw.toLowerCase().trim();

  // Toute la bibliothèque (hors solutions déjà ajoutées à l'espace) ; la
  // recherche filtre par-dessus.
  let available = SOLS.filter(s => !assigned.includes(s.nom));
  if (sSearch) available = available.filter(s => ((s.nom + ' ' + (s.impact || '')).toLowerCase().indexOf(sSearch) >= 0));

  const searchInput = '<input id="creer-sol-search" type="text" value="'+sSearchRaw.replace(/"/g,'&quot;')+'" oninput="creerSolSearchInput(this.value)" placeholder="🔍 Rechercher une solution…" style="width:100%;box-sizing:border-box;padding:.4rem .6rem;margin-bottom:.5rem;border:1.5px solid rgba(46,102,66,.2);border-radius:8px;font-size:.72rem;font-family:inherit;background:#fff;outline:none">';

  if (!available.length)
    return searchInput + '<div style="padding:.65rem;text-align:center;font-size:.68rem;color:var(--moss);opacity:.45;font-style:italic">'+(sSearch?'Aucune solution ne correspond à ta recherche':'Toutes les solutions ont déjà été ajoutées')+'</div>';

  // Grouper par catégorie : celles pertinentes pour l'espace d'abord, puis
  // toutes les autres (accès à la bibliothèque complète).
  const cats = relevantCats.concat(Object.keys(CAT_META).filter(c => relevantCats.indexOf(c) < 0));
  let html = searchInput;
  cats.forEach(cat => {
    const group = available.filter(s => s.cat === cat);
    if (!group.length) return;
    const cm = CAT_META[cat] || {ic:'', l:cat, c:'#666'};
    html += '<div style="font-size:.58rem;font-weight:700;color:'+cm.c+';text-transform:uppercase;letter-spacing:.07em;margin:.55rem 0 .28rem;display:flex;align-items:center;gap:.3rem">'
      + '<span>'+cm.ic+'</span><span>'+cm.l+'</span>'
      + '</div>';
    group.forEach(s => {
      const safeNom = s.nom.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
      html += '<div style="display:flex;align-items:center;gap:.5rem;padding:.38rem .5rem;border-radius:.6rem;background:rgba(46,102,66,.03);border:1px solid rgba(46,102,66,.08);margin-bottom:.2rem">'
        + '<span style="font-size:.88rem;flex-shrink:0">' + s.img + '</span>'
        + '<div style="flex:1;min-width:0">'
        + '<div style="font-size:.68rem;font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + s.nom + '</div>'
        + '<div style="font-size:.57rem;color:var(--moss);opacity:.65">' + (s.impact || '') + '</div>'
        + '</div>'
        + '<button onclick="creerOpenSolDetail(\''+safeNom+'\')" style="flex-shrink:0;padding:.25rem .45rem;border-radius:.45rem;border:1.5px solid rgba(46,102,66,.2);background:transparent;color:var(--forest);font-size:.6rem;cursor:pointer">👁</button>'
        + '<button onclick="creerAddSol('+espIdx+',\''+safeNom+'\')" style="flex-shrink:0;padding:.3rem .65rem;border-radius:.45rem;border:none;background:var(--forest);color:white;font-size:.66rem;font-weight:700;cursor:pointer">+ Ajouter</button>'
        + '</div>';
    });
  });
  return html;
}

function togEsp(id,btn){
  const i=cData.espaces.indexOf(id);
  if(i>=0)cData.espaces.splice(i,1);else cData.espaces.push(id);
  mmEspaces(); renderStep();
}
function togEspace(id){
  const i=cData.espaces.indexOf(id);
  if(i>=0)cData.espaces.splice(i,1);else cData.espaces.push(id);
  renderStep();
}
function computeCircularLinks(espaces) {
  const links = [];
  for (let i = 0; i < espaces.length; i++) {
    for (let j = 0; j < espaces.length; j++) {
      if (i === j) continue;
      const shared = (espaces[i].outputs || []).filter(fid => (espaces[j].inputs || []).includes(fid));
      if (shared.length) {
        links.push({ from: espaces[i], fromIdx: i, to: espaces[j], toIdx: j, fluxIds: shared });
      }
    }
  }
  return links;
}

function mmDrawCircularLinks(espItems, links) {
  if (!links.length) return;
  setTimeout(() => {
    const svg = document.getElementById('mm-svg');
    const nodes = document.getElementById('mm-nodes');

    // Inject arrow marker once
    if (!document.getElementById('arrow-circ')) {
      const defs = document.createElementNS('http://www.w3.org/2000/svg','defs');
      defs.innerHTML = `<marker id="arrow-circ" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#2e9970" opacity=".8"/></marker>`;
      svg.insertBefore(defs, svg.firstChild);
    }

    links.forEach(({ from, to, fluxIds }, li) => {
      const fromItem = espItems.find(x => x.esp === from);
      const toItem   = espItems.find(x => x.esp === to);
      if (!fromItem || !toItem) return;
      const fromEl = document.getElementById('mn-e-' + fromItem.eid);
      const toEl   = document.getElementById('mn-e-' + toItem.eid);
      if (!fromEl || !toEl) return;

      const x1 = parseFloat(fromEl.style.left), y1 = parseFloat(fromEl.style.top);
      const x2 = parseFloat(toEl.style.left),   y2 = parseFloat(toEl.style.top);
      // Control point, offset perpendicular to segment
      const cx = (x1+x2)/2 + (y2-y1)*0.35;
      const cy = (y1+y2)/2 - (x2-x1)*0.35;
      // Midpoint on the quadratic bezier at t=0.5
      const mx = 0.25*x1 + 0.5*cx + 0.25*x2;
      const my = 0.25*y1 + 0.5*cy + 0.25*y2;

      // Draw curved dashed path
      const path = document.createElementNS('http://www.w3.org/2000/svg','path');
      path.setAttribute('d', `M ${x1} ${y1} Q ${cx} ${cy} ${x2} ${y2}`);
      path.setAttribute('stroke','#2e9970');
      path.setAttribute('stroke-width','1.8');
      path.setAttribute('stroke-dasharray','5,4');
      path.setAttribute('fill','none');
      path.setAttribute('opacity','0.7');
      path.setAttribute('marker-end','url(#arrow-circ)');
      svg.appendChild(path);

      // Flux label node at curve midpoint
      const fluxObjs = fluxIds.map(fid => FLUX_CATALOG.find(x => x.id === fid)).filter(Boolean);
      const label = fluxObjs.map(f => f.ic + ' ' + f.label).join(' · ');
      const pill = document.createElement('div');
      pill.className = 'mm-circ-flux';
      pill.style.cssText = `position:absolute;left:${mx}px;top:${my}px;transform:translate(-50%,-50%);
        background:rgba(46,153,112,.12);border:1px solid rgba(46,153,112,.35);border-radius:100px;
        padding:.2rem .55rem;font-size:.58rem;font-weight:600;color:#2e9970;white-space:nowrap;
        pointer-events:none;opacity:0;transition:opacity .3s .1s;z-index:5;`;
      pill.textContent = label;
      nodes.appendChild(pill);
      requestAnimationFrame(() => { pill.style.opacity = '1'; });
    });
  }, 320);
}

function creerNext(){if(cStep<3){if(cStep===2)cData._solsReady=false;/* (re)générer → rejoue l'attente Deva */cStep++;renderStep();}}
function creerPrev(){
  // Depuis l'étape Quête : revenir à Solutions (phase espaces) plutôt qu'à Espaces.
  if(cStep===3 && window._creerPhase==='quetes'){ window._creerPhase='espaces'; window._creerMapOverview=false; renderStep(); if(typeof creerUpdateHint==='function') creerUpdateHint(true); return; }
  if(cStep>0){cStep--;renderStep();}
}
// Saut d'étape via le stepper (seules les étapes passées sont cliquables).
function creerGoStep(i){
  if(i===3){ cStep=3; window._creerPhase='espaces'; window._creerMapOverview=false; renderStep(); if(typeof creerUpdateHint==='function') creerUpdateHint(true); return; }
  cStep=i; window._creerPhase='espaces'; renderStep();
}
// Met à jour le stepper (étape Solutions ↔ Quête) sans redessiner le mind map.
function _creerMajStepper(){
  if (cStep !== 3) return;
  const _stepIdx = (window._creerPhase === 'quetes') ? 4 : 3;
  navWizardSet(STEPS.map(s=>s.t), _stepIdx, creerGoStep);
  _creerMajNav();
}

// Barre du bas : « Retour » + bouton d'action contextuel (Suivant / Générer les
// solutions / Générer les quêtes / Créer mon lieu). Le bouton « Créer le lieu »
// du bandeau haut est masqué (déplacé ici).
function _creerMajNav(){
  const prev = document.getElementById('creer-prev');
  const nx = document.getElementById('creer-next');
  const sv = document.getElementById('creer-save-btn');
  if (sv) sv.style.display = 'none';
  if (prev) prev.style.display = cStep > 0 ? 'block' : 'none';
  if (!nx) return;
  const show = (txt, fn) => { nx.style.display = 'block'; nx.textContent = txt; nx.onclick = fn; };
  if (cStep < 2) { show('Suivant →', creerNext); return; }
  if (cStep === 2) { show('Générer les solutions ✦', creerNext); return; }
  if (cStep === 3) {
    if (window._creerPhase === 'quetes') { show('Publier ma fiche →', function(){ openPublishPreview('lieu'); }); return; }
    // Phase espaces : « Générer les quêtes » seulement quand tous les espaces sont parcourus.
    const espItems = window._creerEspItems || [], valides = cData.espacesValides || [];
    if (espItems.length && valides.length >= espItems.length) show('Générer les quêtes ✦', creerGenererQuetes);
    else nx.style.display = 'none';
    return;
  }
  nx.style.display = 'none';
}

