/* ─── MIND MAP ─── */
function mmW(){return document.getElementById('mm-nodes').parentElement.offsetWidth;}
function mmH(){return document.getElementById('mm-nodes').parentElement.offsetHeight;}

function initMM(){
  if (window.mmPanReset) window.mmPanReset();
  window._mmGen = (window._mmGen || 0) + 1;   // annule les timers d'un rendu précédent
  document.getElementById('mm-nodes').innerHTML='';
  document.getElementById('mm-svg').innerHTML='';
  mmAdd('c',cData.nom||'Mon lieu',mmW()/2,mmH()/2,'center');
}

function mmAdd(id,label,x,y,cls,col,bg){
  const el=document.createElement('div');
  el.className='mm-node mm-'+cls; el.id='mn-'+id;
  el.style.left=x+'px'; el.style.top=y+'px';
  if(col){el.style.color=col;el.style.borderColor=col+'55';el.style.background=bg||col+'18';}
  el.textContent=label; el.style.opacity='0'; el.style.transform='translate(-50%,-50%) scale(.7)';
  document.getElementById('mm-nodes').appendChild(el);
  requestAnimationFrame(()=>{el.style.transition='opacity .35s,transform .35s';el.style.opacity='1';el.style.transform='translate(-50%,-50%) scale(1)';});
  return el;
}

// Courbe organique (branche) entre deux points : léger arc perpendiculaire.
function mmCurve(x1,y1,x2,y2){
  const mx=(x1+x2)/2, my=(y1+y2)/2;
  const dx=x2-x1, dy=y2-y1;
  const bend=0.14;
  return 'M '+x1+' '+y1+' Q '+(mx-dy*bend)+' '+(my+dx*bend)+' '+x2+' '+y2;
}

function mmLine(x1,y1,x2,y2,col,dash,fromId,toId){
  const l=document.createElementNS('http://www.w3.org/2000/svg','path');
  l.setAttribute('d', mmCurve(x1,y1,x2,y2));
  l.setAttribute('fill','none');
  l.setAttribute('stroke',col || 'rgba(46,102,66,.32)');
  l.setAttribute('stroke-width', dash ? '1.7' : '2.1');
  if(dash) l.setAttribute('stroke-dasharray','1,7');   // pointillés « graines »
  l.setAttribute('stroke-linecap','round');
  l.setAttribute('opacity', dash ? '0.7' : '0.9');
  l.setAttribute('data-x1',x1); l.setAttribute('data-y1',y1);
  l.setAttribute('data-x2',x2); l.setAttribute('data-y2',y2);
  if(fromId) l.setAttribute('data-from', fromId);
  if(toId) l.setAttribute('data-to', toId);
  document.getElementById('mm-svg').appendChild(l);
  return l;
}

// Met à jour les extrémités des branches connectées à un nœud déplacé.
function mmUpdateLinesFor(domId, x, y){
  const svg = document.getElementById('mm-svg'); if(!svg) return;
  const redraw = (l)=>{ l.setAttribute('d', mmCurve(+l.getAttribute('data-x1'), +l.getAttribute('data-y1'), +l.getAttribute('data-x2'), +l.getAttribute('data-y2'))); };
  svg.querySelectorAll('path[data-from="'+domId+'"]').forEach(l=>{ l.setAttribute('data-x1', x); l.setAttribute('data-y1', y); redraw(l); });
  svg.querySelectorAll('path[data-to="'+domId+'"]').forEach(l=>{ l.setAttribute('data-x2', x); l.setAttribute('data-y2', y); redraw(l); });
  // Compatibilité : lignes droites résiduelles (anciens rendus)
  svg.querySelectorAll('line[data-from="'+domId+'"]').forEach(l=>{ l.setAttribute('x1', x); l.setAttribute('y1', y); });
  svg.querySelectorAll('line[data-to="'+domId+'"]').forEach(l=>{ l.setAttribute('x2', x); l.setAttribute('y2', y); });
}

/* ─── Déplacement des nœuds du mind map de création (drag) ─── */
(function(){
  let drag=null, sx0=0, sy0=0, nx0=0, ny0=0, moved=false;
  document.addEventListener('mousedown', e=>{
    const node = e.target.closest('#mm-nodes .mm-node');
    if(!node) return;
    drag=node; moved=false;
    sx0=e.clientX; sy0=e.clientY;
    nx0=parseFloat(node.style.left)||0; ny0=parseFloat(node.style.top)||0;
    node.style.zIndex='60'; node.style.cursor='grabbing'; node.style.transition='none';
    e.preventDefault(); e.stopPropagation();
  }, true);
  document.addEventListener('mousemove', e=>{
    if(!drag) return;
    const dx=e.clientX-sx0, dy=e.clientY-sy0;
    if(Math.abs(dx)>3||Math.abs(dy)>3) moved=true;
    const nx=nx0+dx, ny=ny0+dy;
    drag.style.left=nx+'px'; drag.style.top=ny+'px';
    mmUpdateLinesFor(drag.id, nx, ny);
  });
  document.addEventListener('mouseup', ()=>{
    if(!drag) return;
    drag.style.zIndex=''; drag.style.cursor=''; drag.style.transition='';
    if(moved){ window._mmJustDragged=true; setTimeout(()=>{ window._mmJustDragged=false; }, 60); }
    drag=null;
  });
  // Empêche le clic (togSol) juste après un déplacement.
  document.addEventListener('click', e=>{
    if(window._mmJustDragged && e.target.closest('#mm-nodes .mm-node')){ e.stopPropagation(); e.preventDefault(); }
  }, true);
})();

function mmCenter(){
  const el=document.getElementById('mn-c');
  if(!el) return;
  const type=TYPES_LIEU.find(t=>t.id===cData.type);
  const ic=type?.ic||'';
  const loc=cData.localisation?`<div style="font-size:.55rem;opacity:.7;margin-top:1px">📍 ${cData.localisation}</div>`:'';
  const typeLabel=type?(type.id==='autre'&&cData.autreType?cData.autreType:type.l):'';
  const typeLine=typeLabel?`<div style="font-size:.58rem;opacity:.8;margin-top:2px;font-weight:500">${typeLabel}</div>`:'';
  el.innerHTML=`<div style="font-weight:700">${cData.nom||'Mon lieu'}${ic?' · '+ic:''}</div>${typeLine}${loc}`;
}

function mmEspaces(){
  window._mmGen = (window._mmGen || 0) + 1;   // annule les timers d'un rendu précédent (genMM)
  document.querySelectorAll('[id^="mn-e-"],[id^="mn-a-"],[id^="mn-sol-"],[id^="mn-ici-"]').forEach(e=>e.remove());
  document.getElementById('mm-svg').innerHTML='';
  const W=mmW(),H=mmH(),cx=W/2,cy=H/2;
  cData.espaces.forEach((eid,i)=>{
    const e=ESPS.find(x=>x.id===eid)||{l:eid,ic:'📦',c:'#4a8c5c',bg:'rgba(74,140,92,.1)'};
    const a=(2*Math.PI/cData.espaces.length)*i-Math.PI/2;
    const r=Math.min(W,H)*.27; const x=cx+r*Math.cos(a),y=cy+r*Math.sin(a);
    mmLine(cx,cy,x,y,e.c+'88');
    mmAdd('e-'+eid,e.ic+' '+e.l,x,y,'espace',e.c,e.bg);
  });
}

const MM_DOMAINE_STYLE = {
  Alimentation:    { c:'#7a5010', bg:'rgba(200,140,42,0.12)' },
  Travail:         { c:'#1a3a5a', bg:'rgba(58,110,140,0.12)' },
  Fabrication:     { c:'#1a3a5a', bg:'rgba(58,110,140,0.12)' },
  Culture:         { c:'#5a3a80', bg:'rgba(122,100,168,0.12)' },
  Commerce:        { c:'#903060', bg:'rgba(180,78,100,0.12)' },
  Formation:       { c:'#2e6020', bg:'rgba(74,140,92,0.12)' },
  Nature:          { c:'#1a6040', bg:'rgba(26,112,80,0.12)' },
  Habitat:         { c:'#5a3a80', bg:'rgba(122,100,168,0.12)' },
  Santé:           { c:'#2e6020', bg:'rgba(74,140,92,0.12)' },
  Logistique:      { c:'#4a4a4a', bg:'rgba(74,74,74,0.10)' },
  Fonctionnement:  { c:'#2a6a8a', bg:'rgba(42,106,138,0.12)' },
  Autre:           { c:'#4a8c5c', bg:'rgba(74,140,92,0.10)' },
};

function mmEspacesData() {
  window._mmGen = (window._mmGen || 0) + 1;   // annule les timers d'un rendu précédent (genMM)
  document.querySelectorAll('[id^="mn-ed-"]').forEach(e => e.remove());
  document.querySelectorAll('[id^="mn-e-"],[id^="mn-sol-"],[id^="mn-ici-"]').forEach(e => e.remove());
  document.getElementById('mm-svg').innerHTML = '';
  const data = cData.espacesData;
  if (!data.length) return;
  const W = mmW(), H = mmH(), cx = W/2, cy = H/2;
  data.forEach((esp, i) => {
    const fn = FONCTIONS_ESPACE.find(f => f.id === esp.fonctions[0]);
    const style = MM_DOMAINE_STYLE[fn?.domaine] || MM_DOMAINE_STYLE.Autre;
    const ic = fn ? fn.ic : '📦';
    const a = (2*Math.PI/data.length)*i - Math.PI/2;
    const r = Math.min(W,H)*.27;
    const x = cx + r*Math.cos(a), y = cy + r*Math.sin(a);
    mmLine(cx, cy, x, y, style.c+'88');
    mmAdd('ed-'+i, ic+' '+esp.nom, x, y, 'espace', style.c, style.bg);
  });
}

function mmActivites(){
  document.querySelectorAll('[id^="mn-a-"]').forEach(e=>e.remove());
  document.getElementById('mm-svg').innerHTML='';
  const W=mmW(),H=mmH(),cx=W/2,cy=H/2;
  const esps=cData.espaces;
  esps.forEach((eid,i)=>{
    const e=ESPS.find(x=>x.id===eid)||{l:eid,ic:'📦',c:'#4a8c5c',bg:'rgba(74,140,92,.1)'};
    const ae=(2*Math.PI/esps.length)*i-Math.PI/2;
    const re=Math.min(W,H)*.26; const ex=cx+re*Math.cos(ae),ey=cy+re*Math.sin(ae);
    mmLine(cx,cy,ex,ey,e.c+'88');
    const acts=(ESP_ACTS[eid]||[]).filter(a=>cData.activites.includes(a));
    acts.forEach((act,j)=>{
      const sa=ae+(j-(acts.length-1)/2)*.42;
      const rs=re+88; const sx=cx+rs*Math.cos(sa),sy=cy+rs*Math.sin(sa);
      mmLine(ex,ey,sx,sy,e.c+'44',true);
      mmAdd('a-'+eid+'-'+j,act,sx,sy,'sol',e.c,e.bg);
    });
  });
}

function devaPickSols(esps){
  const picked=[]; const seen=new Set();
  esps.forEach(eid=>{
    const e=ESPS.find(x=>x.id===eid);
    if(!e)return;
    (e.sols||[]).forEach(sname=>{
      if(!seen.has(sname)){
        const sol=SOLS.find(s=>s.nom===sname);
        if(sol){picked.push({sol,eid});seen.add(sname);}
      }
    });
  });
  return picked;
}

function togSol(nom){
  const i=cData.solutions.indexOf(nom);
  const wasSel=i>=0;
  if(wasSel)cData.solutions.splice(i,1); else cData.solutions.push(nom);
  const nowSel=!wasSel;
  // Update MM node
  document.querySelectorAll('[id^="mn-sol-"]').forEach(el=>{
    if(el.dataset.solnom===nom){
      const e=ESPS.find(x=>x.id===el.dataset.eid)||{c:'#4a8c5c',bg:'rgba(74,140,92,.1)'};
      el.style.color=nowSel?e.c:'rgba(130,130,130,.55)';
      el.style.borderColor=nowSel?e.c+'55':'rgba(130,130,130,.2)';
      el.style.background=nowSel?e.bg:'rgba(130,130,130,.05)';
      el.style.fontWeight=nowSel?'600':'400';
      mmIciNodes(nom, parseFloat(el.style.left), parseFloat(el.style.top), el.id);
    }
  });
  // Update panel row in-place
  const rid='sol-row-'+nom.replace(/[^a-zA-Z0-9]/g,'_');
  const row=document.getElementById(rid);
  if(row){
    const e=ESPS.find(x=>x.id===row.dataset.eid)||{c:'#4a8c5c',bg:'rgba(74,140,92,.1)'};
    row.style.background=nowSel?e.bg:'rgba(130,130,130,.04)';
    row.style.borderColor=nowSel?e.c+'33':'rgba(130,130,130,.12)';
    const nameEl=row.querySelector('.sol-name');
    if(nameEl)nameEl.style.color=nowSel?'var(--ink)':'rgba(130,130,130,.65)';
    const chkEl=row.querySelector('.sol-chk');
    if(chkEl){chkEl.textContent=nowSel?'✓':'○';chkEl.style.color=nowSel?e.c:'rgba(130,130,130,.35)';}
  }
  // Update counter + Deva message
  const counter=document.getElementById('sol-counter');
  if(counter)counter.textContent=cData.solutions.length+' solution'+(cData.solutions.length!==1?'s':'')+' sélectionnée'+(cData.solutions.length!==1?'s':'');
  const devaTxt=document.querySelector('.deva-txt');
  if(devaTxt)devaTxt.textContent='"Avec '+cData.solutions.length+' solution'+(cData.solutions.length!==1?'s':'')+', '+(cData.nom||'ton lieu')+' peut atteindre une Vadance de '+(10+cData.solutions.length*5)+'/100 dès la première année."';
  if (typeof creerUpdateVadance === 'function') creerUpdateVadance();
}

function genMM(espItems){
  if (window.mmPanReset) window.mmPanReset();
  document.getElementById('mm-nodes').innerHTML='';
  document.getElementById('mm-svg').innerHTML='';
  // Jeton de génération : les nœuds sont ajoutés en différé (setTimeout) pour
  // l'animation ; si un autre rendu du mind map survient entre-temps (ex. clic
  // « Retour »), les timers de CE rendu doivent s'annuler pour ne pas dédoubler.
  window._mmGen = (window._mmGen || 0) + 1;
  const _gen = window._mmGen;
  window._mmCollapsed = {};   // espaces repliés (clic sur l'espace = replier/déplier)
  const W=mmW(),H=mmH(),cx=W/2,cy=H/2;
  mmAdd('c',cData.nom||'Mon lieu',cx,cy,'center');

  // Compatibilité : si on reçoit un tableau d'eids (ancienne signature), convertir
  const items = (espItems.length && typeof espItems[0] === 'string')
    ? espItems.map(eid => ({ esp:{nom:eid}, eid, ic:'📦', c:'#4a8c5c', bg:'rgba(74,140,92,.1)' }))
    : espItems;

  // Use only user-assigned solutions (cData.solsByEspace), no pre-fill
  const byEsp={};
  items.forEach((_,i)=>{
    const noms = (cData.solsByEspace && cData.solsByEspace[i]) || [];
    byEsp[i] = noms.map(n=>SOLS.find(s=>s.nom===n)).filter(Boolean);
  });
  const picked = Object.values(byEsp).flat();

  // Store esp positions for step-4 live refresh
  window._mmStep4State = { cx, cy, W, H };
  window._mmStep4Items = items;
  window._mmStep4EspPos = items.map((item,i)=>{
    const a=(2*Math.PI/items.length)*i-Math.PI/2;
    const re=Math.min(W,H)*.22;
    return { x:cx+re*Math.cos(a), y:cy+re*Math.sin(a), a, re, item, idx:i };
  });

  items.forEach((item,i)=>{
    const {esp, ic, c:col, bg} = item;
    const label = ic + ' ' + (esp.nom || esp.l || item.eid);
    const a=(2*Math.PI/items.length)*i-Math.PI/2;
    const re=Math.min(W,H)*.22; const ex=cx+re*Math.cos(a),ey=cy+re*Math.sin(a);
    const sols=byEsp[i]||[];
    setTimeout(()=>{
      if (_gen !== window._mmGen) return;   // rendu périmé (on a changé d'étape)
      mmLine(cx,cy,ex,ey,col+'99',false,'mn-c','mn-e-'+i);
      const eNode=mmAdd('e-'+i,label,ex,ey,'espace',col,bg);
      eNode.style.cursor='pointer';
      eNode.title='Replier / déplier les solutions';
      eNode.onclick=()=>mmToggleEspace(i);
      sols.forEach((sol,j)=>{
        const sa=a+(j-(sols.length-1)/2)*_mmSolSpread(sols.length); const rs=re+185;
        const sx=cx+rs*Math.cos(sa),sy=cy+rs*Math.sin(sa);
        const isSel=cData.solutions.includes(sol.nom);
        const solDomId='mn-sol-'+i+'-'+j;
        setTimeout(()=>{
          if (_gen !== window._mmGen) return;   // rendu périmé
          if (window._mmCollapsed && window._mmCollapsed[i]) return;   // espace replié entre-temps
          mmLine(ex,ey,sx,sy,col+'55',true,'mn-e-'+i,solDomId);
          const sc=isSel?col:'rgba(130,130,130,.55)';
          const sb=isSel?bg:'rgba(130,130,130,.05)';
          const nd=mmAdd('sol-'+i+'-'+j,sol.img+' '+sol.nom,sx,sy,'sol',sc,sb);
          nd.dataset.solnom=sol.nom; nd.dataset.eid=item.eid;
          if(isSel){nd.style.fontWeight='600';nd.classList.add('sol-sel');}
          nd.style.cursor='grab';
          nd.title=sol.impact;
          // Les solutions ne sont pas cliquables sur le mind map (retrait via la sidebar).
          mmIciNodes(sol.nom, sx, sy, solDomId);
        },j*140);
      });
    },i*220);
  });
}

/* Sous-nœuds ICI sous une solution sélectionnée (mind map de création).
   DÉSACTIVÉS (simplification solarpunk) : la 3e couronne d'indicateurs
   surchargeait la carte ; les ICI vivent dans l'onglet « Indicateurs » de
   l'étape et dans la Bibliothèque. On garde la fonction (appels en place)
   pour nettoyer d'éventuels restes d'un ancien rendu. */
function mmIciNodes(solNom, sx, sy, solDomId){
  const safe = String(solNom).replace(/[^a-zA-Z0-9]/g, '_');
  document.querySelectorAll('[id^="mn-ici-' + safe + '-"]').forEach(e => e.remove());
  document.querySelectorAll('line[data-ici="' + safe + '"]').forEach(e => e.remove());
  return;
  if (!(cData.solutions || []).includes(solNom)) return;
  const icis = (typeof iciPourSolution === 'function') ? iciPourSolution(solNom) : [];
  if (!icis.length) return;
  const st = window._mmStep4State || { cx: mmW() / 2, cy: mmH() / 2 };
  const cx = st.cx, cy = st.cy;
  const baseA = Math.atan2(sy - cy, sx - cx);
  const rIci = Math.hypot(sx - cx, sy - cy) + 128;
  const svg = document.getElementById('mm-svg');
  icis.forEach((ici, k) => {
    const meta = (typeof ICI_LIVRE_META !== 'undefined' ? ICI_LIVRE_META[ici.livre] : null) || { ic: '◆', col: '#4a8c5c' };
    const ia = baseA + (k - (icis.length - 1) / 2) * 0.66;
    const ix = cx + rIci * Math.cos(ia), iy = cy + rIci * Math.sin(ia);
    const iciDomId = 'mn-ici-' + safe + '-' + k;
    const l = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    l.setAttribute('x1', sx); l.setAttribute('y1', sy); l.setAttribute('x2', ix); l.setAttribute('y2', iy);
    l.setAttribute('stroke', meta.col + '66'); l.setAttribute('stroke-width', '1.6');
    l.setAttribute('stroke-dasharray', '3,4'); l.setAttribute('stroke-linecap', 'round'); l.setAttribute('opacity', '0.85');
    l.setAttribute('data-ici', safe);
    if (solDomId) l.setAttribute('data-from', solDomId);
    l.setAttribute('data-to', iciDomId);
    if (svg) svg.appendChild(l);
    const nd = mmAdd('ici-' + safe + '-' + k, meta.ic + ' ' + ici.nom, ix, iy, 'ici', meta.col, meta.col + '22');
    nd.style.fontSize = '.6rem'; nd.style.padding = '.2rem .45rem'; nd.style.fontWeight = '700'; nd.style.borderColor = meta.col + '66'; nd.style.cursor = 'grab';
    nd.title = (ici.unite || '') + ' · cible ' + ((typeof iciPoint100For === 'function') ? iciPoint100For(ici) : ici.point100);
  });
}

// Clic sur un espace de la carte : replie/déplie ses solutions.
function mmToggleEspace(idx){
  window._mmCollapsed = window._mmCollapsed || {};
  window._mmCollapsed[idx] = !window._mmCollapsed[idx];
  mmRefreshSolsStep4();
}

function mmRefreshSolsStep4() {
  if (!window._mmStep4EspPos || !window._mmStep4State) return;
  // Remove all solution + ICI nodes
  document.querySelectorAll('[id^="mn-sol-"],[id^="mn-ici-"]').forEach(e => e.remove());
  // Rebuild SVG (espace lines + solution branches)
  const svg = document.getElementById('mm-svg');
  svg.innerHTML = '';
  const { cx, cy } = window._mmStep4State;
  window._mmStep4EspPos.forEach(({ x:ex, y:ey, a, re, item, idx }) => {
    const { c:col, bg } = item;
    // Position actuelle du nœud espace (il a pu être déplacé à la main).
    const eEl = document.getElementById('mn-e-'+idx);
    if (eEl) { ex = parseFloat(eEl.style.left) || ex; ey = parseFloat(eEl.style.top) || ey; }
    mmLine(cx, cy, ex, ey, col+'99', false, 'mn-c', 'mn-e-'+idx);
    // Espace replié : on garde la branche vers le centre, pas les solutions.
    const closed = !!(window._mmCollapsed && window._mmCollapsed[idx]);
    if (eEl) eEl.classList.toggle('mm-esp-closed', closed);
    if (closed) return;
    const solNoms = cData.solsByEspace[idx] || [];
    solNoms.forEach((solNom, j) => {
      const sol = SOLS.find(s => s.nom === solNom);
      if (!sol) return;
      const sa = a + (j - (solNoms.length-1)/2) * _mmSolSpread(solNoms.length);
      const rs = re + 185;
      const sx = cx + rs*Math.cos(sa), sy = cy + rs*Math.sin(sa);
      const solDomId = 'mn-sol-'+idx+'-'+j;
      mmLine(ex, ey, sx, sy, col+'55', true, 'mn-e-'+idx, solDomId);
      const nd = mmAdd('sol-'+idx+'-'+j, sol.img+' '+sol.nom, sx, sy, 'sol', col, bg);
      nd.dataset.solnom = sol.nom;
      nd.dataset.eid = item.eid;
      nd.style.fontWeight = '600';
      nd.style.cursor = 'grab';
      nd.title = sol.impact || '';
      // Les solutions ne sont pas cliquables sur le mind map (retrait via la sidebar).
      mmIciNodes(sol.nom, sx, sy, solDomId);
    });
  });
}

/* ─── Pan + zoom du canvas mind map ─── */
(function () {
  let panning = false, px = 0, py = 0, tx = 0, ty = 0, sc = 1;

  function getCanvas() { return document.getElementById('mm-canvas'); }
  function getStage()  { return document.getElementById('mm-nodes')?.closest('.mm-stage'); }

  function applyTransform() {
    const c = getCanvas();
    if (c) { c.style.transformOrigin = '50% 50%'; c.style.transform = `translate(${tx}px,${ty}px) scale(${sc})`; }
  }

  // Expose pour que genMM puisse remettre à zéro et pour le focus par espace.
  window.mmPanReset = function () { tx = 0; ty = 0; sc = 1; const c = getCanvas(); if (c) c.style.transition = 'none'; applyTransform(); };
  window.mmSetView  = function (nx, ny, ns) { const c = getCanvas(); if (c) c.style.transition = 'transform .55s cubic-bezier(.4,0,.2,1)'; tx = nx; ty = ny; if (ns != null) sc = ns; applyTransform(); };
  window.mmGetView  = function () { return { tx: tx, ty: ty, sc: sc }; };

  document.addEventListener('mousedown', e => {
    const stage = getStage(); if (!stage || !stage.contains(e.target)) return;
    // Ignorer un nœud, un bouton, le tableau flux, ET le panneau latéral +
    // ses champs de formulaire (sinon preventDefault bloque le focus/la saisie).
    if (e.target.closest('.mm-node, button, #mm-flux-table, #mm-flux-handle, #creer-side-panel, input, textarea, select, label, a')) return;
    panning = true;
    const c = getCanvas(); if (c) c.style.transition = 'none';
    px = e.clientX - tx;
    py = e.clientY - ty;
    stage.style.cursor = 'grabbing';
    e.preventDefault();
  });

  document.addEventListener('mousemove', e => {
    if (!panning) return;
    tx = e.clientX - px;
    ty = e.clientY - py;
    applyTransform();
  });

  document.addEventListener('mouseup', () => {
    if (!panning) return;
    panning = false;
    const stage = getStage(); if (stage) stage.style.cursor = 'grab';
  });
})();

/* ─── Focus du mind map sur l'espace actif (étape 3, flux guidé) ─── */
// Zoome/centre le canvas sur l'espace `window._creerActiveEsp`, atténue les
// autres espaces et révèle quête + indicateurs de chaque solution retenue.
function creerApplyMapFocus(){
  // Vue d'ensemble demandée (bouton) : tout le mind map, sans zoom ni atténuation.
  if (window._creerMapOverview && window._creerPhase !== 'quetes') {
    if (window.mmPanReset) window.mmPanReset();
    mmSetDim(null); mmRevealEsp(null);
    return;
  }
  // Phase QUÊTES : vue d'ensemble, sans zoom ni atténuation, et on révèle les
  // quêtes choisies pour tous les espaces.
  if (window._creerPhase === 'quetes') {
    if (window.mmPanReset) window.mmPanReset();
    mmSetDim(null);
    // Les quêtes n'apparaissent qu'une fois Deva a terminé de composer.
    if (window._creerQuetesReady) mmRevealQuetesAll(); else mmRevealEsp(null);
    return;
  }
  const idx = window._creerActiveEsp;
  const st = window._mmStep4State, pos = window._mmStep4EspPos;
  if (idx == null || !st || !pos || !pos[idx]) {
    if (window.mmPanReset) window.mmPanReset();
    mmSetDim(null); mmRevealEsp(null);
    return;
  }
  const ep = pos[idx];
  // Cadrage automatique : emprise de l'espace + TOUTES ses solutions (mêmes
  // formules de position que mmRefreshSolsStep4) + marge pour les nœuds
  // indicateurs révélés autour, puis zoom ajusté pour que tout soit visible.
  const eEl = document.getElementById('mn-e-' + idx);
  let ex = ep.x, ey = ep.y;
  if (eEl) { ex = parseFloat(eEl.style.left) || ex; ey = parseFloat(eEl.style.top) || ey; }
  const solNoms = (cData.solsByEspace && cData.solsByEspace[idx]) || [];
  const pts = [[ex, ey]];
  const n = solNoms.length;
  for (let j = 0; j < n; j++) {
    const sa = ep.a + (j - (n - 1) / 2) * _mmSolSpread(n);
    const rs = ep.re + 185;
    pts.push([st.cx + rs * Math.cos(sa), st.cy + rs * Math.sin(sa)]);
  }
  const pad = 100;   // demi-largeur des étiquettes des nœuds solution
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  pts.forEach(p => {
    minX = Math.min(minX, p[0] - pad); maxX = Math.max(maxX, p[0] + pad);
    minY = Math.min(minY, p[1] - pad); maxY = Math.max(maxY, p[1] + pad);
  });
  const s = Math.max(0.85, Math.min(1.5, Math.min((st.W - 30) / (maxX - minX), (st.H - 30) / (maxY - minY))));
  const fx = (minX + maxX) / 2, fy = (minY + maxY) / 2;
  if (window.mmSetView) window.mmSetView(s * (st.cx - fx), s * (st.cy - fy), s);
  mmRevealEsp(idx);
  mmSetDim(idx);
}

// Quêtes sur mesure (créées via « Nouvelle quête ») du lieu en cours de
// création, rattachées à un espace (espIdx). Source : PILOTE_QUETES_DEMO en
// mémoire + store (dédupliqué par id), hors quêtes retirées.
function _creerCustomQuetes(){
  const draftId = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.id) || 'lieu-demo';
  const seen = {}, out = [];
  const add = q => {
    if (q && q.custom && q.espIdx != null && q.statut !== 'retiree' && !seen[q.id]) { seen[q.id] = 1; out.push(q); }
  };
  if (typeof PILOTE_QUETES_DEMO !== 'undefined') PILOTE_QUETES_DEMO.forEach(add);
  if (window.store) store.where('quetes', r => r.custom === true && r.espIdx != null && r.statut !== 'retiree'
    && (r.lieu_id === draftId || r.lieu_id === 'lieu-demo' || r.lieu_id === 'draft')).forEach(add);
  return out;
}

// Quêtes rattachées à l'espace `idx` qui n'ont pas de nœud solution propre :
// quêtes ajoutées depuis la biblio (via quetesEspMap) + quêtes sur mesure.
function _creerQuetesEspaceExtra(idx){
  const retirQ = new Set(cData.quetesRetirees || []);
  const qEsp = cData.quetesEspMap || {};
  const out = [];
  (cData.quetesAjoutees || []).forEach(nom => {
    if (qEsp[nom] !== idx || retirQ.has('sol:' + nom)) return;
    const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === nom) : null;
    if (sol && sol.quete) out.push({ titre: sol.quete.titre || nom });
  });
  _creerCustomQuetes().forEach(q => { if (q.espIdx === idx) out.push({ titre: q.titre || 'Quête' }); });
  return out;
}

// Phase quêtes : révèle la quête de chaque solution de tous les espaces.
function mmRevealQuetesAll(){
  document.querySelectorAll('#mm-nodes [id^="mn-q-"], #mm-nodes [id^="mn-ici-"]').forEach(n => n.remove());
  document.querySelectorAll('#mm-svg path[data-reveal="1"]').forEach(p => p.remove());
  const st = window._mmStep4State; if (!st) return;
  const cx = st.cx, cy = st.cy;
  const retirQ = new Set(cData.quetesRetirees || []);
  document.querySelectorAll('#mm-nodes [id^="mn-sol-"]').forEach(sn => {
    const solNom = sn.dataset.solnom; if (!solNom || retirQ.has('sol:' + solNom)) return;
    const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === solNom) : null;
    if (!sol || !sol.quete) return;
    const sx = parseFloat(sn.style.left), sy = parseFloat(sn.style.top);
    if (isNaN(sx) || isNaN(sy)) return;
    let dx = sx - cx, dy = sy - cy; const dl = Math.hypot(dx, dy) || 1; dx /= dl; dy /= dl;
    const base = sn.id.replace('mn-sol-', '');
    const qx = sx + dx * 112, qy = sy + dy * 112;
    const p = mmLine(sx, sy, qx, qy, '#c8732a', '3,5', 'mn-sol-' + base, 'mn-q-' + base);
    if (p) p.setAttribute('data-reveal', '1');
    mmAdd('q-' + base, '⚡ ' + (sol.quete.titre || 'Quête'), qx, qy, 'quete', '#c8732a', 'rgba(200,115,42,.14)');
  });
  // Quêtes rattachées directement à un espace (sans nœud solution) : quêtes
  // ajoutées depuis la biblio + quêtes créées sur mesure. Elles rayonnent
  // autour du nœud espace.
  document.querySelectorAll('#mm-nodes [id^="mn-e-"]').forEach(eEl => {
    const m = (eEl.id || '').match(/^mn-e-(\d+)$/); if (!m) return;
    const idx = +m[1];
    const extra = _creerQuetesEspaceExtra(idx);
    if (!extra.length) return;
    const ex = parseFloat(eEl.style.left), ey = parseFloat(eEl.style.top);
    if (isNaN(ex) || isNaN(ey)) return;
    let edx = ex - cx, edy = ey - cy; const edl = Math.hypot(edx, edy) || 1; edx /= edl; edy /= edl;
    const baseAng = Math.atan2(edy, edx);
    extra.forEach((q, k) => {
      const ang = baseAng + (k - (extra.length - 1) / 2) * 0.42;
      const qx = ex + Math.cos(ang) * 132, qy = ey + Math.sin(ang) * 132;
      const p = mmLine(ex, ey, qx, qy, '#c8732a', '3,5', 'mn-e-' + idx, 'mn-q-' + idx + '-add' + k);
      if (p) p.setAttribute('data-reveal', '1');
      mmAdd('q-' + idx + '-add' + k, '⚡ ' + (q.titre || 'Quête'), qx, qy, 'quete', '#c8732a', 'rgba(200,115,42,.14)');
    });
  });
}

// Atténue tout ce qui n'appartient pas à l'espace `active` (null = tout montrer).
function mmSetDim(active){
  const belongDom = (id) => {
    if (active == null || id === 'mn-c') return true;
    let m;
    if ((m = id.match(/^mn-e-(\d+)$/)))       return +m[1] === active;
    if ((m = id.match(/^mn-sol-(\d+)-\d+$/))) return +m[1] === active;
    if ((m = id.match(/^mn-q-(\d+)-\d+$/)))   return +m[1] === active;
    if ((m = id.match(/^mn-ici-(\d+)-/)))     return +m[1] === active;
    return true;
  };
  document.querySelectorAll('#mm-nodes .mm-node').forEach(n => {
    n.classList.toggle('mm-dim', !belongDom(n.id || ''));
  });
  document.querySelectorAll('#mm-svg path').forEach(p => {
    const from = p.getAttribute('data-from') || '', to = p.getAttribute('data-to') || '';
    const on = active == null || (belongDom(from) && belongDom(to));
    p.style.opacity = on ? '' : '.1';
  });
}

// Révèle (ou nettoie si idx==null) la quête et les indicateurs de chaque
// solution de l'espace `idx`, en nœuds qui rayonnent depuis la solution.
// Écartement angulaire entre solutions d'un même espace, borné à ~⅔ du secteur
// de l'espace pour qu'elles ne débordent pas sur les espaces voisins.
function _mmSolSpread(nSol){
  const nEsp = (window._mmStep4EspPos && window._mmStep4EspPos.length) || 1;
  const maxSpan = ((2 * Math.PI) / Math.max(1, nEsp)) * 0.66;
  return (nSol > 1) ? Math.min(0.6, maxSpan / (nSol - 1)) : 0.6;
}

function mmRevealEsp(idx){
  document.querySelectorAll('#mm-nodes [id^="mn-q-"], #mm-nodes [id^="mn-ici-"]').forEach(n => n.remove());
  document.querySelectorAll('#mm-svg path[data-reveal="1"]').forEach(p => p.remove());
  if (idx == null) return;
  const st = window._mmStep4State; if (!st) return;
  const cx = st.cx, cy = st.cy;
  const retirQ = new Set(cData.quetesRetirees || []);
  const retirI = new Set(cData.icisRetires || []);
  document.querySelectorAll('#mm-nodes [id^="mn-sol-' + idx + '-"]').forEach(sn => {
    const solNom = sn.dataset.solnom; if (!solNom) return;
    const sx = parseFloat(sn.style.left), sy = parseFloat(sn.style.top);
    if (isNaN(sx) || isNaN(sy)) return;
    let dx = sx - cx, dy = sy - cy; const dl = Math.hypot(dx, dy) || 1; dx /= dl; dy /= dl;
    const base = sn.id.replace('mn-sol-', '');           // "idx-j"
    const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === solNom) : null;
    // Quête (au-delà de la solution), seulement en phase quêtes (choisie plus tard).
    // Les indicateurs ne sont plus représentés sur le mind map.
    if (window._creerPhase === 'quetes' && sol && sol.quete && !retirQ.has('sol:' + solNom)) {
      const qx = sx + dx * 118, qy = sy + dy * 118;
      const p = mmLine(sx, sy, qx, qy, '#c8732a', '3,5', 'mn-sol-' + base, 'mn-q-' + base);
      if (p) p.setAttribute('data-reveal', '1');
      mmAdd('q-' + base, '⚡ ' + (sol.quete.titre || 'Quête'), qx, qy, 'quete', '#c8732a', 'rgba(200,115,42,.14)');
    }
  });
  // Quêtes ajoutées depuis la biblio (leur solution n'est pas dans l'espace),
  // rattachées au nœud espace, uniquement en phase quêtes.
  const eEl = document.getElementById('mn-e-' + idx);
  if (eEl && window._creerPhase === 'quetes') {
    const ex = parseFloat(eEl.style.left), ey = parseFloat(eEl.style.top);
    if (!isNaN(ex) && !isNaN(ey)) {
      let edx = ex - cx, edy = ey - cy; const edl = Math.hypot(edx, edy) || 1; edx /= edl; edy /= edl;
      const baseAng = Math.atan2(edy, edx);
      const qEsp = cData.quetesEspMap || {};
      const addedQ = (cData.quetesAjoutees || []).filter(nom => qEsp[nom] === idx && !retirQ.has('sol:' + nom));
      addedQ.forEach((nom, k) => {
        const sol = (typeof SOLS !== 'undefined') ? SOLS.find(s => s.nom === nom) : null;
        if (!sol || !sol.quete) return;
        const ang = baseAng + (k - (addedQ.length - 1) / 2) * 0.4;
        const qx = ex + Math.cos(ang) * 128, qy = ey + Math.sin(ang) * 128;
        const p = mmLine(ex, ey, qx, qy, '#c8732a', '3,5', 'mn-e-' + idx, 'mn-q-' + idx + '-add' + k);
        if (p) p.setAttribute('data-reveal', '1');
        mmAdd('q-' + idx + '-add' + k, '⚡ ' + (sol.quete.titre || 'Quête'), qx, qy, 'quete', '#c8732a', 'rgba(200,115,42,.14)');
      });
    }
  }
}

// Rafraîchit uniquement la révélation quête/ICI (après retrait d'un élément).
function creerMapRevealRefresh(){
  if (window._creerPhase === 'quetes') { if (window._creerQuetesReady) mmRevealQuetesAll(); return; }
  if (window._creerActiveEsp != null) { mmRevealEsp(window._creerActiveEsp); mmSetDim(window._creerActiveEsp); }
}

/* ─── Pan mindmap Bâtisseur ─── */
(function () {
  let panning = false, px = 0, py = 0, tx = 0, ty = 0;

  function getCanvas() { return document.getElementById('bat-canvas'); }
  function getStage()  { return document.getElementById('bat-fiche-stage'); }
  function applyTransform() {
    const c = getCanvas(); if (c) c.style.transform = `translate(${tx}px,${ty}px)`;
  }

  window.batPanReset = function () { tx = 0; ty = 0; applyTransform(); };

  document.addEventListener('mousedown', e => {
    const stage = getStage(); if (!stage || !stage.contains(e.target)) return;
    if (e.target.closest('.mm-node, button, #bat-tree-bubble')) return;
    panning = true;
    px = e.clientX - tx;
    py = e.clientY - ty;
    stage.style.cursor = 'grabbing';
    e.preventDefault();
  });

  document.addEventListener('mousemove', e => {
    if (!panning) return;
    tx = e.clientX - px;
    ty = e.clientY - py;
    applyTransform();
  });

  document.addEventListener('mouseup', () => {
    if (!panning) return;
    panning = false;
    const stage = getStage(); if (stage) stage.style.cursor = 'grab';
  });

  /* Touch support */
  document.addEventListener('touchstart', e => {
    const stage = getStage(); if (!stage || !stage.contains(e.target)) return;
    if (e.target.closest('.mm-node, button, #bat-tree-bubble')) return;
    panning = true;
    px = e.touches[0].clientX - tx;
    py = e.touches[0].clientY - ty;
    e.preventDefault();
  }, { passive: false });

  document.addEventListener('touchmove', e => {
    if (!panning) return;
    tx = e.touches[0].clientX - px;
    ty = e.touches[0].clientY - py;
    applyTransform();
    e.preventDefault();
  }, { passive: false });

  document.addEventListener('touchend', () => { panning = false; });
})();

