/* ─── TABLEAU DE BORD BÂTISSEUR ─── */
const BAT_QUETES = [];

let batCurrentFilter = 'toutes';

function batInitDashboard() {
  batRenderQuetes();
  batReflectProfile();
}

// Reflète le profil créé (batFicheData) dans le topbar + l'aperçu du dashboard.
function batReflectProfile() {
  if (typeof batRenderCran === 'function') batRenderCran();
  const fd = (typeof batFicheData !== 'undefined') ? batFicheData : null;
  if (!fd) return;
  const fullName = ((fd.prenom || '') + ' ' + (fd.nom || '')).trim();
  const has = fullName !== '';
  const sub = document.getElementById('bat-topbar-sub');
  if (sub) sub.textContent = has
    ? (fullName + " · Bâtisseur d'impact" + (fd.ville ? ' · ' + fd.ville : '') + ' · profil complété ✓')
    : "Bâtisseur d'impact · Complète ton profil pour commencer";
  const title = document.getElementById('bat-topbar-title');
  if (title) title.textContent = has ? ('🌿 ' + fullName) : '🌿 Mon profil';
  const label = document.getElementById('bat-hero-label');
  if (label) label.textContent = has ? (fullName + " · Bâtisseur d'impact") : 'Mon profil Bâtisseur';
  const intro = document.getElementById('bat-hero-intro');
  if (intro) intro.textContent = (has && (fd.bio || '').trim())
    ? fd.bio
    : 'Rejoins des quêtes pour commencer à contribuer et gagner des graines';

  // Solde RÉEL de graines (grand livre : bienvenue + quêtes réalisées − achats).
  const _bp = (typeof evadGrainesParty === 'function') ? evadGrainesParty('batisseur') : null;
  if (_bp && typeof evadGrainesEnsureWelcome === 'function') evadGrainesEnsureWelcome(_bp);
  const graines = _bp ? evadGrainesDispo(_bp.type, _bp.id) : (typeof batProfileGraines === 'function' ? batProfileGraines() : 0);
  const nbComp = (fd.skills || []).length;
  const ag = document.getElementById('bat-apercu-graines');
  if (ag) { ag.textContent = graines; ag.style.cursor = 'pointer'; ag.title = 'Voir mes graines'; ag.onclick = evadOpenWallet; }
  const ags = document.getElementById('bat-apercu-graines-sub');
  if (ags) ags.textContent = has ? 'bonus profil' : '-';
  const kg = document.getElementById('bat-kpi-graines');
  if (kg) kg.textContent = graines;
  const kc = document.getElementById('bat-kpi-comp');
  if (kc) kc.textContent = nbComp || '-';
}

// Le prochain cran du Bâtisseur : un objectif clair, choisi selon son état
// (fiche → compétences → 1re quête → 1re preuve → contribuer davantage).
function batNextCran() {
  const fd = (typeof batFicheData !== 'undefined' && batFicheData) ? batFicheData : {};
  const hasName = ((fd.prenom || '') + (fd.nom || '')).trim() !== '';
  const nbComp = (fd.skills || []).length;
  const goFiche = "showScreen('fiche-bat')";
  const goQuetes = "batTab('quetes',document.getElementById('btab-quetes'))";
  const myBid = fd.id || null;
  const joined = (typeof BAT_QUETES !== 'undefined') ? BAT_QUETES.filter(q => q.joined) : [];
  const hasProof = (myBid && window.store)
    ? store.where('quete_preuves', p => p && p.validee === true && p.batisseur_id === myBid).length > 0
    : false;
  const nbDone = joined.filter(q => q.statut === 'terminee').length;

  if (!hasName)      return { icon:'✦',  title:'Crée ta fiche Bâtisseur',            why:'Présente-toi et déclare tes compétences : les lieux te proposeront des quêtes adaptées.',                     from:0, to:1,        val:0,      unit:'fiche à créer',     cta:'Créer ma fiche',      onclick:goFiche };
  if (nbComp === 0)  return { icon:'🌿', title:'Ajoute tes compétences',             why:'Tes compétences déterminent les quêtes qui te correspondent le mieux.',                                       from:0, to:3,        val:0,      unit:'compétences',       cta:'Compléter ma fiche',  onclick:goFiche };
  if (!joined.length) return { icon:'⚡', title:'Rejoins ta première quête',          why:'Passe à l\'action sur un lieu : c\'est le point de départ de ton impact.',                                     from:0, to:1,        val:0,      unit:'quête rejointe',    cta:'Voir les quêtes',     onclick:goQuetes };
  if (!hasProof)     return { icon:'✅', title:'Valide ta première preuve',           why:'Réalise ta quête et fais valider la preuve : tu débloques tes graines de bienvenue et ta Vadité décolle.',    from:0, to:1,        val:0,      unit:'preuve validée',    cta:'Mes quêtes',          onclick:goQuetes };
  return               { icon:'🚀', title:'Continue à faire pousser ton impact', why:'Bravo, ton impact est prouvé ! Rejoins de nouvelles quêtes pour aller plus loin.',                            from:0, to:nbDone + 1, val:nbDone, unit:'quêtes validées',   cta:'Voir les quêtes',     onclick:goQuetes };
}

// Remplit le bloc « Ton prochain cran » de l'aperçu Bâtisseur.
function batRenderCran() {
  const c = (typeof batNextCran === 'function') ? batNextCran() : null;
  if (!c) return;
  const set = (id, fn) => { const el = document.getElementById(id); if (el) fn(el); };
  set('bat-cran-icon',  el => el.textContent = c.icon);
  set('bat-cran-title', el => el.textContent = c.title);
  set('bat-cran-why',   el => el.textContent = c.why);
  set('bat-cran-from',  el => el.textContent = c.unit + ' ' + c.val);
  set('bat-cran-to',    el => el.textContent = 'objectif ' + c.to);
  set('bat-cran-bar',   el => {
    const pct = (c.to > c.from) ? Math.max(0, Math.min(100, Math.round(((c.val - c.from) / (c.to - c.from)) * 100))) : 0;
    el.style.width = pct + '%';
  });
  set('bat-cran-cta',   el => { el.textContent = c.cta + ' →'; el.setAttribute('onclick', c.onclick); });
}

// Solde de graines du bâtisseur, dérivé du profil :
// 50 de bienvenue à la création + 15 par compétence déclarée.
function batProfileGraines() {
  const fd = (typeof batFicheData !== 'undefined') ? batFicheData : null;
  if (!fd) return 0;
  const has = ((fd.prenom || '') + (fd.nom || '')).trim() !== '';
  if (!has) return 0;
  return 50 + (fd.skills || []).length * 15;
}

// Rend l'onglet « Compétences » à partir des compétences déclarées au profil.
function batRenderCompetences() {
  const fd = (typeof batFicheData !== 'undefined') ? batFicheData : null;
  const list = document.getElementById('bat-comp-list');
  const skills = (fd && fd.skills) ? fd.skills.map(id => BAT_SKILLS.find(s => s.id === id)).filter(Boolean) : [];
  const active = document.getElementById('bat-comp-active');
  if (active) active.textContent = skills.length || '-';
  const mult = document.getElementById('bat-comp-mult');
  if (mult) mult.textContent = '×' + (1 + skills.length * 0.2).toFixed(1);
  if (!list) return;
  if (!skills.length) {
    list.innerHTML = '<div style="padding:2rem;text-align:center;font-size:.78rem;color:var(--moss);opacity:.5;background:white;border:1px dashed rgba(46,102,66,.18);border-radius:var(--r-xl)">Renseigne tes compétences dans « Mon profil » pour les afficher ici.</div>';
    return;
  }
  list.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:.7rem">' + skills.map(s => {
    const lvl = (fd.skillLevels && fd.skillLevels[s.id] != null) ? fd.skillLevels[s.id] : (s.stars || 1);
    const stars = '★'.repeat(Math.max(1, lvl)) + '☆'.repeat(Math.max(0, 5 - Math.max(1, lvl)));
    return '<div style="background:white;border:1px solid rgba(46,102,66,.1);border-left:3px solid ' + s.col + ';border-radius:var(--r-lg);padding:.8rem .9rem">' +
      '<div style="display:flex;align-items:center;gap:.55rem;margin-bottom:.35rem">' +
        '<div style="width:34px;height:34px;border-radius:9px;background:' + s.bg + ';display:flex;align-items:center;justify-content:center;font-size:1.05rem">' + s.ic + '</div>' +
        '<div style="flex:1;min-width:0"><div style="font-size:.8rem;font-weight:700;color:var(--ink)">' + s.label + '</div>' +
        '<div style="font-size:.7rem;color:' + s.col + '">' + stars + '</div></div>' +
      '</div>' +
      '<div style="font-size:.66rem;color:var(--moss);opacity:.75;line-height:1.4">' + (s.desc || '') + '</div>' +
    '</div>';
  }).join('') + '</div>';
}

function batFilterQuetes(filter, btn) {
  batCurrentFilter = filter;
  document.querySelectorAll('[onclick^="batFilterQuetes"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  batRenderQuetes();
}

// Génère des quêtes proposées EN FONCTION du profil bâtisseur
// (compétences déclarées + ville), à partir des solutions hébergées par les lieux réels.
const BAT_SKILL_KW = {
  maraichage:  ['jardin','permacult','potager','compost','maraîch','aliment','amap','graine'],
  energie:     ['solaire','énergie','chauffe','pv','électr','low-tech'],
  reparation:  ['repair','réemploi','réparation','recycl','vélo','matériau','récup'],
  facilitation:['atelier','animation','formation','sensibilis','médiation','amap','facilitation'],
  construction:['isolation','paille','toiture','construction','chantier','bois','maçonn'],
  biodiversite:['haie','mare','biodiv','pollinis','arbre','verger','permacult','jardin'],
  eau:         ['eau','pluie','phyto','arrosage','assainiss','potable','toilettes s','récupération d'],
  adaptation:  ['canicule','fraîcheur','fraicheur','ombr','désimperméabilis','desimperméabilis','climat','chaleur','rafraîchiss','îlot','végétalis'],
};
// Palette des pastilles d'équipe (bâtisseurs inscrits).
const _BAT_EQ_COLS = ['#4a8c5c', '#c8732a', '#7a6ea8', '#3a6e8c', '#b84e35', '#2e6642'];

// Construit BAT_QUETES depuis les quêtes RÉELLES publiées par les Pilotes
// (store ← Supabase). Le contenu saisi par le Pilote (desc, plan, matériel,
// preuve attendue, indicateurs, date) est transmis tel quel : une quête sur
// mesure n'arrive plus « vide » chez le Bâtisseur.
function batBuildQuetesFromProfile() {
  if (typeof BAT_QUETES === 'undefined' || typeof SOLS === 'undefined') return;
  const fd = (typeof batFicheData !== 'undefined') ? batFicheData : {};
  BAT_QUETES.length = 0;
  if (!window.store) return;
  const myBid = fd.id || null; // sans créer d'id à la volée : lecture seule ici

  // Quêtes ouvertes (proposables) + terminées (pour l'historique « Mes quêtes »).
  store.where('quetes', q => q.statut === 'ouverte' || q.statut === 'terminee').forEach(q => {
    const lieu = q.lieu_id ? store.get('lieux', q.lieu_id) : null;
    const hostNom = (lieu && lieu.nom) || q.lieu_nom || 'Lieu EVAD';
    const hostVille = (lieu && (lieu.localisation || lieu.ville)) || q.adresse || 'Bordeaux';
    const lieuLat = lieu && Number(lieu.lat), lieuLng = lieu && Number(lieu.lng);

    // Solution d'origine en repli (quêtes dérivées d'une solution).
    const sol = q.source ? SOLS.find(s => s.nom === q.source) : null;
    const _ind = (sol && typeof SOLS_INDICATORS !== 'undefined') ? SOLS_INDICATORS[sol.nom] : null;
    const plan = (Array.isArray(q.plan) && q.plan.length) ? q.plan : ((_ind && _ind.plan) || []);
    const materiel = (Array.isArray(q.materiel) && q.materiel.length) ? q.materiel : ((_ind && _ind.materiel) || []);
    // Indicateurs (ICI) que la preuve de la quête vient valider.
    const icis = (Array.isArray(q.icis) && q.icis.length && typeof iciGetICI === 'function')
      ? q.icis.map(id => iciGetICI(id)).filter(Boolean)
      : ((sol && typeof iciPourSolution === 'function') ? (iciPourSolution(sol.nom) || []) : []);

    // Équipe réelle : bâtisseurs VALIDÉS (statut « inscrit »).
    const cands = store.where('quete_candidatures', c => c.quete_id === q.id && c.statut === 'inscrit');
    const equipe = cands.map((c, i) => ({
      i: ((c.batisseur_nom || 'B').trim().charAt(0) || 'B').toUpperCase(),
      c: _BAT_EQ_COLS[i % _BAT_EQ_COLS.length],
      nom: c.batisseur_nom || 'Bâtisseur',
      bid: c.batisseur_id || null
    }));
    // Demandes en attente de validation du Pilote.
    const pendCands = store.where('quete_candidatures', c => c.quete_id === q.id && c.statut === 'en_attente');
    const estValide = !!(myBid && cands.some(c => c.batisseur_id === myBid));
    const estEnAttente = !!(myBid && pendCands.some(c => c.batisseur_id === myBid));
    const joined = estValide || estEnAttente;
    const nbMax = parseInt(q.nb, 10) || 6;

    const entry = {
      id: 0,
      srcId: q.id, lieuId: q.lieu_id || null, statut: q.statut,
      type: (q.sourceIc || (sol && sol.img) || '⚡') + ' ' + ((sol && sol.cat) || 'Quête'),
      titre: q.titre || (sol && sol.quete && sol.quete.titre) || 'Quête',
      lieu: hostNom, pilote: hostNom, ville: hostVille,
      lieuLat: Number.isFinite(lieuLat) ? lieuLat : null,
      lieuLng: Number.isFinite(lieuLng) ? lieuLng : null,
      desc: q.desc || (sol && sol.desc) || q.titre || '',
      impact: q.impact || (sol && sol.quete && sol.quete.impact_quete) || '',
      competence: q.competence || '',
      solNom: sol ? sol.nom : '', solCat: (sol && sol.cat) || '',
      plan: plan,
      materiel: materiel,
      preuve: q.preuve || 'Photos de l\'action réalisée + indicateurs mesurés (avant / après).',
      apprendre: q.competence ? ('Compétence : ' + q.competence)
        : (sol ? ('Mise en œuvre de « ' + sol.nom + ' » et documentation de l\'impact.') : (q.titre || '')),
      duree: q.duree || (sol && sol.quete && sol.quete.duree) || '1 journée',
      places: Math.min(equipe.length, nbMax) + '/' + nbMax,
      etape_actuelle: 1, etapes: plan.length || 4,
      etapeLabels: plan.length ? plan.map(p => p.titre) : ['Lancement', 'Préparation', 'Réalisation', 'Certification'],
      tokens: q.graines || (sol && sol.tok) || 50, co2: (sol && sol.co2) || 0,
      esrs: ((sol && sol.esrs) || []).map(e => String(e).replace('ESRS ', '').trim()),
      financement: { objectif: 0, montant: 0, semeur: null },
      equipe: equipe, joined: joined, pending: estEnAttente,
      dateISO: q.dateISO || null, heure: q.heure || null,
      icis: icis,
      dates: [] // plus de dates factices : la vraie date vient de dateISO/heure
    };

    // Score de compatibilité : calcul UNIQUE (le même partout).
    const mf = calcMatchFull(fd, entry);
    entry.match = mf.score;
    entry.matchDetails = mf.details;
    entry.matchedSkills = mf.matchedSkills;
    entry._matched = mf.matchedSkills.length > 0;
    // Proximité réelle pour le filtre « 📍 Proches ».
    const rayon = Number(fd.rayon) || 20;
    if (Number.isFinite(fd.lat) && Number.isFinite(fd.lng) && entry.lieuLat != null && entry.lieuLng != null) {
      entry._proche = _geoDistKm(fd.lat, fd.lng, entry.lieuLat, entry.lieuLng) <= rayon;
    } else {
      const bv = (fd.ville || '').trim().toLowerCase();
      entry._proche = !!(bv && hostVille.toLowerCase().includes(bv));
    }
    BAT_QUETES.push(entry);
  });

  BAT_QUETES.sort((a, b) => b.match - a.match);
  BAT_QUETES.forEach((q, i) => { q.id = i; });
}

// Carte quête de la liste Bâtisseur (liste « pour toi » et « mes quêtes »).
/* ── Quêtes sélectionnées à l'étape « Matching » de l'assistant Bâtisseur ──
   Le Bâtisseur coche les quêtes qu'il veut garder sous la main : elles le
   suivent dans « Mes quêtes » du tableau de bord. C'est un repère personnel,
   pas une candidature : rejoindre une quête reste un geste distinct, qui
   engage le Bâtisseur et demande la validation du Pilote. La sélection est
   donc locale à l'appareil, et réversible d'un second clic. */
const BAT_SEL_KEY = 'evad:v1:bat-quetes-selection';
function batQueteSelAll() {
  try { return JSON.parse(localStorage.getItem(BAT_SEL_KEY) || '[]') || []; } catch (e) { return []; }
}
function batQueteSelKey(q) { return q ? String(q.srcId || q.id) : ''; }
function batQueteSelHas(q) {
  const k = batQueteSelKey(q);
  return !!k && batQueteSelAll().indexOf(k) >= 0;
}
function batQueteSelToggle(q) {
  const k = batQueteSelKey(q);
  if (!k) return false;
  const l = batQueteSelAll(), i = l.indexOf(k);
  if (i >= 0) l.splice(i, 1); else l.push(k);
  try { localStorage.setItem(BAT_SEL_KEY, JSON.stringify(l.slice(-200))); } catch (e) {}
  return i < 0;
}
// Bascule depuis l'étoile d'une carte de la liste « Matching ». On met l'étoile
// à jour sur place plutôt que de re-rendre l'étape : un re-rendu rejouerait le
// récap de Deva et ferait sauter la liste sous le curseur.
function batQueteSelFromCard(btn) {
  if (!btn) return;
  const key = String(btn.getAttribute('data-selq') || '');
  const q = BAT_QUETES.find(x => String(x.srcId || x.id) === key);
  if (!q) return;
  const on = batQueteSelToggle(q);
  btn.textContent = on ? '★' : '☆';
  btn.style.color = on ? '#8a6a12' : 'var(--moss)';
  btn.style.background = on ? 'rgba(240,176,50,.16)' : 'transparent';
  btn.title = on ? 'Retirer de ma sélection' : 'Garder cette quête dans « Mes quêtes »';
  const card = btn.closest('div[onclick]');
  if (card) card.style.background = on ? 'rgba(240,176,50,.07)' : 'white';
  if (typeof mmBubble === 'function') {
    mmBubble(on ? '⭐ Quête gardée : tu la retrouveras dans « Mes quêtes »' : 'Quête retirée de ta sélection');
  }
}

// Bouton « Sélectionner cette quête » du panneau : bascule et re-rend.
function qdSelectQuete() {
  const q = qdQuest(); if (!q) return;
  const on = batQueteSelToggle(q);
  if (typeof mmBubble === 'function') {
    mmBubble(on ? '⭐ Quête gardée : tu la retrouveras dans « Mes quêtes »' : 'Quête retirée de ta sélection');
  }
  qdRerender();
}

function _batQueteCard(q) {
  const matchColor = q.match >= 65 ? 'var(--fern)' : q.match >= 45 ? 'var(--amber)' : 'var(--sky)';
  const etapePct = Math.round((q.etape_actuelle / q.etapes) * 100);
  const statutBadge = q.statut === 'terminee'
    ? '<span class="quete-status" style="font-size:.58rem;background:rgba(74,140,92,.12);color:var(--fern)">✓ Terminée</span>'
    : q.pending
      ? '<span class="quete-status" style="font-size:.58rem;background:rgba(200,115,42,.12);color:#8a4a1a">🕓 En attente</span>'
      : q.joined
        ? '<span class="quete-status" style="font-size:.58rem;background:rgba(1,130,98,.1);color:var(--forest)">🔨 Inscrit</span>'
        : batQueteSelHas(q)
          ? '<span class="quete-status" style="font-size:.58rem;background:rgba(240,176,50,.14);color:#8a6a12">★ Sélectionnée</span>'
          : '<span class="quete-status qs-open" style="font-size:.58rem">Ouvert</span>';
  const dateTxt = (q.dateISO && typeof qdFormatDateFr === 'function') ? qdFormatDateFr(q.dateISO, q.heure) : '';
  return `<div class="quete-card" onclick="batSelectQuete(${q.id})" style="display:flex;align-items:center;gap:1rem;padding:1rem 1.1rem">
    <div style="width:42px;height:42px;border-radius:10px;background:rgba(74,140,92,0.1);display:flex;align-items:center;justify-content:center;font-size:1.1rem;flex-shrink:0">${q.type.split(' ')[0]}</div>
    <div style="flex:1;min-width:0">
      <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.25rem">
        <div style="font-size:.84rem;font-weight:600;color:var(--ink)">${q.titre}</div>
        <span style="font-size:.58rem;padding:.1rem .4rem;border-radius:100px;background:rgba(74,140,92,.1);color:${matchColor};font-weight:700;flex-shrink:0">${q.match}% match</span>
      </div>
      <div style="font-size:.67rem;color:var(--moss);opacity:.7;display:flex;gap:.6rem;flex-wrap:wrap;margin-bottom:.35rem">
        <span>📍 ${q.lieu}</span><span>⏱ ${q.duree}</span><span>👥 ${q.places}</span>${dateTxt ? `<span>📅 ${dateTxt}</span>` : ''}
      </div>
      <div style="display:flex;align-items:center;gap:.5rem">
        <div style="flex:1;height:3px;background:rgba(46,102,66,.1);border-radius:100px;overflow:hidden"><div style="height:100%;width:${etapePct}%;background:var(--fern);border-radius:100px"></div></div>
        <span style="font-size:.6rem;color:var(--moss);white-space:nowrap">Étape ${q.etape_actuelle}/${q.etapes}</span>
      </div>
    </div>
    <div style="display:flex;flex-direction:column;align-items:flex-end;gap:.3rem;flex-shrink:0">
      <span style="font-size:.72rem;font-weight:700;color:var(--amber)">🪙 +${q.tokens}</span>
      <span style="font-size:.62rem;color:#4a9a40;font-weight:600">−${q.co2}t CO₂</span>
      ${statutBadge}
    </div>
  </div>`;
}

function batRenderQuetes() {
  const list = document.getElementById('bat-quetes-list');
  if (!list) return;
  batBuildQuetesFromProfile();

  const joined = BAT_QUETES.filter(q => q.joined);
  const terminees = joined.filter(q => q.statut === 'terminee');
  // Quêtes cochées à l'étape « Matching » : elles remontent dans « Mes quêtes »
  // et sortent de la liste générale, pour ne pas y figurer deux fois.
  const selection = BAT_QUETES.filter(q => !q.joined && batQueteSelHas(q));
  const ouvertes = BAT_QUETES.filter(q => q.statut === 'ouverte' && !q.joined && !batQueteSelHas(q));

  // ── KPIs « Mes quêtes » (réels, plus jamais figés à 0) ──
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  set('bat-q-kpi-encours', joined.length - terminees.length);
  set('bat-q-kpi-terminees', terminees.length);
  set('bat-q-kpi-graines', terminees.reduce((s, q) => s + (q.tokens || 0), 0));
  set('bat-q-kpi-co2', terminees.reduce((s, q) => s + (q.co2 || 0), 0) + ' t');

  // ── Mes quêtes rejointes (inscriptions persistées via quete_candidatures) ──
  const mesBox = document.getElementById('bat-mes-quetes-box');
  const mesList = document.getElementById('bat-mes-quetes');
  if (mesBox) mesBox.style.display = (joined.length || selection.length) ? 'block' : 'none';
  if (mesList) mesList.innerHTML = joined.concat(selection).map(q => _batQueteCard(q)).join('');

  if (!BAT_QUETES.length) {
    list.innerHTML = `<div style="text-align:center;padding:2.5rem 1.2rem;color:var(--moss)">
      <div style="font-size:2rem;margin-bottom:.75rem">🌱</div>
      <div style="font-size:.85rem;font-weight:700;color:var(--ink);margin-bottom:.4rem">Aucune quête publiée pour l'instant</div>
      <div style="font-size:.72rem;opacity:.75;line-height:1.55">Les quêtes apparaîtront ici dès qu'un Pilote en publiera sur son lieu.</div>
    </div>`;
    return;
  }
  let quetes = [...ouvertes];
  if (batCurrentFilter === 'proches') quetes = quetes.filter(q => q._proche);
  if (batCurrentFilter === 'competences') quetes = quetes.filter(q => q._matched);
  quetes.sort((a, b) => b.match - a.match);
  if (!quetes.length) {
    const msg = batCurrentFilter === 'proches' ? 'Aucune quête ouverte dans ton rayon d\'action pour l\'instant.'
      : batCurrentFilter === 'competences' ? 'Aucune quête ouverte ne correspond à tes compétences pour l\'instant.'
      : 'Toutes les quêtes ouvertes sont déjà dans « Mes quêtes rejointes » 💪';
    list.innerHTML = `<div style="text-align:center;padding:1.6rem 1rem;color:var(--moss);font-size:.72rem;opacity:.8">${msg}</div>`;
    return;
  }
  list.innerHTML = quetes.map(q => _batQueteCard(q)).join('');
}

function batSelectQuete(id) {
  showQueteDetail(id, 'quete');
}

/* ─── FICHE QUÊTE DÉDIÉE ─── */
let _qdCurrentId = 0;
let _qdFrom = 'quete';
let _qdQuestOverride = null;  // quête arbitraire (ex. quête Pilote) affichée dans la fiche
let _qdEdit = false;          // (déprécié) ancien mode édition global
let _qdEditSection = null;    // section en cours d'édition : 'infos' | 'materiel' | 'etapes' | null
let _qdOpenSections = {};     // sections dépliées (matériel/étapes repliés par défaut)
function qdSet(field, val, num){ const q = qdQuest(); if(!q) return; const t = String(val).trim(); q[field] = num ? (parseFloat(t.replace(',','.'))||0) : t; }
function qdSetArr(field, i, val){ const q = qdQuest(); if(!q || !Array.isArray(q[field])) return; q[field][i] = String(val).trim(); }
function qdSetObj(field, i, key, val){ const q = qdQuest(); if(!q || !Array.isArray(q[field]) || !q[field][i]) return; q[field][i][key] = String(val).trim(); }
// Date de la quête choisie au calendrier (input type=date → ISO yyyy-mm-dd) + heure optionnelle.
function qdSetDate(val){ const q = qdQuest(); if(!q) return; q.dateISO = (val || '').trim() || null; }
function qdSetHeure(val){ const q = qdQuest(); if(!q) return; q.heure = (val || '').trim() || null; }
// Formate une date ISO en français : « samedi 12 septembre 2026 » (+ heure si fournie).
function qdFormatDateFr(iso, heure){
  if(!iso) return '';
  // Midi local pour éviter tout décalage de fuseau (yyyy-mm-dd est interprété en UTC).
  const d = new Date(iso + 'T12:00:00');
  if(isNaN(d.getTime())) return iso;
  let s = d.toLocaleDateString('fr-FR', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
  s = s.charAt(0).toUpperCase() + s.slice(1);
  if(heure) s += ' · ' + String(heure).replace(':', 'h');
  return s;
}

function showQueteDetail(id, from) {
  _qdQuestOverride = null;
  _qdEditSection = null; _qdOpenSections = {};
  _qdCurrentId = id;
  _qdFrom = from || 'quete';
  showScreen('quete-detail');
}

// Ouvre la fiche quête dans le PANNEAU LATÉRAL de l'assistant Bâtisseur : il
// glisse de la gauche vers la droite par-dessus le mind map, et la liste de
// matching reste sous les yeux. En pleine page, on quittait l'assistant pour y
// revenir ensuite, ce qui cassait le fil de la création de fiche.
function openQueteModalFromFiche(id) {
  const ov  = document.getElementById('bat-quete-ov');
  const box = document.getElementById('bat-quete-ov-box');
  // Repli : appelé depuis un écran sans panneau, on garde la pleine page.
  if (!ov || !box) { window._batQueteInline = false; showQueteDetail(id, 'fiche-bat'); return; }

  _qdQuestOverride = null;
  _qdEditSection = null; _qdOpenSections = {};
  _qdCurrentId = id;
  _qdFrom = 'fiche-bat';
  window._batQueteInline = true;

  // renderQueteDetail écrit dans l'écran « quete-detail », resté masqué ; on
  // recopie son rendu ici. Les ids qm-* sont ceux qu'attend
  // refreshFicheQueteModal, pour que les actions (postuler, plier une section)
  // se répercutent dans le panneau sans le rouvrir.
  renderQueteDetail();
  box.innerHTML =
      '<div style="position:sticky;top:0;background:#fff;padding:.95rem 1.3rem .8rem;border-bottom:1px solid rgba(46,102,66,.1);display:flex;align-items:flex-start;gap:.9rem;z-index:2">'
    +   '<button class="btn btn-ghost" style="font-size:.72rem;padding:.32rem .8rem;flex-shrink:0" onclick="closeFicheQueteModal()">← Retour</button>'
    +   '<div style="min-width:0">'
    +     '<div class="topbar-title" id="qm-title" style="font-size:.95rem"></div>'
    +     '<div class="topbar-sub" id="qm-sub"></div>'
    +   '</div>'
    + '</div>'
    + '<div style="padding:1.1rem 1.3rem 1.6rem;display:flex;flex-direction:column;gap:1.1rem">'
    +   '<div id="qm-main" style="display:flex;flex-direction:column;gap:1.1rem"></div>'
    +   '<div id="qm-panel" style="display:flex;flex-direction:column;gap:.9rem"></div>'
    + '</div>';
  refreshFicheQueteModal();

  ov.style.display = 'block';
  box.scrollTop = 0;
  // Reflux forcé plutôt que requestAnimationFrame, qui ne se déclenche pas
  // dans un onglet en arrière-plan : le panneau resterait alors hors champ.
  void box.offsetWidth;
  box.style.transform = 'translateX(0)';
}

// Recopie le contenu rendu de la fiche quête dans le panneau (sync après une
// action). Fonctionne tant que les cibles qm-main / qm-panel existent.
function refreshFicheQueteModal() {
  const map = { 'qm-main': 'qd-main', 'qm-panel': 'qd-panel' };
  let any = false;
  for (const [dst, src] of Object.entries(map)) {
    const d = document.getElementById(dst), s = document.getElementById(src);
    if (d && s) { d.innerHTML = s.innerHTML; any = true; }
  }
  if (!any) return;
  const t = document.getElementById('qm-title'), st = document.getElementById('qd-topbar-title');
  if (t && st) t.textContent = st.textContent;
  const sb = document.getElementById('qm-sub'), ss = document.getElementById('qd-topbar-sub');
  if (sb && ss) sb.textContent = ss.textContent;
}

function closeFicheQueteModal() {
  const modal = document.getElementById('bat-quete-modal');
  if (modal) modal.style.display = 'none';
  // Panneau latéral : « ← Retour » le referme (glissement puis masquage). La
  // liste de matching, jamais détruite, reste affichée dans la colonne de gauche.
  if (window._batQueteInline) {
    window._batQueteInline = false;
    const ov  = document.getElementById('bat-quete-ov');
    const box = document.getElementById('bat-quete-ov-box');
    if (box) box.style.transform = 'translateX(-100%)';
    if (ov)  setTimeout(() => { ov.style.display = 'none'; }, 300);
  }
}

// Ouvre la fiche quête (même présentation) pour n'importe quelle quête.
function showQueteFiche(quest, from) {
  _qdQuestOverride = quest;
  _qdEditSection = null; _qdOpenSections = {};
  _qdFrom = from || (typeof currentRole !== 'undefined' ? currentRole : 'quete');
  showScreen('quete-detail');
}

// Ouvre la fiche lieu rattachée à la quête : lieu du réseau (MAP_PLACES) sinon lieu du Pilote courant.
function qdVoirLieu() {
  const q = qdQuest(); if (!q) return;
  const nom = q.lieu || q.pilote;
  const idx = (typeof MAP_PLACES !== 'undefined') ? MAP_PLACES.findIndex(p => p.nom === nom) : -1;
  if (idx >= 0) { openLieuModalFromPlace(idx); return; }
  // Quête du Pilote sur son propre lieu → on affiche sa fiche (myLieuData).
  if (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) {
    try { cData = Object.assign(_CDATA_EMPTY(), myLieuData); } catch (e) {}
    openLieuModal();
    return;
  }
  if (typeof mmBubble === 'function') mmBubble('Aucune fiche lieu rattachée à cette quête');
}

// ─── Actions fonctionnelles de la fiche quête (mutent la quête + re-render) ───
function qdQuest() { return _qdQuestOverride || (typeof BAT_QUETES !== 'undefined' ? BAT_QUETES[_qdCurrentId] : null) || null; }
function qdRerender() { try { renderQueteDetail(); refreshFicheQueteModal(); } catch (e) {} }

// Côté Pilote : ouvre la conversation avec un bâtisseur inscrit, sur la quête.
function qdContactBatisseur(bid, nom) {
  const q = qdQuest() || {};
  if (typeof evadOpenChat !== 'function' || !q.srcId || !bid) return;
  evadOpenChat(evadChatThreadQuete(q.srcId, bid), {
    title: '💬 ' + (nom || 'Bâtisseur'),
    sub: 'À propos de « ' + (q.titre || 'la quête') + ' »',
    quete_id: q.srcId, lieu_id: q.lieuId || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.id) || null,
    dest_id: bid
  });
}

function qdContactPilote() {
  const q = qdQuest() || {};
  // Vraie conversation Bâtisseur ↔ Pilote, contextualisée à la quête.
  if (typeof evadOpenChat === 'function' && q.srcId) {
    const bid = (typeof _currentBatisseurId === 'function') ? _currentBatisseurId() : 'bat';
    const pilote = String(q.pilote || q.lieu || 'le Pilote').split('·')[0].trim();
    evadOpenChat(evadChatThreadQuete(q.srcId, bid), {
      title: '💬 ' + pilote,
      sub: 'À propos de « ' + (q.titre || 'la quête') + ' »',
      quete_id: q.srcId, lieu_id: q.lieuId || null, dest_id: q.lieuId || null
    });
    return;
  }
  if (typeof mmBubble === 'function') mmBubble('La conversation sera disponible une fois la quête publiée.');
}

// Métadonnées des types de preuve (partagées fiche quête).
const QD_PREUVE_META = { photo:{ic:'📷',label:'Photo'}, mesure:{ic:'📊',label:'Mesure chiffrée'}, temoignage:{ic:'👥',label:'Témoignage pair'} };
// Phases d'une preuve : T0 = état AVANT l'action, T1 = état APRÈS. Le couple
// donne un avant/après vérifiable (la différence T1−T0 = l'impact prouvé).
const QD_PHASE_META = {
  t0: { ic: '🌱', label: 'T0 · État initial', desc: 'Photographie l\'état AVANT l\'action : on pourra mesurer la différence à la fin.' },
  t1: { ic: '🌳', label: 'T1 · État final',   desc: 'L\'action est faite : documente le résultat (même cadrage que la T0 si possible).' }
};

// Preuves déposées sur cette quête : lues depuis le store (table
// quete_preuves, synchronisée Supabase) → persistées et visibles du Pilote.
function qdPreuvesBat(q) {
  if (!q || !q.srcId || !window.store) return [];
  return store.where('quete_preuves', p => p.quete_id === q.srcId)
    .sort((a, b) => String(a.created_at || '').localeCompare(String(b.created_at || '')));
}
// Phase attendue au prochain dépôt : T0 tant qu'aucune preuve T0 n'existe.
function qdPhaseAttendue(q) {
  return qdPreuvesBat(q).some(p => p.phase === 't0') ? 't1' : 't0';
}

// ── Formulaire de dépôt de preuve (type + note + valeur + photo → bucket) ──
function qdPreuveEnsureDom() {
  if (document.getElementById('qd-pv-modal')) return;
  const wrap = document.createElement('div');
  wrap.id = 'qd-pv-modal';
  wrap.style.cssText = 'display:none;position:fixed;inset:0;z-index:100010;font-family:\'Satoshi\',sans-serif';
  const inputStyle = 'width:100%;box-sizing:border-box;padding:.55rem .7rem;border-radius:10px;border:1px solid rgba(46,102,66,.2);font-family:inherit;font-size:.82rem;color:var(--ink);background:#fff';
  wrap.innerHTML =
    '<div style="position:absolute;inset:0;background:rgba(13,43,34,.6);backdrop-filter:blur(4px)" onclick="qdPreuveFermer()"></div>'
  + '<div role="dialog" aria-label="Déposer une preuve" style="position:relative;max-width:440px;width:calc(100% - 2rem);margin:6vh auto 0;max-height:86vh;overflow-y:auto;background:#fff;border-radius:20px;box-shadow:0 24px 60px rgba(0,0,0,.32);padding:1.3rem 1.4rem 1.4rem">'
  +   '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem">'
  +     '<div>'
  +       '<div id="qd-pv-titre" style="font-size:1.02rem;font-weight:800;color:var(--ink)">📎 Déposer une preuve</div>'
  +       '<div id="qd-pv-phase-desc" style="font-size:.75rem;line-height:1.5;color:var(--moss);margin-top:.3rem"></div>'
  +     '</div>'
  +     '<button onclick="qdPreuveFermer()" aria-label="Fermer" style="flex-shrink:0;background:none;border:none;font-size:1.2rem;line-height:1;color:var(--moss);opacity:.5;cursor:pointer">✕</button>'
  +   '</div>'
  +   '<div style="font-size:.72rem;font-weight:700;color:var(--moss);margin:.85rem 0 .35rem">Type de preuve</div>'
  +   '<div id="qd-pv-types" style="display:flex;gap:.45rem;flex-wrap:wrap">'
  +     Object.keys(QD_PREUVE_META).map(t => '<button type="button" data-pt="' + t + '" onclick="qdPreuveType(\'' + t + '\')" style="border:1.5px solid rgba(46,102,66,.2);background:white;color:var(--moss);border-radius:100px;padding:.4rem .8rem;font-size:.72rem;font-weight:700;cursor:pointer;font-family:inherit">' + QD_PREUVE_META[t].ic + ' ' + QD_PREUVE_META[t].label + '</button>').join('')
  +   '</div>'
  +   '<div style="font-size:.72rem;font-weight:700;color:var(--moss);margin:.85rem 0 .35rem">📷 Photo (avant / après)</div>'
  +   '<input id="qd-pv-photo" type="file" accept="image/*" onchange="qdPreuvePhotoPreview(this)" style="' + inputStyle + ';padding:.4rem .5rem">'
  +   '<div id="qd-pv-photo-prev" style="display:none;margin-top:.45rem;border-radius:10px;overflow:hidden;max-height:150px"></div>'
  +   '<div style="font-size:.72rem;font-weight:700;color:var(--moss);margin:.85rem 0 .35rem">📊 Valeur mesurée <span style="font-weight:400;opacity:.7">(si mesure : ex. « 320 L », « 12 plants »)</span></div>'
  +   '<input id="qd-pv-valeur" style="' + inputStyle + '" placeholder="Ex : 320 L récupérés">'
  +   '<div style="font-size:.72rem;font-weight:700;color:var(--moss);margin:.85rem 0 .35rem">📝 Note</div>'
  +   '<textarea id="qd-pv-note" rows="3" style="' + inputStyle + ';resize:vertical" placeholder="Décris ce que montre la preuve : ce qui a été fait, où, comment…"></textarea>'
  +   '<div id="qd-pv-hint" style="font-size:.7rem;color:var(--terracotta);margin-top:.45rem;min-height:1rem"></div>'
  +   '<div style="display:flex;align-items:center;justify-content:flex-end;gap:.6rem;margin-top:.4rem">'
  +     '<button onclick="qdPreuveFermer()" style="background:none;border:none;color:var(--moss);font-size:.8rem;font-weight:600;cursor:pointer;padding:.5rem .6rem;font-family:inherit">Annuler</button>'
  +     '<button id="qd-pv-submit" onclick="qdPreuveSubmit()" style="background:var(--forest);color:#fff;border:none;border-radius:100px;padding:.55rem 1.3rem;font-size:.8rem;font-weight:700;cursor:pointer;font-family:inherit">✅ Déposer la preuve</button>'
  +   '</div>'
  + '</div>';
  document.body.appendChild(wrap);
}
function qdPreuveType(t) {
  window._qdPvType = t;
  document.querySelectorAll('#qd-pv-types [data-pt]').forEach(b => {
    const on = b.getAttribute('data-pt') === t;
    b.style.background = on ? 'var(--forest)' : 'white';
    b.style.color = on ? '#fff' : 'var(--moss)';
    b.style.borderColor = on ? 'var(--forest)' : 'rgba(46,102,66,.2)';
  });
}
function qdPreuvePhotoPreview(input) {
  const prev = document.getElementById('qd-pv-photo-prev');
  if (!prev) return;
  const file = input.files && input.files[0];
  if (!file) { prev.style.display = 'none'; prev.innerHTML = ''; return; }
  prev.style.display = 'block';
  prev.innerHTML = '<img src="' + URL.createObjectURL(file) + '" style="width:100%;max-height:150px;object-fit:cover">';
}
function qdPreuveFermer() {
  const m = document.getElementById('qd-pv-modal');
  if (m) m.style.display = 'none';
}

// Le Bâtisseur (ou le Pilote pour la T0) dépose une preuve → formulaire réel.
function qdDeposerPreuve() {
  const q = qdQuest(); if (!q) return;
  if (!q.srcId || !window.store) { mmBubble('⚠️ Cette quête de démonstration n\'accepte pas encore de preuve'); return; }
  qdPreuveEnsureDom();
  const phase = qdPhaseAttendue(q);
  const meta = QD_PHASE_META[phase];
  const m = document.getElementById('qd-pv-modal');
  m.setAttribute('data-phase', phase);
  const t = document.getElementById('qd-pv-titre');
  if (t) t.textContent = meta.ic + ' Preuve ' + meta.label;
  const d = document.getElementById('qd-pv-phase-desc');
  if (d) d.textContent = meta.desc;
  ['qd-pv-valeur', 'qd-pv-note'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
  const ph = document.getElementById('qd-pv-photo'); if (ph) ph.value = '';
  const pp = document.getElementById('qd-pv-photo-prev'); if (pp) { pp.style.display = 'none'; pp.innerHTML = ''; }
  const hint = document.getElementById('qd-pv-hint'); if (hint) hint.textContent = '';
  const sb = document.getElementById('qd-pv-submit'); if (sb) { sb.disabled = false; sb.textContent = '✅ Déposer la preuve'; }
  qdPreuveType('photo');
  m.style.display = 'block';
}

async function qdPreuveSubmit() {
  const q = qdQuest(); if (!q || !q.srcId || !window.store) return;
  const modal = document.getElementById('qd-pv-modal');
  const phase = (modal && modal.getAttribute('data-phase')) || 't1';
  const type = window._qdPvType || 'photo';
  const note = ((document.getElementById('qd-pv-note') || {}).value || '').trim();
  const valeur = ((document.getElementById('qd-pv-valeur') || {}).value || '').trim();
  const fileInput = document.getElementById('qd-pv-photo');
  const file = fileInput && fileInput.files && fileInput.files[0];
  if (!note && !file && !valeur) {
    const hint = document.getElementById('qd-pv-hint');
    if (hint) hint.textContent = 'Ajoute au moins une photo, une valeur ou une note 🙂';
    return;
  }
  const sb = document.getElementById('qd-pv-submit');
  if (sb) { sb.disabled = true; sb.textContent = 'Envoi…'; }
  // Photo → bucket public « preuves » (URL stockée avec la preuve).
  let photoUrl = null;
  if (file && window.evadSupabase) {
    try {
      const safe = (file.name || 'preuve').replace(/[^a-zA-Z0-9._-]+/g, '_').slice(-50);
      const path = q.srcId + '/' + Date.now() + '-' + Math.random().toString(36).slice(2, 8) + '-' + safe;
      const { error } = await window.evadSupabase.storage.from('preuves').upload(path, file);
      if (error) throw error;
      const { data } = window.evadSupabase.storage.from('preuves').getPublicUrl(path);
      photoUrl = data.publicUrl;
    } catch (e) {
      console.warn('Upload photo de preuve échoué :', e);
      mmBubble('⚠️ Photo non envoyée (' + ((e && e.message) || 'erreur réseau') + ') · preuve enregistrée sans photo');
    }
  }
  const estPilote = (typeof currentRole !== 'undefined' && currentRole === 'pilote');
  const bid = estPilote ? null : ((typeof _currentBatisseurId === 'function') ? _currentBatisseurId() : null);
  const batNom = estPilote
    ? (((typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) || 'Pilote') + ' (Pilote)')
    : ((((typeof batFicheData !== 'undefined' && batFicheData.prenom) || '') + ' ' + ((typeof batFicheData !== 'undefined' && batFicheData.nom) || '')).trim() || 'Bâtisseur');
  store.insert('quete_preuves', {
    id: 'pv-' + store.uuid(),
    quete_id: q.srcId,
    lieu_id: q.lieuId || null,
    batisseur_id: bid,
    batisseur_nom: batNom,
    phase: phase, type: type, note: note,
    valeur: valeur || null, photo_url: photoUrl, validee: false
  });
  q.proofSubmitted = true;
  qdPreuveFermer();
  mmBubble(phase === 't0'
    ? '🌱 Preuve T0 (état initial) déposée · dépose la T1 à la fin de la quête pour montrer la différence'
    : '🌳 Preuve T1 (état final) déposée · en attente de validation du Pilote');
  qdRerender();
}

// Le Pilote valide une preuve (par id) → persistée, nourrit Vadité + journal.
// Quand l'état final (T1) est validé, et l'état initial (T0) aussi s'il
// existe, la quête passe au statut « terminee » (persistant).
function qdValiderPreuveBat(pvId) {
  const q = qdQuest(); if (!q || !window.store) return;
  const p = store.get('quete_preuves', pvId);
  if (!p || p.validee) return;
  store.update('quete_preuves', pvId, { validee: true });
  const phMeta = QD_PHASE_META[p.phase === 't0' ? 't0' : 't1'];
  // Entrée au Journal des preuves : même fabrique que la reconstruction au
  // chargement (rebuildJournalFromPreuves) → pas de doublon, mêmes convergences.
  if (typeof actionsTerrains !== 'undefined' && typeof journalEntryFromPreuve === 'function') {
    const pRow = store.get('quete_preuves', pvId) || p;
    const qRow = (q.srcId && store.get('quetes', q.srcId)) || { id: q.srcId || null, titre: q.titre, impact: q.impact };
    if (!actionsTerrains.some(a => a.preuve_id === pRow.id)) actionsTerrains.push(journalEntryFromPreuve(pRow, qRow));
  }
  // Rattachement par ID de quête (plus jamais par titre : deux quêtes issues
  // de la même solution partagent le même titre).
  const qid = q.srcId || null;
  const proofs = qid ? store.where('quete_preuves', x => x.quete_id === qid) : [];
  const t0s = proofs.filter(x => x.phase === 't0');
  const t1ok = proofs.some(x => x.phase !== 't0' && x.validee === true);
  const t0ok = !t0s.length || t0s.some(x => x.validee === true);
  if (qid && t1ok && t0ok) {
    if (typeof quetesValidees !== 'undefined') quetesValidees.add(qid);
    store.update('quetes', qid, { statut: 'terminee' });
    if (typeof PILOTE_QUETES_DEMO !== 'undefined') {
      const pe = PILOTE_QUETES_DEMO.find(x => x.id === qid);
      if (pe) pe.statut = 'terminee';
    }
    q.validated = true;
    // Récompense regen : chaque bâtisseur inscrit à la quête reçoit ses graines
    // (une seule fois par quête → garde-fou via ref_id du grand livre).
    try {
      const qGraines = (typeof q.tokens === 'number') ? q.tokens : (parseInt(q.tokens, 10) || 50);
      const dejaCredite = store.where('graines_tx', t => t.type === 'quete' && t.ref_id === String(qid));
      const cands = store.where('quete_candidatures', c => c.quete_id === qid && c.statut === 'inscrit');
      cands.forEach(c => {
        if (!c.batisseur_id) return;
        if (dejaCredite.some(t => t.party_id === c.batisseur_id)) return;
        evadGrainesMove({ type: 'batisseur', id: c.batisseur_id }, qGraines, 'quete', 'Quête réalisée · ' + (q.titre || ''), 'quetes', qid);
      });
    } catch (e) {}
    mmBubble('🌳 Preuves validées · quête terminée ! Graines distribuées aux bâtisseurs, impact propagé 🌱');
    if (typeof renderPiloteQuetes === 'function') renderPiloteQuetes();
  } else {
    mmBubble('✅ ' + phMeta.label + ' validée' + (p.phase === 't0' ? ' · en attente de la preuve T1 (état final)' : ''));
  }
  if (typeof updateApercuFromQuetes === 'function') updateApercuFromQuetes();
  qdRerender();
}

// Le Pilote valide l'étape en cours → la progression avance.
function qdValiderEtape() {
  const q = qdQuest(); if (!q) return;
  const total = (q.plan && q.plan.length) ? q.plan.length : q.etapes;
  if ((q.etape_actuelle || 1) > total) { mmBubble('🌳 Toutes les étapes sont franchies !'); return; }
  q.etape_actuelle = Math.min(total + 1, (q.etape_actuelle || 1) + 1);
  mmBubble((q.etape_actuelle > total) ? '🌳 Toutes les étapes franchies · quête prête à certifier !' : '✓ Étape ' + (q.etape_actuelle - 1) + ' validée · on avance 🌱');
  qdRerender();
}

// Annule la validation de la dernière étape franchie (revient en arrière).
function qdDevaliderEtape() {
  const q = qdQuest(); if (!q) return;
  if ((q.etape_actuelle || 1) <= 1) { mmBubble('Aucune étape validée à annuler'); return; }
  q.validated = false;
  q.etape_actuelle = Math.max(1, (q.etape_actuelle || 1) - 1);
  mmBubble('↩ Validation annulée · retour à l\'étape ' + q.etape_actuelle);
  qdRerender();
}

// Matérialise q.plan (depuis les labels génériques) si besoin, pour l'édition.
function _qdEnsurePlan(q) {
  if (Array.isArray(q.plan) && q.plan.length) return;
  const labels = (q.etapeLabels && q.etapeLabels.length) ? q.etapeLabels
    : Array.from({ length: q.etapes || 4 }, (_, i) => 'Étape ' + (i + 1));
  q.plan = labels.map(l => ({ ic: '🪜', titre: l, desc: '' }));
  q.etapes = q.plan.length;
}
// Ajoute une étape au plan (mode édition).
function qdAddStep() {
  const q = qdQuest(); if (!q) return;
  _qdEnsurePlan(q);
  q.plan.push({ ic: '🪜', titre: 'Nouvelle étape', desc: '' });
  q.etapes = q.plan.length;
  qdRerender();
}
// Supprime une étape du plan (mode édition).
function qdRemoveStep(i) {
  const q = qdQuest(); if (!q || !Array.isArray(q.plan)) return;
  q.plan.splice(i, 1);
  q.etapes = q.plan.length || 1;
  if ((q.etape_actuelle || 1) > q.plan.length + 1) q.etape_actuelle = q.plan.length + 1;
  qdRerender();
}
// Ajoute / supprime un élément de matériel (mode édition).
function qdAddMat() {
  const q = qdQuest(); if (!q) return;
  if (!Array.isArray(q.materiel)) q.materiel = [];
  q.materiel.push('Nouvel élément');
  qdRerender();
}
function qdRemoveMat(i) {
  const q = qdQuest(); if (!q || !Array.isArray(q.materiel)) return;
  q.materiel.splice(i, 1);
  if (Array.isArray(q.materielChecked)) q.materielChecked.splice(i, 1);
  qdRerender();
}

// Édition ciblée par section ('infos' | 'materiel' | 'etapes') au lieu d'un mode global.
function qdEditSection(sec) {
  const q = qdQuest();
  if (!q) return;
  _qdEditSection = (_qdEditSection === sec) ? null : sec;
  // À l'entrée en édition des étapes, matérialise un plan éditable si absent.
  if (_qdEditSection === 'etapes' && typeof _qdEnsurePlan === 'function') _qdEnsurePlan(q);
  // À l'entrée en édition du matériel, garantit un tableau (pour l'ajout).
  if (_qdEditSection === 'materiel' && !Array.isArray(q.materiel)) q.materiel = [];
  qdRerender();
}
function qdSaveSection() {
  // Persistance : les quêtes du Pilote portent l'id réel du store dans `srcId`
  // (posé par openPiloteQueteFiche). On réécrit les champs éditables dans la
  // table `quetes` → la modification survit au rechargement et à la re-synchro.
  const q = qdQuest();
  if (q && q.srcId && window.store) {
    try {
      const patch = {
        titre: q.titre,
        duree: q.duree,
        graines: (typeof q.tokens === 'number') ? q.tokens : (parseInt(q.tokens, 10) || 50),
        impact: q.impact,
        desc: q.desc,
        dateISO: q.dateISO || null,
        heure: q.heure || null
      };
      // Matériel et étapes édités dans la fiche : sans ces deux lignes, le
      // bouton « Enregistrer » les affichait comme sauvés sans rien écrire.
      if (Array.isArray(q.materiel)) patch.materiel = q.materiel.filter(Boolean);
      if (Array.isArray(q.plan)) patch.plan = q.plan;
      store.update('quetes', q.srcId, patch);
    } catch (e) {}
  }
  _qdEditSection = null;
  mmBubble('✏️ Modifications enregistrées');
  qdRerender();
}
// Replie / déplie une section (matériel, étapes), repliées par défaut.
function qdToggleSection(sec) {
  _qdOpenSections[sec] = !_qdOpenSections[sec];
  qdRerender();
}
// « Modifier les paramètres » = éditer le bloc d'infos principal.
function qdModifier() {
  if (!qdQuest()) return;
  qdEditSection('infos');
}

function qdToggleMat(i, el) {
  const q = qdQuest(); if (!q || !q.materiel) return;
  q.materielChecked = q.materielChecked || [];
  const on = el ? el.checked : !q.materielChecked[i];
  q.materielChecked[i] = on;
  if (el) {
    const span = el.parentElement.querySelector('span');
    if (span) { span.style.textDecoration = on ? 'line-through' : 'none'; span.style.opacity = on ? '.6' : '1'; span.style.color = on ? 'var(--moss)' : 'var(--ink)'; }
  }
  const nb = q.materiel.filter((_, k) => q.materielChecked[k]).length;
  const c = document.getElementById('qd-mat-count');
  if (c) { c.textContent = (nb === q.materiel.length) ? '🎉 Tout est prêt' : (nb + '/' + q.materiel.length); c.style.color = (nb === q.materiel.length) ? 'var(--fern)' : 'var(--moss)'; }
}

function qdPause() {
  const q = qdQuest(); if (!q) return;
  q.paused = !q.paused;
  // Pause = retirée du réseau : la quête passe en statut « en_pause » (donc
  // supprimée de Supabase, invisible pour les Bâtisseurs) mais reste chez le
  // Pilote. Réactiver = re-publier (statut « ouverte » → réinscrite en base).
  if (q.srcId && window.store) {
    if (q.paused) {
      store.update('quetes', q.srcId, { statut: 'en_pause', paused: true });
      if (typeof store.deleteQueteRemote === 'function') store.deleteQueteRemote(q.srcId);
    } else {
      store.update('quetes', q.srcId, { statut: 'ouverte', paused: false });
    }
    // Refléter le nouveau statut dans la liste du tableau de bord.
    if (typeof PILOTE_QUETES_DEMO !== 'undefined') {
      const pe = PILOTE_QUETES_DEMO.find(x => x.id === q.srcId);
      if (pe) pe.statut = q.paused ? 'en_pause' : 'ouverte';
    }
  }
  mmBubble(q.paused ? '⏸ Quête mise en pause · retirée du réseau' : '▶️ Quête réactivée · de nouveau visible');
  qdRerender();
  if (typeof renderPiloteQuetes === 'function') renderPiloteQuetes();
}

function qdSupprimer() {
  const q = qdQuest(); if (!q) return;
  if (!_qdQuestOverride && typeof BAT_QUETES !== 'undefined') { const i = BAT_QUETES.indexOf(q); if (i >= 0) BAT_QUETES.splice(i, 1); }
  else if (typeof PILOTE_QUETES_DEMO !== 'undefined') { const i = PILOTE_QUETES_DEMO.findIndex(x => x.titre === q.titre); if (i >= 0) PILOTE_QUETES_DEMO.splice(i, 1); }
  mmBubble('🗑 Quête supprimée');
  setTimeout(queteDetailBack, 250);
}

// Ouvre le détail d'une quête depuis la fiche lieu (modal carte). Construit
// l'objet quête à partir de la ligne du store, rattaché au LIEU AFFICHÉ (cData),
// puis masque le modal le temps d'afficher la fiche (retour = réouverture).
let _qdLieuReturnScreen = null;
function openLieuQueteFiche(qid) {
  if (!window.store || typeof showQueteFiche !== 'function') return;
  const r = store.get('quetes', qid);
  if (!r) return;
  const sol = (typeof SOLS !== 'undefined' && r.source) ? SOLS.find(s => s.nom === r.source) : null;
  const lieuNom = (typeof cData !== 'undefined' && cData && cData.nom) || 'Ce lieu';
  const ville   = (typeof cData !== 'undefined' && cData && (cData.localisation || cData.ville)) || '';
  const _si = (sol && typeof SOLS_INDICATORS !== 'undefined' && SOLS_INDICATORS[sol.nom]) ? SOLS_INDICATORS[sol.nom] : null;
  const _plan = (Array.isArray(r.plan) && r.plan.length) ? r.plan : ((_si && _si.plan) || []);
  const _mat  = (Array.isArray(r.materiel) && r.materiel.length) ? r.materiel : ((_si && _si.materiel) || []);
  const _icis = (Array.isArray(r.icis) && r.icis.length && typeof iciGetICI === 'function')
    ? r.icis.map(id => iciGetICI(id)).filter(Boolean)
    : ((sol && typeof iciPourSolution === 'function') ? (iciPourSolution(sol.nom) || []) : []);
  const _cands = store.where('quete_candidatures', c => c.quete_id === r.id && c.statut === 'inscrit');
  const _eqCols = ['#4a8c5c', '#c8732a', '#7a6ea8', '#3a6e8c', '#b84e35', '#2e6642'];
  const _equipe = _cands.map((c, i) => ({ i: ((c.batisseur_nom || 'B').trim().charAt(0) || 'B').toUpperCase(), c: _eqCols[i % _eqCols.length], nom: c.batisseur_nom || 'Bâtisseur', bid: c.batisseur_id || null }));
  const _nbMax = parseInt(r.nb, 10) || 6;
  // Masque le modal lieu (overlay) et mémorise l'écran sous-jacent pour le retour.
  _qdLieuReturnScreen = document.querySelector('.screen.active')?.id?.replace('screen-', '') || 'carte';
  const m = document.getElementById('lieu-modal');
  if (m) m.style.display = 'none';
  showQueteFiche({
    titre: r.titre || 'Quête',
    type: (r.sourceIc || (sol && sol.img) || '⚡') + ' ' + ((sol && sol.cat) || 'Quête'),
    lieu: lieuNom, pilote: lieuNom, ville: ville,
    desc: r.desc || (sol && sol.desc) || r.titre,
    impact: r.impact || (sol && sol.impact) || '',
    plan: _plan, materiel: _mat,
    preuve: r.preuve || 'Photos de l\'action réalisée + indicateurs mesurés.',
    apprendre: r.competence ? ('Compétence : ' + r.competence) : ('Mise en œuvre de « ' + ((sol && sol.nom) || r.titre) + ' ».'),
    duree: r.duree || '1 journée',
    places: Math.min(_equipe.length, _nbMax) + '/' + _nbMax,
    etape_actuelle: 1, etapes: _plan.length || 4,
    etapeLabels: _plan.length ? _plan.map(p => p.titre) : ['Lancement', 'Préparation', 'Réalisation', 'Certification'],
    tokens: r.graines || 50, co2: (sol && sol.co2) || 0,
    esrs: ((sol && sol.esrs) || []).map(e => String(e).replace('ESRS ', '').trim()),
    financement: { objectif: 0, montant: 0, semeur: null },
    equipe: _equipe, dates: [], dateISO: r.dateISO || null, heure: r.heure || null,
    icis: _icis,
    srcId: r.id, published: r.statut === 'ouverte' || r.statut === 'terminee', paused: r.statut === 'en_pause'
  }, 'lieu-modal');
}

function queteDetailBack() {
  // Retour vers la fiche lieu (modal carte) d'où la quête a été ouverte.
  if (_qdFrom === 'lieu-modal') {
    showScreen(_qdLieuReturnScreen || 'carte');
    const m = document.getElementById('lieu-modal');
    if (m) { m.style.display = 'block'; document.body.style.overflow = 'hidden'; }
    // L'onglet Quêtes a fusionné dans « Espaces & quêtes ».
    if (typeof lieuTab === 'function') { try { lieuTab('espaces', document.getElementById('ltab-espaces')); } catch (e) {} }
    if (typeof lieuRenderEspaces === 'function') { try { lieuRenderEspaces(); } catch (e) {} }
    return;
  }
  showScreen(_qdFrom);
  // Retour à l'étape de création de fiche bâtisseur (liste des quêtes matchées).
  if (_qdFrom === 'fiche-bat' && typeof batFicheRenderStep === 'function') {
    try { batFicheRenderStep(); } catch (e) {}
  }
  // showScreen('pilote') réinitialise sur l'onglet Aperçu : on rétablit l'onglet
  // Quêtes, d'où la fiche quête du Pilote est toujours ouverte.
  if (_qdFrom === 'pilote' && typeof piloteTab === 'function') {
    try { piloteTab('quetes', document.getElementById('ptab-quetes')); } catch (e) {}
  }
}

function renderQueteDetail() {
  const q = _qdQuestOverride || BAT_QUETES[_qdCurrentId];
  if (!q) return;

  // Édition ciblée : une section à la fois (infos / desc / materiel / etapes / impact)
  const EDinfos  = _qdEditSection === 'infos';
  const EDdesc   = _qdEditSection === 'desc';
  const EDdates  = _qdEditSection === 'dates';
  const EDmat    = _qdEditSection === 'materiel';
  const EDplan   = _qdEditSection === 'etapes';
  const EDimpact = _qdEditSection === 'impact';
  // Sections repliables (matériel/étapes), dépliées si ouvertes OU en édition
  const matOpen  = !!_qdOpenSections.materiel || EDmat;
  const planOpen = !!_qdOpenSections.etapes   || EDplan;
  // Contrôle pilote d'une section repliable : crayon (éditer) / ✓ (enregistrer)
  const secCtrl = (sec, on) => currentRole !== 'pilote' ? '' : (on
    ? `<button onclick="event.stopPropagation();qdSaveSection()" style="background:var(--forest);color:#fff;border:none;border-radius:100px;padding:.22rem .6rem;font-size:.62rem;font-weight:700;cursor:pointer;font-family:inherit">✓ Enregistrer</button>`
    : `<button onclick="event.stopPropagation();qdEditSection('${sec}')" title="Modifier" style="background:rgba(46,102,66,.07);color:var(--forest);border:1px solid rgba(46,102,66,.2);border-radius:100px;padding:.22rem .5rem;font-size:.62rem;font-weight:700;cursor:pointer;font-family:inherit">✏️</button>`);

  // Helpers d'édition inline (les champs ne sont éditables que si leur section l'est)
  const _eb = (f,v,num,dark)=> EDinfos
    ? `<span contenteditable="true" onblur="qdSet('${f}',this.textContent${num?',1':''})" style="outline:1px dashed ${dark?'rgba(255,255,255,.5)':'rgba(46,102,66,.4)'};border-radius:4px;padding:0 .25rem;cursor:text;min-width:1ch;display:inline-block">${v}</span>`
    : `${v}`;
  const edDark = (f,v,num)=>_eb(f,v,num,true);
  const edLight= (f,v,num)=>_eb(f,v,num,false);
  const edArr = (on,f,i,v)=> on
    ? `<span contenteditable="true" onblur="qdSetArr('${f}',${i},this.textContent)" style="outline:1px dashed rgba(46,102,66,.4);border-radius:4px;padding:0 .25rem;cursor:text;min-width:1ch;display:inline-block">${v}</span>`
    : `${v}`;
  const edObj = (f,i,k,v)=> EDplan
    ? `<span contenteditable="true" onblur="qdSetObj('${f}',${i},'${k}',this.textContent)" style="outline:1px dashed rgba(46,102,66,.4);border-radius:4px;padding:0 .25rem;cursor:text;min-width:1ch;display:inline-block">${v}</span>`
    : `${v}`;
  // Champ éditable dont l'activation dépend d'un flag de section quelconque
  // (utilisé par Description et Impact, qui ont chacun leur propre crayon).
  const edSec = (on,f,v,num,dark)=> on
    ? `<span contenteditable="true" onblur="qdSet('${f}',this.textContent${num?',1':''})" style="outline:1px dashed ${dark?'rgba(255,255,255,.5)':'rgba(46,102,66,.4)'};border-radius:4px;padding:0 .25rem;cursor:text;min-width:1ch;display:inline-block">${v}</span>`
    : `${v}`;

  // Topbar
  document.getElementById('qd-topbar-title').textContent = q.titre;
  document.getElementById('qd-topbar-sub').textContent = q.lieu + ' · ' + q.ville + ' · ' + q.duree;
  // Actions (bandeau + colonne de droite selon le rôle, conscientes de l'état)
  const funded = q.financement && q.financement.objectif > 0 && q.financement.montant >= q.financement.objectif;
  const done = (k) => `<button class="btn" disabled style="opacity:.65;cursor:default;background:rgba(74,140,92,.12);color:var(--fern);border:1px solid rgba(74,140,92,.3)">${k}</button>`;
  // Dans le panneau de l'assistant Bâtisseur, on ne rejoint pas encore : on
  // SÉLECTIONNE les quêtes à garder, la fiche n'étant même pas publiée. Ailleurs
  // (tableau de bord, carte), le bouton « Rejoindre » reste inchangé.
  const _selMode = !!window._batQueteInline;
  const _selOn = _selMode && batQueteSelHas(q);
  const _btnSel = (full) => `<button class="btn ${_selOn ? '' : 'btn-primary'}" ${_selOn ? 'style="background:rgba(240,176,50,.14);color:#8a6a12;border:1px solid rgba(240,176,50,.4)' + (full ? ';width:100%;padding:.8rem;font-size:.82rem' : '') + '"' : (full ? 'style="width:100%;padding:.8rem;font-size:.82rem"' : '')} onclick="qdSelectQuete()">${_selOn ? '★ Quête sélectionnée' : '☆ Sélectionner cette quête'}</button>`;
  const ctas = {
    batisseur: _selMode ? _btnSel(false) : q.pending ? done('🕓 Demande en attente') : q.joined ? done('✓ Tu participes') : `<button class="btn btn-primary" onclick="qdJoindre()">✅ Rejoindre cette quête</button>`,
    semeur: funded ? done('✓ Quête financée') : `<button class="btn btn-primary" onclick="qdFinancer()">💰 Financer cette quête</button>`,
    // Pilote : pas de bouton dans le bandeau, les actions vivent dans
    // « Gestion de la quête » (publier/modifier) et « Preuves des bâtisseurs » (valider).
    pilote: ''
  };
  const _qdta = document.getElementById('qd-topbar-actions'); if (_qdta) _qdta.innerHTML = (currentRole in ctas) ? ctas[currentRole] : ctas.batisseur;

  // Étapes = le plan d'action de la Bibliothèque (sinon labels génériques)
  const _planSteps = (q.plan && q.plan.length) ? q.plan : null;
  const _stepCount = _planSteps ? _planSteps.length : q.etapes;
  const labels = q.etapeLabels || ['Lancement','Préparation','Réalisation','Certification'];
  const steps = Array.from({length:_stepCount},(_,i)=>{
    const done=i<q.etape_actuelle-1, active=i===q.etape_actuelle-1;
    const ps = _planSteps ? _planSteps[i] : null;
    const titre = ps ? ((ps.ic?ps.ic+' ':'')+(EDplan ? edObj('plan', i, 'titre', ps.titre||('Étape '+(i+1))) : (ps.titre||('Étape '+(i+1))))) : (labels[i]||('Étape '+(i+1)));
    const desc = (ps && (ps.desc || EDplan)) ? `<div style="font-size:.66rem;font-weight:400;color:var(--moss);opacity:.8;line-height:1.45;margin-top:.15rem">${EDplan ? edObj('plan', i, 'desc', ps.desc||'(description)') : ps.desc}</div>` : '';
    return `<div style="display:flex;align-items:flex-start;gap:.7rem;padding:.55rem .8rem;border-radius:var(--r);border:1px solid ${active?'rgba(200,115,42,.35)':done?'rgba(74,140,92,.2)':'rgba(46,102,66,.1)'};background:${active?'rgba(200,115,42,.04)':done?'rgba(74,140,92,.04)':'transparent'};margin-bottom:.35rem">
      <div style="width:22px;height:22px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:.65rem;font-weight:700;margin-top:.05rem;background:${done?'var(--fern)':active?'var(--amber)':'rgba(46,102,66,.12)'};color:${done||active?'white':'var(--moss)'}">
        ${done?'✓':i+1}
      </div>
      <div style="flex:1;min-width:0"><div style="font-size:.75rem;font-weight:${active?'700':done?'600':'500'};color:${active?'var(--ink)':done?'var(--moss)':'var(--ink)'}">${titre}</div>${desc}</div>
      ${EDplan ? `<button onclick="qdRemoveStep(${i})" title="Supprimer l'étape" style="flex-shrink:0;background:none;border:none;color:var(--moss);opacity:.5;font-size:.8rem;cursor:pointer;margin-top:.05rem">🗑️</button>` : (active?'<span style="font-size:.58rem;padding:.12rem .4rem;border-radius:100px;background:rgba(200,115,42,.15);color:var(--amber);font-weight:600;flex-shrink:0;margin-top:.1rem">En cours</span>':'')}
    </div>`;
  }).join('') + (EDplan ? `<button onclick="qdAddStep()" style="width:100%;margin-top:.1rem;background:rgba(46,102,66,.07);border:1px dashed rgba(46,102,66,.3);color:var(--forest);border-radius:8px;padding:.45rem;font-size:.72rem;font-weight:700;cursor:pointer;font-family:inherit">+ Ajouter une étape</button>` : '');

  // Financement bar
  const fin = q.financement;
  const finHtml = fin && fin.objectif>0 ? (() => {
    const pct = Math.round((fin.montant/fin.objectif)*100);
    return `<div style="background:white;border:1px solid rgba(46,102,66,.1);border-radius:var(--r-lg);padding:.9rem 1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">
        <div style="font-size:.72rem;font-weight:600;color:var(--ink)">💰 Financement</div>
        <span style="font-size:.68rem;font-weight:700;color:${pct>=100?'var(--fern)':'var(--amber)'}">
          ${fin.montant}€ / ${fin.objectif}€ (${pct}%)
        </span>
      </div>
      <div style="height:6px;background:rgba(46,102,66,.1);border-radius:100px;overflow:hidden;margin-bottom:.45rem">
        <div style="height:100%;width:${Math.min(pct,100)}%;background:${pct>=100?'var(--fern)':'var(--amber)'};border-radius:100px;transition:width .6s ease"></div>
      </div>
      ${fin.semeur?`<div style="font-size:.65rem;color:var(--moss);opacity:.75">🏢 ${fin.semeur}</div>`:'<div style="font-size:.65rem;color:var(--terracotta)">Aucun financement, <span style="cursor:pointer;text-decoration:underline" onclick="qdFinancer()">être le premier à financer</span></div>'}
    </div>`;
  })() : '';

  // Équipe, masquée tant qu'aucun Bâtisseur n'a rejoint (fiche épurée).
  const equipeHtml = (!q.equipe || !q.equipe.length) ? '' : `<div style="background:white;border:1px solid rgba(46,102,66,.1);border-radius:var(--r-lg);padding:.9rem 1rem">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.6rem">
      <div style="font-size:.72rem;font-weight:600;color:var(--ink)">👥 Équipe (${q.equipe.length}/${q.places.split('/')[1]})</div>
      <span style="font-size:.6rem;color:var(--moss);opacity:.6">${q.places} inscrits</span>
    </div>
    <div style="display:flex;gap:.4rem;align-items:center;flex-wrap:wrap">
      ${q.equipe.map(m=>`<div style="width:32px;height:32px;border-radius:50%;background:${m.c};color:white;display:flex;align-items:center;justify-content:center;font-size:.6rem;font-weight:700;border:2px solid white;box-shadow:0 1px 4px rgba(0,0,0,.15)">${m.i}</div>`).join('')}
      <div style="width:32px;height:32px;border-radius:50%;background:rgba(74,140,92,.12);border:2px dashed rgba(74,140,92,.3);display:flex;align-items:center;justify-content:center;font-size:.8rem;cursor:pointer" onclick="qdJoindre()" title="Rejoindre">+</div>
    </div>
  </div>`;

  // ESRS badges
  const esrsColors = {E1:'#2e7d32',E2:'#388e3c',E3:'#43a047',E4:'#4caf50',S1:'#1565c0',S2:'#1976d2',S3:'#1e88e5',S4:'#2196f3',G1:'#6a1b9a'};
  const esrsBadges = (q.esrs||[]).map(e=>`<span style="font-size:.62rem;padding:.18rem .5rem;border-radius:var(--r);background:${esrsColors[e]||'#546e7a'}22;color:${esrsColors[e]||'#546e7a'};border:1px solid ${esrsColors[e]||'#546e7a'}44;font-weight:600">📋 ESRS ${e}</span>`).join('');

  // Date de la quête, choisie au calendrier (input type=date). Rétro-compat :
  // à défaut de dateISO, on affiche les anciennes dates libres (q.dates).
  const _dateSet = !!q.dateISO;
  const _legacyDates = (!_dateSet && q.dates && q.dates.length) ? q.dates : null;
  // Section visible si une date existe, ou pour le Pilote (qui peut en définir une).
  const _showDates = _dateSet || _legacyDates || currentRole === 'pilote';
  const _inp = 'font-family:inherit;font-size:.8rem;color:var(--ink);border:1px solid rgba(46,102,66,.25);border-radius:10px;padding:.45rem .6rem;background:#fff';
  const dateBody = EDdates
    ? `<div style="display:flex;gap:.5rem;flex-wrap:wrap;align-items:center">
        <input type="date" value="${q.dateISO || ''}" onchange="qdSetDate(this.value)" style="${_inp}">
        <input type="time" value="${q.heure || ''}" onchange="qdSetHeure(this.value)" title="Heure (optionnel)" style="${_inp}">
        ${_dateSet ? `<button onclick="qdSetDate('');qdSetHeure('');qdRerender()" style="background:none;border:none;color:var(--moss);opacity:.6;font-size:.68rem;cursor:pointer;font-family:inherit;text-decoration:underline">effacer</button>` : ''}
       </div>`
    : _dateSet
      ? `<div style="font-size:.78rem;color:var(--ink)">📅 ${qdFormatDateFr(q.dateISO, q.heure)}</div>`
      : _legacyDates
        ? `<div style="display:flex;gap:.4rem;flex-wrap:wrap">${_legacyDates.map(d=>`<span style="font-size:.68rem;padding:.3rem .7rem;border-radius:var(--r);background:rgba(46,102,66,.07);border:1px solid rgba(46,102,66,.15);color:var(--ink)">📅 ${d}</span>`).join('')}</div>`
        : `<div style="font-size:.72rem;color:var(--moss);opacity:.7">Aucune date définie${currentRole === 'pilote' ? ', clique sur ✏️ pour en choisir une.' : ''}</div>`;

  // Colonne principale (mode édition: champs contenteditable)
  document.getElementById('qd-main').innerHTML = `
    ${EDinfos ? '<button onclick="qdSaveSection()" style="width:100%;background:var(--forest);color:#fff;border:none;border-radius:100px;padding:.65rem;font-size:.82rem;font-weight:700;cursor:pointer;margin-bottom:.2rem">✓ Enregistrer les infos</button>' : ''}

    <!-- Hero -->
    <div style="background:linear-gradient(135deg,#0e2a1a,#1a3a22);border-radius:var(--r-xl);padding:1.4rem 1.8rem;position:relative;overflow:hidden">
      <div style="position:absolute;right:-30px;top:-30px;width:150px;height:150px;background:radial-gradient(circle,rgba(122,184,64,.12),transparent);pointer-events:none;border-radius:50%"></div>
      ${currentRole === 'pilote' && !EDinfos ? `<button onclick="qdEditSection('infos')" title="Modifier les infos" style="position:absolute;top:.9rem;right:.9rem;z-index:2;background:rgba(255,255,255,.14);color:#fff;border:1px solid rgba(255,255,255,.32);border-radius:100px;padding:.22rem .5rem;font-size:.62rem;font-weight:700;cursor:pointer;font-family:inherit">✏️</button>` : ''}
      <div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:.7rem">
        <span style="font-size:.65rem;padding:.18rem .55rem;border-radius:100px;background:rgba(255,255,255,.1);color:rgba(255,255,255,.8)">${q.type}</span>
        <span style="font-size:.65rem;padding:.18rem .55rem;border-radius:100px;background:rgba(255,255,255,.08);color:rgba(255,255,255,.6)">📍 ${edDark('ville', q.ville)}</span>
        ${q.validated ? '<span style="font-size:.62rem;padding:.18rem .5rem;border-radius:100px;background:rgba(74,140,92,.25);color:#9be3a6;border:1px solid rgba(74,140,92,.4);font-weight:700">✓ Validée</span>' : ''}
        ${q.closed ? '<span style="font-size:.62rem;padding:.18rem .5rem;border-radius:100px;background:rgba(200,115,42,.2);color:#f0b96a;border:1px solid rgba(200,115,42,.35);font-weight:700">🔒 Clôturée</span>' : ''}
        ${q.paused ? '<span style="font-size:.62rem;padding:.18rem .5rem;border-radius:100px;background:rgba(240,200,74,.2);color:#f0d878;border:1px solid rgba(240,200,74,.35);font-weight:700">⏸ En pause</span>' : ''}
        ${q.pending ? '<span style="font-size:.62rem;padding:.18rem .5rem;border-radius:100px;background:rgba(200,115,42,.2);color:#f0b96a;border:1px solid rgba(200,115,42,.35);font-weight:700">🕓 En attente</span>' : q.joined ? '<span style="font-size:.62rem;padding:.18rem .5rem;border-radius:100px;background:rgba(74,140,92,.2);color:#9be3a6;border:1px solid rgba(74,140,92,.35);font-weight:700">✓ Tu participes</span>' : ''}
      </div>
      <div style="font-family:'Satoshi', sans-serif;font-size:1.5rem;font-weight:900;color:white;line-height:1.15;margin-bottom:.5rem">${edDark('titre', q.titre)}</div>
      <div style="display:flex;align-items:center;gap:.8rem;margin-bottom:${EDinfos ? '1rem' : '.7rem'};flex-wrap:wrap">
        <div style="font-size:.72rem;color:rgba(255,255,255,.5)">🏡 Pilote : ${edDark('pilote', q.pilote)}</div>
        <div style="font-size:.72rem;color:rgba(255,255,255,.5)">⏱ ${edDark('duree', q.duree)}</div>
      </div>
      ${EDinfos ? '' : `<button onclick="qdVoirLieu()" style="display:inline-flex;align-items:center;gap:.35rem;margin-bottom:1rem;background:rgba(255,255,255,.12);color:#fff;border:1px solid rgba(255,255,255,.25);border-radius:100px;padding:.4rem .85rem;font-size:.7rem;font-weight:700;cursor:pointer;font-family:inherit">🏡 Voir le lieu →</button>`}
      <div style="display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.07);border-radius:var(--r);padding:.5rem .9rem">
        <span style="font-family:'Satoshi', sans-serif;font-size:1.3rem;font-weight:900;color:var(--amber)">🌱 ${edDark('tokens', q.tokens, true)}</span>
        <span style="font-size:.6rem;color:rgba(255,255,255,.45);text-transform:uppercase;letter-spacing:.1em">graines${q.grainesParDemiJour ? ' / demi-j / pers.' : ''}</span>
      </div>
    </div>

    <!-- Description -->
    <div style="background:white;border:1px solid rgba(46,102,66,.1);border-radius:var(--r-lg);padding:1rem 1.1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">
        <div style="font-size:.72rem;font-weight:600;color:var(--ink)">📝 Description</div>
        ${secCtrl('desc', EDdesc)}
      </div>
      <p style="font-size:.8rem;color:var(--moss);line-height:1.6;margin:0">${edSec(EDdesc, 'desc', q.desc || '-')}</p>
    </div>

    <!-- Date (calendrier) -->
    ${_showDates ? `<div style="background:white;border:1px solid rgba(46,102,66,.1);border-radius:var(--r-lg);padding:.9rem 1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.55rem">
        <div style="font-size:.72rem;font-weight:600;color:var(--ink)">📅 Date</div>
        ${secCtrl('dates', EDdates)}
      </div>
      ${dateBody}
    </div>` : ''}

    <!-- Avant / Après : preuves T0 (état initial) et T1 (état final) -->
    ${(() => {
      const pvs = (typeof qdPreuvesBat === 'function') ? qdPreuvesBat(q) : [];
      if (!pvs.length) return '';
      const t0 = pvs.filter(p => p.phase === 't0').pop();
      const t1 = pvs.filter(p => p.phase !== 't0').pop();
      if (!t0 && !t1) return '';
      const card = (p, ph) => {
        const meta = QD_PHASE_META[ph];
        if (!p) return `<div style="border:1.5px dashed rgba(46,102,66,.2);border-radius:12px;padding:.9rem;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:120px">
          <div style="font-size:1.2rem;margin-bottom:.3rem;opacity:.5">${meta.ic}</div>
          <div style="font-size:.62rem;color:var(--moss);opacity:.6">${meta.label}<br>pas encore déposée</div>
        </div>`;
        return `<div style="border:1px solid rgba(46,102,66,.14);border-radius:12px;overflow:hidden;background:rgba(46,102,66,.02)">
          ${p.photo_url
            ? `<a href="${p.photo_url}" target="_blank" rel="noopener"><img src="${p.photo_url}" alt="${meta.label}" style="width:100%;height:120px;object-fit:cover;display:block"></a>`
            : `<div style="height:120px;display:flex;align-items:center;justify-content:center;font-size:2rem;background:rgba(46,102,66,.05)">${(QD_PREUVE_META[p.type] || {}).ic || '📊'}</div>`}
          <div style="padding:.55rem .7rem">
            <div style="display:flex;align-items:center;justify-content:space-between;gap:.4rem">
              <span style="font-size:.62rem;font-weight:800;color:var(--forest)">${meta.ic} ${meta.label}</span>
              ${p.validee
                ? '<span style="font-size:.56rem;font-weight:700;color:var(--fern);white-space:nowrap">✓ validée</span>'
                : '<span style="font-size:.56rem;font-weight:700;color:var(--amber);white-space:nowrap">en attente</span>'}
            </div>
            ${p.valeur ? `<div style="font-size:.7rem;font-weight:700;color:var(--ink);margin-top:.2rem">📊 ${p.valeur}</div>` : ''}
            ${p.note ? `<div style="font-size:.62rem;color:var(--moss);opacity:.8;line-height:1.4;margin-top:.15rem">${p.note}</div>` : ''}
            <div style="font-size:.56rem;color:var(--moss);opacity:.55;margin-top:.2rem">${p.batisseur_nom || 'Bâtisseur'}</div>
          </div>
        </div>`;
      };
      return `<div style="background:white;border:1px solid rgba(46,102,66,.1);border-radius:var(--r-lg);padding:1rem 1.1rem">
        <div style="font-size:.72rem;font-weight:600;color:var(--ink);margin-bottom:.6rem">📸 Avant / Après <span style="font-weight:400;opacity:.55">· la différence entre T0 et T1, c'est l'impact prouvé</span></div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:.7rem">${card(t0, 't0')}${card(t1, 't1')}</div>
      </div>`;
    })()}

    <!-- Matériel nécessaire (checklist · Bibliothèque) · replié par défaut -->
    ${(() => {
      // Toujours affichée (présentation identique pour toutes les quêtes).
      const _mat = Array.isArray(q.materiel) ? q.materiel : [];
      const checked = q.materielChecked || (q.materielChecked = []);
      const nb = _mat.filter((_, i) => checked[i]).length;
      const rows = _mat.map((m, i) => EDmat
        ? `<div style="display:flex;align-items:center;gap:.6rem;padding:.42rem .2rem;border-bottom:1px solid rgba(46,102,66,.05)"><span style="opacity:.5">🔩</span><span style="font-size:.74rem;color:var(--ink);flex:1">${edArr(EDmat, 'materiel', i, m)}</span><button onclick="qdRemoveMat(${i})" title="Supprimer" style="background:none;border:none;color:var(--moss);opacity:.5;font-size:.8rem;cursor:pointer">🗑️</button></div>`
        : `<label style="display:flex;align-items:center;gap:.6rem;padding:.42rem .2rem;cursor:pointer;border-bottom:1px solid rgba(46,102,66,.05)">
          <input type="checkbox" ${checked[i] ? 'checked' : ''} onchange="qdToggleMat(${i}, this)" style="width:16px;height:16px;accent-color:var(--forest);cursor:pointer;flex-shrink:0">
          <span style="font-size:.74rem;color:${checked[i] ? 'var(--moss)' : 'var(--ink)'};${checked[i] ? 'text-decoration:line-through;opacity:.6' : ''}">${m}</span>
        </label>`).join('')
        + (EDmat ? `<button onclick="qdAddMat()" style="width:100%;margin-top:.35rem;background:rgba(46,102,66,.07);border:1px dashed rgba(46,102,66,.3);color:var(--forest);border-radius:8px;padding:.45rem;font-size:.72rem;font-weight:700;cursor:pointer;font-family:inherit">+ Ajouter du matériel</button>` : '');
      const body = _mat.length ? `<div style="display:flex;flex-direction:column;gap:.1rem">${rows}</div>`
        : (EDmat ? `<div style="display:flex;flex-direction:column;gap:.1rem">${rows}</div>`
          : `<div style="font-size:.7rem;color:var(--moss);opacity:.55;padding:.2rem 0">Aucun matériel indiqué${currentRole === 'pilote' ? ' — ✏️ pour en ajouter' : ''}</div>`);
      return `<div style="background:white;border:1px solid rgba(46,102,66,.1);border-radius:var(--r-lg);padding:1rem 1.1rem">
      <div onclick="qdToggleSection('materiel')" style="display:flex;align-items:center;justify-content:space-between;cursor:pointer;${matOpen?'margin-bottom:.6rem':''}">
        <div style="font-size:.72rem;font-weight:600;color:var(--ink)">🧰 Le matériel <span style="font-weight:400;opacity:.5">· ${_mat.length} élément${_mat.length>1?'s':''}</span></div>
        <div style="display:flex;align-items:center;gap:.55rem">
          ${_mat.length ? `<span id="qd-mat-count" style="font-size:.62rem;font-weight:700;color:${nb===_mat.length?'var(--fern)':'var(--moss)'}">${nb===_mat.length?'🎉 Tout est prêt':nb+'/'+_mat.length}</span>` : ''}
          ${secCtrl('materiel', EDmat)}
          <span style="font-size:.7rem;color:var(--moss);opacity:.6">${matOpen?'▾':'▸'}</span>
        </div>
      </div>
      ${matOpen ? body : ''}
    </div>`; })()}

    <!-- Les étapes (le plan) -->
    ${(() => {
      const total = _stepCount;
      const fait = Math.max(0, Math.min(total, (q.etape_actuelle || 1) - 1));
      const pct = total ? Math.round(fait / total * 100) : 0;
      const complete = (q.etape_actuelle || 1) > total;
      return `<div style="background:white;border:1px solid rgba(46,102,66,.1);border-radius:var(--r-lg);padding:1rem 1.1rem">
      <div onclick="qdToggleSection('etapes')" style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem;cursor:pointer">
        <div style="font-size:.74rem;font-weight:700;color:var(--ink)">🎯 Les étapes <span style="font-weight:400;opacity:.55">· ${total} étape${total>1?'s':''}</span></div>
        <div style="display:flex;align-items:center;gap:.55rem">
          <span style="font-size:.68rem;font-weight:800;color:${complete?'var(--fern)':'var(--moss)'}">${fait}/${total} ${complete?'🌳':''}</span>
          ${secCtrl('etapes', EDplan)}
          <span style="font-size:.7rem;color:var(--moss);opacity:.6">${planOpen?'▾':'▸'}</span>
        </div>
      </div>
      <div style="height:8px;background:rgba(46,102,66,.08);border-radius:100px;overflow:hidden;margin-bottom:.75rem"><div style="height:100%;width:${pct}%;background:linear-gradient(90deg,var(--fern),#7ab840);border-radius:100px;transition:width .6s cubic-bezier(.34,1.2,.5,1)"></div></div>
      ${planOpen ? steps : ''}
      ${currentRole === 'pilote' ? `<div style="display:flex;gap:.5rem;margin-top:.5rem">
        ${!complete ? `<button onclick="qdValiderEtape()" style="flex:1;background:rgba(74,140,92,.1);color:var(--fern);border:1px solid rgba(74,140,92,.3);border-radius:100px;padding:.55rem;font-size:.74rem;font-weight:700;cursor:pointer;font-family:inherit">✓ Valider l'étape en cours →</button>`
          : `<div style="flex:1;text-align:center;font-size:.72rem;font-weight:700;color:var(--fern);background:rgba(74,140,92,.08);border-radius:100px;padding:.55rem">🌳 Toutes les étapes franchies !</div>`}
        ${(fait > 0) ? `<button onclick="qdDevaliderEtape()" title="Annuler la dernière validation" style="background:rgba(200,115,42,.08);color:#8a4a1a;border:1px solid rgba(200,115,42,.28);border-radius:100px;padding:.55rem .9rem;font-size:.72rem;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap">↩ Annuler</button>` : ''}
      </div>` : ''}
    </div>`;
    })()}

    <!-- Équipe -->
    ${equipeHtml}

    <!-- Financement -->
    ${finHtml}

    <!-- Impact -->
    <div style="background:rgba(74,140,92,.05);border:1px solid rgba(74,140,92,.2);border-radius:var(--r-lg);padding:.9rem 1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.4rem">
        <div style="font-size:.72rem;font-weight:600;color:var(--fern)">🌿 Impact si complétée</div>
        ${secCtrl('impact', EDimpact)}
      </div>
      <div style="font-size:.78rem;color:var(--ink);line-height:1.6">${edSec(EDimpact, 'impact', q.impact)}</div>
      <div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-top:.6rem">${esrsBadges}</div>
    </div>

    <!-- Preuve pour valider la quête + indicateurs qu'elle alimente -->
    <div style="background:rgba(58,110,140,.05);border:1px solid rgba(58,110,140,.2);border-radius:var(--r-lg);padding:.9rem 1rem">
      <div style="font-size:.72rem;font-weight:600;color:var(--sky);margin-bottom:.4rem">✅ Preuve pour valider la quête</div>
      <div style="font-size:.78rem;color:var(--ink);line-height:1.6;margin-bottom:${(Array.isArray(q.icis)&&q.icis.length)?'.75rem':'0'}">${q.preuve||'Photos de l\'action réalisée + indicateurs mesurés.'}</div>
      ${(Array.isArray(q.icis)&&q.icis.length)?`
        <div style="font-size:.62rem;font-weight:700;color:var(--sky);text-transform:uppercase;letter-spacing:.06em;margin-bottom:.4rem">📊 Une preuve validée alimente ${q.icis.length} indicateur${q.icis.length>1?'s':''}</div>
        <div style="display:flex;flex-wrap:wrap;gap:.35rem">${q.icis.map(ici=>`<span style="font-size:.66rem;font-weight:600;color:var(--sky);background:rgba(58,110,140,.1);border:1px solid rgba(58,110,140,.28);border-radius:100px;padding:.24rem .6rem">${ici.nom}${ici.unite?` · <span style="opacity:.7">${ici.unite}</span>`:''}</span>`).join('')}</div>`:''}
    </div>

    ${currentRole === 'pilote' ? `<button onclick="qdSaveSection()" style="width:100%;background:var(--forest);color:#fff;border:none;border-radius:100px;padding:.7rem;font-size:.82rem;font-weight:800;cursor:pointer;font-family:inherit;margin-top:.3rem">✓ Valider et enregistrer</button>` : ''}
  `;

  // Panneau profil
  const panel = document.getElementById('qd-panel');
  if (currentRole === 'batisseur' || !currentRole) {
    const md = q.matchDetails || [];
    // Score de compatibilité : présent quand la quête vient du matching bâtisseur.
    // Ouverte depuis une fiche lieu sans profil bâtisseur → on le calcule si un
    // profil existe, sinon on affiche un tiret plutôt que « undefined ».
    let _match = (q.match != null && !isNaN(q.match)) ? Math.round(q.match) : null;
    if (_match == null && typeof batFicheData !== 'undefined' && batFicheData && typeof calcMatchFull === 'function') {
      try { const _mf = calcMatchFull(batFicheData, q); if (_mf && !isNaN(_mf.score)) _match = Math.round(_mf.score); } catch (e) {}
    }
    const _hasMatch = _match != null;
    panel.innerHTML = `
      <!-- Match score -->
      <div style="background:linear-gradient(135deg,#1a3a2e,#0e2820);border-radius:var(--r-xl);padding:1.2rem;text-align:center;border:1px solid rgba(74,140,92,.2)">
        <div style="font-size:.58rem;color:var(--sage);text-transform:uppercase;letter-spacing:.12em;margin-bottom:.6rem">✦ Score de compatibilité</div>
        <div style="position:relative;width:80px;height:80px;margin:0 auto .7rem">
          <svg viewBox="0 0 80 80" style="width:100%;height:100%;transform:rotate(-90deg)">
            <circle cx="40" cy="40" r="33" fill="none" stroke="rgba(255,255,255,.08)" stroke-width="7"/>
            <circle cx="40" cy="40" r="33" fill="none" stroke="#7ab840" stroke-width="7" stroke-linecap="round"
              stroke-dasharray="${2*Math.PI*33}" stroke-dashoffset="${2*Math.PI*33*(1-(_hasMatch?_match:0)/100)}"/>
          </svg>
          <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center">
            <span style="font-family:'Satoshi', sans-serif;font-size:1.4rem;font-weight:900;color:white;line-height:1">${_hasMatch?_match:'–'}</span>
            <span style="font-size:.48rem;color:rgba(255,255,255,.4);text-transform:uppercase">match</span>
          </div>
        </div>
        ${_hasMatch ? '' : '<div style="font-size:.58rem;color:rgba(255,255,255,.45);line-height:1.4;margin-bottom:.2rem">Crée ta fiche bâtisseur pour voir ta compatibilité</div>'}
        ${md.map(m=>`<div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.3rem">
          <span style="font-size:.62rem;color:rgba(255,255,255,.55);flex:1;text-align:left">${m.skill}</span>
          <div style="width:60px;height:3px;background:rgba(255,255,255,.1);border-radius:100px;overflow:hidden">
            <div style="height:100%;width:${m.pct}%;background:#7ab840;border-radius:100px"></div>
          </div>
          <span style="font-size:.6rem;color:#7ab840;font-weight:600;min-width:28px">${m.pct}%</span>
        </div>`).join('')}
      </div>

      <!-- Ce que tu vas apprendre -->
      <div style="background:white;border:1px solid rgba(46,102,66,.12);border-radius:var(--r-lg);padding:.9rem 1rem">
        <div style="font-size:.68rem;font-weight:600;color:var(--ink);margin-bottom:.45rem">🎓 Ce que tu vas apprendre</div>
        <div style="font-size:.73rem;color:var(--moss);line-height:1.5">${q.apprendre||'Compétences terrain et documentation d\'impact'}</div>
      </div>

      <!-- Preuve attendue -->
      <div style="background:rgba(58,110,140,.06);border:1px solid rgba(58,110,140,.2);border-radius:var(--r-lg);padding:.9rem 1rem">
        <div style="font-size:.68rem;font-weight:600;color:var(--sky);margin-bottom:.45rem">📸 Preuve d'impact attendue</div>
        <div style="font-size:.72rem;color:var(--ink);line-height:1.5;margin-bottom:.7rem">${q.preuve}</div>
        ${(Array.isArray(q.icis)&&q.icis.length)?`<div style="display:flex;flex-wrap:wrap;gap:.3rem;margin-bottom:.7rem">${q.icis.map(ici=>`<span style="font-size:.62rem;font-weight:600;color:var(--sky);background:rgba(58,110,140,.1);border:1px solid rgba(58,110,140,.25);border-radius:100px;padding:.2rem .5rem">📊 ${ici.nom}</span>`).join('')}</div>`:''}
        <button class="btn" style="width:100%;font-size:.68rem;padding:.45rem;background:rgba(58,110,140,.12);color:var(--sky);border:1px solid rgba(58,110,140,.25)" onclick="qdDeposerPreuve()">Soumettre une preuve →</button>
      </div>

      <!-- CTA -->
      ${_selMode
        ? _btnSel(true)
        : q.pending
        ? `<button class="btn" disabled style="width:100%;padding:.8rem;font-size:.82rem;background:rgba(200,115,42,.1);color:#8a4a1a;border:1px solid rgba(200,115,42,.3);cursor:default">🕓 Demande en attente de validation du lieu</button>`
        : q.joined
        ? `<button class="btn" disabled style="width:100%;padding:.8rem;font-size:.82rem;background:rgba(74,140,92,.12);color:var(--fern);border:1px solid rgba(74,140,92,.3);cursor:default">✓ Tu participes à cette quête</button>
           <button class="btn btn-ghost" style="width:100%;font-size:.72rem" onclick="qdDeposerPreuve()">📎 Déposer une preuve</button>`
        : `<button class="btn btn-primary" style="width:100%;padding:.8rem;font-size:.82rem" onclick="qdJoindre()">✅ Rejoindre cette quête</button>`}
      ${_selMode ? '<div style="font-size:.66rem;color:var(--moss);opacity:.8;line-height:1.5;text-align:center">Tu la retrouveras dans « Mes quêtes ». Tu pourras la rejoindre une fois ta fiche publiée.</div>' : ''}
      <button class="btn btn-ghost" style="width:100%;font-size:.72rem" onclick="qdContactPilote()">💬 Poser une question au Pilote</button>
    `;
  } else if (currentRole === 'semeur') {
    const fin = q.financement;
    const restant = fin ? Math.max(0, fin.objectif - fin.montant) : 200;
    const funded = fin ? fin.montant >= fin.objectif && fin.objectif > 0 : false;
    panel.innerHTML = `
      <!-- ESRS alignment -->
      <div style="background:linear-gradient(135deg,#0e1e35,#162a4a);border-radius:var(--r-xl);padding:1.2rem;border:1px solid rgba(33,150,243,.2)">
        <div style="font-size:.6rem;color:rgba(144,202,249,.7);text-transform:uppercase;letter-spacing:.12em;margin-bottom:.6rem">📋 Alignement CSRD</div>
        <div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:.8rem">
          ${(q.esrs||[]).map(e=>`<span style="font-size:.7rem;padding:.25rem .6rem;border-radius:var(--r);background:rgba(33,150,243,.2);color:#90caf9;border:1px solid rgba(33,150,243,.3);font-weight:600">ESRS ${e}</span>`).join('')}
        </div>
        <div style="font-size:.7rem;color:rgba(255,255,255,.55);line-height:1.5">Cette quête couvre ${(q.esrs||[]).length} indicateur${(q.esrs||[]).length>1?'s':''} de ton référentiel. Financer = preuve auditable certifiée EVAD.</div>
      </div>

      <!-- Financer -->
      <div style="background:white;border:1px solid rgba(46,102,66,.12);border-radius:var(--r-lg);padding:.9rem 1rem">
        <div style="font-size:.68rem;font-weight:600;color:var(--ink);margin-bottom:.6rem">💰 Engager un financement</div>
        ${funded
          ? `<div style="text-align:center;padding:.6rem;background:rgba(74,140,92,.07);border-radius:var(--r);font-size:.72rem;color:var(--fern);font-weight:600;margin-bottom:.6rem">✅ Cette quête est entièrement financée</div>`
          : `<div style="background:rgba(46,102,66,.04);border:1px solid rgba(46,102,66,.15);border-radius:var(--r);padding:.7rem .85rem;margin-bottom:.7rem">
              <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.2rem">
                <span style="font-size:.65rem;color:var(--moss)">Montant total à financer</span>
                <span style="font-family:'Satoshi', sans-serif;font-size:1.3rem;font-weight:900;color:var(--ink)">${restant}€</span>
              </div>
              <div style="font-size:.6rem;color:var(--moss);opacity:.65">Engagement unique · La quête est financée en totalité ou pas du tout</div>
            </div>
            <button class="btn btn-primary" style="width:100%;padding:.65rem;font-size:.78rem" onclick="qdFinancer()">💰 Je finance cette quête (${restant}€) →</button>`
        }
        <!-- Graines + gain CSRD -->
        <div style="margin-top:.75rem;border:1px solid rgba(200,115,42,.2);border-radius:var(--r);overflow:hidden">
          <div style="background:rgba(200,115,42,.07);padding:.6rem .8rem;display:flex;align-items:center;justify-content:space-between">
            <div>
              <div style="font-size:.6rem;color:var(--moss);opacity:.75;margin-bottom:.1rem">Si complétée avec preuves certifiées</div>
              <div style="font-size:.68rem;font-weight:600;color:var(--ink)">Tu recevras en graines CSRD</div>
            </div>
            <div style="font-family:'Satoshi', sans-serif;font-size:1.25rem;font-weight:900;color:var(--amber)">+${SEM_QUETES.find(sq=>sq.id===_qdCurrentId)?.graines||Math.round((q.financement?.objectif||200)*0.15)} 🌱</div>
          </div>
          <div style="background:rgba(46,102,66,.04);border-top:1px solid rgba(200,115,42,.15);padding:.55rem .8rem">
            <div style="font-size:.62rem;font-weight:600;color:var(--moss);margin-bottom:.35rem">📋 Ce que tu gagnes en CSRD</div>
            <div style="display:flex;flex-direction:column;gap:.25rem">
              ${(q.esrs||[]).map(e => {
                const isGap = ESRS_GAP.includes(e);
                return `<div style="display:flex;align-items:center;justify-content:space-between">
                  <span style="font-size:.68rem;color:var(--ink)"><strong>${e}</strong>, ${ESRS_LABELS[e]||e}</span>
                  <span style="font-size:.6rem;padding:.1rem .45rem;border-radius:100px;font-weight:600;background:${isGap?'rgba(184,78,53,.1)':'rgba(74,140,92,.1)'};color:${isGap?'var(--terracotta)':'var(--fern)'}">
                    ${isGap?'⚠️ Gap comblé':'✓ Renforcé'}
                  </span>
                </div>`;
              }).join('')}
            </div>
          </div>
        </div>
      </div>

      <!-- Contact Pilote -->
      <div style="background:rgba(46,102,66,.05);border:1px solid rgba(46,102,66,.15);border-radius:var(--r-lg);padding:.85rem 1rem">
        <div style="font-size:.68rem;font-weight:600;color:var(--ink);margin-bottom:.3rem">🏡 Pilote responsable</div>
        <div style="font-size:.73rem;color:var(--moss);margin-bottom:.6rem">${q.pilote}</div>
        <button class="btn btn-ghost" style="width:100%;font-size:.7rem" onclick="qdContactPilote()">Contacter le Pilote →</button>
      </div>
    `;
  } else if (currentRole === 'pilote') {
    panel.innerHTML = `
      <!-- Statut -->
      <div style="background:white;border:1px solid rgba(46,102,66,.12);border-radius:var(--r-lg);padding:.9rem 1rem">
        <div style="font-size:.68rem;font-weight:600;color:var(--ink);margin-bottom:.6rem">⚙️ Gestion de la quête</div>
        <div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:.7rem">
          <button class="btn" style="font-size:.65rem;padding:.3rem .7rem;background:rgba(74,140,92,.1);color:var(--fern);border:1px solid rgba(74,140,92,.25)" onclick="qdPause()">${q.paused ? '▶️ Réactiver' : '⏸ Mettre en pause'}</button>
          <button class="btn" style="font-size:.65rem;padding:.3rem .7rem;background:rgba(200,115,42,.1);color:var(--amber);border:1px solid rgba(200,115,42,.25)" onclick="qdCloturer()">🔒 Clôturer</button>
        </div>
        <button class="btn btn-ghost" style="width:100%;font-size:.7rem;margin-bottom:.45rem" onclick="qdModifier()">✏️ Modifier les paramètres →</button>
        ${q.published
          ? `<button class="btn" style="width:100%;font-size:.72rem;background:rgba(74,140,92,.1);color:var(--fern);border:1px solid rgba(74,140,92,.3)" onclick="qdPublierReseau()">✓ Publiée · revoir au réseau →</button>`
          : `<button class="btn btn-primary" style="width:100%;font-size:.72rem;background:rgba(240,176,50,.16);color:#a06c00;border:1px solid rgba(240,176,50,.35)" onclick="qdPublier()">📣 Publier la quête →</button>`}
      </div>

      <!-- Preuves déposées (T0 état initial / T1 état final), à valider une par une -->
      ${(() => {
        const pvb = qdPreuvesBat(q);
        const pending = pvb.filter(p => !p.validee).length;
        const hasT0 = pvb.some(p => p.phase === 't0');
        const rows = pvb.length ? pvb.map(p => {
          const meta = QD_PREUVE_META[p.type] || QD_PREUVE_META.mesure;
          const ph = QD_PHASE_META[p.phase === 't0' ? 't0' : 't1'];
          const ini = ((p.batisseur_nom || 'B').trim().charAt(0) || 'B').toUpperCase();
          return `<div style="display:flex;align-items:flex-start;gap:.6rem;padding:.55rem 0;border-bottom:1px solid rgba(200,115,42,.12)">
            <div style="width:26px;height:26px;border-radius:50%;background:#4a8c5c;color:#fff;display:flex;align-items:center;justify-content:center;font-size:.56rem;font-weight:700;flex-shrink:0;margin-top:.1rem">${ini}</div>
            <div style="flex:1;min-width:0">
              <div style="font-size:.68rem;font-weight:700;color:var(--ink)">${ph.ic} ${ph.label} <span style="font-weight:500;color:var(--moss)">· ${meta.ic} ${meta.label}</span></div>
              <div style="font-size:.6rem;color:var(--moss);opacity:.7">${p.batisseur_nom || 'Bâtisseur'}${p.valeur ? ' · <b>' + p.valeur + '</b>' : ''}</div>
              ${p.note ? `<div style="font-size:.62rem;color:var(--moss);opacity:.85;line-height:1.4">${p.note}</div>` : ''}
              ${p.photo_url ? `<a href="${p.photo_url}" target="_blank" rel="noopener"><img src="${p.photo_url}" alt="preuve" style="margin-top:.3rem;max-width:100%;max-height:90px;border-radius:8px;display:block"></a>` : ''}
            </div>
            ${p.validee
              ? '<span style="font-size:.6rem;font-weight:700;color:var(--fern);white-space:nowrap;margin-top:.2rem">✓ Validée</span>'
              : '<button onclick="qdValiderPreuveBat(\'' + p.id + '\')" style="background:var(--forest);color:#fff;border:none;border-radius:100px;padding:.3rem .7rem;font-size:.62rem;font-weight:700;cursor:pointer;white-space:nowrap;flex-shrink:0;margin-top:.1rem;font-family:inherit">✅ Valider</button>'}
          </div>`;
        }).join('') : '<div style="font-size:.7rem;color:var(--moss);opacity:.55">Aucune preuve déposée pour l\'instant. Astuce : dépose toi-même la preuve T0 (état initial) dès la publication, la différence avec la T1 montrera l\'impact réel.</div>';
        return `<div style="background:rgba(200,115,42,.06);border:1px solid rgba(200,115,42,.25);border-radius:var(--r-lg);padding:.9rem 1rem">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.4rem">
            <div style="font-size:.68rem;font-weight:700;color:var(--amber)">📥 Preuves (avant / après)</div>
            <span style="font-size:.62rem;background:rgba(200,115,42,.15);color:var(--amber);padding:.1rem .45rem;border-radius:100px;font-weight:700">${pending} en attente</span>
          </div>
          <div style="font-size:.62rem;color:var(--moss);opacity:.7;margin-bottom:.55rem">T0 (état initial) puis T1 (état final) : valide les deux pour terminer la quête et nourrir ta Vadité 🌱</div>
          ${rows}
          <button class="btn btn-ghost" style="width:100%;font-size:.68rem;margin-top:.55rem" onclick="qdDeposerPreuve()">${hasT0 ? '📎 Déposer une preuve T1 (état final)' : '🌱 Déposer la preuve T0 (état initial)'}</button>
        </div>`;
      })()}

      <!-- Bâtisseurs inscrits -->
      <div style="background:white;border:1px solid rgba(46,102,66,.12);border-radius:var(--r-lg);padding:.9rem 1rem">
        <div style="font-size:.68rem;font-weight:600;color:var(--ink);margin-bottom:.5rem">👥 Bâtisseurs inscrits (${q.equipe.length})</div>
        ${q.equipe.length ? q.equipe.map(m=>`<div style="display:flex;align-items:center;gap:.6rem;padding:.3rem 0;border-bottom:1px solid rgba(46,102,66,.06)">
          <div style="width:26px;height:26px;border-radius:50%;background:${m.c};color:white;display:flex;align-items:center;justify-content:center;font-size:.58rem;font-weight:700">${m.i}</div>
          <div style="flex:1;font-size:.7rem;color:var(--ink)">${m.nom || ('Bâtisseur ' + m.i)}</div>
          ${m.bid ? `<button onclick="qdContactBatisseur('${m.bid}','${String(m.nom||'').replace(/'/g,"\\'")}')" style="flex-shrink:0;background:rgba(46,102,66,.07);color:var(--forest);border:1px solid rgba(46,102,66,.2);border-radius:100px;padding:.22rem .6rem;font-size:.62rem;font-weight:700;cursor:pointer;font-family:inherit">💬 Message</button>` : ''}
        </div>`).join('') : '<div style="font-size:.68rem;color:var(--moss);opacity:.6">Aucun bâtisseur inscrit pour l\'instant. Publie la quête au Réseau pour en mobiliser.</div>'}
      </div>

      <!-- Financement reçu -->
      ${q.financement?.semeur ? `<div style="background:rgba(58,110,140,.06);border:1px solid rgba(58,110,140,.2);border-radius:var(--r-lg);padding:.85rem 1rem">
        <div style="font-size:.68rem;font-weight:600;color:var(--sky);margin-bottom:.3rem">💰 Financement reçu</div>
        <div style="font-family:'Satoshi', sans-serif;font-size:1.2rem;font-weight:900;color:var(--sky)">${q.financement.montant}€</div>
        <div style="font-size:.65rem;color:var(--moss);opacity:.8">🏢 ${q.financement.semeur}</div>
      </div>` : ''}
    `;
  }
}

/* ─── Loops relationnels (prêts pour Supabase) : candidatures, financements,
   transactions graines. Chaque action métier écrit une ligne de jointure. ── */
function _currentBatisseurId() {
  if (!window.store) return null;
  if (!batFicheData.id) {
    // Id stable entre sessions (localStorage) : sans lui, une inscription
    // faite hier ne serait plus reconnue comme la mienne au rechargement.
    try {
      const saved = localStorage.getItem('evad:batisseur-id');
      batFicheData.id = saved || store.uuid();
      localStorage.setItem('evad:batisseur-id', batFicheData.id);
    } catch (e) { batFicheData.id = store.uuid(); }
  }
  return batFicheData.id;
}
function _currentSemeurId() {
  if (!window.store) return null;
  if (!semFicheData.id) {
    // Id stable entre sessions (localStorage) : ma fiche reste reconnue comme
    // la mienne au rechargement, et les financements pointent le bon semeur.
    try {
      const saved = localStorage.getItem('evad:semeur-id');
      semFicheData.id = saved || store.uuid();
      localStorage.setItem('evad:semeur-id', semFicheData.id);
    } catch (e) { semFicheData.id = store.uuid(); }
  }
  return semFicheData.id;
}
// Id réel de la quête dans le store (posé par batBuildQuetesFromProfile /
// openPiloteQueteFiche dans `srcId`). On ne crée plus de ligne fantôme
// « q-<index> » : l'index de BAT_QUETES change à chaque rendu et polluait
// la table quetes avec des doublons sans statut.
function _persistQuete(q) {
  if (!q) return null;
  return q.srcId || null;
}
// ═══════════════════════════════════════════════════════════════
//  ÉCONOMIE DES GRAINES (monnaie EVAD) — grand livre + escrow
//  Boucle regen : le Bâtisseur gagne en réalisant des quêtes (preuve
//  validée), le Pilote gagne quand on achète dans sa Marketplace, le
//  Semeur injecte des graines en finançant. Soldes/historique réels et
//  partagés via Supabase (tables graines_tx + mkt_transactions).
// ═══════════════════════════════════════════════════════════════

// Profil courant en tant que « partie » d'un mouvement de graines.
function evadGrainesParty(role) {
  role = role || (typeof currentRole !== 'undefined' ? currentRole : null);
  if (role === 'batisseur') {
    const id = (typeof _currentBatisseurId === 'function') ? _currentBatisseurId() : ((typeof batFicheData !== 'undefined' && batFicheData) ? batFicheData.id : null);
    const nom = ((typeof batFicheData !== 'undefined' && batFicheData) ? ((batFicheData.prenom || '') + ' ' + (batFicheData.nom || '')).trim() : '') || 'Bâtisseur';
    return id ? { type: 'batisseur', id: id, nom: nom } : null;
  }
  if (role === 'semeur') {
    const id = (typeof _currentSemeurId === 'function') ? _currentSemeurId() : ((typeof semFicheData !== 'undefined' && semFicheData) ? semFicheData.id : null);
    const nom = ((typeof semFicheData !== 'undefined' && semFicheData && semFicheData.nom) || 'Financeur');
    return id ? { type: 'semeur', id: id, nom: nom } : null;
  }
  const id = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.id) || null;
  const nom = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) || 'Mon lieu';
  return id ? { type: 'pilote', id: id, nom: nom } : null;
}

// Solde brut (grand livre) : somme des mouvements signés du profil.
function evadGrainesLedger(type, id) {
  if (!window.store || !type || !id) return 0;
  return store.where('graines_tx', t => t.party_type === type && t.party_id === id).reduce((s, t) => s + (+t.delta || 0), 0);
}
// Déblocage des graines de bienvenue : une 1ère preuve de quête VALIDÉE liée au
// profil (bâtisseur → sa preuve validée ; Pilote → une preuve validée sur ses
// quêtes). Tant que cette condition n'est pas remplie, les graines de bienvenue
// restent bloquées (inutilisables). Semeur & autres : aucun blocage.
function evadWelcomeUnlocked(type, id) {
  if (!window.store || !type || !id) return true;
  if (type === 'batisseur') return store.where('quete_preuves', p => p && p.validee === true && p.batisseur_id === id).length > 0;
  if (type === 'pilote')    return store.where('quete_preuves', p => p && p.validee === true && p.lieu_id === id).length > 0;
  return true;
}
// Montant des graines de bienvenue encore bloquées pour ce profil.
function evadWelcomeLocked(type, id) {
  if ((type !== 'batisseur' && type !== 'pilote') || !window.store) return 0;
  if (evadWelcomeUnlocked(type, id)) return 0;
  const w = store.where('graines_tx', t => t.party_type === type && t.party_id === id && t.type === 'welcome')
    .reduce((s, t) => s + (+t.delta || 0), 0);
  return w > 0 ? w : 0;
}
// Graines bloquées : achats en attente de confirmation du vendeur + graines de
// bienvenue non encore débloquées (1ère preuve validée).
function evadGrainesBlocked(type, id) {
  if (!window.store || !type || !id) return 0;
  const escrow = store.where('mkt_transactions', t => t.buyer_type === type && t.buyer_id === id && t.statut === 'en_attente').reduce((s, t) => s + (+t.prix || 0), 0);
  return escrow + evadWelcomeLocked(type, id);
}
// Solde disponible = grand livre − bloqué.
function evadGrainesDispo(type, id) {
  const p = (type && id) ? { type: type, id: id } : evadGrainesParty();
  if (!p) return 0;
  return Math.max(0, evadGrainesLedger(p.type, p.id) - evadGrainesBlocked(p.type, p.id));
}
// Écrit un mouvement de graines (delta signé) et notifie l'UI.
function evadGrainesMove(party, delta, txType, label, refTable, refId) {
  if (!window.store || !party || !party.id || !delta) return null;
  const row = store.insert('graines_tx', {
    party_type: party.type, party_id: party.id, delta: delta,
    type: txType || 'ajustement', label: label || '',
    ref_table: refTable || null, ref_id: refId != null ? String(refId) : null
  });
  try { window.dispatchEvent(new CustomEvent('evad:graines-changed')); } catch (e) {}
  return row;
}
function _evadWelcomeAmount(party) {
  // Bâtisseur & Pilote : 10 graines de bienvenue, bloquées jusqu'à leur 1ère
  // Vadité validée (preuve d'une quête) — voir evadWelcomeLocked /
  // evadWelcomeUnlocked. Semeur : aucune graine de bienvenue.
  if (party.type === 'batisseur') return 10;
  if (party.type === 'pilote') return 10;
  return 0;
}
// Don de bienvenue (une seule fois par profil) : amorce l'économie regen.
function evadGrainesEnsureWelcome(party) {
  party = party || evadGrainesParty();
  if (!window.store || !party || !party.id) return;
  const has = store.where('graines_tx', t => t.party_type === party.type && t.party_id === party.id && t.type === 'welcome').length;
  if (has) return;
  const amt = _evadWelcomeAmount(party);
  if (amt > 0) evadGrainesMove(party, amt, 'welcome', 'Graines de bienvenue');
}
// Historique (récent d'abord), réservations d'achat en attente incluses.
function evadGrainesHistory(type, id) {
  const p = (type && id) ? { type: type, id: id } : evadGrainesParty();
  if (!p || !window.store) return [];
  const led = store.where('graines_tx', t => t.party_type === p.type && t.party_id === p.id)
    .map(t => ({ ts: t.created_at || '', delta: +t.delta || 0, type: t.type, label: t.label || '', pending: false }));
  const pend = store.where('mkt_transactions', t => t.buyer_type === p.type && t.buyer_id === p.id && t.statut === 'en_attente')
    .map(t => ({ ts: t.created_at || '', delta: -(+t.prix || 0), type: 'reservation', label: 'Réservation · ' + (t.offer_titre || 'offre'), pending: true }));
  return led.concat(pend).sort((a, b) => (b.ts || '').localeCompare(a.ts || ''));
}

// Vendeur d'une offre = le lieu qui l'a publiée (id null = offre catalogue de
// démo sans vendeur réel → achat direct sans escrow).
function evadOfferSeller(o) {
  const src = (typeof pmktOffers !== 'undefined') ? pmktOffers.find(x => x.id === o.id) : null;
  const id = (src && src.lieu_id) || o.seller_id || null;
  const nom = (src && src.lieu_nom) || o.seller_nom || o.lieu || 'Lieu';
  return { type: 'pilote', id: id, nom: nom };
}
function _mktCode() { return String(Math.floor(1000 + Math.random() * 9000)); }

// Ventes / achats en attente pour le profil courant.
function evadPendingSales() {
  const p = evadGrainesParty(); if (!p || !window.store) return [];
  return store.where('mkt_transactions', t => t.seller_type === p.type && t.seller_id === p.id && t.statut === 'en_attente')
    .sort((a, b) => (b.created_at || '').localeCompare(a.created_at || ''));
}
function evadPendingPurchases() {
  const p = evadGrainesParty(); if (!p || !window.store) return [];
  return store.where('mkt_transactions', t => t.buyer_type === p.type && t.buyer_id === p.id && t.statut === 'en_attente')
    .sort((a, b) => (b.created_at || '').localeCompare(a.created_at || ''));
}
// ── Récolte : le déverrouillage passe par l'Edge Function « recolte-unlock ».
// Le front n'écrit JAMAIS graines_tx / mkt_transactions / places en direct : il
// appelle la fonction (réserver / confirmer / annuler), puis re-hydrate.
async function evadRecolteEdge(action, payload) {
  if (!window.evadSupabase || !window.evadSupabase.functions) {
    return { error: { message: 'Connexion indisponible, réessaie dans un instant.' } };
  }
  try {
    const r = await window.evadSupabase.functions.invoke('recolte-unlock', {
      body: Object.assign({ action: action }, payload || {})
    });
    if (r.error) {
      let msg = r.error.message || 'Opération impossible.';
      try { const b = JSON.parse(await r.error.context.text()); msg = b.message || b.error || msg; } catch (e) {}
      return { error: { message: msg } };
    }
    return { data: r.data };
  } catch (e) { return { error: { message: e.message || 'Opération impossible.' } }; }
}
// Recharge accès + transactions + grand livre depuis Supabase, puis rafraîchit l'UI.
async function evadRecolteRefresh() {
  try { if (store.hydrateOffres) await store.hydrateOffres(); } catch (e) {}
  try { if (store.hydrateMktTx) await store.hydrateMktTx(); } catch (e) {}
  try { if (store.hydrateGraines) await store.hydrateGraines(); } catch (e) {}
  try { if (typeof evadSyncPmktFromStore === 'function') evadSyncPmktFromStore(); } catch (e) {}
  try { window.dispatchEvent(new CustomEvent('evad:graines-changed')); } catch (e) {}
  try { if (typeof evadWalletRender === 'function') evadWalletRender(); } catch (e) {}
}

// Le Pilote hôte confirme la remise → transfert réel des graines (via l'Edge Function).
async function evadConfirmSale(txId) {
  const tx = store.get('mkt_transactions', txId);
  if (!tx || tx.statut !== 'en_attente') return;
  const p = (typeof evadGrainesParty === 'function') ? evadGrainesParty() : null;
  const r = await evadRecolteEdge('confirm', { tx_id: txId, confirming_lieu: (p && p.id) || tx.seller_id || '' });
  if (r.error) { if (typeof mmBubble === 'function') mmBubble('⚠️ ' + r.error.message); return; }
  await evadRecolteRefresh();
  const prix = +tx.prix || 0;
  if (typeof mmBubble === 'function') mmBubble('✅ Remise confirmée · ' + (prix > 0 ? '+' + prix + ' graines reçues de ' + (tx.buyer_nom || 'ce Bâtisseur') : 'accès gratuit ouvert'));
}
// Annulation tant que non confirmée (via l'Edge Function) : la place est rendue,
// aucune graine ne bouge.
async function evadCancelTx(txId) {
  const tx = store.get('mkt_transactions', txId);
  if (!tx || tx.statut !== 'en_attente') return;
  const r = await evadRecolteEdge('cancel', { tx_id: txId });
  if (r.error) { if (typeof mmBubble === 'function') mmBubble('⚠️ ' + r.error.message); return; }
  await evadRecolteRefresh();
  if (typeof mmBubble === 'function') mmBubble('Réservation annulée · graines débloquées');
}

// Compat : ancien helper, redirigé vers le grand livre.
function _grainesTx(userId, type, montant, label, refTable, refId) {
  if (!window.store || !montant) return;
  const party = evadGrainesParty();
  if (!party) return;
  const delta = (type === 'depense' || type === 'achat') ? -Math.abs(montant) : Math.abs(montant);
  evadGrainesMove(party, delta, type, label, refTable, refId);
}

// ─── Portefeuille de graines : solde, bloqué, échanges à valider, historique ───
const EVAD_TX_ICON = { welcome: '🎁', quete: '🌾', vente: '🛒', achat: '🛍', reservation: '🔒', financement: '💧', injection: '🌱', ajustement: '⚙️' };
function _evadTxDate(ts) {
  if (!ts) return '';
  try { return new Date(ts).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' }); } catch (e) { return ''; }
}
function evadOpenWallet() {
  let m = document.getElementById('evad-wallet-modal');
  if (!m) {
    m = document.createElement('div');
    m.id = 'evad-wallet-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:9000;display:none;align-items:center;justify-content:center;background:rgba(20,40,30,.45);padding:1rem';
    m.innerHTML = '<div id="evad-wallet-box" style="background:white;border-radius:var(--r-xl,20px);max-width:520px;width:100%;max-height:86vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.25)"></div>';
    m.addEventListener('click', e => { if (e.target === m) evadCloseWallet(); });
    document.body.appendChild(m);
  }
  m.style.display = 'flex';
  evadWalletRender();
}
function evadCloseWallet() { const m = document.getElementById('evad-wallet-modal'); if (m) m.style.display = 'none'; }
function evadWalletRender() {
  const box = document.getElementById('evad-wallet-box');
  if (!box) return;
  const p = evadGrainesParty();
  if (!p) {
    box.innerHTML = '<div style="padding:2rem;text-align:center;color:var(--moss)">Crée ton profil pour activer ton portefeuille de graines.<div style="margin-top:1rem"><button class="btn btn-ghost" onclick="evadCloseWallet()">Fermer</button></div></div>';
    return;
  }
  evadGrainesEnsureWelcome(p);
  const dispo = evadGrainesDispo(p.type, p.id);
  const bloque = evadGrainesBlocked(p.type, p.id);
  const wLocked = evadWelcomeLocked(p.type, p.id);   // graines de bienvenue non débloquées
  const ventes = evadPendingSales();
  const achats = evadPendingPurchases();
  const hist = evadGrainesHistory(p.type, p.id);
  const roleLbl = { pilote: 'Pilote · ' + p.nom, batisseur: 'Bâtisseur', semeur: 'Financeur' }[p.type] || p.type;

  const venteHtml = !ventes.length ? '' : `
    <div style="padding:0 1.2rem 0.2rem">
      <div style="font-size:.66rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:var(--forest);margin:.9rem 0 .5rem">🤝 Échanges à confirmer (${ventes.length})</div>
      ${ventes.map(t => `
        <div style="border:1px solid rgba(74,140,92,.25);border-radius:var(--r-lg,14px);padding:.7rem .85rem;margin-bottom:.5rem;background:rgba(74,140,92,.04)">
          <div style="display:flex;justify-content:space-between;gap:.5rem;align-items:start">
            <div style="min-width:0">
              <div style="font-size:.78rem;font-weight:700;color:var(--ink)">${t.offer_titre || 'Offre'}</div>
              <div style="font-size:.66rem;color:var(--moss);margin-top:.15rem">Acheteur : <b>${t.buyer_nom || '—'}</b> · code <b style="letter-spacing:.15em">${t.code || '----'}</b></div>
            </div>
            <div style="font-weight:800;color:var(--amber);white-space:nowrap">🌱 ${t.prix}</div>
          </div>
          <div style="display:flex;gap:.4rem;margin-top:.6rem">
            <button class="btn btn-primary" style="flex:1;padding:.4rem;font-size:.7rem" onclick="evadConfirmSale('${t.id}')">✅ Confirmer la remise</button>
            <button class="btn btn-ghost" style="padding:.4rem .7rem;font-size:.7rem" onclick="evadCancelTx('${t.id}')">Refuser</button>
          </div>
        </div>`).join('')}
    </div>`;

  const achatHtml = !achats.length ? '' : `
    <div style="padding:0 1.2rem 0.2rem">
      <div style="font-size:.66rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:var(--amber);margin:.9rem 0 .5rem">🔒 Mes achats en attente (${achats.length})</div>
      ${achats.map(t => `
        <div style="border:1px solid rgba(200,115,42,.28);border-radius:var(--r-lg,14px);padding:.7rem .85rem;margin-bottom:.5rem;background:rgba(200,115,42,.04)">
          <div style="display:flex;justify-content:space-between;gap:.5rem;align-items:start">
            <div style="min-width:0">
              <div style="font-size:.78rem;font-weight:700;color:var(--ink)">${t.offer_titre || 'Offre'}</div>
              <div style="font-size:.66rem;color:var(--moss);margin-top:.15rem">Chez <b>${t.seller_nom || '—'}</b> · montre le code <b style="letter-spacing:.15em">${t.code || '----'}</b></div>
            </div>
            <div style="font-weight:800;color:var(--amber);white-space:nowrap">−${t.prix}</div>
          </div>
          <div style="margin-top:.5rem"><button class="btn btn-ghost" style="padding:.35rem .7rem;font-size:.68rem" onclick="evadCancelTx('${t.id}')">Annuler la réservation</button></div>
        </div>`).join('')}
    </div>`;

  const histHtml = !hist.length
    ? '<div style="padding:1rem 1.2rem;font-size:.72rem;color:var(--moss);opacity:.6">Aucun mouvement pour l\'instant.</div>'
    : hist.slice(0, 40).map(h => {
        const pos = h.delta >= 0;
        return `<div style="display:flex;align-items:center;gap:.6rem;padding:.5rem 1.2rem;border-top:1px solid rgba(46,102,66,.06)">
          <div style="width:26px;height:26px;border-radius:7px;background:rgba(46,102,66,.07);display:flex;align-items:center;justify-content:center;font-size:.85rem">${EVAD_TX_ICON[h.type] || '•'}</div>
          <div style="flex:1;min-width:0">
            <div style="font-size:.72rem;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${h.label || h.type}${h.pending ? ' <span style="font-size:.58rem;color:var(--amber);font-weight:700">· bloqué</span>' : ''}</div>
            <div style="font-size:.58rem;color:var(--moss);opacity:.6">${_evadTxDate(h.ts)}</div>
          </div>
          <div style="font-weight:800;font-size:.8rem;color:${pos ? 'var(--fern)' : 'var(--terracotta)'};white-space:nowrap">${pos ? '+' : ''}${h.delta}</div>
        </div>`;
      }).join('');

  box.innerHTML = `
    <div style="padding:1.2rem 1.2rem .5rem;position:sticky;top:0;background:white;z-index:1">
      <div style="display:flex;justify-content:space-between;align-items:start">
        <div>
          <div style="font-family:'Satoshi',sans-serif;font-size:1.1rem;font-weight:900;color:var(--ink)">🌱 Mes graines</div>
          <div style="font-size:.64rem;color:var(--moss);opacity:.7">${roleLbl}</div>
        </div>
        <button onclick="evadCloseWallet()" style="background:rgba(46,102,66,.08);border:none;border-radius:50%;width:30px;height:30px;cursor:pointer;font-size:.85rem;color:var(--moss)">✕</button>
      </div>
      <div style="margin-top:.8rem;background:linear-gradient(135deg,#1a3a2e,#0e2820);border-radius:var(--r-lg,14px);padding:1rem 1.2rem;color:white">
        <div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.12em;color:rgba(255,255,255,.6)">Solde disponible</div>
        <div style="font-family:'Satoshi',sans-serif;font-size:2rem;font-weight:900;line-height:1.1">🌱 ${dispo}</div>
        ${bloque > 0 ? `<div style="font-size:.64rem;color:rgba(255,255,255,.75);margin-top:.35rem;line-height:1.55">
          ${wLocked > 0 ? `🔒 ${wLocked} graines de bienvenue · débloquées dès ta 1<sup>re</sup> Vadité validée (preuve d'une quête)` : ''}
          ${(bloque - wLocked) > 0 ? `${wLocked > 0 ? '<br>' : ''}🔒 ${bloque - wLocked} bloquées · achats en attente` : ''}
        </div>` : ''}
      </div>
    </div>
    ${venteHtml}
    ${achatHtml}
    <div style="padding:.2rem 0 1rem">
      <div style="font-size:.66rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:var(--moss);opacity:.7;margin:.9rem 1.2rem .3rem">Historique</div>
      ${histHtml}
    </div>`;
}

function qdJoindre() {
  const q = qdQuest(); if (!q) return;
  if (q.pending) { mmBubble('🕓 Ta demande est déjà en attente de validation du lieu'); return; }
  if (q.joined) { mmBubble('Tu participes déjà à cette quête'); return; }
  const prenom = (typeof batFicheData !== 'undefined' && batFicheData.prenom) || '';
  const nom = (typeof batFicheData !== 'undefined' && batFicheData.nom) || '';
  const batNom = (prenom + ' ' + nom).trim() || 'Bâtisseur';
  q.joined = true;
  q.equipe = q.equipe || [];
  q.equipe.push({ i: (batNom.charAt(0) || 'B').toUpperCase(), c: '#018262', nom: batNom });
  const m = String(q.places || '0/6').split('/');
  const cur = Math.min((parseInt(m[0], 10) || 0) + 1, parseInt(m[1], 10) || 6);
  q.places = cur + '/' + (m[1] || 6);
  // Demande d'inscription persistée : table quete_candidatures (locale + Supabase).
  // Statut « en_attente » : le Pilote doit valider avant que le bâtisseur
  // rejoigne réellement l'équipe. Id composite bâtisseur × quête → pas de doublon.
  if (window.store && q.srcId) {
    try {
      const bid = _currentBatisseurId();
      store.upsert('quete_candidatures', {
        id: 'cand-' + bid + '-' + q.srcId,
        quete_id: q.srcId,
        lieu_id: q.lieuId || null,
        batisseur_id: bid,
        batisseur_nom: batNom,
        statut: 'en_attente'
      });
    } catch (e) {}
  }
  q.pending = true;
  mmBubble('🕓 Demande envoyée · en attente de validation du lieu pour « ' + (q.titre || 'la quête') + ' »');
  qdRerender();
}
function qdFinancer() {
  const q = qdQuest(); if (!q) return;
  const semNom = (typeof semFicheData !== 'undefined' && semFicheData && semFicheData.nom) ? semFicheData.nom : 'Mon organisation';
  q.financement = q.financement || {};
  if (!q.financement.objectif || q.financement.objectif <= 0) q.financement.objectif = Math.max(2000, (q.tokens || 50) * 40);
  q.financement.montant = q.financement.objectif;
  q.financement.semeur = semNom;
  // Financement : jointure semeur × quête (id composite → pas de doublon).
  if (window.store) {
    try {
      const sid = _currentSemeurId(), qid = _persistQuete(q);
      store.upsert('financements', { id: 'fin-' + sid + '-' + qid, semeur_id: sid, quete_id: qid, montant: q.financement.objectif });
      // Injection regen : le Semeur verse des graines (montant de la quête) au
      // lieu → ce sont elles qui alimentent la récompense du bâtisseur.
      const qrow = qid ? store.get('quetes', qid) : null;
      const lieuId = qrow && qrow.lieu_id;
      const sp = (typeof evadGrainesParty === 'function') ? evadGrainesParty('semeur') : null;
      const inject = (typeof q.tokens === 'number') ? q.tokens : (parseInt(q.tokens, 10) || 50);
      if (sp && lieuId) {
        const dejaInj = store.where('graines_tx', t => t.type === 'financement' && t.ref_id === String(qid) && t.party_id === sp.id).length;
        if (!dejaInj && evadGrainesDispo(sp.type, sp.id) >= inject) {
          evadGrainesMove(sp, -inject, 'financement', 'Financement quête · ' + (q.titre || ''), 'quetes', qid);
          evadGrainesMove({ type: 'pilote', id: lieuId }, inject, 'injection', 'Financement reçu · ' + (q.titre || ''), 'quetes', qid);
        }
      }
    } catch (e) {}
  }
  mmBubble('💰 Quête financée par ' + semNom + ' · preuve auditable certifiée EVAD');
  qdRerender();
}
function qdValider() {
  const q = qdQuest(); if (!q) return;
  if (q.etape_actuelle < q.etapes) {
    q.etape_actuelle++;
    if (q.etape_actuelle >= q.etapes) { q.validated = true; mmBubble('✅ Preuve certifiée · quête complétée, graines distribuées 🌱'); }
    else mmBubble('✅ Étape validée · progression ' + q.etape_actuelle + '/' + q.etapes);
  } else { q.validated = true; mmBubble('✅ Toutes les preuves sont validées'); }
  qdRerender();
}
function qdCloturer() {
  const q = qdQuest(); if (!q) return;
  q.closed = true; mmBubble('🔒 Quête clôturée'); qdRerender();
}
// Publie la quête : la rend visible aux bâtisseurs (statut 'ouverte') + la pousse au Réseau.
function qdPublier() {
  const q = qdQuest(); if (!q) return;
  q.published = true;
  // Répercute sur la quête source du Pilote → désormais proposée aux bâtisseurs.
  if (q.srcId && typeof PILOTE_QUETES_DEMO !== 'undefined') {
    const src = PILOTE_QUETES_DEMO.find(x => x.id === q.srcId);
    if (src) { src.statut = 'ouverte'; if (window.store) { try { store.update('quetes', src.id, { statut: 'ouverte' }); } catch (e) {} } }
  }
  qdPublierReseau();
}
function qdPublierReseau() {
  const q = qdQuest(); if (!q || typeof RESEAU_POSTS === 'undefined') return;
  const lieuNom = q.pilote || q.lieu || ((typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) || 'Mon lieu');
  const ville = q.ville || 'Bordeaux';
  if (!(RESEAU_POSTS[0] && RESEAU_POSTS[0].quest && RESEAU_POSTS[0].quest.titre === q.titre && RESEAU_POSTS[0].author === lieuNom)) {
    const post = {
      profile: 'pilote', author: lieuNom, lieu: ville, time: "à l'instant",
      type: 'quete', regen: 'activer',
      text: "On lance une nouvelle quête sur notre lieu ⚡ « " + q.titre + " ». On mobilise des Bâtisseurs, rejoignez-nous !",
      // L'id de la quête voyage avec le post : le CTA « Rejoindre la quête »
      // du fil ouvre la vraie fiche (reseauJoinQuete).
      quest: { id: q.srcId || null, titre: q.titre, meta: [q.duree, (q.places ? q.places.split('/')[1] + ' pers.' : ''), (q.tokens + ' graines')].filter(Boolean).join(' · ') },
      cta: 'Rejoindre la quête'
    };
    RESEAU_POSTS.unshift(post);
    // Persistance : sans ça le post n'existait qu'en mémoire (invisible des
    // autres utilisateurs, perdu au rechargement).
    if (typeof reseauPersistPost === 'function') reseauPersistPost(post);
  }
  showScreen('reseau');
  setTimeout(() => {
    if (typeof reseauTab === 'function') { try { reseauTab('fil', document.getElementById('rtab-fil')); } catch (e) {} }
    if (typeof reseauSetFilter === 'function') reseauSetFilter('tout', document.querySelector('.reseau-filter[data-f="tout"]'));
  }, 120);
  if (typeof mmBubble === 'function') mmBubble('📣 Quête publiée au Réseau !');
}

/* ─── GESTION MARKETPLACE PILOTE ─── */
const PMKT_OFFERS_INIT = [];

let pmktOffers = PMKT_OFFERS_INIT.map(o => ({...o}));
let pmktFilter = 'toutes';
let pmktEditingId = null;

// Ligne store `offres_mkt` → format d'offre utilisé par l'UI.
function _offreRowToPmkt(r) {
  return {
    id: r.id, emoji: r.emoji || '🌿', bg: r.bg || 'rgba(74,140,92,.1)',
    titre: r.titre || '', cat: r.cat || 'service', prix: +r.prix || 0,
    stock: +r.stock || 0, stockMax: +r.stockMax || +r.stock_max || 0,
    desc: r.desc || r.description || '', status: r.status || r.statut || 'active',
    vues: +r.vues || 0, echanges: +r.echanges || 0, date: r.date || '',
    hors_exploitation: !!r.hors_exploitation,
    lieu_id: r.lieu_id || null, lieu_nom: r.lieu_nom || null
  };
}
// Reconstruit pmktOffers (les offres de MON lieu) depuis le store.
function evadSyncPmktFromStore() {
  if (!window.store) return;
  const myId = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.id) || null;
  const rows = store.all('offres_mkt') || [];
  pmktOffers = rows.filter(r => myId ? r.lieu_id === myId : true).map(_offreRowToPmkt);
}
// Enregistre une offre dans le store (→ Supabase). Estampille le lieu vendeur.
function evadPersistOffre(o) {
  if (!window.store || !o) return;
  const lieuId = o.lieu_id || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.id) || null;
  const lieuNom = o.lieu_nom || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) || 'Mon lieu';
  store.upsert('offres_mkt', {
    id: o.id, lieu_id: lieuId, lieu_nom: lieuNom,
    titre: o.titre, cat: o.cat, prix: o.prix, stock: o.stock, stockMax: o.stockMax,
    emoji: o.emoji, desc: o.desc, date: o.date || '', status: o.status, vues: o.vues, echanges: o.echanges,
    hors_exploitation: !!o.hors_exploitation
  });
  o.lieu_id = lieuId; o.lieu_nom = lieuNom;
}

function pmktFilterOffers(f, btn) {
  pmktFilter = f;
  document.querySelectorAll('.pmkt-filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  pmktRenderOffers();
}

function pmktRenderOffers() {
  const list = document.getElementById('pmkt-offers-list');
  if (!list) return;
  // Reflète l'état partagé (store/Supabase) : offres de MON lieu.
  if (typeof evadSyncPmktFromStore === 'function') evadSyncPmktFromStore();
  let offers = [...pmktOffers];
  if (pmktFilter === 'actives') offers = offers.filter(o => o.status === 'active');
  if (pmktFilter === 'pausees') offers = offers.filter(o => o.status === 'paused' || o.status === 'full');

  const statusLabel = { active:'Active', paused:'En pause', full:'Stock épuisé' };
  const statusCls   = { active:'pmkt-status-active', paused:'pmkt-status-paused', full:'pmkt-status-full' };

  const noOffersAtAll = pmktOffers.length === 0;
  const exemples = ['📚 un atelier', '🤝 un coup de main', '🛠 un prêt de matériel', '🏛 une location de salle', '🏡 un hébergement'];
  const inviteHtml = '<div style="padding:1.8rem 1.6rem;text-align:center">'
    + '<div style="font-size:2.2rem;margin-bottom:.5rem">🤲</div>'
    + '<div style="font-family:\'Satoshi\',sans-serif;font-size:1rem;font-weight:800;color:var(--ink);margin-bottom:.4rem">Ouvre les portes de ton lieu</div>'
    + '<div style="font-size:.76rem;color:var(--moss);line-height:1.6;max-width:460px;margin:0 auto .9rem">Propose des <b>accès que les Bâtisseurs déverrouillent avec leurs graines</b>, reçues en reconnaissance de ce qu\'ils ont fait pousser ici. Chaque porte ouverte, c\'est une raison de plus de venir contribuer à ton lieu.</div>'
    + '<div style="display:flex;flex-wrap:wrap;gap:.4rem;justify-content:center;margin-bottom:1.1rem">' + exemples.map(e => '<span style="font-size:.66rem;color:var(--ink);background:rgba(46,102,66,.06);border:1px solid rgba(46,102,66,.12);border-radius:100px;padding:.25rem .6rem">' + e + '</span>').join('') + '</div>'
    + '<button class="btn btn-primary" style="font-size:.78rem;padding:.6rem 1.4rem" onclick="piloteMktOpenAdd()">+ Ouvrir mon premier accès</button>'
    + '</div>';
  // En-tête : échanges à confirmer (escrow). Le solde vit dans la carte KPI
  // « mes graines » (en haut), pas dans un bouton séparé.
  const _wp2 = (typeof evadGrainesParty === 'function') ? evadGrainesParty('pilote') : null;
  if (_wp2 && typeof evadGrainesEnsureWelcome === 'function') evadGrainesEnsureWelcome(_wp2);
  const _sales = (typeof evadPendingSales === 'function') ? evadPendingSales() : [];
  const _dispo = (typeof evadGrainesDispo === 'function') ? evadGrainesDispo() : 0;
  const _soldeEl = document.getElementById('pmkt-graines-solde');
  if (_soldeEl) _soldeEl.textContent = _dispo;
  const _walletBtn = '';
  const _salesBanner = _sales.length
    ? `<div style="display:flex;align-items:center;justify-content:space-between;gap:.7rem;background:rgba(74,140,92,.08);border:1px solid rgba(74,140,92,.28);border-radius:var(--r-lg,14px);padding:.7rem .9rem;margin-bottom:.8rem">
         <div style="font-size:.74rem;color:var(--forest)">🤝 <b>${_sales.length} déverrouillage${_sales.length > 1 ? 's' : ''}</b> en attente de ta confirmation (remise de l'accès).</div>
         <button class="btn btn-primary" style="font-size:.72rem;padding:.4rem 1rem;white-space:nowrap" onclick="evadOpenWallet()">Confirmer →</button>
       </div>`
    : '';
  list.innerHTML = _walletBtn + _salesBanner + (offers.length === 0
    ? (noOffersAtAll ? inviteHtml : `<div style="padding:2rem;text-align:center;font-size:.78rem;color:var(--moss);opacity:.6">Aucun accès dans ce type.</div>`)
    : offers.map(o => `
    <div class="pmkt-offer-row">
      <div class="pmkt-offer-icon" style="background:${o.bg}">${o.emoji}</div>
      <div class="pmkt-offer-info">
        <div class="pmkt-offer-title">${o.titre}</div>
        <div class="pmkt-offer-meta">
          <span>🌱 ${o.prix} graines</span>
          <span>🎟 Places : ${o.stock}/${o.stockMax}</span>
          <span>👁 ${o.vues} vues</span>
          <span>✅ ${o.echanges} déverrouillages</span>
        </div>
      </div>
      <div style="display:flex;align-items:center;gap:.6rem;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end">
        <span class="pmkt-status-pill ${statusCls[o.status]}">${statusLabel[o.status]}</span>
        <div class="pmkt-actions">
          <button class="pmkt-btn pmkt-btn-edit" onclick="piloteMktOpenEdit('${o.id}')">✏️ Modifier</button>
          <button class="pmkt-btn pmkt-btn-toggle" onclick="piloteMktToggle('${o.id}')">${o.status === 'paused' ? '▶ Activer' : '⏸ Pause'}</button>
          <button class="pmkt-btn pmkt-btn-delete" onclick="piloteMktDelete('${o.id}')">🗑</button>
        </div>
      </div>
    </div>`).join(''));

  // update active count badge
  const activeCount = pmktOffers.filter(o => o.status === 'active').length;
  const el = document.getElementById('pmkt-count-active');
  if (el) el.textContent = activeCount;

  // Historique des graines juste en dessous des offres.
  if (typeof pmktRenderHistory === 'function') pmktRenderHistory();
}

// Historique des mouvements de graines du lieu (crédits/débits + achats en
// attente), affiché dans l'onglet « Marché » du tableau de bord.
function pmktRenderHistory() {
  const box = document.getElementById('pmkt-tx-history');
  if (!box) return;
  const soldeEl = document.getElementById('pmkt-tx-solde');
  const p = (typeof evadGrainesParty === 'function') ? evadGrainesParty('pilote') : null;
  if (!p) {
    box.innerHTML = '<div style="padding:1rem 1.2rem;font-size:.72rem;color:var(--moss);opacity:.6">Publie ta fiche lieu pour activer ton portefeuille de graines.</div>';
    if (soldeEl) soldeEl.textContent = '';
    return;
  }
  if (typeof evadGrainesEnsureWelcome === 'function') evadGrainesEnsureWelcome(p);
  if (soldeEl) soldeEl.textContent = 'Solde : 🌱 ' + evadGrainesDispo(p.type, p.id);
  const hist = (typeof evadGrainesHistory === 'function') ? evadGrainesHistory(p.type, p.id) : [];
  if (!hist.length) {
    box.innerHTML = '<div style="padding:1rem 1.2rem;font-size:.72rem;color:var(--moss);opacity:.6">Aucun mouvement pour l\'instant. Tes ventes et financements reçus apparaîtront ici.</div>';
    return;
  }
  box.innerHTML = hist.slice(0, 50).map(h => {
    const pos = h.delta >= 0;
    const ic = (typeof EVAD_TX_ICON !== 'undefined' && EVAD_TX_ICON[h.type]) || '•';
    const dt = (typeof _evadTxDate === 'function') ? _evadTxDate(h.ts) : '';
    return `<div style="display:flex;align-items:center;gap:.6rem;padding:.55rem 1.2rem;border-top:1px solid rgba(46,102,66,.06)">
      <div style="width:26px;height:26px;border-radius:7px;background:rgba(46,102,66,.07);display:flex;align-items:center;justify-content:center;font-size:.85rem;flex-shrink:0">${ic}</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:.72rem;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${h.label || h.type}${h.pending ? ' <span style="font-size:.58rem;color:var(--amber);font-weight:700">· bloqué</span>' : ''}</div>
        <div style="font-size:.58rem;color:var(--moss);opacity:.6">${dt}</div>
      </div>
      <div style="font-weight:800;font-size:.8rem;color:${pos ? 'var(--fern)' : 'var(--terracotta)'};white-space:nowrap">${pos ? '+' : ''}${h.delta}</div>
    </div>`;
  }).join('');
}

function piloteMktToggle(id) {
  const o = pmktOffers.find(o => o.id === id);
  if (!o) return;
  if (o.status === 'full') return;
  o.status = o.status === 'active' ? 'paused' : 'active';
  evadPersistOffre(o);
  pmktRenderOffers();
  mmBubble(`Offre "${o.titre.substring(0,28)}…" ${o.status === 'active' ? 'réactivée ✅' : 'mise en pause ⏸'}`);
}

function piloteMktDelete(id) {
  const o = pmktOffers.find(o => o.id === id);
  if (!o) return;
  if (!confirm(`Supprimer l'offre « ${o.titre} » ?\nCette action est définitive.`)) return;
  pmktOffers = pmktOffers.filter(o => o.id !== id);
  if (window.store) { try { store.remove('offres_mkt', id); } catch (e) {} }
  pmktRenderOffers();
  mmBubble(`Offre "${o.titre.substring(0,28)}…" supprimée.`);
}

function piloteMktOpenAdd() {
  pmktEditingId = null;
  const modal = document.getElementById('pmkt-modal');
  document.getElementById('pmkt-modal-content').innerHTML = pmktFormHtml(null);
  modal.style.display = 'flex';
}

function piloteMktOpenEdit(id) {
  pmktEditingId = id;
  const o = pmktOffers.find(o => o.id === id);
  const modal = document.getElementById('pmkt-modal');
  document.getElementById('pmkt-modal-content').innerHTML = pmktFormHtml(o);
  modal.style.display = 'flex';
}

// Catégories du Marché : source unique (valeur technique sans accent + libellé).
// Les valeurs servent aux filtres (bmktFilter/smktFilter) et doivent rester
// stables ; les libellés (emoji + accents) sont affichés partout via mktCatLabel.
// Flag « périmètre marchand » : catégories réservées à une phase 2. false =
// invisibles dans l'UI, mais CONSERVÉES en base et dans les types (elles
// reviendront). Ne pas les supprimer.
const PERIMETRE_MARCHAND = false;

// Types d'accès de la Récolte. `actif:true` = toujours visible ; `actif:false`
// = derrière le flag PERIMETRE_MARCHAND. Les zones réglementées (mobilité,
// énergie, réparation, service, bien-être & santé) ont été retirées.
const MKT_CATS = [
  { v:'formation',    e:'📚', l:'📚 Formation & atelier',      actif:true },
  { v:'coupdemain',   e:'🤝', l:'🤝 Coup de main',             actif:true },
  { v:'materiel',     e:'🛠', l:'🛠 Prêt de matériel',         actif:true },
  { v:'location',     e:'🔑', l:"🔑 Location d'espace",         actif:true },
  { v:'hebergement',  e:'🏡', l:'🏡 Hébergement',              actif:true },
  { v:'evenement',    e:'🎉', l:'🎉 Événement',                actif:true },
  { v:'culture',      e:'🎨', l:'🎨 Culture & art',            actif:true },
  { v:'numerique',    e:'💻', l:'💻 Accompagnement numérique', actif:true },
  // Périmètre marchand (phase 2) — masquées tant que PERIMETRE_MARCHAND est false.
  { v:'alimentation', e:'🥦', l:'🥦 Alimentation',             actif:false },
  { v:'maraichage',   e:'🌱', l:'🌱 Maraîchage & plants',      actif:false },
  { v:'artisanat',    e:'🪵', l:'🪵 Artisanat',                actif:false },
  { v:'textile',      e:'🧵', l:'🧵 Textile & couture',        actif:false },
];
// Types d'accès visibles dans l'UI, selon le flag périmètre marchand.
function mktActiveCats() {
  return MKT_CATS.filter(c => c.actif || PERIMETRE_MARCHAND);
}
function mktCatLabel(v) {
  const c = MKT_CATS.find(x => x.v === v);
  return c ? c.l : (v ? v.charAt(0).toUpperCase() + v.slice(1) : '');
}
// Emoji de l'offre = celui de sa catégorie (plus de saisie manuelle).
function mktCatEmoji(v) {
  const c = MKT_CATS.find(x => x.v === v);
  return c ? c.e : '🌿';
}

function pmktFormHtml(o) {
  // Lieu par défaut : celui porté par l'offre, sinon mon lieu courant.
  const lieuDefault = (o && o.lieu_nom) || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) || '';
  const dateVal = (o && o.date) ? o.date : '';
  // Texte d'aide sous un champ (même style partout).
  const help = (t) => `<div style="font-size:.66rem;color:var(--moss);opacity:.72;margin-top:.28rem;line-height:1.45">${t}</div>`;
  return `
    <h2 style="font-family:'Satoshi', sans-serif;font-size:1.2rem;font-weight:900;color:var(--ink);margin-bottom:1.2rem">${o ? '✏️ Modifier l\'accès' : '🤲 Ouvrir un accès dans la Récolte'}</h2>
    <div class="pmkt-form-row">
      <label class="pmkt-label">Intitulé de l'accès</label>
      <input class="pmkt-input" id="pf-titre" placeholder="Ex : atelier vannerie, samedi matin" value="${o ? o.titre : ''}">
      ${help('Ce que vous ouvrez aux Bâtisseurs, en quelques mots.')}
    </div>
    <div class="pmkt-form-row">
      <label class="pmkt-label">Type d'accès <span style="font-weight:400;opacity:.5;font-size:.65rem">(définit l'icône)</span></label>
      <select class="pmkt-select" id="pf-cat">
        ${mktActiveCats().map(c => `<option value="${c.v}" ${o && o.cat===c.v?'selected':''}>${c.l}</option>`).join('')}
      </select>
    </div>
    <div class="pmkt-form-row">
      <label class="pmkt-label">Description courte</label>
      <textarea class="pmkt-textarea" id="pf-desc" placeholder="Ce qu'on y fait, ce qu'on y apprend…">${o && o.desc ? o.desc : ''}</textarea>
      ${help('Ce qu\'on y fait, ce qu\'on y apprend, ce qu\'on y partage.')}
    </div>
    <div class="pmkt-two-col">
      <div class="pmkt-form-row" style="margin-bottom:0">
        <label class="pmkt-label">Graines pour déverrouiller</label>
        <input class="pmkt-input" id="pf-prix" type="number" min="0" placeholder="30" value="${o ? o.prix : ''}">
        ${help('Le nombre de graines qui ouvre cet accès. Repère : un acte étendu vaut 30 graines.')}
      </div>
      <div class="pmkt-form-row" style="margin-bottom:0">
        <label class="pmkt-label">Places disponibles</label>
        <input class="pmkt-input" id="pf-stock" type="number" min="0" placeholder="10" value="${o ? o.stock : ''}">
        ${help('Combien de Bâtisseurs peuvent déverrouiller cet accès.')}
      </div>
    </div>
    <div style="height:.75rem"></div>
    <div class="pmkt-two-col">
      <div class="pmkt-form-row" style="margin-bottom:0">
        <label class="pmkt-label">Date <span style="font-weight:400;opacity:.5;font-size:.65rem">(optionnel)</span></label>
        <input class="pmkt-input" id="pf-date" type="date" value="${dateVal}">
        ${help('Si l\'accès a lieu à une date précise. Laissez vide sinon.')}
      </div>
      <div class="pmkt-form-row" style="margin-bottom:0">
        <label class="pmkt-label">Lieu</label>
        <input class="pmkt-input" id="pf-lieu" placeholder="Nom du lieu" value="${lieuDefault}">
      </div>
    </div>
    <div style="height:.9rem"></div>
    <label style="display:flex;gap:.6rem;align-items:flex-start;padding:.75rem .85rem;border:1px solid rgba(46,102,66,.22);border-radius:10px;background:rgba(46,102,66,.04);cursor:pointer">
      <input type="checkbox" id="pf-hors-exploitation" ${o && o.hors_exploitation ? 'checked' : ''} style="margin-top:.15rem;flex-shrink:0;width:16px;height:16px;accent-color:var(--forest)">
      <span style="font-size:.72rem;line-height:1.5;color:var(--ink)">Cet accès ne relève pas de l'exploitation économique de mon lieu et ne remplace aucun emploi ni prestation que j'aurais facturés.</span>
    </label>
    <div id="pf-hint" style="font-size:.68rem;color:var(--terracotta);margin-top:.5rem;min-height:1rem"></div>
    <div style="display:flex;gap:.6rem;margin-top:.4rem">
      <button class="btn btn-primary" style="flex:1;padding:.7rem" onclick="pmktSaveOffer()">${o ? '💾 Enregistrer les modifications' : '🤲 Ouvrir l\'accès'}</button>
      <button class="btn btn-ghost" onclick="document.getElementById('pmkt-modal').style.display='none'">Annuler</button>
    </div>`;
}

function pmktSaveOffer() {
  const titre = document.getElementById('pf-titre').value.trim();
  const cat   = document.getElementById('pf-cat').value;
  const emoji = mktCatEmoji(cat); // icône déduite de la catégorie
  const prix  = parseInt(document.getElementById('pf-prix').value) || 0;
  const stock = parseInt(document.getElementById('pf-stock').value) || 0;
  const descEl = document.getElementById('pf-desc');
  const desc  = descEl ? descEl.value.trim() : '';
  const dateEl = document.getElementById('pf-date');
  const date  = dateEl ? dateEl.value : '';
  const lieuEl = document.getElementById('pf-lieu');
  const lieu  = lieuEl ? lieuEl.value.trim() : '';
  const horsExploitation = !!(document.getElementById('pf-hors-exploitation') || {}).checked;
  const hint = document.getElementById('pf-hint');
  if (!titre) { document.getElementById('pf-titre').style.borderColor='var(--terracotta)'; return; }
  // Garde-fou obligatoire : pas d'ouverture d'accès sans l'attestation « hors
  // exploitation ». Contrôle client ici ; le contrôle serveur (non contournable)
  // sera assuré par l'Edge Function de publication.
  if (!horsExploitation) {
    if (hint) hint.textContent = "Coche l'attestation ci-dessus pour ouvrir cet accès.";
    return;
  }
  if (hint) hint.textContent = '';

  if (pmktEditingId !== null) {
    const o = pmktOffers.find(o => o.id === pmktEditingId);
    if (o) { o.titre=titre; o.cat=cat; o.emoji=emoji; o.prix=prix; o.stock=stock; o.stockMax=stock; o.desc=desc; o.date=date; o.hors_exploitation=horsExploitation; if(lieu) o.lieu_nom=lieu; if(stock>0 && o.status==='full') o.status='active'; evadPersistOffre(o); }
    mmBubble(`Accès "${titre.substring(0,28)}…" mis à jour ✅`);
  } else {
    // id chaîne stable (uuid) pour Supabase.
    const newId = (window.store && store.uuid) ? store.uuid() : String(Date.now());
    const o = { id:newId, emoji, bg:'rgba(74,140,92,.1)', titre, cat, prix, stock, stockMax:stock, desc, date, hors_exploitation:horsExploitation, lieu_nom:(lieu || undefined), status:'active', vues:0, echanges:0 };
    pmktOffers.push(o);
    evadPersistOffre(o);
    mmBubble(`Accès "${titre.substring(0,28)}…" ouvert dans la Récolte 🤲`);
  }
  document.getElementById('pmkt-modal').style.display = 'none';
  pmktRenderOffers();
}

/* ─── MARKETPLACE BÂTISSEUR ─── */
const MKT_OFFRES = [];

let mktCurrentCat = 'tous';
let mktCurrentSort = 'pertinence';
let mktBalance = 0;

function mktFilter(cat, btn) {
  mktCurrentCat = cat;
  document.querySelectorAll('.mkt-tab').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  mktRender();
}

function mktSort(sort, btn) {
  mktCurrentSort = sort;
  document.querySelectorAll('.mkt-sort').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  mktRender();
}

// Convertit une offre du tableau de bord Pilote vers le format Marketplace.
function pmktToMkt(o) {
  // Nom du lieu vendeur : celui porté par l'offre (autre lieu) sinon le mien.
  const lieu = o.lieu_nom || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom ? myLieuData.nom : (typeof EVAD !== 'undefined' ? EVAD.activeLieu.nom : 'Mon lieu'));
  const ville = o.ville || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.localisation ? myLieuData.localisation : 'Bordeaux');
  // Vendeur = le lieu du Pilote courant (les offres de « ma Marketplace » lui
  // appartiennent) ; sert à créditer le bon lieu lors d'une vente.
  const sellerId = o.lieu_id || (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.id) || null;
  return {
    id: o.id, cat: o.cat, titre: o.titre,
    desc: o.desc || ('Offre proposée par ' + lieu + '.'),
    lieu: lieu, ville: ville, prix: o.prix,
    seller_id: sellerId, seller_nom: (o.lieu_nom || lieu),
    unite: o.unite || (o.prix > 0 ? 'à déverrouiller en graines' : 'accès libre'),
    emoji: o.emoji, bg: o.bg || 'rgba(74,140,92,.1)', badge: o.badge || 'new',
    stock: o.stock, date: o.date || '', impact: o.impact || "Soutient l'économie locale et circulaire du lieu."
  };
}
// Offres affichées dans le Marché = TOUTES les offres publiées (tous lieux),
// lues depuis le store (partagées via Supabase), disponibles (actives + stock).
function mktAllOffres() {
  let offres = [];
  if (window.store) {
    offres = (store.all('offres_mkt') || [])
      .map(_offreRowToPmkt)
      .filter(o => o.status !== 'full' && o.status !== 'paused' && o.stock > 0)
      .map(pmktToMkt);
  } else if (typeof pmktOffers !== 'undefined') {
    offres = pmktOffers.filter(o => o.status !== 'full' && o.stock > 0).map(pmktToMkt);
  }
  return [...MKT_OFFRES, ...offres];
}

function mktRender() {
  const grid = document.getElementById('mkt-grid');
  if (!grid) return;
  // Solde RÉEL du profil courant (grand livre − graines bloquées), plus de
  // valeur de démo. Amorce le don de bienvenue au premier affichage.
  const _wp = evadGrainesParty(); if (_wp) evadGrainesEnsureWelcome(_wp);
  mktBalance = evadGrainesDispo();
  const _bal = document.getElementById('mkt-balance'); if (_bal) { _bal.textContent = mktBalance; _bal.style.cursor = 'pointer'; _bal.title = 'Voir mes graines'; _bal.onclick = evadOpenWallet; }
  let offres = mktAllOffres();
  if (mktCurrentCat !== 'tous') offres = offres.filter(o => o.cat === mktCurrentCat);
  if (mktCurrentSort === 'prix_asc') offres.sort((a,b) => a.prix - b.prix);
  else if (mktCurrentSort === 'prix_desc') offres.sort((a,b) => b.prix - a.prix);
  else if (mktCurrentSort === 'proche') offres.sort((a,b) => a.ville.localeCompare(b.ville));

  grid.innerHTML = offres.map(o => {
    const canAfford = mktBalance >= o.prix;
    const badgeHtml = o.badge ? `<div class="mkt-card-badge mkt-badge-${o.badge}">${o.badge==='new'?'Nouveau':o.badge==='promo'?'Promo':'Premium'}</div>` : '';
    const stockHtml = o.stock <= 3 ? `<div style="font-size:.6rem;color:var(--terracotta);font-weight:600;margin-top:.2rem">⚠ Plus que ${o.stock} disponibles</div>` : '';
    return `<div class="mkt-card" onclick="mktOpenModal('${o.id}')">
      <div class="mkt-card-img" style="background:${o.bg}">
        <span>${o.emoji}</span>
        ${badgeHtml}
      </div>
      <div class="mkt-card-body">
        <div class="mkt-card-cat">${mktCatLabel(o.cat)}</div>
        <div class="mkt-card-title">${o.titre}</div>
        <div class="mkt-card-lieu">📍 ${o.lieu} · ${o.ville}</div>
        <div class="mkt-card-desc">${o.desc}</div>
        ${stockHtml}
      </div>
      <div class="mkt-card-footer">
        <div>
          <div class="mkt-price">${o.prix > 0 ? '🪙 '+o.prix : '🎁 Gratuit'}</div>
          <div class="mkt-price-sub">${o.prix > 0 ? o.unite : 'accès libre'}</div>
        </div>
        <button class="mkt-btn-buy ${canAfford?'can-afford':'cant-afford'}" onclick="event.stopPropagation();mktOpenModal('${o.id}')">
          ${canAfford ? (o.prix===0 ? 'Accéder →' : 'Déverrouiller →') : 'Insuffisant'}
        </button>
      </div>
    </div>`;
  }).join('');
}

// Formate une date d'offre (AAAA-MM-JJ) en français lisible, sans casser si vide.
function _mktFmtDate(d) {
  if (!d) return '';
  try {
    const dt = new Date(d + 'T00:00:00');
    if (isNaN(dt.getTime())) return d;
    return dt.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });
  } catch (e) { return d; }
}

function mktOpenModal(id) {
  const o = mktAllOffres().find(x => x.id === id) || MKT_OFFRES[id];
  if (!o) return;
  mktBalance = evadGrainesDispo();
  const canAfford = mktBalance >= o.prix;
  const modal = document.getElementById('mkt-modal');
  const content = document.getElementById('mkt-modal-content');
  content.innerHTML = `
    <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.2rem">
      <div style="width:64px;height:64px;border-radius:var(--r-lg);background:${o.bg};display:flex;align-items:center;justify-content:center;font-size:1.9rem;flex-shrink:0">${o.emoji}</div>
      <div>
        <div style="font-size:.62rem;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.1em;margin-bottom:.2rem">${mktCatLabel(o.cat)}</div>
        <h2 style="font-family:'Satoshi', sans-serif;font-size:1.25rem;font-weight:900;color:var(--ink);line-height:1.15;margin-bottom:.2rem">${o.titre}</h2>
        <div style="font-size:.7rem;color:var(--moss)">📍 ${o.lieu} · ${o.ville}</div>
        ${o.date ? `<div style="font-size:.7rem;color:var(--moss);margin-top:.15rem">📅 ${_mktFmtDate(o.date)}</div>` : ''}
      </div>
    </div>
    <p style="font-size:.8rem;color:var(--moss);line-height:1.55;margin-bottom:1rem">${o.desc}</p>
    <div style="background:rgba(74,140,92,.06);border:1px solid rgba(74,140,92,.15);border-radius:var(--r-lg);padding:.8rem 1rem;margin-bottom:1rem;font-size:.74rem;color:var(--forest)">
      🌱 Impact estimé : ${o.impact}
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;padding:.8rem 1rem;background:${canAfford?'rgba(74,140,92,.06)':'rgba(184,78,53,.05)'};border:1px solid ${canAfford?'rgba(74,140,92,.2)':'rgba(184,78,53,.2)'};border-radius:var(--r-lg);margin-bottom:1rem">
      <div>
        <div style="font-size:.62rem;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.1em">Coût</div>
        <div style="font-family:'Satoshi', sans-serif;font-size:1.4rem;font-weight:900;color:var(--amber)">${o.prix>0?'🌱 '+o.prix+' graines':'🎁 Gratuit'}</div>
      </div>
      <div style="text-align:right">
        <div style="font-size:.62rem;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.1em">Ton solde</div>
        <div style="font-family:'Satoshi', sans-serif;font-size:1.1rem;font-weight:700;color:${canAfford?'var(--fern)':'var(--terracotta)'}">🪙 ${mktBalance} ${canAfford?'✓':'– insuffisant'}</div>
      </div>
    </div>
    <div style="display:flex;gap:.6rem">
      ${canAfford
        ? `<button class="btn btn-primary" style="flex:1;padding:.75rem" onclick="mktConfirmBuy('${o.id}')">${o.prix===0?'🎟 Accéder gratuitement':'🔒 Déverrouiller (−'+o.prix+' graines bloquées)'}</button>`
        : `<button class="btn" style="flex:1;padding:.75rem;background:rgba(46,102,66,.08);color:var(--moss);cursor:default" disabled>🔒 graines insuffisantes (manque ${o.prix - mktBalance})</button>`
      }
      <button class="btn btn-ghost" onclick="document.getElementById('mkt-modal').style.display='none'">Fermer</button>
    </div>`;
  modal.style.display = 'flex';
}

// Escrow (double validation) : le Bâtisseur DÉVERROUILLE (ses graines sont
// bloquées) ; le Pilote hôte confirme la remise de l'accès → transfert effectif.
async function mktConfirmBuy(id) {
  const o = mktAllOffres().find(x => x.id === id) || MKT_OFFRES[id];
  if (!o) return;
  const buyer = evadGrainesParty();
  if (!buyer) { mmBubble('Crée ton profil pour déverrouiller des accès'); return; }
  const prix = +o.prix || 0;
  const seller = evadOfferSeller(o);
  if (seller.id && buyer.type === seller.type && buyer.id === seller.id) { mmBubble('C\'est ton propre accès 🙂'); return; }
  if (prix > 0 && evadGrainesDispo(buyer.type, buyer.id) < prix) { mmBubble('🔒 Graines insuffisantes'); return; }

  // Accès catalogue de démo (aucun lieu hôte réel) : déverrouillage local direct.
  if (!seller.id) {
    if (prix > 0) evadGrainesMove(buyer, -prix, 'acces', 'Accès · ' + o.titre, 'offres_mkt', id);
    const _m = MKT_OFFRES.find(x => x.id === id); if (_m && _m.stock != null) _m.stock = Math.max(0, _m.stock - 1);
    document.getElementById('mkt-modal').style.display = 'none';
    mktRender();
    mmBubble(`✅ Accès déverrouillé ! « ${o.titre} », ${prix > 0 ? '−' + prix + ' graines' : 'gratuit'}`);
    return;
  }

  // Accès réel : RÉSERVATION via l'Edge Function (aucune écriture directe).
  const key = (window.store && store.uuid) ? store.uuid() : String(Date.now());
  const btn = document.querySelector('#mkt-modal-content .btn-primary');
  if (btn) { btn.disabled = true; btn.textContent = 'Patiente…'; }
  const r = await evadRecolteEdge('reserve', {
    access_id: id, buyer_type: buyer.type, buyer_id: buyer.id, buyer_nom: buyer.nom || '', idempotency_key: key
  });
  if (r.error) {
    if (btn) { btn.disabled = false; }
    mmBubble('⚠️ ' + r.error.message);
    return;
  }
  await evadRecolteRefresh();
  const tx = r.data && r.data.transaction;
  const code = (tx && tx.code) || '';
  const mdl = document.getElementById('mkt-modal'); if (mdl) mdl.style.display = 'none';
  mktRender();
  if (prix > 0) mmBubble(`🔒 Réservé ! Montre le code ${code} à ${seller.nom}. ${prix} graines bloquées jusqu'à sa confirmation.`);
  else mmBubble(`🎟 Réservé gratuitement chez ${seller.nom} · présente-toi sur place`);
}

/* ─── PILOTE TABS JS ─── */
// Remplit l'onglet « Fiche lieu » du tableau de bord avec le lieu créé.
function ficheFillFromMyLieu() {
  const d = (typeof myLieuData !== 'undefined' && myLieuData) ? myLieuData : (typeof cData !== 'undefined' ? cData : null);
  if (!d) return;
  const root = document.getElementById('pilote-panel-fiche');
  if (!root) return;
  const set = (id, val) => { const el = document.getElementById(id); if (el && val != null && val !== '') el.value = val; };

  set('fiche-f-nom', d.nom);
  // Type : id interne -> libellé du select
  const typeLbl = (typeof TYPES_LIEU !== 'undefined') ? (TYPES_LIEU.find(t => t.id === d.type) || {}).l : null;
  if (typeLbl) { const s = document.getElementById('fiche-f-type'); if (s) s.value = typeLbl; }
  // Adresse (le code postal est inclus dans la localisation)
  if (d.localisation) set('fiche-f-adresse', d.localisation);
  set('fiche-f-annee', d.annee);
  set('fiche-f-surface', d.surface);
  // Statut : id -> libellé
  const STAT = { asso:'Association loi 1901', scic:'SCIC', sas:'SAS', coop:'Coopérative', autre:'Autre' };
  if (d.statut) { const s = document.getElementById('fiche-f-statut'); if (s) s.value = STAT[d.statut] || d.statut; }
  set('fiche-f-desc', d.desc);
  // Contact & accès
  set('fiche-f-responsable', d.responsable);
  set('fiche-f-email', d.email);
  set('fiche-f-tel', d.tel);
  set('fiche-f-web', d.web);
  set('fiche-f-horaires', d.horaires);
  // Phase : bouton actif par libellé
  const PH = { idee:'Idée', conception:'Conception', chantier:'Chantier', operationnel:'Opérationnel' };
  if (d.phase) {
    const lbl = PH[d.phase];
    root.querySelectorAll('.fiche-tag').forEach(b => b.classList.toggle('active', !!lbl && b.textContent.indexOf(lbl) !== -1));
  }
  // Logo
  const logo = document.getElementById('fiche-logo-preview');
  if (logo) {
    if (d.logo) logo.innerHTML = '<img src="' + d.logo + '" style="width:100%;height:100%;object-fit:cover" alt="">';
    else if (d.icon) logo.textContent = d.icon;
  }
  // Besoins : coche les chips correspondantes ; réinjecte les besoins
  // personnalisés (absents des chips prédéfinies) en les ajoutant sélectionnés.
  const bt = document.getElementById('fiche-besoins-tags');
  if (bt && Array.isArray(d.besoins)) {
    const chips = Array.from(bt.querySelectorAll('.esp-tag'));
    const known = chips.map(b => (b.textContent || '').trim());
    chips.forEach(b => b.classList.toggle('sel', d.besoins.includes((b.textContent || '').trim())));
    d.besoins.filter(x => x && !known.includes(x)).forEach(x => {
      const btn = document.createElement('button');
      btn.className = 'esp-tag sel';
      btn.textContent = x;
      btn.onclick = () => btn.classList.toggle('sel');
      bt.appendChild(btn);
    });
  }
}

// Enregistre RÉELLEMENT l'onglet « Fiche lieu » du tableau de bord :
// lit tous les champs → myLieuData → Supabase (le bouton n'était qu'un toast).
function piloteFicheSave() {
  const val = (id) => { const el = document.getElementById(id); return el ? String(el.value || '').trim() : ''; };
  if (typeof myLieuData === 'undefined' || !myLieuData) myLieuData = (typeof cData !== 'undefined' && cData) ? cData : {};

  // Type : libellé du select → id interne.
  const typeLbl = val('fiche-f-type');
  const typeId = (typeof TYPES_LIEU !== 'undefined' && (TYPES_LIEU.find(t => t.l === typeLbl) || {}).id) || myLieuData.type || '';
  // Statut : libellé → id.
  const STAT_INV = { 'Association loi 1901':'asso', 'SCIC':'scic', 'SAS':'sas', 'Coopérative':'coop', 'Autre':'autre' };
  const statutId = STAT_INV[val('fiche-f-statut')] || myLieuData.statut || '';
  // Phase : bouton actif → id.
  const PH_INV = { 'Idée':'idee', 'Conception':'conception', 'Chantier':'chantier', 'Opérationnel':'operationnel' };
  let phaseId = myLieuData.phase || '';
  const root = document.getElementById('pilote-panel-fiche');
  if (root) {
    const activeTag = Array.from(root.querySelectorAll('.fiche-tag.active'))
      .find(b => Object.keys(PH_INV).some(l => b.textContent.indexOf(l) !== -1));
    if (activeTag) { const l = Object.keys(PH_INV).find(l => activeTag.textContent.indexOf(l) !== -1); if (l) phaseId = PH_INV[l]; }
  }

  // Besoins : chips sélectionnées (prédéfinies + personnalisées ajoutées).
  const besoins = [];
  const bt = document.getElementById('fiche-besoins-tags');
  if (bt) bt.querySelectorAll('.esp-tag.sel').forEach(b => { const t = (b.textContent || '').trim(); if (t && !besoins.includes(t)) besoins.push(t); });

  const patch = {
    nom: val('fiche-f-nom') || myLieuData.nom,
    type: typeId,
    localisation: val('fiche-f-adresse') || myLieuData.localisation,
    annee: val('fiche-f-annee'),
    surface: val('fiche-f-surface'),
    statut: statutId,
    phase: phaseId,
    desc: val('fiche-f-desc'),
    responsable: val('fiche-f-responsable'),
    email: val('fiche-f-email'),
    tel: val('fiche-f-tel'),
    web: val('fiche-f-web'),
    horaires: val('fiche-f-horaires'),
    besoins: besoins
  };
  Object.assign(myLieuData, patch);

  if (window.store) {
    try {
      // FUSION (pas d'écrasement) : on ne met à jour QUE les champs de la fiche
      // d'identité/contact. store.update fusionne le patch sur la ligne stockée,
      // donc espacesData / solsByEspace / solutions sont PRÉSERVÉS (ne jamais les
      // écraser depuis un myLieuData potentiellement périmé).
      let saved = myLieuData.id ? store.update('lieux', myLieuData.id, patch) : null;
      if (!saved) saved = store.upsert('lieux', Object.assign({}, myLieuData)); // 1re création
      // Resynchronise myLieuData depuis la ligne fusionnée (récupère les espaces
      // complets si l'état local était tronqué).
      if (saved) { myLieuData = Object.assign({}, saved); }
    } catch (e) {}
  }
  // Reflète le lieu mis à jour dans l'en-tête du tableau de bord et sur la carte.
  if (typeof evadReflectLieuInDashboard === 'function') { try { evadReflectLieuInDashboard(); } catch (e) {} }
  // Carte : reconstruit les données ET force le re-rendu complet (marqueurs +
  // cartes communauté + panneau du lieu) pour que la fiche carte reflète l'édition.
  try {
    if (typeof syncMapPlacesFromStore === 'function') syncMapPlacesFromStore();
    _mapCommunityRendered = false;
    if (typeof evadMap !== 'undefined' && evadMap) { try { evadMap.remove(); } catch (e) {} evadMap = null; }
    const _carte = document.getElementById('screen-carte');
    if (_carte && _carte.classList.contains('active') && typeof initRealMap === 'function') initRealMap();
    // Si le panneau d'un lieu est ouvert sur CE lieu, on le rafraîchit.
    const _panel = document.getElementById('map-acteur-panel');
    if (_panel && _panel.style.display !== 'none' && typeof mapShowLieu === 'function') {
      const _idx = MAP_PLACES.findIndex(p => p.fiche && p.fiche.id === myLieuData.id);
      if (_idx >= 0) mapShowLieu(_idx);
    }
  } catch (e) {}
  if (typeof mmBubble === 'function') mmBubble('💾 Fiche enregistrée · modifications publiées ✅');
}

// Reflète le lieu créé (myLieuData) dans l'en-tête du tableau de bord.
function evadReflectLieuInDashboard() {
  const d = (typeof myLieuData !== 'undefined' && myLieuData) ? myLieuData : null;
  const sub = document.getElementById('pilote-lieu-sub');
  const title = document.getElementById('pilote-lieu-title');
  const lieuType = (d && typeof TYPES_LIEU !== 'undefined') ? (TYPES_LIEU.find(t => t.id === d.type) || {}).l : null;
  const ville = (d && (d.localisation || lieuType)) || '';
  // Titre = « Tableau de bord {nom du lieu} », sous-titre = la ville.
  if (title) title.textContent = (d && d.nom) ? ('📊 Tableau de bord ' + d.nom) : '📊 Tableau de bord du lieu';
  if (sub)   sub.textContent   = (d && d.nom) ? (ville || '-') : '-';
}

function piloteTab(tab, btn) {
  try { localStorage.setItem('evad:tab:pilote', tab); } catch (e) {}
  evadReflectLieuInDashboard();
  document.querySelectorAll('.pilote-tab').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  document.querySelectorAll('.pilote-panel').forEach(p => p.classList.remove('active'));
  const panel = document.getElementById('pilote-panel-' + tab);
  if (panel) panel.classList.add('active');
  if (tab === 'marketplace') setTimeout(pmktRenderOffers, 50);
  if (tab === 'dossiers')   { setTimeout(initDossiers, 50); setTimeout(() => { if (typeof impactRenderEtat === 'function') impactRenderEtat(); var _sb = document.getElementById('ici-saisie'); if (_sb) _sb.innerHTML = ''; if (typeof iciRenderExports === 'function') iciRenderExports(); }, 50); }
  if (tab === 'quetes')     { if (typeof syncPiloteQuetesFromLieu === 'function') syncPiloteQuetesFromLieu(); setTimeout(renderPiloteQuetes, 50); }
  if (tab === 'fiche')      {
    // Reflète le lieu créé : identité + espaces + carte mentale
    if (typeof myLieuData !== 'undefined' && myLieuData) {
      ficheEspaces = (myLieuData.espacesData || []).map(e => Object.assign({}, e));
      // Recharge les solutions déjà choisies (persistées) au lieu de repartir de
      // zéro : sinon le mind map réappliquait les défauts et perdait les choix.
      ficheSolsByEspace = {};
      if (myLieuData.solsByEspace) {
        Object.keys(myLieuData.solsByEspace).forEach(k => { ficheSolsByEspace[k] = (myLieuData.solsByEspace[k] || []).slice(); });
      }
    }
    ficheFillFromMyLieu();
    ficheRenderEspaces();
    if (typeof ficheRenderEspacePicker === 'function') ficheRenderEspacePicker();
    setTimeout(ficheMmRender, 80);
  }
  if (tab === 'apercu') setTimeout(() => {
    regenInit();
    updateApercuFromQuetes();
  }, 80);
}

/* ─── FIL ROUGE : score vivant du lieu de l'utilisateur ───
   Score = base 40 + somme des « +X pts » des quêtes validées (plafonné à 100).
   Source unique partagée par l'aperçu, la carte, le marqueur et la fiche. */
function evadLieuScoreData() {
  let bonus = 0, graines = 0, nbVal = 0;
  if (typeof PILOTE_QUETES_DEMO !== 'undefined' && typeof quetesValidees !== 'undefined') {
    PILOTE_QUETES_DEMO.forEach(q => {
      if (quetesValidees.has(q.id)) {
        const m = String(q.impact || '').match(/(\d+)\s*pts?/i);
        bonus += m ? parseInt(m[1], 10) : 5;
        graines += q.graines || 0; nbVal++;
      }
    });
  }
  return { score: Math.min(100, 10 + bonus), bonus: bonus, graines: graines, nbValidees: nbVal };
}

/* ─── Vadance (promesse) vs Vadité (preuve) + indice de confiance ───
   Vadance : impact projeté figé à la création.
   Vadité  : impact réellement prouvé (quêtes validées + actions terrain certifiées).
   Taux    : Vadité ÷ Vadance, l'indicateur anti-greenwashing. */
function evadImpactData() {
  let vadance = 0;
  if (typeof myLieuData !== 'undefined' && myLieuData) {
    vadance = (typeof myLieuData.vadance === 'number') ? myLieuData.vadance : 0;
    if (!vadance && typeof computeVadance === 'function') vadance = computeVadance(myLieuData);
  }
  // Repli : fiche saisie mais pas encore publiée → on calcule depuis cData.
  if (!vadance && typeof cData !== 'undefined' && cData && cData.type && typeof computeVadance === 'function') {
    vadance = computeVadance(cData);
  }
  // Preuve = moyenne des preuves par capital (quêtes validées + actions du jardin).
  let vadite = 0;
  if (typeof apercuCapitauxPaire === 'function') {
    const p = apercuCapitauxPaire();
    vadite = Math.round(((p.ecologie.vit || 0) + (p.social.vit || 0) + (p.economie_locale.vit || 0)) / 3);
  } else if (typeof evadLieuScoreData === 'function') {
    vadite = evadLieuScoreData().bonus || 0;   // preuve réelle (0 tant que rien n'est validé)
  }
  // La preuve ne dépasse pas la promesse : l'indice de confiance est plafonné à 100 %.
  if (vadance > 0) vadite = Math.min(vadite, vadance);
  const taux = vadance > 0 ? Math.round(vadite / vadance * 100) : 0;
  return { vadance: vadance, vadite: vadite, taux: taux };
}

/* ─── Preuve PAR capital d'un lieu (0..100), reliée aux indicateurs (ICI) ───
   Fini les « 10 » décoratifs : chaque barre reflète la preuve réelle.
   - Mon lieu : valeurs de l'aperçu (quêtes validées + actions du jardin,
     réparties par couverture ICI) → la Vadité est exactement leur moyenne.
   - Lieu du réseau : points des quêtes TERMINÉES du lieu, répartis selon la
     couverture ICI de ses solutions (table lieu_solutions). Sans preuve : 0. */
function evadLieuDims(lieuRow, estMonLieu) {
  // Couleurs en hexa (les consommateurs composent des alphas « ${c}0d »).
  const DIM_META = [
    { k: 'ecologie',        l: 'Environnement', c: '#4a8c5c' },
    { k: 'social',          l: 'Social',        c: '#3a6e8c' },
    { k: 'economie_locale', l: 'Éco. locale',   c: '#c8732a' }
  ];
  const zero = () => DIM_META.map(d => ({ l: d.l, v: 0, c: d.c }));
  try {
    if (estMonLieu && typeof apercuCapitauxPaire === 'function') {
      const p = apercuCapitauxPaire();
      return DIM_META.map(d => ({ l: d.l, v: (p[d.k] && p[d.k].vit) || 0, c: d.c }));
    }
    if (!lieuRow) return zero();
    // Solutions du lieu : champ à plat de la fiche, sinon table lieu_solutions.
    let sols = (typeof evadLieuSols === 'function') ? evadLieuSols(lieuRow) : ((lieuRow.solutions) || []);
    if ((!sols || !sols.length) && lieuRow.id && window.store) {
      sols = store.where('lieu_solutions', s => s.lieu_id === lieuRow.id).map(s => s.nom).filter(Boolean);
    }
    // Points de preuve : quêtes terminées du lieu (« +X pts » de leur impact).
    let bonus = 0;
    if (lieuRow.id && window.store) {
      store.where('quetes', q => q.lieu_id === lieuRow.id && q.statut === 'terminee').forEach(q => {
        const m = String(q.impact || '').match(/(\d+)\s*pts?/i);
        bonus += m ? parseInt(m[1], 10) : 5;
      });
    }
    if (!bonus) return zero();
    // Répartition par couverture ICI (mêmes poids que l'aperçu du Pilote).
    const covered = { ecologie: 0, social: 0, economie_locale: 0 };
    const total = { ecologie: 0, social: 0, economie_locale: 0 };
    const seen = {};
    if (typeof ICI_CATALOG !== 'undefined') ICI_CATALOG.forEach(i => total[i.livre] = (total[i.livre] || 0) + 1);
    if (typeof iciPourSolution === 'function') (sols || []).forEach(sn => (iciPourSolution(sn) || []).forEach(i => {
      if (!seen[i.id]) { seen[i.id] = 1; covered[i.livre] = (covered[i.livre] || 0) + 1; }
    }));
    const POIDS = (typeof APERCU_PREUVE_POIDS !== 'undefined') ? APERCU_PREUVE_POIDS : { ecologie: 1, social: 1, economie_locale: 1 };
    const share = {}; let maxShare = 0;
    DIM_META.forEach(d => {
      const r = total[d.k] ? (covered[d.k] || 0) / total[d.k] : 0;
      share[d.k] = r * (POIDS[d.k] || 1);
      if (share[d.k] > maxShare) maxShare = share[d.k];
    });
    return DIM_META.map(d => ({
      l: d.l, c: d.c,
      v: maxShare > 0 ? Math.max(0, Math.min(100, Math.round(bonus * (share[d.k] / maxShare)))) : 0
    }));
  } catch (e) { return zero(); }
}

/* ─── APERÇU : « où en est mon lieu, et quel est le prochain cran ? » ─── */

/* ════════ IMPACT « FUN » : actions concrètes en 1 geste ════════
   Chaque action ajoute des points de preuve à un capital, raconte une
   équivalence parlante, et fait pousser le jardin. */
const FUN_ACTIONS = [
  { id:'plante',   ic:'🌱', label:'J\'ai planté',     capital:'ecologie',        unit:'plants',    gain:7,  q:(n)=> (n*4) + ' m² végétalisés' },
  { id:'composte', ic:'♻️', label:'J\'ai composté',    capital:'ecologie',        unit:'kg',        gain:6,  q:(n)=> Math.round(n*0.5) + ' kg CO₂ évités' },
  { id:'energie',  ic:'☀️', label:'Énergie propre',   capital:'ecologie',        unit:'kWh',       gain:6,  q:(n)=> Math.round(n*0.06) + ' kg CO₂ évités' },
  { id:'repare',   ic:'🔧', label:'J\'ai réparé',      capital:'economie_locale', unit:'objets',    gain:7,  q:(n)=> n + ' objets sauvés de la benne' },
  { id:'local',    ic:'🥗', label:'Repas local',      capital:'economie_locale', unit:'repas',     gain:5,  q:(n)=> n + ' repas en circuit court' },
  { id:'forme',    ic:'👥', label:'J\'ai formé',       capital:'social',          unit:'personnes', gain:9,  q:(n)=> n + ' personnes montées en compétence' },
];
window._funLog = window._funLog || [];        // { id, qty }
window._funBadges = window._funBadges || {};  // id de badge -> true

// Bonus de preuve accumulé par capital (issu des actions saisies).
function funCapBonus() {
  const cap = { ecologie: 0, social: 0, economie_locale: 0 };
  (window._funLog || []).forEach(e => {
    const a = FUN_ACTIONS.find(x => x.id === e.id);
    if (a) cap[a.capital] = (cap[a.capital] || 0) + a.gain;
  });
  return cap;
}
// Score global de preuve issu des actions (0–100) → alimente la Vadité.
function funGlobalScore() {
  const c = funCapBonus();
  return Math.min(100, c.ecologie + c.social + c.economie_locale);
}
// Cumuls concrets par type d'action (pour les équivalences parlantes).
function funTotals() {
  const t = {};
  (window._funLog || []).forEach(e => { t[e.id] = (t[e.id] || 0) + e.qty; });
  return t;
}

// Score par capital (0–100), dérivé de la couverture ICI des solutions du lieu,
// mis à l'échelle de la Vadance. Un capital peu couvert tombe sous le plancher.
function apercuCapitauxScores() {
  const imp = (typeof evadImpactData === 'function') ? evadImpactData() : { vadance: 0 };
  const v = imp.vadance || 0;
  const L = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) ? myLieuData : (typeof cData !== 'undefined' ? cData : {});
  const sols = (L && L.solutions) || [];
  const covered = { ecologie: 0, social: 0, economie_locale: 0 };
  const seen = {};
  if (typeof iciPourSolution === 'function') {
    sols.forEach(sn => (iciPourSolution(sn) || []).forEach(ici => {
      if (!seen[ici.id]) { seen[ici.id] = 1; covered[ici.livre] = (covered[ici.livre] || 0) + 1; }
    }));
  }
  const total = { ecologie: 0, social: 0, economie_locale: 0 };
  if (typeof ICI_CATALOG !== 'undefined') ICI_CATALOG.forEach(ici => total[ici.livre] = (total[ici.livre] || 0) + 1);
  const out = {};
  ['ecologie', 'social', 'economie_locale'].forEach(k => {
    const ratio = total[k] ? covered[k] / total[k] : 0;
    const w = 0.65 + 0.55 * ratio; // 0 couverture → 0.65·V ; pleine → 1.2·V
    out[k] = v > 0 ? Math.max(0, Math.min(100, Math.round(v * w))) : 0;
  });
  return out;
}

// Promesse (Vadance) + preuve (Vadité) PAR capital. La part prouvée varie d'un
// capital à l'autre : l'écologie se prouve plus vite (mesures CO₂…), l'économie
// locale plus lentement. La preuve ne dépasse jamais la promesse du capital.
const APERCU_PREUVE_POIDS = { ecologie: 1.18, social: 1.0, economie_locale: 0.72 };
function apercuCapitauxPaire() {
  // Promesse = 100 par capital (le plein potentiel). Preuve = preuve des quêtes
  // validées (répartie selon la couverture du capital) + actions du jardin.
  const L = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) ? myLieuData : (typeof cData !== 'undefined' ? cData : {});
  const sols = (L && L.solutions) || [];
  const covered = { ecologie: 0, social: 0, economie_locale: 0 };
  const total = { ecologie: 0, social: 0, economie_locale: 0 };
  const seen = {};
  if (typeof ICI_CATALOG !== 'undefined') ICI_CATALOG.forEach(i => total[i.livre] = (total[i.livre] || 0) + 1);
  if (typeof iciPourSolution === 'function') sols.forEach(sn => (iciPourSolution(sn) || []).forEach(i => { if (!seen[i.id]) { seen[i.id] = 1; covered[i.livre] = (covered[i.livre] || 0) + 1; } }));
  const questGlobal = (typeof evadLieuScoreData === 'function') ? (evadLieuScoreData().bonus || 0) : 0; // 0..90 : preuve RÉELLE (points des quêtes validées, sans le plancher de 10)
  const fun = (typeof funCapBonus === 'function') ? funCapBonus() : { ecologie: 0, social: 0, economie_locale: 0 };
  const share = {}; let maxShare = 0;
  ['ecologie', 'social', 'economie_locale'].forEach(k => {
    const r = total[k] ? covered[k] / total[k] : 0;
    share[k] = r * (APERCU_PREUVE_POIDS[k] || 1);
    if (share[k] > maxShare) maxShare = share[k];
  });
  const out = {};
  ['ecologie', 'social', 'economie_locale'].forEach(k => {
    const qPart = maxShare > 0 ? Math.round(questGlobal * (share[k] / maxShare)) : 0; // preuve des quêtes, par couverture
    const vit = Math.max(0, Math.min(100, qPart + (fun[k] || 0)));                    // + actions du jardin
    out[k] = { vad: 100, vit: vit };
  });
  return out;
}

// Le prochain cran : un seul objectif clair, choisi selon l'état du lieu.
function apercuNextCran() {
  const imp = (typeof evadImpactData === 'function') ? evadImpactData() : { vadance: 0, vadite: 0, taux: 0 };
  const v = imp.vadance, vit = imp.vadite, taux = imp.taux;
  const goFiche  = "piloteTab('fiche',document.getElementById('ptab-fiche'))";
  const goQuetes = "piloteTab('quetes',document.getElementById('ptab-quetes'))";
  const goImpact = "piloteTab('dossiers',document.getElementById('ptab-dossiers'))";
  if (v <= 0)   return { icon:'✦', title:'Crée ton lieu', why:'Compose ta fiche : Deva génère ta Vadance à partir de tes solutions.', from:0, to:10, val:0, unit:'Vadance', cta:'Créer mon lieu', onclick:"showScreen('creer')" };
  if (v < 38)   return { icon:'🌱', title:'Déclare plus d\'impact', why:'Ajoute des solutions et des espaces : chacune porte de vrais ICI qui font monter ta Vadance.', from:10, to:38, val:v, unit:'Vadance', cta:'Enrichir ma fiche', onclick:goFiche };
  if (v < 65)   return { icon:'✨', title:'Vise le palier « Prêt à publier »', why:'Quelques solutions à fort impact de plus et ton lieu devient convaincant pour la communauté.', from:38, to:65, val:v, unit:'Vadance', cta:'Enrichir ma fiche', onclick:goFiche };
  if (vit <= 10) return { icon:'✅', title:'Transforme ta promesse en preuve', why:'Ta Vadance est solide. Valide ta première quête pour faire décoller ta Vadité (l\'impact prouvé).', from:0, to:25, val:vit, unit:'Vadité', cta:'Aller aux quêtes', onclick:goQuetes };
  if (taux < 50) return { icon:'⚖️', title:'Atteins 50% d\'indice de confiance', why:'C\'est le seuil qui rend ton lieu éligible aux financements Semeur. Continue à certifier tes actions.', from:0, to:50, val:taux, unit:'% de tenue', cta:'Saisir une action', onclick:goImpact };
  if (taux < 80) return { icon:'📣', title:'Attire des financeurs', why:'Tu es éligible au financement Semeur. Publie au réseau pour gagner en visibilité.', from:50, to:80, val:taux, unit:'% de tenue', cta:'Publier au réseau', onclick:"evadPublishLieuToReseau()" };
  return { icon:'🚀', title:'Élève ton impact', why:'Lieu à fort indice de confiance : fais auditer tes preuves pour viser la certification maximale.', from:80, to:100, val:taux, unit:'% de tenue', cta:'Voir mon impact', onclick:goImpact };
}

// Remplit l'« état du lieu » (comparatif Vadance/Vadité + triptyque) et le « prochain cran ».
function apercuRender() {
  const imp = (typeof evadImpactData === 'function') ? evadImpactData() : { vadance: 0, vadite: 0, taux: 0 };
  const hasV = imp.vadance > 0;
  // Tant qu'aucune fiche n'est composée, on masque la carte de métriques (sinon
  // « -/100 » partout, déroutant) : le Pilote est guidé par « Ton prochain cran ».
  const etatCard = document.getElementById('apercu-etat-card');
  if (etatCard) etatCard.style.display = hasV ? '' : 'none';
  const L = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) ? myLieuData : (typeof cData !== 'undefined' ? cData : {});
  const setTxt = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  setTxt('apercu-lieu-nom', (L && L.nom) ? L.nom : 'mon lieu');
  // Comparatif Vadance (promesse) ↔ Vadité (preuve) + indice de confiance
  setTxt('apercu-vadance-num', hasV ? imp.vadance : '-');
  setTxt('apercu-vadite-num', hasV ? imp.vadite : '-');
  setTxt('apercu-taux-num', hasV ? imp.taux + ' %' : '-');
  // Palier
  const palEl = document.getElementById('apercu-palier');
  if (palEl) {
    const p = (typeof creerVadancePalier === 'function') ? creerVadancePalier(imp.vadance) : null;
    palEl.textContent = hasV ? (p ? p.label : '🌿 Lieu esquissé') : '✦ À composer';
  }
  // Triptyque : 3 capitaux, jamais compensés (plancher)
  const PLANCHER = (typeof ICI_PLANCHER !== 'undefined') ? ICI_PLANCHER : 40;
  const META = (typeof ICI_LIVRE_META !== 'undefined') ? ICI_LIVRE_META : { ecologie:{label:'Écologie',ic:'🌿',col:'#2e9960'}, social:{label:'Social',ic:'🤝',col:'#3a6e8c'}, economie_locale:{label:'Éco. locale',ic:'♻️',col:'#c8732a'} };
  const paire = apercuCapitauxPaire();
  const KS = ['ecologie', 'social', 'economie_locale'];
  const vits = KS.map(k => (paire[k] || {}).vit || 0);
  const maxVit = Math.max.apply(null, vits), minVit = Math.min.apply(null, vits);
  // Alerte plancher : un capital en retard sous le seuil alors qu'un autre progresse.
  let alertCap = null;
  if (hasV && maxVit >= PLANCHER && minVit < PLANCHER) {
    const k = KS[vits.indexOf(minVit)];
    alertCap = { key: k, label: (META[k] || {}).label || k, val: minVit };
  }
  const trip = document.getElementById('apercu-triptyque');
  if (trip) {
    const legende = '<div style="display:flex;gap:1rem;align-items:center;margin-bottom:.6rem;font-size:.58rem;color:var(--moss);opacity:.75">'
      + '<span style="display:inline-flex;align-items:center;gap:.3rem"><span style="width:14px;height:8px;border-radius:100px;background:rgba(46,102,66,.22);display:inline-block"></span> promesse (sur 100)</span>'
      + '<span style="display:inline-flex;align-items:center;gap:.3rem"><span style="width:14px;height:8px;border-radius:100px;background:var(--forest);display:inline-block"></span> preuve (Vadité)</span>'
      + '</div>';
    trip.innerHTML = legende + KS.map(k => {
      const m = META[k] || { label: k, ic: '◆', col: '#4a8c5c' };
      const vit = hasV ? ((paire[k] || {}).vit || 0) : 0; // preuve (variable par capital)
      const low = alertCap && alertCap.key === k;
      return '<div style="display:flex;align-items:center;gap:.7rem;margin-bottom:.65rem">'
        + '<div style="width:108px;flex-shrink:0;font-size:.72rem;font-weight:600;color:var(--ink)">' + m.ic + ' ' + m.label + '</div>'
        + '<div style="flex:1;position:relative;height:11px;background:rgba(46,102,66,.07);border-radius:100px">'
          + '<div style="position:absolute;left:0;top:0;height:100%;width:100%;background:' + m.col + ';opacity:.18;border-radius:100px"></div>'
          + '<div style="position:absolute;left:0;top:0;height:100%;width:' + vit + '%;background:' + (low ? '#b84e35' : m.col) + ';border-radius:100px;transition:width .6s ease"></div>'
          + '<div style="position:absolute;left:' + PLANCHER + '%;top:-3px;bottom:-3px;width:2px;background:rgba(46,102,66,.45)"></div>'
        + '</div>'
        + '<div style="width:54px;text-align:right;font-family:\'Satoshi\',sans-serif;line-height:1">'
          + '<span style="font-size:1rem;font-weight:800;color:' + (low ? '#b84e35' : m.col) + '">' + (hasV ? vit : '-') + '</span>'
          + '<span style="font-size:.62rem;font-weight:700;color:var(--moss);opacity:.5"> / 100</span>'
        + '</div>'
      + '</div>';
    }).join('');
  }
  const alertBox = document.getElementById('apercu-plancher-alert');
  if (alertBox) {
    if (alertCap) {
      alertBox.style.display = 'block';
      alertBox.innerHTML = '⚠️ <b>' + alertCap.label + ' est en retard (' + alertCap.val + ' / 100, sous le plancher ' + PLANCHER + ').</b> Un capital ne rachète pas l\'autre : fais grandir ce capital pour débloquer la suite.';
    } else {
      alertBox.style.display = 'none';
    }
  }
  // Prochain cran
  const cran = apercuNextCran();
  const set = (id, fn) => { const el = document.getElementById(id); if (el) fn(el); };
  set('apercu-cran-icon',  el => el.textContent = cran.icon);
  set('apercu-cran-title', el => el.textContent = cran.title);
  set('apercu-cran-why',   el => el.textContent = cran.why);
  set('apercu-cran-from',  el => el.textContent = cran.unit + ' ' + cran.val);
  set('apercu-cran-to',    el => el.textContent = 'objectif ' + cran.to);
  set('apercu-cran-bar',   el => {
    const span = cran.to - cran.from;
    const pct = span > 0 ? Math.max(0, Math.min(100, Math.round((cran.val - cran.from) / span * 100))) : 0;
    el.style.width = pct + '%';
  });
  set('apercu-cran-cta',   el => { el.textContent = cran.cta + ' →'; el.setAttribute('onclick', cran.onclick); });
}

// Stade de croissance d'une plante selon le % de preuve.
function funPlantStage(pct) {
  if (pct >= 80) return '🌳';
  if (pct >= 45) return '🌿';
  if (pct >= 15) return '🌱';
  return '🌰';
}

// Onglet Impact : le « jardin vivant », 3 plantes qui poussent (promesse → preuve) + équivalences.
function impactRenderEtat() {
  const box = document.getElementById('ici-mesure-impact');
  if (!box) return;
  const imp = (typeof evadImpactData === 'function') ? evadImpactData() : { vadance: 0, vadite: 0, taux: 0 };
  const hasV = imp.vadance > 0;
  const PLANCHER = (typeof ICI_PLANCHER !== 'undefined') ? ICI_PLANCHER : 40;
  const META = (typeof ICI_LIVRE_META !== 'undefined') ? ICI_LIVRE_META : { ecologie:{label:'Écologie',ic:'🌿',col:'#2e9960'}, social:{label:'Social',ic:'🤝',col:'#3a6e8c'}, economie_locale:{label:'Éco. locale',ic:'♻️',col:'#c8732a'} };
  const paire = apercuCapitauxPaire();
  const KS = ['ecologie', 'social', 'economie_locale'];
  const vits = KS.map(k => (paire[k] || {}).vit || 0);
  const maxVit = Math.max.apply(null, vits), minVit = Math.min.apply(null, vits);
  let alertCap = null;
  if (hasV && maxVit >= PLANCHER && minVit < PLANCHER) {
    const lk = KS[vits.indexOf(minVit)];
    alertCap = { key: lk, label: (META[lk] || {}).label || lk, val: minVit };
  }

  const HT = 132; // hauteur du bac de culture (px)
  const plants = KS.map(k => {
    const m = META[k] || { label: k, ic: '◆', col: '#4a8c5c' };
    const vad = 100;                                   // promesse = plein potentiel
    const vit = hasV ? ((paire[k] || {}).vit || 0) : 0; // preuve
    const low = alertCap && alertCap.key === k;
    const stage = funPlantStage(hasV ? vit : 0);
    const proPx = Math.round(HT * vad / 100);
    const prePx = Math.round(HT * vit / 100);
    const planchPx = Math.round(HT * PLANCHER / 100);
    return '<div style="flex:1;min-width:96px;text-align:center">'
      // bac de culture
      + '<div style="position:relative;height:' + HT + 'px;width:64px;margin:0 auto .55rem;border-radius:12px 12px 6px 6px;background:rgba(46,102,66,.05);border:1px solid rgba(46,102,66,.1);overflow:hidden">'
        // silhouette promesse (claire)
        + '<div style="position:absolute;left:0;right:0;bottom:0;height:' + proPx + 'px;background:' + m.col + ';opacity:.13"></div>'
        // preuve (pleine, dégradé végétal)
        + '<div style="position:absolute;left:0;right:0;bottom:0;height:' + prePx + 'px;background:linear-gradient(0deg,' + m.col + ',' + m.col + 'aa);transition:height .7s cubic-bezier(.34,1.3,.5,1)"></div>'
        // marqueur plancher
        + '<div style="position:absolute;left:0;right:0;bottom:' + planchPx + 'px;height:0;border-top:1.5px dashed rgba(46,102,66,.4)"></div>'
        // plante (emoji) au sommet de la preuve
        + '<div style="position:absolute;left:50%;transform:translateX(-50%);bottom:' + (prePx - 4) + 'px;font-size:1.5rem;transition:bottom .7s cubic-bezier(.34,1.3,.5,1);filter:drop-shadow(0 2px 3px rgba(0,0,0,.12))">' + stage + '</div>'
      + '</div>'
      + '<div style="font-size:.68rem;font-weight:700;color:' + m.col + '">' + m.ic + ' ' + m.label + '</div>'
      + '<div style="font-family:\'Satoshi\',sans-serif;line-height:1;margin-top:.15rem"><span style="font-size:1.05rem;font-weight:800;color:' + m.col + '">' + (hasV ? vit : '-') + '</span><span style="font-size:.6rem;font-weight:700;color:' + (low ? '#b84e35' : 'var(--moss)') + ';opacity:.6"> / ' + (hasV ? vad : '-') + '</span></div>'
    + '</div>';
  }).join('');

  // Équivalences parlantes (cumuls concrets)
  const T = (typeof funTotals === 'function') ? funTotals() : {};
  const eqv = [];
  FUN_ACTIONS.forEach(a => { if (T[a.id]) eqv.push('<span style="display:inline-flex;align-items:center;gap:.3rem;background:rgba(46,102,66,.06);border-radius:100px;padding:.25rem .6rem;font-size:.66rem;color:var(--ink)">' + a.ic + ' <b>' + a.q(T[a.id]) + '</b></span>'); });
  const equivBlock = eqv.length
    ? '<div style="margin-top:1rem;padding-top:.9rem;border-top:1px solid rgba(46,102,66,.1)"><div style="font-size:.6rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.1em;margin-bottom:.5rem">Ce que ça représente</div><div style="display:flex;flex-wrap:wrap;gap:.4rem">' + eqv.join('') + '</div></div>'
    : '<div style="margin-top:1rem;padding-top:.9rem;border-top:1px solid rgba(46,102,66,.1);font-size:.66rem;color:var(--moss);opacity:.6">🌿 Ton jardin grandit avec les preuves de tes quêtes validées. Valide une quête pour le faire pousser.</div>';

  const alerte = alertCap
    ? '<div style="background:rgba(200,115,42,.08);border:1px solid rgba(200,115,42,.3);border-radius:var(--r);padding:.7rem .85rem;font-size:.68rem;color:#9a4a1a;line-height:1.5;margin-top:.7rem">⚠️ <b>' + alertCap.label + ' a besoin d\'attention (' + alertCap.val + ' / 100, sous le plancher ' + PLANCHER + ').</b> Un capital ne rachète pas l\'autre : fais grandir cette plante pour débloquer la suite.</div>'
    : '';

  box.innerHTML = ''
    + '<div class="dash-card" style="margin-bottom:1rem;padding:1.3rem 1.4rem">'
      + '<div style="display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;flex-wrap:wrap;margin-bottom:1.1rem">'
        + '<div><div style="font-size:.82rem;font-weight:800;color:var(--ink)">🌱 Le jardin de ton impact</div><div style="font-size:.66rem;color:var(--moss);opacity:.7;margin-top:.15rem">La silhouette claire, c\'est ta promesse. La plante pleine, c\'est ce que tu as déjà prouvé.</div></div>'
        + '<div style="text-align:right;flex-shrink:0"><div style="font-family:\'Satoshi\',sans-serif;font-size:1.5rem;font-weight:900;color:var(--forest);line-height:1">' + (hasV ? imp.taux + ' %' : '-') + '</div><div style="font-size:.55rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.08em">prouvé sur promis</div></div>'
      + '</div>'
      + '<div style="display:flex;gap:.6rem;align-items:flex-end;justify-content:center">' + plants + '</div>'
      + equivBlock
      + alerte
    + '</div>';
}

/* ── Saisie en 1 geste : grosses cartes « J'ai fait ça » ── */
function funSaisieRender() {
  const box = document.getElementById('ici-saisie');
  if (!box) return;
  const cards = FUN_ACTIONS.map(a =>
    '<button onclick="funPick(\'' + a.id + '\')" id="funcard-' + a.id + '" style="background:white;border:1.5px solid rgba(46,102,66,.15);border-radius:var(--r-lg);padding:.9rem .7rem;cursor:pointer;font-family:inherit;text-align:center;transition:all .15s" onmouseover="this.style.borderColor=\'var(--fern)\';this.style.boxShadow=\'0 4px 14px rgba(46,102,66,.12)\'" onmouseout="this.style.borderColor=\'rgba(46,102,66,.15)\';this.style.boxShadow=\'\'">'
    + '<div style="font-size:1.7rem;line-height:1;margin-bottom:.35rem">' + a.ic + '</div>'
    + '<div style="font-size:.72rem;font-weight:700;color:var(--ink)">' + a.label + '</div>'
    + '<div style="font-size:.58rem;color:var(--moss);opacity:.6">en ' + a.unit + '</div>'
    + '</button>').join('');
  box.innerHTML = ''
    + '<div class="dash-card" style="margin-bottom:1rem;padding:1.2rem 1.3rem">'
      + '<div style="font-size:.82rem;font-weight:800;color:var(--ink);margin-bottom:.2rem">⚡ J\'ai fait ça aujourd\'hui</div>'
      + '<div style="font-size:.66rem;color:var(--moss);opacity:.7;margin-bottom:.9rem">Un geste, un nombre. Deva transforme ça en impact, ta plante pousse. 🌿</div>'
      + '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem">' + cards + '</div>'
      + '<div id="fun-input-zone" style="display:none;margin-top:.9rem;background:rgba(46,102,66,.04);border:1px solid rgba(46,102,66,.12);border-radius:var(--r);padding:.8rem .9rem"></div>'
    + '</div>';
}

// Ouvre la mini-saisie pour une action.
function funPick(id) {
  const a = FUN_ACTIONS.find(x => x.id === id);
  const zone = document.getElementById('fun-input-zone');
  if (!a || !zone) return;
  zone.style.display = 'block';
  zone.innerHTML = ''
    + '<div style="display:flex;align-items:center;gap:.7rem;flex-wrap:wrap">'
      + '<span style="font-size:1.4rem">' + a.ic + '</span>'
      + '<span style="font-size:.78rem;font-weight:700;color:var(--ink)">' + a.label + '</span>'
      + '<span style="font-size:.7rem;color:var(--moss)">combien de <b>' + a.unit + '</b> ?</span>'
      + '<input id="fun-qty" type="number" min="1" value="1" style="width:90px;padding:.45rem .6rem;border:1px solid rgba(46,102,66,.2);border-radius:8px;font-family:inherit;font-size:.8rem" onkeydown="if(event.key===\'Enter\')funValider(\'' + a.id + '\')">'
      + '<button onclick="funValider(\'' + a.id + '\')" style="background:var(--forest);border:none;border-radius:100px;padding:.45rem 1.1rem;font-size:.72rem;font-weight:700;color:white;cursor:pointer;font-family:inherit">✅ Valider</button>'
    + '</div>'
    + '<div id="fun-preview" style="font-size:.66rem;color:var(--fern);font-weight:600;margin-top:.5rem">= ' + a.q(1) + '</div>';
  const qty = document.getElementById('fun-qty');
  if (qty) { qty.focus(); qty.select(); qty.oninput = () => { const p = document.getElementById('fun-preview'); if (p) p.textContent = '= ' + a.q(Math.max(0, parseFloat(qty.value) || 0)); }; }
}

// Enregistre l'action → fait pousser le jardin + célébration.
function funValider(id) {
  const a = FUN_ACTIONS.find(x => x.id === id);
  if (!a) return;
  const qtyEl = document.getElementById('fun-qty');
  const qty = Math.max(1, Math.round(parseFloat(qtyEl && qtyEl.value) || 1));
  window._funLog = window._funLog || [];
  window._funLog.push({ id: id, qty: qty });
  // La preuve issue des actions alimente la Vadité globale.
  if (typeof funGlobalScore === 'function') window._evadProvenActions = funGlobalScore();
  const zone = document.getElementById('fun-input-zone');
  if (zone) zone.style.display = 'none';
  // Rafraîchit jardin + aperçu + carte lieu.
  if (typeof impactRenderEtat === 'function') impactRenderEtat();
  if (typeof updateApercuFromQuetes === 'function') updateApercuFromQuetes();
  // Célébration + équivalence.
  funCelebrate('+' + a.gain + ' 🌱', a.q(qty));
  funCheckBadges(id);
  if (typeof mmBubble === 'function') mmBubble('🌿 Bravo ! ' + a.q(qty) + ', ta plante a poussé.');
}

// Petit feu d'artifice + label flottant.
function funCelebrate(gainTxt, equivTxt) {
  const host = document.getElementById('ici-mesure-impact');
  if (!host) return;
  host.style.position = host.style.position || 'relative';
  const f = document.createElement('div');
  f.innerHTML = '<div style="font-family:Satoshi,sans-serif;font-weight:900;font-size:1.3rem;color:#018262">' + gainTxt + '</div><div style="font-size:.68rem;color:var(--fern);font-weight:600">' + equivTxt + '</div>';
  f.style.cssText = 'position:absolute;top:14px;left:50%;transform:translateX(-50%);z-index:30;text-align:center;pointer-events:none;text-shadow:0 2px 8px rgba(255,255,255,.9);animation:vadFloat 1.4s ease-out forwards';
  host.appendChild(f);
  setTimeout(() => f.remove(), 1400);
  ['🌱','✨','🌿','💚','🍃','✨'].forEach((e, i) => {
    const ang = (i / 6) * Math.PI * 2;
    const s = document.createElement('div');
    s.textContent = e;
    s.style.cssText = 'position:absolute;top:26px;left:50%;z-index:29;font-size:1.1rem;pointer-events:none;transform:translate(-50%,0);transition:transform .9s cubic-bezier(.2,.8,.2,1),opacity .9s ease-out';
    host.appendChild(s);
    requestAnimationFrame(() => { s.style.transform = 'translate(calc(-50% + ' + Math.round(Math.cos(ang) * 90) + 'px), ' + Math.round(-30 - Math.abs(Math.sin(ang)) * 60) + 'px)'; s.style.opacity = '0'; });
    setTimeout(() => s.remove(), 920);
  });
}

// Badges débloqués selon les cumuls.
const FUN_BADGES = [
  { id: 'first',    test: (T) => Object.keys(T).length >= 1, ic: '🌟', label: 'Premier impact prouvé !' },
  { id: 'compost50',test: (T) => (T.composte || 0) >= 50,    ic: '♻️', label: '50 kg compostés' },
  { id: 'repare10', test: (T) => (T.repare || 0) >= 10,      ic: '🔧', label: '10 objets réparés' },
  { id: 'forme10',  test: (T) => (T.forme || 0) >= 10,       ic: '🎓', label: '10 personnes formées' },
  { id: 'jardinier',test: (T) => (T.plante || 0) >= 20,      ic: '🌳', label: 'Jardinier·ère confirmé·e' },
];
function funCheckBadges() {
  const T = funTotals();
  window._funBadges = window._funBadges || {};
  FUN_BADGES.forEach(b => {
    if (!window._funBadges[b.id] && b.test(T)) {
      window._funBadges[b.id] = true;
      funBadgeToast(b.ic, b.label);
    }
  });
}
function funBadgeToast(ic, label) {
  let host = document.getElementById('fun-badge-toast');
  if (!host) { host = document.createElement('div'); host.id = 'fun-badge-toast'; host.style.cssText = 'position:fixed;bottom:1.5rem;left:50%;transform:translateX(-50%);z-index:100000;display:flex;flex-direction:column;gap:.5rem;align-items:center;pointer-events:none'; document.body.appendChild(host); }
  const t = document.createElement('div');
  t.style.cssText = 'background:white;border:1.5px solid var(--fern);border-radius:100px;padding:.6rem 1.1rem;box-shadow:0 8px 28px rgba(46,102,66,.22);font-family:Satoshi,sans-serif;font-weight:700;font-size:.82rem;color:var(--ink);display:flex;align-items:center;gap:.5rem;opacity:0;transform:translateY(10px);transition:all .3s';
  t.innerHTML = '<span style="font-size:1.2rem">' + ic + '</span> Badge débloqué · ' + label;
  host.appendChild(t);
  requestAnimationFrame(() => { t.style.opacity = '1'; t.style.transform = 'translateY(0)'; });
  setTimeout(() => { t.style.opacity = '0'; t.style.transform = 'translateY(10px)'; setTimeout(() => t.remove(), 350); }, 3200);
}

/* Reflète Vadance / Vadité / taux dans le bandeau « Mon lieu » (aperçu Pilote). */
function evadReflectImpact() {
  const d = evadImpactData();
  const val = document.getElementById('apercu-regen-val');
  if (val) val.textContent = d.vadance > 0 ? d.vadance : '-';
  const arc = document.getElementById('regen-arc');
  if (arc) arc.style.strokeDashoffset = String(226.2 * (1 - d.vadance / 100));
  const vit = document.getElementById('apercu-vadite-val');
  if (vit) vit.textContent = d.vadance > 0 ? d.vadite : '-';
  const tx = document.getElementById('apercu-taux-val');
  if (tx) tx.textContent = d.vadance > 0 ? d.taux + '%' : '-';
}

// Marqueur Leaflet du lieu créé par l'utilisateur (pour MAJ live du popup)
let evadMyLieuMarker = null;

// Répercute le score vivant sur la carte : carte du panneau + marqueur.
function evadSyncMyLieuOnMap() {
  const d = evadLieuScoreData();
  if (typeof myLieuData !== 'undefined' && myLieuData) myLieuData.score = d.score;
  const imp = (typeof evadImpactData === 'function') ? evadImpactData() : { vadance: d.score, vadite: d.score, taux: 100 };
  const bar = document.getElementById('evad-mylieu-scorebar');
  if (bar) bar.style.width = imp.vadance + '%';
  const lbl = document.getElementById('evad-mylieu-scorelabel');
  if (lbl) {
    lbl.innerHTML = 'Vadance ' + imp.vadance + '/100 <span style="opacity:.6;font-weight:500">(promesse)</span>';
    lbl.style.color = 'var(--fern)';
  }
  const pv = document.getElementById('evad-mylieu-preuve');
  if (pv) pv.textContent = '✅ Vadité ' + imp.vadite + '/100 · ⚖️ Indice de confiance ' + imp.taux + '%';
  if (evadMyLieuMarker && typeof myLieuData !== 'undefined' && myLieuData) {
    try {
      evadMyLieuMarker.setPopupContent(
        '<div class="popup-place-title">' + (myLieuData.nom || 'Mon lieu') + '</div>' +
        '<div class="popup-place-meta">' + (myLieuData.localisation || 'Bordeaux') + '</div>' +
        '<div class="popup-place-score">Vadance ' + imp.vadance + ' · Vadité ' + imp.vadite + ' · taux ' + imp.taux + '%</div>'
      );
    } catch (e) {}
  }
}

/* Reflète les quêtes validées sur l'aperçu (Vadance + wallet graines)
   et propage le score sur la carte (fil rouge). */
function updateApercuFromQuetes() {
  const d = evadLieuScoreData();
  if (typeof myLieuData !== 'undefined' && myLieuData) myLieuData.score = d.score;
  // Hero : Vadance (promesse) + Vadité (preuve) + indice de confiance
  if (typeof evadReflectImpact === 'function') evadReflectImpact();
  const wallet = document.getElementById('apercu-graines-wallet');
  if (wallet) wallet.textContent = d.graines.toLocaleString('fr');
  // Aperçu : nom, palier, capitaux, prochain cran
  if (typeof apercuRender === 'function') apercuRender();
  // Onglet Impact : le jardin pousse avec les preuves des quêtes validées.
  if (typeof impactRenderEtat === 'function') impactRenderEtat();
  evadSyncMyLieuOnMap();
}

/* ─── PARCOURS VADE (boucle + détail par étape) ─── */
/* Boucle VADE (charte des ICI) : Valoriser → Activer → Développer → Essaimer.
   Un même parcours, un cran plus haut à chaque tour ; chaque étape outillée. */
const VADE_STEPS = [
  {
    letter: 'V', name: 'Valoriser', color: '#018262',
    title: 'Valoriser l’existant',
    desc: 'Établir la base de référence T0 et repérer l’impact déjà présent sur le lieu.',
    tags: ['📍 Diagnostic T0', '📚 Bibliothèque d’ICI'],
    outils: ['Diagnostic T0', 'Bibliothèque d’ICI', 'Deva'],
    taches: [
      'Établir la base de référence T0 de ton lieu',
      'Repérer l’impact déjà présent (écologie, social, économie locale)',
      'Identifier les ICI pertinents avec l’aide de Deva',
    ],
  },
  {
    letter: 'A', name: 'Activer', color: '#2d6a9f',
    title: 'Activer les solutions',
    desc: 'Déclarer les solutions mises en œuvre et mobiliser la communauté.',
    tags: ['🌱 Solutions', '🤝 Communauté'],
    outils: ['Bibliothèque de solutions', 'Déclaration des ICI', 'Quêtes'],
    taches: [
      'Déclarer les solutions que tu mets en œuvre',
      'Chaque solution embarque ses ICI à suivre',
      'Ouvrir des quêtes et mobiliser les Bâtisseurs',
    ],
  },
  {
    letter: 'D', name: 'Développer', color: '#c8732a',
    title: 'Développer la preuve',
    desc: 'Mesurer et prouver l’impact, puis sécuriser le financement.',
    tags: ['📊 Vadité', '💶 Financement'],
    outils: ['Mesure d’impact', 'Attestation Vadité', 'Monnaie Vade'],
    taches: [
      'Saisir les valeurs observées et leur niveau de preuve',
      'Produire l’attestation Vadité (impact réellement prouvé)',
      'Sécuriser le financement des Semeurs en euros',
    ],
  },
  {
    letter: 'E', name: 'Essaimer', color: '#6b5b95',
    title: 'Essaimer le commun',
    desc: 'Faire vérifier par les pairs et l’audit, puis faire remonter les retours dans le référentiel.',
    tags: ['🔍 Audit tiers', '🌍 Commun ouvert'],
    outils: ['Audit tiers', 'Passeport du lieu', 'Amendement du commun'],
    taches: [
      'Faire vérifier tes preuves par les pairs puis l’audit tiers',
      'Publier le passeport du lieu',
      'Remonter tes retours pour amender le référentiel commun',
    ],
  },
];
// état des tâches cochées par étape
const regenTasksDone = VADE_STEPS.map(s => s.taches.map(() => false));
// Pré-cochées : l'utilisateur a déjà franchi ces étapes en créant son lieu
// (fiche, repérage de l'impact, choix des solutions) → on lui montre sa progression.
if (regenTasksDone[0]) regenTasksDone[0] = regenTasksDone[0].map(() => true); // Valoriser (T0, impact, ICI)
if (regenTasksDone[1]) { regenTasksDone[1][0] = true; regenTasksDone[1][1] = true; } // Activer : solutions + ICI embarqués
let regenSelected = 0;

function regenSelect(i) {
  regenSelected = i;
  // nœuds : mise en avant du sélectionné
  VADE_STEPS.forEach((s, k) => {
    const circ = document.getElementById('rn-circ-' + k);
    const lbl = document.getElementById('rn-lbl-' + k);
    if (!circ) return;
    if (k === i) {
      circ.style.background = s.color;
      circ.style.color = 'white';
      circ.style.transform = 'scale(1.12)';
      circ.style.boxShadow = '0 4px 14px ' + s.color + '55';
      if (lbl) { lbl.style.color = s.color; lbl.style.fontWeight = '800'; }
    } else {
      circ.style.background = 'white';
      circ.style.color = s.color;
      circ.style.transform = '';
      circ.style.boxShadow = '';
      if (lbl) { lbl.style.color = 'var(--moss)'; lbl.style.fontWeight = '600'; }
    }
  });
  regenRenderDetail();
}

function regenToggleTask(stepIdx, taskIdx) {
  regenTasksDone[stepIdx][taskIdx] = !regenTasksDone[stepIdx][taskIdx];
  regenRenderDetail();
  regenUpdateCenter();
}

function regenRenderDetail() {
  const box = document.getElementById('regen-detail');
  if (!box) return;
  const s = VADE_STEPS[regenSelected];
  const done = regenTasksDone[regenSelected];
  const nDone = done.filter(Boolean).length;

  const tags = s.tags.map(t =>
    `<span style="font-size:.6rem;font-weight:600;color:var(--moss);background:rgba(46,102,66,.08);border-radius:100px;padding:.25rem .6rem">${t}</span>`
  ).join('');

  const outils = s.outils.map(o =>
    `<span style="font-size:.62rem;font-weight:600;color:${s.color};border:1px solid ${s.color}40;border-radius:100px;padding:.28rem .7rem">${o}</span>`
  ).join('');

  const taches = s.taches.map((t, k) => {
    const on = done[k];
    return `<div onclick="regenToggleTask(${regenSelected},${k})" style="display:flex;align-items:center;gap:.7rem;padding:.6rem .2rem;border-bottom:1px solid rgba(46,102,66,.08);cursor:pointer">
      <div style="width:24px;height:24px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:.68rem;font-weight:800;color:white;background:${on ? s.color : 'rgba(46,102,66,.18)'};transition:background .15s">${on ? '✓' : (k + 1)}</div>
      <div style="font-size:.76rem;color:var(--ink);line-height:1.35;${on ? 'text-decoration:line-through;opacity:.5' : ''}">${t}</div>
    </div>`;
  }).join('');

  box.innerHTML = `
    <div style="display:flex;align-items:flex-start;gap:.85rem;margin-bottom:.7rem">
      <div style="width:46px;height:46px;border-radius:12px;background:${s.color};color:white;display:flex;align-items:center;justify-content:center;font-family:'Satoshi', sans-serif;font-weight:900;font-size:1.3rem;flex-shrink:0">${s.letter}</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:.58rem;font-weight:700;color:${s.color};text-transform:uppercase;letter-spacing:.1em">Étape ${regenSelected + 1} / ${VADE_STEPS.length} · ${s.name} · Pilote</div>
        <div style="font-family:'Satoshi', sans-serif;font-size:1.2rem;font-weight:900;color:var(--ink);line-height:1.15;margin-top:.15rem">${s.title}</div>
      </div>
    </div>

    <div style="font-size:.78rem;color:var(--moss);line-height:1.5;margin-bottom:.8rem">${s.desc}</div>

    <div style="display:flex;flex-wrap:wrap;gap:.4rem;margin-bottom:1rem">${tags}</div>

    <div style="font-size:.58rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.12em;margin-bottom:.45rem">Outils mobilisés</div>
    <div style="display:flex;flex-wrap:wrap;gap:.4rem;margin-bottom:1.1rem">${outils}</div>

    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.3rem">
      <span style="font-size:.58rem;font-weight:700;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.12em">À faire</span>
      <span style="font-size:.62rem;font-weight:700;color:${s.color}">${nDone}/${s.taches.length} fait${nDone > 1 ? 's' : ''}</span>
    </div>
    <div>${taches}</div>
  `;
}

function regenUpdateCenter() {
  // Centre = progression du parcours (tâches faites), pas un score Vadance concurrent.
  const total = regenTasksDone.reduce((a, arr) => a + arr.length, 0);
  const done = regenTasksDone.reduce((a, arr) => a + arr.filter(Boolean).length, 0);
  const scoreEl = document.getElementById('regen-center-score');
  const sub = document.getElementById('regen-center-sub');
  if (scoreEl) scoreEl.innerHTML = done + '<span style="font-size:.62rem;font-weight:700;opacity:.45">/' + total + '</span>';
  if (!sub) return;
  if (done === 0) sub.textContent = '🌱 à démarrer';
  else if (done >= total) sub.textContent = '🌳 boucle complète';
  else sub.textContent = '🌿 en cours';
}

function regenInit() {
  regenSelect(regenSelected);
  regenUpdateCenter();
}

function lqPiloteFilter(filter, btn) {
  document.querySelectorAll('#pilote-panel-quetes .pmkt-filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  piloteQueteFilter = filter || 'toutes';
  if (typeof renderPiloteQuetes === 'function') renderPiloteQuetes();
}

// Bascule Liste / Agenda du suivi des quêtes Pilote.
function lqPiloteView(view, btn) {
  piloteQueteView = (view === 'agenda') ? 'agenda' : 'liste';
  document.querySelectorAll('#pilote-panel-quetes .lqv-btn').forEach(b => {
    const on = b === btn;
    b.classList.toggle('active', on);
    b.style.background = on ? 'white' : 'transparent';
    b.style.color = on ? 'var(--forest)' : 'var(--moss)';
  });
  if (typeof renderPiloteQuetes === 'function') renderPiloteQuetes();
}

/* ─── SEMEUR TABS ─── */
function semeurTab(tab, btn) {
  try { localStorage.setItem('evad:tab:semeur', tab); } catch (e) {}
  document.querySelectorAll('.semeur-tab').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  document.querySelectorAll('.semeur-panel').forEach(p => p.classList.remove('active'));
  const panel = document.getElementById('semeur-panel-' + tab);
  if (panel) panel.classList.add('active');
  if (tab === 'apercu') {
    setTimeout(() => {
      const arc = document.getElementById('sem-rse-arc');
      if (arc) arc.style.strokeDashoffset = String(226.2 * (1 - 74/100));
      regenLoopBuild('regenS', 'semeur');
    }, 80);
  }
  if (tab === 'graines') setTimeout(smktRender, 60);
  if (tab === 'rse') setTimeout(renderESRS, 50);
  if (tab === 'quetes') setTimeout(semRenderQuetes, 60);
  if (tab === 'fiche')  setTimeout(semFillProfile, 60);
  semReflectProfile();
}

// Remplit l'onglet « Mon profil » du dashboard Semeur depuis semFicheData.
function semFillProfile() {
  const sd = (typeof semFicheData !== 'undefined') ? semFicheData : null;
  if (!sd) return;
  const set = (id, v) => { const e = document.getElementById(id); if (e && v != null && v !== '') e.value = v; };
  set('sem-f-nom', sd.nom);
  if (sd.type) { const t = document.getElementById('sem-f-type'); if (t) t.value = sd.type; }
  set('sem-f-secteur', sd.secteur);
  set('sem-f-zone', sd.zone);
  const logo = document.getElementById('sem-logo-preview');
  if (logo && sd.logo) logo.innerHTML = '<img src="' + sd.logo + '" style="width:100%;height:100%;object-fit:cover" alt="">';
}

// Reflète le profil financeur créé dans le topbar, l'aperçu, le KPI ESRS et le portefeuille.
function semReflectProfile() {
  if (typeof semRenderCran === 'function') semRenderCran();
  const sd = (typeof semFicheData !== 'undefined') ? semFicheData : null;
  if (!sd) return;
  const has = (sd.nom || '').trim() !== '';
  const name = sd.nom || 'Mon organisation';
  const esrs = (sd.selectedCadres || []).length || (sd.axes || []).length || (sd.selectedODD || []).length;
  const tt = document.getElementById('sem-topbar-title'); if (tt) tt.textContent = '🏢 ' + (has ? name : 'Mon organisation');
  const ts = document.getElementById('sem-topbar-sub'); if (ts) ts.textContent = has ? ((sd.type || 'Financeur') + (sd.zone ? ' · ' + sd.zone : '') + ' · profil complété ✓') : 'Semeur · Configure ton profil';
  const hl = document.getElementById('sem-hero-label'); if (hl) hl.textContent = has ? (name + ' · ' + (sd.type || 'Financeur')) : 'Mon organisation · Score RSE Global';
  const hi = document.getElementById('sem-hero-intro'); if (hi) hi.textContent = has ? ('Finance des lieux à impact' + (sd.zone ? ' alignés ' + sd.zone : '') + '.' + (esrs ? ' ' + esrs + ' cadre(s) ESRS ciblé(s).' : '')) : 'Configure ton profil RSE pour commencer';
  const ke = document.getElementById('sem-kpi-esrs'); if (ke) ke.textContent = esrs || '-';
  const pf = document.getElementById('sem-portefeuille-list');
  if (pf && has) pf.innerHTML = '<div style="padding:1rem;text-align:center;font-size:.72rem;color:var(--moss);opacity:.6">Aucun lieu financé pour l\'instant. Finance un lieu aligné ' + (sd.zone || 'ton territoire') + ' depuis la carte 🌱</div>';
}

// Le prochain cran du Semeur : profil RSE → cadres ESRS → financer un lieu.
function semNextCran() {
  const sd = (typeof semFicheData !== 'undefined' && semFicheData) ? semFicheData : {};
  const hasFiche = (sd.nom || '').trim() !== '';
  const esrs = (sd.selectedCadres || []).length || (sd.axes || []).length || (sd.selectedODD || []).length;
  const goFiche = "showScreen('fiche-sem')";
  const goQuetes = "semeurTab('quetes',document.getElementById('stab-quetes'))";
  if (!hasFiche) return { icon:'✦',  title:'Configure ton profil RSE',            why:'Renseigne ton organisation : Deva alignera les lieux à financer sur tes objectifs extra-financiers.',                        from:0, to:1, val:0, unit:'profil',        cta:'Configurer mon profil',          onclick:goFiche };
  if (!esrs)     return { icon:'📋', title:'Cible tes cadres ESRS',                why:'Choisis les axes et cadres CSRD que tu veux couvrir : on te proposera les lieux les plus alignés.',                          from:0, to:2, val:0, unit:'cadres ciblés', cta:'Compléter mon profil',           onclick:goFiche };
  return              { icon:'💰', title:'Finance ton premier lieu à impact', why:'Ton profil est prêt. Soutiens une quête : les fonds se débloquent au fil des preuves validées, avec un reporting auditable.', from:0, to:1, val:0, unit:'lieu financé', cta:'Voir les quêtes à financer',    onclick:goQuetes };
}

// Remplit le bloc « Ton prochain cran » de l'aperçu Semeur.
function semRenderCran() {
  const c = (typeof semNextCran === 'function') ? semNextCran() : null;
  if (!c) return;
  const set = (id, fn) => { const el = document.getElementById(id); if (el) fn(el); };
  set('sem-cran-icon',  el => el.textContent = c.icon);
  set('sem-cran-title', el => el.textContent = c.title);
  set('sem-cran-why',   el => el.textContent = c.why);
  set('sem-cran-from',  el => el.textContent = c.unit + ' ' + c.val);
  set('sem-cran-to',    el => el.textContent = 'objectif ' + c.to);
  set('sem-cran-bar',   el => {
    const pct = (c.to > c.from) ? Math.max(0, Math.min(100, Math.round(((c.val - c.from) / (c.to - c.from)) * 100))) : 0;
    el.style.width = pct + '%';
  });
  set('sem-cran-cta',   el => { el.textContent = c.cta + ' →'; el.setAttribute('onclick', c.onclick); });
}

/* ─── QUÊTES À FINANCER (SEMEUR) ─── */
const SEM_QUETES = [];

const ESRS_CAT = { E1:'e',E2:'e',E3:'e',E4:'e',S1:'s',S2:'s',S3:'s',S4:'s',G1:'g',G2:'g' };
const ESRS_LABELS = { E1:'Climat',E2:'Pollution',E3:'Eau',E4:'Biodiversité',S1:'Salariés',S2:'Chaîne valeur',S3:'Communautés',S4:'Consommateurs',G1:'Gouvernance',G2:'Éthique' };
const ESRS_GAP = ['E4','S1']; // gaps identifiés dans le rapport Semeur
let semQCurrentFilter = 'toutes';

function semQFilter(f, btn) {
  semQCurrentFilter = f;
  document.querySelectorAll('#semeur-panel-quetes .mkt-tab').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  semRenderQuetes();
}

// Construit les quêtes à financer du tableau de bord semeur à partir des
// quêtes des lieux de la démo (les mêmes que celles des projets à financer),
// classées par alignement avec les axes d'impact du profil.
function semBuildQuetesAFinancer() {
  if (typeof SEM_QUETES === 'undefined' || typeof MAP_PLACES === 'undefined' || typeof SOLS === 'undefined') return;
  SEM_QUETES.length = 0;
  const axes = (typeof semFicheData !== 'undefined' && semFicheData.axes) || [];
  const AXE_KW = {
    climat:['solaire','énergie','chauffe','isolation','carbone'],
    biodiversite:['haie','mare','biodiv','jardin','permacult','arbre','verger'],
    social:['repair','atelier','amap','partagé','collectif','social'],
    alimentation:['jardin','potager','maraîch','amap','compost','aliment'],
    economie:['réemploi','repair','recycl','matériaux','circul'],
    habitat:['isolation','paille','toiture','construction','bois']
  };
  // Seules les quêtes réellement publiées par un Pilote sont proposées au financement.
  if (typeof syncPiloteQuetesFromLieu === 'function') { try { syncPiloteQuetesFromLieu(); } catch (e) {} }
  const publishedSols = (typeof PILOTE_QUETES_DEMO !== 'undefined')
    ? new Set(PILOTE_QUETES_DEMO.filter(q => q.statut === 'ouverte').map(q => q.source))
    : new Set();
  MAP_PLACES.forEach((l, li) => {
    const sols = (l.fiche && l.fiche.solutions) || [];
    sols.forEach((nom, j) => {
      if (!publishedSols.has(nom)) return;
      const sol = SOLS.find(s => s.nom === nom);
      if (!sol || !sol.quete) return;
      const text = (nom + ' ' + (sol.cat || '') + ' ' + sol.quete.titre).toLowerCase();
      const aligned = axes.some(a => (AXE_KW[a] || []).some(k => text.includes(k)));
      const tok = sol.tok || 50;
      const objectif = 1500 + tok * 18;
      const esrs = (sol.esrs || []).map(e => String(e).replace('ESRS ', '').trim());
      const _ind = (typeof SOLS_INDICATORS !== 'undefined') ? SOLS_INDICATORS[nom] : null;
      const plan = (_ind && _ind.plan) || [];
      SEM_QUETES.push({
        type: sol.img || '⚡', titre: sol.quete.titre,
        lieu: l.nom, pilote: l.nom, ville: l.ville || 'Bordeaux',
        desc: sol.desc || sol.quete.titre,
        impact: sol.quete.impact_quete || sol.impact || '',
        esrs, graines: tok, objectif, montant: 0,
        urgence: 'normal',
        aligned,
        plan, materiel: (_ind && _ind.materiel) || [],
        preuve: 'Photos de l\'action réalisée + indicateurs mesurés (CO₂, énergie, déchets…).',
        apprendre: 'Mise en œuvre de « ' + nom + ' » et documentation de l\'impact.',
        duree: sol.quete.duree || '1 journée',
        places: '0/' + (parseInt(sol.quete.nb, 10) || 6),
        etape_actuelle: 1, etapes: plan.length || 4,
        etapeLabels: plan.length ? plan.map(p => p.titre) : ['Lancement', 'Préparation', 'Réalisation', 'Certification'],
        tokens: tok, co2: sol.co2 || 0,
        financement: { objectif, montant: 0, semeur: null },
        equipe: [],
        dates: ['Samedi · 9h–17h', 'Dimanche · 9h–13h']
      });
    });
  });
  // Quêtes créées à la main par le Pilote et publiées.
  (typeof PILOTE_QUETES_DEMO !== 'undefined' ? PILOTE_QUETES_DEMO : [])
    .filter(q => q.custom && q.statut === 'ouverte')
    .forEach(q => {
      const lieuNom = (typeof myLieuData !== 'undefined' && myLieuData && myLieuData.nom) || 'Mon lieu';
      const lieuVille = (typeof myLieuData !== 'undefined' && myLieuData && (myLieuData.localisation || myLieuData.ville)) || 'Bordeaux';
      const tok = q.graines || 50;
      const objectif = 1500 + tok * 18;
      SEM_QUETES.push({
        type: q.sourceIc || '⚡', titre: q.titre,
        lieu: lieuNom, pilote: lieuNom, ville: lieuVille,
        desc: q.titre, impact: q.impact || '',
        esrs: [], graines: tok, objectif, montant: 0,
        urgence: 'normal', aligned: false,
        plan: [], materiel: [],
        preuve: 'Photos de l\'action réalisée + indicateurs mesurés.',
        apprendre: q.titre,
        duree: q.duree || '1 journée',
        places: '0/' + (parseInt(q.nb, 10) || 6),
        etape_actuelle: 1, etapes: 4,
        etapeLabels: ['Lancement', 'Préparation', 'Réalisation', 'Certification'],
        tokens: tok, co2: 0,
        financement: { objectif, montant: 0, semeur: null },
        equipe: [], dates: []
      });
    });
  SEM_QUETES.sort((a, b) =>
    (b.aligned - a.aligned)
    || ((b.urgence === 'urgent') - (a.urgence === 'urgent'))
    || ((b.objectif - b.montant) - (a.objectif - a.montant)));
  SEM_QUETES.forEach((q, i) => { q.id = i; });
}

// Ouvre la fiche d'une quête à financer (depuis le dashboard semeur).
function semOpenQuete(id) {
  const q = (typeof SEM_QUETES !== 'undefined') ? SEM_QUETES.find(x => x.id === id) : null;
  if (!q) return;
  currentRole = 'semeur';
  showQueteFiche(q, 'semeur');
}

function semRenderQuetes() {
  const list = document.getElementById('sem-quetes-list');
  if (!list) return;
  semBuildQuetesAFinancer();
  let quetes = [...SEM_QUETES];
  if (semQCurrentFilter === 'urgent') quetes = quetes.filter(q => q.urgence === 'urgent');
  if (['e','s','g'].includes(semQCurrentFilter)) {
    quetes = quetes.filter(q => q.esrs.some(e => ESRS_CAT[e] === semQCurrentFilter));
  }

  const esrsColors = {E1:'#2e7d32',E2:'#388e3c',E3:'#43a047',E4:'#4caf50',S1:'#1565c0',S2:'#1976d2',S3:'#1e88e5',S4:'#2196f3',G1:'#6a1b9a'};

  list.innerHTML = quetes.map(q => {
    const pct = q.objectif > 0 ? Math.round((q.montant / q.objectif) * 100) : 100;
    const restant = q.objectif > 0 ? Math.max(0, q.objectif - q.montant) : 0;
    const funded = pct >= 100;
    const esrsBadges = q.esrs.map(e => `<span style="font-size:.6rem;padding:.14rem .45rem;border-radius:var(--r);background:${esrsColors[e]||'#546e7a'}22;color:${esrsColors[e]||'#546e7a'};border:1px solid ${esrsColors[e]||'#546e7a'}44;font-weight:600">ESRS ${e}</span>`).join('');

    return `<div onclick="semOpenQuete(${q.id})"
      style="background:white;border:1px solid ${q.urgence==='urgent'?'rgba(184,78,53,.25)':'rgba(46,102,66,.1)'};border-left:3px solid ${q.urgence==='urgent'?'var(--terracotta)':'var(--fern)'};border-radius:var(--r-lg);padding:1rem 1.2rem;cursor:pointer;transition:all .18s"
      onmouseover="this.style.boxShadow='0 4px 14px rgba(46,102,66,.1)';this.style.borderColor='rgba(74,140,92,.3)'"
      onmouseout="this.style.boxShadow='none';this.style.borderColor='${q.urgence==='urgent'?'rgba(184,78,53,.25)':'rgba(46,102,66,.1)'}'">

      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:.7rem">
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.3rem;flex-wrap:wrap">
            ${q.urgence==='urgent'?'<span style="font-size:.58rem;padding:.1rem .4rem;border-radius:100px;background:rgba(184,78,53,.1);color:var(--terracotta);font-weight:700;border:1px solid rgba(184,78,53,.2)">🔴 Urgent</span>':''}
            ${esrsBadges}
          </div>
          <div style="font-size:.88rem;font-weight:700;color:var(--ink);margin-bottom:.2rem">${q.type} ${q.titre}</div>
          <div style="font-size:.68rem;color:var(--moss);opacity:.75">📍 ${q.lieu} · ${q.ville} · Pilote : ${q.pilote}</div>
        </div>
        <div style="text-align:right;flex-shrink:0">
          ${funded
            ? `<div style="font-size:.65rem;font-weight:700;color:var(--fern);background:rgba(74,140,92,.1);padding:.25rem .6rem;border-radius:100px;border:1px solid rgba(74,140,92,.2)">✅ Financé</div>`
            : `<div style="font-family:'Satoshi', sans-serif;font-size:1.1rem;font-weight:900;color:var(--amber)">${restant}€</div>
               <div style="font-size:.58rem;color:var(--moss);opacity:.6">restant à financer</div>`
          }
        </div>
      </div>

      ${q.objectif > 0 ? `
      <div style="margin-bottom:.6rem">
        <div style="height:5px;background:rgba(46,102,66,.08);border-radius:100px;overflow:hidden">
          <div style="height:100%;width:${Math.min(pct,100)}%;background:${funded?'var(--fern)':'var(--amber)'};border-radius:100px;transition:width .6s ease"></div>
        </div>
        <div style="display:flex;justify-content:space-between;margin-top:.3rem">
          <span style="font-size:.6rem;color:var(--moss);opacity:.6">${q.montant}€ engagés</span>
          <span style="font-size:.6rem;color:var(--moss);opacity:.6">${pct}% financé</span>
        </div>
      </div>` : ''}

      <div style="display:flex;align-items:center;justify-content:space-between;gap:.8rem">
        <div style="flex:1;min-width:0">
          <div style="font-size:.68rem;color:var(--moss);opacity:.7;margin-bottom:.3rem">🌿 ${q.impact}</div>
          <div style="display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;margin-bottom:.3rem">
            <div style="display:inline-flex;align-items:center;gap:.3rem;background:rgba(200,115,42,.08);border:1px solid rgba(200,115,42,.2);border-radius:100px;padding:.18rem .55rem">
              <span style="font-size:.62rem;color:var(--moss);opacity:.75">Si complétée :</span>
              <span style="font-family:'Satoshi', sans-serif;font-size:.8rem;font-weight:900;color:var(--amber)">+${q.graines} 🌱</span>
              <span style="font-size:.58rem;color:var(--moss);opacity:.6">graines CSRD</span>
            </div>
          </div>
          <div style="font-size:.65rem;color:var(--moss);line-height:1.5">
            📋 <strong>Indicateurs couverts :</strong>
            ${q.esrs.map(e=>`<span style="font-weight:600;color:${ESRS_GAP.includes(e)?'var(--terracotta)':'var(--fern)'}">${e} ${ESRS_LABELS[e]||''}${ESRS_GAP.includes(e)?' ⚠️ gap':''}</span>`).join(' · ')}
          </div>
        </div>
        <button class="btn btn-primary" style="font-size:.65rem;padding:.32rem .8rem;flex-shrink:0"
          onclick="event.stopPropagation();semOpenQuete(${q.id})">
          ${funded ? 'Voir la quête →' : `Financer (${restant}€) →`}
        </button>
      </div>
    </div>`;
  }).join('') || '<div style="text-align:center;padding:2rem;color:var(--moss);opacity:.5;font-size:.8rem">Aucune quête pour ce filtre</div>';
}

let semESRSExpanded = false;
function semToggleESRS() {
  semESRSExpanded = !semESRSExpanded;
  const rows = document.getElementById('esrs-rows');
  const btn = document.getElementById('esrs-toggle-btn');
  if (semESRSExpanded) {
    renderESRS();
    rows.style.display = 'block';
    if (btn) btn.textContent = 'Masquer ↑';
  } else {
    rows.style.display = 'none';
    if (btn) btn.textContent = 'Voir les 10 ESRS ↓';
  }
}

/* ─── MARKETPLACE SEMEUR ─── */
let smktCurrentCat = 'tous';
let smktBalance = 0;

function smktFilter(cat, btn) {
  smktCurrentCat = cat;
  document.querySelectorAll('#semeur-panel-graines .mkt-tab').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  smktRender();
}

// Mêmes offres que le Marketplace, vues côté Semeur (« Utiliser mes graines ») :
// id = index (la modale lit SMKT_OFFRES[id]), badge « financer » sur les lieux soutenus.
const SMKT_OFFRES = ((typeof MKT_OFFRES !== 'undefined') ? MKT_OFFRES : []).map((o, i) => ({
  ...o,
  id: i,
  badge: (o.lieu === 'Darwin Écosystème' || o.lieu === 'Le Jardin de ta Sœur') ? 'financer' : o.badge
}));

function smktRender() {
  const grid = document.getElementById('smkt-grid');
  if (!grid) return;
  // Solde RÉEL du semeur (grand livre : budget de bienvenue − financements).
  const _sp = (typeof evadGrainesParty === 'function') ? evadGrainesParty('semeur') : null;
  if (_sp && typeof evadGrainesEnsureWelcome === 'function') evadGrainesEnsureWelcome(_sp);
  smktBalance = _sp ? evadGrainesDispo(_sp.type, _sp.id) : (smktBalance || 0);
  const balMain = document.getElementById('semeur-graines-balance');
  if (balMain) { balMain.textContent = smktBalance.toLocaleString('fr-FR'); balMain.style.cursor = 'pointer'; balMain.onclick = evadOpenWallet; }
  const balMkt = document.getElementById('smkt-balance-display');
  if (balMkt) { balMkt.textContent = smktBalance.toLocaleString('fr-FR'); balMkt.style.cursor = 'pointer'; balMkt.onclick = evadOpenWallet; }
  let offres = [...SMKT_OFFRES];
  if (smktCurrentCat !== 'tous') offres = offres.filter(o => o.cat === smktCurrentCat);
  grid.innerHTML = offres.map(o => {
    const canAfford = smktBalance >= o.prix;
    let badgeHtml = '';
    if (o.badge === 'financer') badgeHtml = `<div style="position:absolute;top:.4rem;right:.4rem;font-size:.52rem;font-weight:700;padding:.15rem .45rem;border-radius:100px;background:rgba(74,140,92,.88);color:white;letter-spacing:.04em">✓ Vous financez</div>`;
    else if (o.badge === 'new') badgeHtml = `<div style="position:absolute;top:.4rem;right:.4rem;font-size:.52rem;font-weight:700;padding:.15rem .45rem;border-radius:100px;background:var(--fern);color:white">Nouveau</div>`;
    else if (o.badge === 'premium') badgeHtml = `<div style="position:absolute;top:.4rem;right:.4rem;font-size:.52rem;font-weight:700;padding:.15rem .45rem;border-radius:100px;background:linear-gradient(135deg,var(--lavender),var(--sky));color:white">Premium</div>`;
    const stockHtml = o.stock <= 3 ? `<div style="font-size:.6rem;color:var(--terracotta);font-weight:600;margin-top:.2rem">⚠ Plus que ${o.stock} disponibles</div>` : '';
    return `<div class="smkt-card" onclick="smktOpenModal(${o.id})">
      <div class="smkt-img" style="background:${o.bg}">${o.emoji}${badgeHtml}</div>
      <div class="smkt-body">
        <div class="smkt-cat">${mktCatLabel(o.cat)}</div>
        <div class="smkt-title">${o.titre}</div>
        <div class="smkt-lieu">📍 ${o.lieu} · ${o.ville}</div>
        <div class="smkt-impact">🌱 ${o.impact}</div>
        ${stockHtml}
      </div>
      <div class="smkt-footer">
        <div><div class="smkt-price">${o.prix > 0 ? '🌱 '+o.prix : '🎁 Gratuit'}</div><div style="font-size:.58rem;color:var(--moss);opacity:.6">${o.prix > 0 ? o.unite : 'accès libre'}</div></div>
        <button class="smkt-btn ${canAfford ? 'smkt-btn-ok' : 'smkt-btn-no'}" onclick="event.stopPropagation();smktOpenModal(${o.id})">${canAfford ? (o.prix === 0 ? 'Accéder →' : 'Déverrouiller →') : 'Insuffisant'}</button>
      </div>
    </div>`;
  }).join('');
}

function smktOpenModal(id) {
  const o = SMKT_OFFRES[id];
  if (!o) return;
  const canAfford = smktBalance >= o.prix;
  const modal = document.getElementById('smkt-modal');
  const content = document.getElementById('smkt-modal-content');
  const circularityMsg = o.badge === 'financer'
    ? `<div style="background:rgba(74,140,92,.08);border:1px solid rgba(74,140,92,.2);border-radius:var(--r-lg);padding:.6rem .9rem;margin-bottom:.9rem;font-size:.7rem;color:var(--fern);font-weight:500">✓ Vous financez ce lieu via un smart contract actif, dépenser vos graines ici renforce la circularité de l'écosystème EVAD.</div>`
    : '';
  content.innerHTML = `
    <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.2rem">
      <div style="width:60px;height:60px;border-radius:var(--r-lg);background:${o.bg};display:flex;align-items:center;justify-content:center;font-size:1.8rem;flex-shrink:0">${o.emoji}</div>
      <div>
        <div style="font-size:.6rem;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.1em;margin-bottom:.15rem">${mktCatLabel(o.cat)}</div>
        <h2 style="font-family:'Satoshi', sans-serif;font-size:1.1rem;font-weight:900;color:var(--ink);line-height:1.15;margin-bottom:.2rem">${o.titre}</h2>
        <div style="font-size:.7rem;color:var(--moss)">📍 ${o.lieu} · ${o.ville}</div>
      </div>
    </div>
    <p style="font-size:.78rem;color:var(--moss);line-height:1.55;margin-bottom:.9rem">${o.desc}</p>
    <div style="background:rgba(74,140,92,.06);border:1px solid rgba(74,140,92,.15);border-radius:var(--r-lg);padding:.7rem .9rem;margin-bottom:.9rem;font-size:.72rem;color:var(--forest)">🌱 Impact estimé : ${o.impact}</div>
    ${circularityMsg}
    <div style="display:flex;align-items:center;justify-content:space-between;padding:.8rem 1rem;background:${canAfford ? 'rgba(74,140,92,.06)' : 'rgba(184,78,53,.05)'};border:1px solid ${canAfford ? 'rgba(74,140,92,.2)' : 'rgba(184,78,53,.2)'};border-radius:var(--r-lg);margin-bottom:.9rem">
      <div>
        <div style="font-size:.6rem;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.1em">Coût</div>
        <div style="font-family:'Satoshi', sans-serif;font-size:1.3rem;font-weight:900;color:var(--amber)">${o.prix > 0 ? '🌱 '+o.prix+' graines' : '🎁 Gratuit'}</div>
      </div>
      <div style="text-align:right">
        <div style="font-size:.6rem;color:var(--moss);opacity:.6;text-transform:uppercase;letter-spacing:.1em">Votre solde</div>
        <div style="font-family:'Satoshi', sans-serif;font-size:1rem;font-weight:700;color:${canAfford ? 'var(--fern)' : 'var(--terracotta)'}">🌱 ${smktBalance.toLocaleString('fr-FR')} ${canAfford ? '✓' : '– insuffisant'}</div>
      </div>
    </div>
    <div style="display:flex;gap:.6rem">
      ${canAfford
        ? `<button class="btn btn-primary" style="flex:1;padding:.7rem" onclick="smktConfirmBuy(${o.id})">${o.prix === 0 ? '🎟 Accéder gratuitement' : '🌱 Déverrouiller (−'+o.prix+' graines)'}</button>`
        : `<button class="btn" style="flex:1;padding:.7rem;background:rgba(46,102,66,.08);color:var(--moss);cursor:default" disabled>🔒 graines insuffisants (manque ${o.prix - smktBalance})</button>`}
      <button class="btn btn-ghost" onclick="document.getElementById('smkt-modal').style.display='none'">Fermer</button>
    </div>`;
  modal.style.display = 'flex';
}

function smktConfirmBuy(id) {
  const o = SMKT_OFFRES[id];
  if (!o || smktBalance < o.prix) return;
  smktBalance -= o.prix;
  // Sync both balance displays
  const balMain = document.getElementById('semeur-graines-balance');
  if (balMain) balMain.textContent = smktBalance.toLocaleString('fr-FR');
  const balMkt = document.getElementById('smkt-balance-display');
  if (balMkt) balMkt.textContent = smktBalance.toLocaleString('fr-FR');
  document.getElementById('smkt-modal').style.display = 'none';
  smktRender();
  mmBubble(`✅ Accès déverrouillé ! "${o.titre}" chez ${o.lieu}, ${o.prix > 0 ? '−'+o.prix+' graines' : 'gratuit'} · Confirmation envoyée`);
}

